\title{The negative symmetry classification problem}

\author[]{M.P. Kolesnikov\thanks{kolesnikov.mp@phystech.edu}} 
\affil[]{Center of Integrable Systems, P.G. Demidov Yaroslavl State University, Yaroslavl, Russia}

\date{}

