  \centering
  \includegraphics[width=0.9\textwidth, trim={1cm 0cm 2.2cm 1cm}, clip]{fig3.pdf}
  \caption{\textbf{rHHG within the IPA.} \textbf{(a-c)} Same as (b-d) in Fig.\ref{fig:TDFT_gabor}. Note the spin-down response on resonance is in-phase with the maxima/minima of the driving field and strongly suppressed, unlike in Fig.\ref{fig:TDFT_gabor}.} \label{fig:IPA_gabor}
