\section{Expression for the T-matrix}
\label{app:T-matrix}

In this section, we deduce the T-matrix for a split-ring Helmholtz in \eqref{eq:T-matrix_general} and use an expression for $z(\lambda)$ in \eqref{eq:int_geom_factor} combined with \eqref{eq:h_expression} for a split ring resonator.


Consider a resonator with outer radius $b$, inner radius $a$, aperture size $2\ell$, and orientation $\theta_0$, as shown in Figure \ref{fig:split-ring_resonator}. Let us obtain the scattered field for the incident plane incident wave:
%
\begin{equation}
    \notag
    v_{\text{inc}}(\bm{r}) = \mathrm e^{\mathrm i k r \cos (\theta - \theta_{\text{inc}})},
\end{equation}
%
Using \cite[Equation (3.1)]{Atom-Helmholtz} we can calculate the scattered field for $\theta_0 = 0$ which in our notation becomes
%
\begin{equation}
    \label{eq:field_outside}
    v_{\text{sc}} (\bm{r}) = A \mathrm U_0(k \bm{\tilde{r}}) +  \sum_{n = -\infty}^{\infty} c_n \mathrm U_n(k \bm{r}),
\end{equation}
%
where $\bm{\tilde{r}} = \bm{r} - b(\cos(\theta_{0}), \sin(\theta_{0}))$ is the aperture location, $c_n$ and $A$ are coefficients given by \cite[Eqs. (3.4) and (3.6) respectively]{Atom-Helmholtz}. To obtain the scattered field for $\theta_0 \not = 0$, we rotate the coordinate system $\theta \to \theta - \theta_{0}$, followed by the rotation of the incident wave $\theta_{\text{inc}} \to \theta_{\text{inc}} - \theta_{0}$. These rotations leave the incident wave unaltered while rotating the resonator by an angle of $\theta_{0}$ which together with \cite[Equation (3.1)]{Atom-Helmholtz} results in:
%
\begin{equation}
    \label{eq:plane_wave_coefs}
    \begin{aligned}
        &A = - z(\lambda) \sum_{p = -\infty}^{\infty} \frac{\mathrm i^p kb}{\mathrm H'_p(kb)} \mathrm e^{\mathrm i p (\theta_{0} - \theta_{\text{inc}})},
\\
        &c_n = - \mathrm i^n \frac{\mathrm J_n'(k b)}{\mathrm H'_n (k b)} \mathrm e^{-\mathrm i n \theta_{\text{inc}}} - \frac{A}{2} \frac{\mathrm Q_n(kb)}{\mathrm H'_n(kb)} \mathrm e^{-\mathrm i n \theta_{0}},
    \end{aligned}
\end{equation}
%
where $\mathrm Q_n (x) = \mathrm J_n(x) \mathrm H'_n(x) + \mathrm J'_n(x) \mathrm H_n(x)$, the prime notation denotes the derivative with respect to the argument. We call the function $z(\lambda)$ the resonance factor and it is defined by \eqref{eq:int_geom_factor} in \Cref{app:expansion}.

To rewrite \eqref{eq:field_outside} in terms of a T-matrix, shown in \eqref{eq:T-matrix}, we need to express all the terms centred at the origin, which leads us to use Graf's addition theorem to rewrite the monopole term evaluated at $k \bm{\tilde{r}}$ in the form:
%
\begin{equation}
    \notag
    \mathrm U_0(k \bm{\tilde{r}}) = \sum_{n = -\infty}^{\infty} \mathrm J_{-n}(kb) \mathrm e^{\mathrm i n (\pi - \theta_{0})} \mathrm U_n(k\bm{r}),
\end{equation}
%
which substituted into \eqref{eq:field_outside} leads to 
% allows us to recombine the coefficients for the Hankel expansion \eqref{eq:field_outside} into:
%
\begin{equation}
    \label{eq:field_outside_one_series}
    v_{\text{sc}} (\bm{r}) = \sum_{n=-\infty}^{\infty} d_n \mathrm U_n(k\bm{r}), \quad \text{with} \quad d_n = c_n + A \mathrm J_n(kb) \mathrm e^{-\mathrm i n \theta_{0}}.
\end{equation}

Next, the T-matrix \eqref{eq:T-matrix} relates any incident wave to the scattered wave, so we need to rewrite any incident wave $u_{\text{inc}}(\bm{r})$ in terms of plane waves to use the results above. To achieve this, we use the Jacobi-Anger expansion of the plane wave:
% \eqref{eq:regular_expansion}
%
\begin{equation}
    \notag
    v_{\text{inc}}(\bm{r}) = \mathrm e^{\mathrm i k r \cos(\theta - \theta_{\text{inc}})} = \sum_{n = -\infty}^{\infty} \mathrm i^n \mathrm J_n(kr) \mathrm e^{\mathrm i n (\theta - \theta_{\text{inc}})},
\end{equation}
%
followed by a superposition of plane waves:
%
\begin{equation}
\label{eq:incident_wave_superposition}
    \begin{aligned}
        u_{\text{inc}}(\bm{r}) &= \int_0^{2\pi} v_{\text{inc}}(\bm{r}) \mathrm g(\theta_{\text{inc}}) \mathrm d \theta_{\text{inc}}
    = \int_0^{2\pi} \sum_{n} \mathrm g(\theta_{\text{inc}}) \mathrm i^n \mathrm J_n(kr) \mathrm e^{\mathrm i n (\theta - \theta_{\text{inc}})} \mathrm d \theta_{\text{inc}}
\\
        &= \sum_{n} \left[ \mathrm i^n \int_0^{2\pi} \mathrm g(\theta_{\text{inc}}) \mathrm e^{-\mathrm i n \theta_{\text{inc}}} \mathrm d \theta_{\text{inc}} \right] \mathrm V_n(k \bm{r}).
    \end{aligned}
\end{equation}
%
Without loss of generality, we choose the amplitude of the packet of plane waves $\mathrm g(\theta_{\text{inc}})$ in \eqref{eq:incident_wave_superposition} such that:
%
\begin{equation}
    \notag
    \mathrm i^n \int_0^{2\pi} \mathrm g(\theta_{\text{inc}}) \mathrm e^{-\mathrm i n \theta_{\text{inc}}} \mathrm d \theta_{\text{inc}} = g_n,
\end{equation}
%
which implies that \eqref{eq:incident_wave_superposition} now matches the form of any regular incident wave \eqref{eq:regular_expansion}.

% means \eqref{eq:incident_wave_superposition} can be rewritten as \eqref{eq:regular_expansion} from \Cref{sec:design}.

Now we need to perform the same operations on the scattered field $v_{\text{sc}}$ \eqref{eq:field_outside_one_series} from a plane wave to obtain the total scattered field from any incident wave $u_{\text{sc}}$, which is possible due to the linearity of the Helmholtz equation and results in:
% the scattering field from one split-ring resonator as the same superposition considered in \eqref{eq:incident_wave_superposition}, but for the scattered field \eqref{eq:field_outside_one_series} instead:
%
\begin{equation}
    \label{eq:superposition_scat_wave}
    \begin{aligned}
        u_{\text{sc}} (\bm{r}) &= \int_{0}^{2\pi} v_{\text{sc}}(\bm{r}) \mathrm g(\theta_{\text{inc}}) \mathrm d \theta_{\text{inc}}
        = \sum_{n} \left[ \int_0^{2\pi} d_n \mathrm g(\theta_{\text{inc}}) \mathrm d \theta_{\text{inc}} \right] \mathrm U_n(k\bm{r}),
\\
        &= \sum_{n,p} \left[ -\delta_{np} \frac{\mathrm J'_p(kb)}{\mathrm H'_p(kb)} + \frac{2 \mathrm e^{-\mathrm i(n - p) \theta_{0}}}{(\pi k b)^2 h(\lambda)\mathrm H'_n(kb)\mathrm H'_p(kb)} \right] g_p \mathrm U_n(k\bm{r}),
    \end{aligned}
\end{equation}
%
where we have used the Wronskian of Bessel-Hankel functions in the second line:
%
\begin{equation}
    \notag
    \mathrm J_n(x) \mathrm H'_n(x) - \mathrm J'_n(x) \mathrm H_n(x) = \frac{2 \mathrm i}{\pi x}.
\end{equation}
%
Finally by comparing \eqref{eq:T-matrix}, \eqref{eq:T-matrix_general} and \eqref{eq:superposition_scat_wave} we conclude that:
%
\begin{equation}
    \label{eq:T-matrix_expression}
    T_{np} = - \frac{\mathrm J'_p(kb)}{\mathrm H'_p(kb)}\delta_{np} + \frac{\mathrm i \mathrm e^{\mathrm i(n - p) \theta_{0}}}{\pi \mathrm H'_n(kb)\mathrm H'_p(kb) } z(\lambda),
     % z(\lambda) = \frac{2 \mathrm i}{\pi (kb)^2 h(\lambda)}.
\end{equation}
%
which is the general T-matrix for a Helmholtz resonator using formulae in \cite{Atom-Helmholtz}.

% allowing us to rewrite \eqref{eq:T-matrix_expression} into \eqref{eq:T-matrix_general}.

% A typical analogy used to explain the low-frequency resonance in Helmholtz resonators is to compare it with a spring with a mass on the end \cite[7.4.1 The Helmholtz Resonator]{pierce2019acoustics}: the volume of air in the neck is considered to be the mass, while the way the air in the center compresses and expands is related to the spring constant.

In \Cref{subsec:low_freq}, the T-matrix \eqref{eq:T-matrix_general} is used to calculate the dispersion equation. However, as discussed in \cite{Gower_2021,napal2023effective}, only the average T-matrix over all orientations of the aperture $\theta_0$ contributes to the dispersion equation. We call this orientation averaged version of \eqref{eq:T-matrix_general} the isotropic T-matrix, which is given by terms in the diagonal of \eqref{eq:T-matrix_general}, as follows:
%
\begin{equation}
    \label{eq:diagonal_T-matrix}
    \overline{T}_{n}(\lambda) = - \frac{\mathrm J'_n(kb)}{\mathrm H'_n(kb)} - \frac{\mathrm i z(\lambda)}{\pi [\mathrm H'_n(kb)]^2}.
\end{equation}
%

\section{Low-frequency behaviour of the resonance factor}
\label{app:expansion}

In this section we show $z(\lambda)$ for a 2D thin walled-split resonator. Other expressions for $z(\lambda)$ for other Helmholtz resonators can be deduced from~\cite{Krynkin_2011, Scat_perforated_cylinders, Split_ring_lipmann_scwinger}  

We use the results from \cite{Atom-Helmholtz}, where $z(\lambda)$ is related to the function $h(\lambda)$ through:
%
\begin{equation}
    \label{eq:int_geom_factor}
    z(\lambda) = \frac{2 \mathrm i}{\pi (kb)^2 h(\lambda)}.
\end{equation}

For a thin-walled Helmholtz resonator ($b=a$ in \Cref{fig:split-ring_resonator}) $h(\lambda)$ is given by \cite[equation (3.7)]{Atom-Helmholtz}:
%
\begin{equation}
    \label{eq:h_expression} 
    h(kb, k\ell) =
        2 +
        \frac{4 \mathrm i}{\pi} \left( \gamma_e + \log{\frac{k\ell}{4}} \right) - \frac{1}{2} \sum_{m = -\infty}^{\infty} \frac{\mathrm Q_m^2(kb)}{ \mathrm H'(kb) \mathrm J'(kb)},
\end{equation}
%
where $\mathrm Q_m(x) = \mathrm J_m(x) \mathrm H_m'(x) + \mathrm J_m'(x) \mathrm H_m(x)$ and $\gamma_e$ is the Euler-Mascheroni constant. For the expression for $h(kb, ka, k\ell)$ for a thick-walled resonator ($a < b$) see \cite[equation (3.7)]{Atom-Helmholtz}, which we use to produce the results in \Cref{fig:three-species-example}.

Performing the asymptotic expansion of $\epsilon = k b \ll 1$ in \eqref{eq:h_expression} we obtain
\begin{equation}
    \label{eq:h_expansion} 
    h(kb, k\ell) =
        2 +
        \frac{4 \mathrm i}{\pi} \left( \gamma_e + \log{\frac{k\ell}{4}} \right) + \frac{2 \mathrm i}{\pi} \frac{1}{\epsilon^2} + \mathcal O \left( \frac{1}{\epsilon} \right),
\end{equation}
where we do not expand the logarithmic term. From the above, and noting that $k \ell < k b$, we can conclude that $|h| \in \mathcal{O}(\epsilon^2)$ for frequencies away from resonance, which implies that $|z| \in \mathcal {O}(1)$. At resonance we have that $h(\lambda)$ is purely real, which occurs when $h(kb, k\ell) = 2$, and then $|z| \in \mathcal O(\epsilon^{-2})$. In other words, $z(\lambda)$ changes its order in $\epsilon$ when passing through resonance, which complicates an asymptotic analysis. 
%The resonance occurs at the frequency where $|h(kb, k\ell)|$ becomes small. The exact frequency that this occurs requires numerical computation to predict.
%We also note that it is best not to perform an asymptotic expansion for \eqref{eq:h_expression}, as
Luckily, we do not need to perform an asymptotic expansion on $z(\lambda)$ to deduce simple effective formulae for the leading order term.

% Is it possible to add formulae for thick wall? Now might be easy as no asymptotic analysis is needed.

% Then, assuming that $\epsilon = kb \ll 1$, we perform a power series expansion of \eqref{eq:h_expression}, leading to:
% %
% \begin{equation}
%     \label{eq:h_expansion} 
%     h(kb, k\ell) =
%         2 +
%         \frac{4 \mathrm i}{\pi} \left( \gamma_e + \log{\frac{k\ell}{4}} \right) + \frac{2 \mathrm i}{\pi} \frac{1}{\epsilon^2} + \mathcal O \left( \frac{1}{\epsilon} \right),
% \end{equation}
