\title{Well-posed Self-Similarity in Incompressible Standard Flows}
\author{J. Polihronov}
\address{Department of Mathematics, Lambton College, 1457 London Rd, Sarnia, ON N7S 6K4, Canada}
\email{jack.polihronov@lambtoncollege.ca}
