Throughout the paper we shall use the following notations.
\begin{itemize}
\item $\mathcal{O}_\epsilon(1)$ is a bounded quantity independent of $\epsilon$, and $o_{\epsilon}(1)$ is a small quantity tending to zero as $\epsilon$ goes to zero.
\item $\R_{+}^{d}=\{(z=(z',z^{d})\in\R^d:z^{d}>0\}$, $\partial\R_{+}^{d}=\{z=(z',z^{d})\in\R^d:z^{d}=0\}$, and $\overline\R_{+}^{d}=\R_{+}^{d}\cup\partial\R_{+}^{d}$.
\item $e_d$ stands for the unit vector in the positive direction of $z^{d}$-axis.
\item $|\Omega|$ denotes the volume of $\Omega$, and $|\partial\Omega_k|$ stands for the surface area of $\partial\Omega_k$ for $k=0,1,\dots,K$.
\item $\Omega_{k,T,\epsilon}=\{x\in\Omega\,:\,\dist(x,\partial\Omega_k)<T\sqrt\epsilon\}$, $\Omega_{k,T,\epsilon,\beta}=\{x\in\Omega\,:\,T\sqrt\epsilon<\dist(x,\partial\Omega_k)<\epsilon^\beta\}$, $\Omega_{k,\epsilon,\beta}=\{x\in\Omega\,:\,\dist(x,\partial\Omega_k)<\epsilon^\beta\}$ and $\Omega_{\epsilon,\beta}=\{x\in\Omega\,:\,\dist(x,\partial\Omega)>\epsilon^\beta\}$, where $\dist$ denotes the distance.
\item $\delta_{k}(x)=\dist(x,\partial\Omega_k)$ and $\delta(x)=\dist(x,\partial\Omega)=\min\{\delta_{0}(x),\delta_{1}(x),\dots,\delta_{K}(x)\}$.
\item $\dd\underline{\phi_{bd}}=\min_{0\leq k\leq K}\phi_{bd,k}$ and $\dd\overline{\phi_{bd}}=\max_{0\leq k\leq K}\phi_{bd,k}$.
\item $\epsilon^{*}>0$ is a sufficiently small constant, and $M>0$ is a generic constant independent of $\epsilon>0$.
\end{itemize}

