\section{Exponential-type estimate of radial solution}
\label{appendix:A}

Here we study the radial solutions $\Phi_\epsilon=\Phi_\epsilon(r)$ to equations $\eqref{eq.1.01}$ and \eqref{eq.3.001} in the ball $B_R(0)$ with the Dirichlet boundary condition, respectively.
Equation \eqref{eq.1.01} with the Dirichlet boundary condition can be denoted as
\begin{align}
\label{eq.A.01}
&-\epsilon(r^{d-1}\Phi_{\epsilon}'(r))'=r^{d-1}f(\Phi_{\epsilon}(r))\quad\text{for}~r\in(0,R),\\
\label{eq.A.02}
&\Phi_{\epsilon}'(0)=0,\\
\label{eq.A.03}
&\Phi_{\epsilon}(R)=\Phi_{bd},
\end{align}
where $f\in\C^1(\R)$ is a strictly decreasing function satisfying (A1)--(A2), and $\Phi_{bd}$ is a constant independent of $\epsilon$.
Note that if $\Phi_{bd}=\phi^{*}$ ($\phi^{*}$ is the unique zero of $f$), then by the uniqueness of \eqref{eq.A.01}--\eqref{eq.A.03}, $\Phi_\epsilon\equiv\phi^{*}$ is a trivial solution.
Hence we assume $\Phi_{bd}\neq\phi^{*}$. By (A1)--(A2), it is easy to prove

\begin{proposition}
\label{proposition:A.1}
Assume that $f$ satisfies (A1)--(A2).
Let $\Phi_{\epsilon}$ be the solution to \eqref{eq.A.01}--\eqref{eq.A.03} for $\epsilon>0$.
\begin{enumerate}
\item[(a)] If $\Phi_{bd}>\phi^{*}$, then $\Phi_{\epsilon}(0)>\phi^{*}$ and $\Phi_{\epsilon}$ is strictly increasing;
\item[(b)] if $\Phi_{bd}<\phi^{*}$, then $\Phi_{\epsilon}(0)<\phi^{*}$ and $\Phi_{\epsilon}$ is strictly decreasing.
\end{enumerate}
\end{proposition}

\begin{proposition}\label{proposition:A.2}
Assume that $f$ satisfies (A1)--(A2).
Let $\Phi_\epsilon$ be the solution to \eqref{eq.A.01}--\eqref{eq.A.03} for $\epsilon>0$. Then
\begin{align}
\label{eq.A.04}
|\Phi_{\epsilon}(r)-\phi^{*}|\leq2|\Phi_{bd}-\phi^{*}|\exp\left(-\frac{m_f(R-r)}{8\sqrt\epsilon}\right)\end{align}
for $r\in[0,R]$ and $0<\epsilon<(m_fR)^2/[8(d-1)^2]$, where $m_f=m_f([\min\{\phi^{*},\Phi_{bd}\},\max\{\phi^{*},\Phi_{bd}\}])$ is given in (A1).
\end{proposition}
\begin{proof}
Let $\overline\Phi_{\epsilon}:=\Phi_{\epsilon}-\phi^{*}$ on $[0,R]$ for $\epsilon>0$.
Then from \eqref{eq.A.01}--\eqref{eq.A.03}, $\overline{\Phi}_{\epsilon}$ satisfies
\begin{align}
\label{eq.A.05}
&-\epsilon(r^{d-1}\overline{\Phi}_{\epsilon}'(r))'=r^{d-1}f(\phi^{*}+\overline{\Phi}_{\epsilon}(r))\quad\text{for}~r\in(0,R),\\
\label{eq.A.06}
&\overline{\Phi}_{\epsilon}'(0)=0,\\
\label{eq.A.07}
&\overline{\Phi}_{\epsilon}(R)=\Phi_{bd}-\phi^{*}.
\end{align}
By (A1)--(A2), we have
\begin{align}
\label{eq.A.08}
\begin{aligned}
f(\phi^{*}+\overline\Phi_\epsilon(r))\overline\Phi_\epsilon(r)&=\left(\int_0^1\!\frac{\mathrm{d}}{\mathrm{d}s}f(\phi^{*}+s\overline\Phi_\epsilon(r))\,\mathrm{d}s\right)\overline\Phi_\epsilon(r)\\&=\left(\int_0^1\!f'(\phi^{*}+s\overline\Phi_\epsilon(r))\,\mathrm{d}s\right)\overline\Phi_\epsilon^2(r)\leq-m_f^2\overline\Phi_\epsilon^2(r)
\end{aligned}
\end{align}
for $r\in(0,R)$.
Here we have used the fact that $\overline\Phi_\epsilon=\Phi_{\epsilon}-\phi^{*}$ is uniformly bounded (cf. \Cref{proposition:2.1} also works for the Dirichlet boundary condition \eqref{eq.A.03}).
By \eqref{eq.A.05} and \eqref{eq.A.08}, we obtain
\begin{equation}
\label{eq.A.09}
\begin{aligned}
\epsilon(\overline{\Phi}_{\epsilon}^2(r))''&=2\epsilon\overline{\Phi}_{\epsilon}'^2(r)+2\epsilon\overline{\Phi}_{\epsilon}''(r)\overline{\Phi}_{\epsilon}(r)\\
&=2\epsilon\overline{\Phi}_{\epsilon}'^2(r)-\frac{2\epsilon(d-1)}{r}\overline{\Phi}_{\epsilon}'(r)\overline{\Phi}_{\epsilon}(r)-2f(\phi^{*}+\overline{\Phi}_{\epsilon}(r))\overline{\Phi}_{\epsilon}(r)\\
&\geq2\epsilon\overline{\Phi}_{\epsilon}'^2(r)-\frac{2\epsilon(d-1)}{r}\overline{\Phi}_{\epsilon}'(r)\overline{\Phi}_{\epsilon}(r)+2m_f^2\overline{\Phi}_{\epsilon}^2(r)\quad\text{for}~r\in(0,R).
\end{aligned}
\end{equation}
On the other hand, by Young's inequality, we have
\begin{align}
\label{eq.A.10}
\begin{aligned}\frac{2\epsilon(d-1)}{r}\overline{\Phi}_{\epsilon}'(r)\overline{\Phi}_{\epsilon}(r)
&\leq2\epsilon\overline{\Phi}_{\epsilon}'^2(r)+\frac{\epsilon(d-1)^2}{2r^2}\overline{\Phi}_{\epsilon}^{2}(r)
\\&\leq2\epsilon\overline{\Phi}_{\epsilon}'^2(r)+\frac{8\epsilon(d-1)^2}{R^2}\overline{\Phi}_{\epsilon}^{2}(r)\quad\text{for}~r\in[R/4,R).
\end{aligned}
\end{align}
Combining \eqref{eq.A.09} and \eqref{eq.A.10}, we get
\begin{align}
\label{eq.A.11}
\epsilon(\overline{\Phi}_{\epsilon}^2(r))''\geq\left(2m_f^2-\frac{8\epsilon(d-1)^2}{R^2}\right)\overline{\Phi}_{\epsilon}^{2}(r)\geq m_f^2\overline{\Phi}_{\epsilon}^{2}(r)\quad\text{for}~r\in[R/4,R).
\end{align}
Here we have used that $0<\epsilon<(m_fR)^2/[8(d-1)^2]$.
Applying the comparison theorem to \eqref{eq.A.11}, it yields
\begin{align}
\label{eq.A.12}
\overline{\Phi}_{\epsilon}^{2}(r)\leq\max\{\overline{\Phi}_{\epsilon}^{2}(R/4),\overline{\Phi}_{\epsilon}^{2}(R)\}\left[\exp\left(-\frac{m_f(R-r)}{\sqrt{\epsilon}}\right)+\exp\left(-\frac{m_f(r-R/4)}{\sqrt{\epsilon}}\right)\right]
\end{align}
for $r\in[R/4,R]$.
By \Cref{proposition:A.1}, $(\overline{\Phi}_{\epsilon}^2(r))'=2\overline{\Phi}_{\epsilon}'(r)\overline{\Phi}_{\epsilon}(r)>0$ on $(0,R)$, and $\overline{\Phi}^2$ is strictly increasing on $[0,R]$.
Consequently, we have $\overline{\Phi}_{\epsilon}^2(R/4)<\overline\Phi_{\epsilon}^2(R)=(\Phi_{bd}-\phi^{*})^2$.
From \eqref{eq.A.12}, we get
\[|\overline{\Phi}_{\epsilon}(r)|\leq|\Phi_{bd}-\phi^{*}|\left[\exp\left(-\frac{m_f(R-r)}{2\sqrt\epsilon}\right)+\exp\left(-\frac{m_fR}{8\sqrt\epsilon}\right)\right]\quad\text{for}~r\in[3R/4,R],\]
which implies
\begin{align}
\label{eq.A.13}
|\overline{\Phi}_{\epsilon}(r)|\leq2|\Phi_{bd}-\phi^{*}|\exp\left(-\frac{m_f(R-r)}{2\sqrt{\epsilon}}\right)\quad\text{for}~r\in[3R/4,R].
\end{align}
Since $\overline{\Phi}_{\epsilon}^2$ is strictly increasing on $[0,R]$, $|\overline{\Phi}|$ is also strictly increasing on $[0,R]$.
Then by \eqref{eq.A.13}, we have
\begin{align}
\label{eq.A.14}
|\overline{\Phi}_{\epsilon}(r)|\leq|\overline{\Phi}_{\epsilon}(3R/4)|\leq2|\Phi_{bd}-\phi^{*}|\exp\left(-\frac{m_fR}{8\sqrt\epsilon}\right)\leq2|\Phi_{bd}-\phi^{*}|\exp\left(-\frac{m_f(R-r)}{8\sqrt\epsilon}\right)
\end{align}
for $r\in[0,3R/4]$.
Combining \eqref{eq.A.13} and \eqref{eq.A.14}, we arrive at \eqref{eq.A.04} and complete the proof of \Cref{proposition:A.2}.
\end{proof}

Now we consider the radial solution $\Phi_\epsilon=\Phi_\epsilon(r)$ to equation \eqref{eq.3.001} with the Dirichlet boundary condition, which satisfies
\begin{align}
\label{eq.A.15}
&-\epsilon(r^{d-1}\Phi_\epsilon'(r))'=r^{d-1}f_{\epsilon}(\Phi_\epsilon(r))\quad\text{for}~r\in(0,R),\\
\label{eq.A.16}
&\Phi_\epsilon'(0)=0,\\
\label{eq.A.17}
&\Phi_\epsilon(R)=\Phi_{bd},
\end{align}
where $f_{\epsilon}$ has a unique zero $\phi_{\epsilon}^{*}\in\R$ and satisfies $f_{\epsilon}'(\phi)\leq-M^2<0$ for $\phi\in\R$. Note that $f_{\epsilon}$ and its zero $\phi_{\epsilon}^{*}$ may depend on $\epsilon$ but $M$ is independent of $\epsilon$.

\newpage

Analogous to \Cref{proposition:A.1,proposition:A.2} (with $\phi^{*}$ replaced by $\phi_{\epsilon}^{*}$), we can prove
\begin{proposition}\label{proposition:A.3}
Assume that $f_{\epsilon}$ has a unique zero $\phi_{\epsilon}^{*}\in\R$ and satisfies $f_{\epsilon}'(\phi)\leq-M^2<0$ for $\phi\in\R$ and $\epsilon>0$, where $M$ is independent of $\epsilon$.
Let $\Phi_\epsilon$ be the solution to \eqref{eq.A.15}--\eqref{eq.A.17} for $\epsilon>0$.
\begin{enumerate}
\item[(a)] If $\Phi_{bd}>\phi_{\epsilon}^{*}$ for $\epsilon>0$, then $\Phi_\epsilon(0)>\phi_{\epsilon}^{*}$ and $\Phi_\epsilon$ is strictly increasing for $\epsilon>0$;
\item[(b)] if $\Phi_{bd}<\phi_{\epsilon}^{*}$ for $\epsilon>0$, then $\Phi_\epsilon(0)<\phi_{\epsilon}^{*}$ and $\Phi_\epsilon$ is strictly decreasing for $\epsilon>0$.
\end{enumerate}
\end{proposition}
\begin{proposition}\label{proposition:A.4}
Assume that $f_{\epsilon}$ has a unique zero $\phi_{\epsilon}^{*}\in\R$ and satisfies $f_{\epsilon}'(\phi)\leq-M^2<0$ for $\phi\in\R$ and $\epsilon>0$, where $M$ is independent of $\epsilon$.
Let $\Phi_\epsilon$ be the solution to \eqref{eq.A.15}--\eqref{eq.A.17} for $\epsilon>0$. Then
\begin{align}
\label{eq.A.18}
|\phi_{\epsilon}(r)-\phi_{\epsilon}^{*}|\leq2|\Phi_{bd}-\phi_{\epsilon}^{*}|\exp\left(-\frac{M(R-r)}{8\sqrt\epsilon}\right)\end{align}
for $r\in[0,R]$ and $0<\epsilon<(MR)^2/[8(d-1)^2]$.
\end{proposition}

\section{Properties of the solution to \texorpdfstring{\eqref{eq.1.07}}{(1.7)}--\texorpdfstring{\eqref{eq.1.09}}{(1.9)} and \texorpdfstring{\eqref{eq.1.19}}{(1.19)}--\texorpdfstring{\eqref{eq.1.21}}{(1.21)}}
\label{appendix:B}

In this appendix, we establish the existence, uniqueness, qualitative properties, and asymptotic behaviors of solutions to \eqref{eq.1.07}--\eqref{eq.1.09} and \eqref{eq.1.19}--\eqref{eq.1.21}.
For the sake of simplicity, equations \eqref{eq.1.07}--\eqref{eq.1.09} and \eqref{eq.1.19}--\eqref{eq.1.21} can be represented as follows.
\begin{align}
\label{eq.B.01}
&U''+f(U)=0\quad\text{in}~(0,\infty),\\
\label{eq.B.02}
&U(0)-\gamma\,U'(0)=\Phi_{bd},\\
\label{eq.B.03}
&\lim_{t\to\infty}U(t)=\phi^{*},
\end{align}
where $\gamma\geq0$ and $\Phi_{bd}\neq\phi^{*}$ are fixed constants. (When $\Phi_{bd}=\phi^{*}$, the solution $U\equiv\phi^{*}$ is trivial.)
Here the function $f\in\C^\infty(\R)$ satisfies assumptions (A1) and (A2).
It is clear that the existence and uniqueness of solution to equations \eqref{eq.1.07}--\eqref{eq.1.09} and \eqref{eq.1.19}--\eqref{eq.1.21} for $k=0,1,\dots,K$ follow from that of solution to equations \eqref{eq.B.01}--\eqref{eq.B.03}.
We may approach \eqref{eq.B.01}--\eqref{eq.B.03} by the following initial-value problem
\begin{align}
\label{eq.B.04}
&\tilde U''+f(\tilde U)=0\quad\text{in}~(0,\infty),\\
\label{eq.B.05}
&\tilde U(0)=U_0,\\
\label{eq.B.06}
&\tilde U'(0)=U_0',
\end{align}
where $U_0$ (between $\phi^{*}$ and $\Phi_{bd}$) and $U_0'$ are constants to be determined such that $\tilde U\equiv U$ on $[0,\infty)$.
The existence and uniqueness of \eqref{eq.B.04}--\eqref{eq.B.06} follow from the standard ODE theory.
From \eqref{eq.B.02} and \eqref{eq.B.05}--\eqref{eq.B.06}, $U_0$ and $U_0'$ must satisfy
\begin{align}
\label{eq.B.07}
U_0-\gamma U_0'=\Phi_{bd}.
\end{align}
Multiplying \eqref{eq.B.04} by $\tilde U'$ and then integrating it over $[0,t]$, we can use \eqref{eq.B.05}--\eqref{eq.B.06} to get
\begin{align}
\label{eq.B.08}
\tilde U'^2(t)+2F(\tilde U(t))=U_0'^2+2F(U_0)\quad\text{for}~t\geq0,
\end{align}
where $F(\phi)=\int_{\phi^{*}}^{\phi}\!f(s)\,\mathrm{d}s$ for $\phi\in\R$.
Note that $F'(\phi^{*})=f(\phi^{*})=0$ and $F''(\phi)=f'(\phi)<0$ for $\phi\in\R$ (by (A1)--(A2)) so
\begin{align}
\label{eq.B.09}
0=F(\phi^{*})>F(\phi)\quad\text{for}~\phi\neq\phi^{*}.
\end{align}
Suppose that $\dd\lim_{t\to\infty}\tilde U'(t)=0$.
Then we use \eqref{eq.B.03} and \eqref{eq.B.07}--\eqref{eq.B.08} to find that $U_0$ (between $\phi^{*}$ and $\Phi_{bd}$) must satisfy
\begin{align}
\label{eq.B.10}
&\Phi_{bd}-U_0=\sgn(\Phi_{bd}-\phi^{*})\gamma\sqrt{-2F(U_0)}.
\end{align}
To show that there exists a unique $U_0$, between $\phi^{*}$ and $\Phi_{bd}$, satisfying \eqref{eq.B.10}, we define a function $g:\R\to\R$ by
\[g(s)=\Phi_{bd}-s-\sgn(\Phi_{bd}-\phi^{*})\gamma\sqrt{-2F(s)}\quad\text{for}~s\in\R,\]
which is well-defined because of \eqref{eq.B.09}.
Since $g(\phi^{*})g(\Phi_{bd})<0$ and $g'(s)<0$ for $s$ between $\phi^{*}$ and $\Phi_{bd}$, function $g$ has a unique zero $U_0$ between $\phi^{*}$ and $\Phi_{bd}$, which means that equation \eqref{eq.B.10} has a unique solution.
Here one may use the facts that (i) if $\Phi_{bd}>\phi^{*}$, then $f(s)<0$ for $s\in(\phi^{*},\Phi_{bd}]$ and (ii) if $\Phi_{bd}<\phi^{*}$, then $f(s)>0$ for $s\in[\Phi_{bd},\phi^{*})$ due to (A1)--(A2).
Therefore, the initial-value problem \eqref{eq.B.04}--\eqref{eq.B.06} can be reformulated as
\begin{align}
\label{eq.B.11}
&\tilde U''+f(\tilde U)=0\quad\text{in}~(0,\infty),\\
\label{eq.B.12}
&\tilde U(0)=U_0,\\
\label{eq.B.13}
&\tilde U'(0)=\sgn(\phi^{*}-\Phi_{bd})\sqrt{-2F(U_0)},
\end{align}
where $U_0$ (between $\phi^{*}$ and $\Phi_{bd}$) is uniquely determined  by \eqref{eq.B.10}.

\begin{figure}[!htb]\centering\includegraphics[scale=0.7]{U.pdf}
\caption{We sketch the numerical profile for the solution $U$ to \eqref{eq.B.01}--\eqref{eq.B.03} for the case (a) $\Phi_{bd}=1$ and the case (b) $\Phi_{bd}=-1$, which is consistent with \Cref{proposition:B.1}.
Here $f(\phi)=\exp(\phi)-\exp(-\phi)$ and $\gamma=0.1$.}
\label{fig:U}\end{figure}

\newpage

To prove $\tilde U\equiv U$ on $[0,\infty)$, we need the following proposition.
\begin{proposition}
\label{proposition:B.1}
Let $\tilde U$ be the solution to \eqref{eq.B.11}--\eqref{eq.B.13}.
\begin{enumerate}
\item[(a)] If $\Phi_{bd}>\phi^{*}$, then $\Phi_{bd}\geq\tilde U(t)>\phi^{*}$ and $\tilde U'(t)<0$ for $t\geq0$;
\item[(b)] if $\Phi_{bd}<\phi^{*}$, then $\Phi_{bd}\leq\tilde U(t)<\phi^{*}$ and $\tilde U'(t)>0$ for $t\geq0$.
\end{enumerate}
\end{proposition}
\begin{proof}
We firstly claim that $\tilde U'(t)\neq0$ for $t\geq0$.
Suppose by contradiction that there exists $t_1\in(0,\infty)$ such that $\tilde U'(t_1)=0$.
Multiplying \eqref{eq.B.11} by $\tilde U$ and then integrating it over $[0,t]$, we obtain
\begin{align}
\label{eq.B.14}
\tilde U'^2(t)=\tilde U'^2(0)+2(F(\tilde U(0))-F(\tilde U(t)))=-2F(\tilde U(t))\quad\text{for}~t\geq0.
\end{align}
Here we have used \eqref{eq.B.12}--\eqref{eq.B.13}.
By \eqref{eq.B.14} and $\tilde U'(t_1)=0$, we get $\tilde U(t_1)=\phi^{*}$, which implies $\tilde U\equiv\phi^{*}$ on $[t_1,\infty)$.
Due to the unique continuation, $U\equiv\phi^{*}$ on $[0,\infty)$, which contradicts to \eqref{eq.B.12}.
Hence $\tilde U'(t)\neq0$ for $t\geq0$.
By \eqref{eq.B.09} and \eqref{eq.B.14}, it is clear that $\tilde U(t)\neq\phi^{*}$ for $t\geq0$ because $\tilde U'(t)\neq0$ for $t\geq0$.

Now we prove (a) and (b).
For the case of (a), we assume that $\Phi_{bd}>\phi^{*}$.
From \eqref{eq.B.10} and \eqref{eq.B.12}--\eqref{eq.B.13}, we have $\Phi_{bd}\geq\tilde U(0)>\phi^{*}$ and $\tilde U'(0)<0$.
Since $\tilde U(t)\neq\phi^{*}$ and $\tilde U'(t)\neq0$ for $t\geq0$, which implies $\Phi_{bd}\geq\tilde U(t)>\phi^{*}$ and $\tilde U'(t)<0$ for $t\geq0$.
Thus, the proof of (a) is complete.
The proof of (b) is similar to (a).
Therefore, we complete the proof of \Cref{proposition:B.1}.\end{proof}

Now we are in the position to show that $\tilde U$ solves equations \eqref{eq.B.01}--\eqref{eq.B.03} and the uniqueness of \eqref{eq.B.01}--\eqref{eq.B.03}, which implies $\tilde U\equiv U$ in $[0,\infty)$.
By \eqref{eq.B.10} and \eqref{eq.B.12}--\eqref{eq.B.13}, we have
\[\tilde U(0)-\gamma\tilde U'(0)=U_0\gamma\sgn(\phi^{*}-\Phi_{bd})\sqrt{-2F(U_0)}=\Phi_{bd},\]
which means $\tilde U$ satisfies \eqref{eq.B.02}.
By \Cref{proposition:B.1}, $\tilde U$ is bounded and strictly monotonic on $[0,\infty)$, which implies that there exists a constant $C$ such that\[\lim_{t\to\infty}\tilde U(t)=C.\]
Suppose by contradiction that $C\neq\phi^{*}$.
By \eqref{eq.B.09} and \eqref{eq.B.12}--\eqref{eq.B.14}, we get
\begin{align}
\label{eq.B.15}
\lim_{t\to\infty}\tilde U'^2(t)=\tilde U'^2(0)+2(F(U_0)-F(C))=-2F(C)>0.
\end{align}
Since $\tilde U'(t)\neq0$ for $t\geq0$, we can use \eqref{eq.B.15} to get $\dd\lim_{t\to\infty}|\tilde U(t)|=\infty$, which leads to a contradiction.
Thus, $\dd\lim_{t\to\infty}\tilde U(t)=\phi^{*}$, i.e., $\tilde U$ satisfies \eqref{eq.B.03}.
Hence $\tilde U$ solves equations \eqref{eq.B.01}--\eqref{eq.B.03}.
To prove $\tilde U\equiv U$ on $[0,\infty)$, it suffices to show the uniqueness of solution to \eqref{eq.B.01}--\eqref{eq.B.03}.
Suppose that there exist two solutions $U_1$ and $U_2$ to equations \eqref{eq.B.01}--\eqref{eq.B.03}.
Let $\overline{U}=U_1-U_2$.
Then $\overline{U}$ satisfies
\begin{align}
\label{eq.B.16}
&\overline{U}''+c(t)\overline{U}=0\quad\text{in}~(0,\infty),\\
\label{eq.B.17}
&\overline{U}(0)-\gamma\,\overline{U}'(0)=0,\\
\label{eq.B.18}
&\lim_{t\to\infty}\overline{U}(t)=0,
\end{align}
where
\[c(t)=\begin{cases}\dd\frac{f(U_1(t))-f(U_2(t))}{U_1(t)-U_2(t)}&\text{if}~U_1(t)\neq U_2(t);\\
f'(U_1(t))&\text{if}~U_1(t)=U_2(t).
\end{cases}\]
Note that $c(t)<0$ for $t\geq0$ by (A1).
Thus, by the standard maximum principle, $\overline{U}\equiv0$ on $[0,\infty)$, and we obtain the uniqueness of solution to \eqref{eq.B.01}--\eqref{eq.B.03}.
Therefore, $\tilde U\equiv U$ on $[0,\infty)$ and hence $U$ satisfies \Cref{proposition:B.1} and \eqref{eq.B.14}.

The following result will be used in \Cref{appendix:C} to prove the existence of solution to \eqref{eq.1.10}--\eqref{eq.1.12} and \eqref{eq.1.22}--\eqref{eq.1.24}.
\begin{proposition}\label{proposition:B.2}
Let $U$ be the solution to \eqref{eq.B.01}--\eqref{eq.B.03}. Then we have
\begin{itemize}
\item[(a)] $|U'(t)|\leq|U'(0)|\exp(-m_ft)$ for $t\geq0$, where $m_f=m_f([\min\{\phi^{*},\Phi_{bd}\},\max\{\phi^{*},\Phi_{bd}\}])$.
\item[(b)] $\int_0^\infty\!U'^2(t)\,\mathrm{d}t=\sgn(\phi^{*}-\Phi_{bd})\int_{U_0}^{\phi^{*}}\!\sqrt{-2F(s)}\,\mathrm{d}s<\infty$.
\item[(c)] $\int_0^t\!(U'(s))^{-2}\,\mathrm{d}s\geq t^2(\int_0^\infty\!U'^2(s)\,\mathrm{d}s)^{-1}$ for $t\geq0$.
\item[(d)] $\lim_{t\to\infty}[f(U(t))/U'(t)]=-\sqrt{-f'(\phi^{*})}$.
\item[(e)] $\int_0^\infty\!(U'(s_1))^{-2}\int_{s_1}^\infty\!U'^2(s_2)\,\mathrm{d}s_2\,\mathrm{d}s_1=\infty$.
\end{itemize}
\end{proposition}
\noindent The proof of \Cref{proposition:B.2} is easy by \Cref{proposition:B.1} and calculus so we omit it here.

\section{Properties of the solution to \texorpdfstring{\eqref{eq.1.10}}{(1.10)}--\texorpdfstring{\eqref{eq.1.12}}{(1.12)} and \texorpdfstring{\eqref{eq.1.22}}{(1.22)}--\texorpdfstring{\eqref{eq.1.24}}{(1.24)}}
\label{appendix:C}

In this appendix, we establish the existence, uniqueness, and qualitative properties for solutions to \eqref{eq.1.10}--\eqref{eq.1.12} and \eqref{eq.1.22}--\eqref{eq.1.24}.
For the sake of simplicity, equations \eqref{eq.1.10}--\eqref{eq.1.12} and \eqref{eq.1.22}--\eqref{eq.1.24} can be represented as follows.
\begin{align}
\label{eq.C.01}
&V''+f'(U)V=U'\quad\text{in}~(0,\infty),\\
\label{eq.C.02}
&V(0)-\gamma\,V'(0)=0,\\
\label{eq.C.03}
&\lim_{t\to\infty}V(t)=0,
\end{align}
where $U$ is the solution to equations \eqref{eq.B.01}--\eqref{eq.B.03}, $f\in\C^\infty(\R)$ and $\gamma\geq0$ are as given in \eqref{eq.B.01}--\eqref{eq.B.02}.
By standard ODE theory, the solution $V$ to equations \eqref{eq.C.01}--\eqref{eq.C.03} can be represented as
\begin{align}
\label{eq.C.04}
V(t)=\frac{V_0}{U'(0)}U'(t)-U'(t)\int_0^t\frac{1}{U'^2(s_1)}\int_{s_1}^{\infty}\!U'^2(s_2)\,\mathrm{d}s_2\,\mathrm{d}s_1\quad\text{for}~t\geq0,
\end{align}
where $V_0$ is given by
\begin{align}
\label{eq.C.05}
V_0=-\frac{\gamma}{U'(0)+\gamma f(U_0)}\int_0^\infty\!U'^2(t)\,\mathrm{d}t.
\end{align}
Note that $V_0$ is well-defined due to \Cref{proposition:B.2}(b) and $U'(0)+\gamma f(U_0)\neq0$.
Clearly, \eqref{eq.C.04} with \eqref{eq.C.05} satisfies \eqref{eq.C.01}--\eqref{eq.C.02}.
It suffices to verify that \eqref{eq.C.04} satisfies \eqref{eq.C.03}.
By \eqref{eq.B.01}, \eqref{eq.B.03}, (A1)--(A2), \Cref{proposition:B.2} and L'H\^opital's rule, we obtain $\lim\limits_{t\to\infty}V(t)=\lim\limits_{t\to\infty}(U'(t)/f'(U(t)))=0$.
Thus, \eqref{eq.C.04} defines a solution to \eqref{eq.C.01}--\eqref{eq.C.03}.

Now we prove the uniqueness of the solution to \eqref{eq.C.01}--\eqref{eq.C.03}.
Suppose that there exist two solutions $V$ and $\tilde V$ to \eqref{eq.C.01}--\eqref{eq.C.03}.
Let $\overline V=V-\tilde V$.
Then $\overline V$ satisfies
\begin{align}
\label{eq.C.06}
&\overline V''+f'(U)\overline V=0\quad\text{in}~(0,\infty),\\
\label{eq.C.07}
&\overline V(0)-\gamma\overline V'(0)=0,\\
\label{eq.C.08}
&\lim_{t\to\infty}\overline V(t)=0.
\end{align}
Hence by (A1) and the standard maximum principle, $\overline V\equiv0$ on $[0,\infty)$, and the solution to \eqref{eq.C.01}--\eqref{eq.C.03} must be given by \eqref{eq.C.04}.

\begin{proposition}
\label{proposition:C.1}
Let $V$ be the unique solution to \eqref{eq.C.01}--\eqref{eq.C.03}.
\begin{itemize}
\item[(a)] If $\Phi_{bd}>\phi^{*}$, then $V$ is nonnegative on $[0,\infty)$, and there exists a unique $t^{*}\in(0,\infty)$ such that $V$ is strictly increasing on $[0,t^{*})$ and strictly decreasing on $(t^{*},\infty)$. Moreover, if $\gamma>0$, then $V$ is positive on $[0,\infty)$.
\item[(b)] If $\Phi_{bd}<\phi^{*}$, then $V$ is nonpositive on $[0,\infty)$, and there exists a unique $t^{*}\in(0,\infty)$ such that $V$ is strictly decreasing on $[0,t^{*})$ and strictly increasing on $(t^{*},\infty)$. Moreover, if $\gamma>0$, then $V$ is negative on $[0,\infty)$.
\end{itemize}
\end{proposition}
\begin{proof}
We first note that
\begin{claim}
\label{claim:6}
$\dd\lim_{t\to\infty}V'(t)=0$.
\end{claim}
\begin{proof}[Proof of \Cref{claim:6}]
By \eqref{eq.B.01} and \eqref{eq.C.04}, we have
\[V'(t)=-\frac{V_0}{U'(0)}f(U(t))+f(U(t))\int_0^t\!\frac1{U'^2(s_1)}\int_{s_1}^{\infty}\!U'^2(s_2)\,\mathrm ds_2\,\mathrm ds_1-\frac1{U'(t)}\int_t^\infty\!U'^2(s)\,\mathrm ds.\]
By (A2), \eqref{eq.B.01} and \Cref{proposition:B.2}(d), we apply the L'H\^opital's rule to obtain
\begin{align*}
\lim_{t\to\infty}V'(t)&=\lim_{t\to\infty}\left[\frac{\dd\int_0^t\!\frac1{U'^2(s_1)}\int_{s_1}^{\infty}\!U'^2(s_2)\,\mathrm ds_2\,\mathrm ds_1}{[f(U(t)]^{-1}}-\frac{\dd\int_t^\infty\!U'^2(s)\,\mathrm ds}{U'(t)}\right]=\lim_{t\to\infty}\left[\frac{\dd\frac1{U'^2(t)}\int_t^\infty\!U'^2(s)\,\mathrm ds}{[f(U(t))]^{-2}f'(U(t))U'(t)}+\frac{U'^2(t)}{U''(t)}\right]\\
&=\frac1{f'(\phi^*)}\lim_{t\to\infty}\frac{\dd[f(U(t))]^2\int_t^\infty\!U'^2(s)\,\mathrm ds}{U'^3(t)}-\lim_{t\to\infty}\frac{U'^2(t)}{f(U(t))}=-\lim_{t\to\infty}\frac{\dd\int_t^\infty\!U'^2(s)\,\mathrm ds}{U'(t)}=\lim_{t\to\infty}\frac{U'^2(t)}{U''(t)}\\
&=-\lim_{t\to\infty}\frac{U'^2(t)}{f(U(t))}=0,
\end{align*}which completes the proof of \Cref{claim:6}.
\end{proof}
We now assume $\Phi_{bd}>\phi^*$ and prove (a).
By \Cref{proposition:B.1}(a), we have $U'(0)<0$ and $f(U_0)<0$. Along with \eqref{eq.C.05}, we get $V(0)=V_0>0$, and $V'(0)=-(U'(0)+\gamma f(U_0))^{-1}\int_0^\infty\!U'^2(t)\,\mathrm dt>0$.
Suppose by contradiction that there exists $t_0\in(0,\infty)$ such that $V(t_0)\leq0$.
Since $\dd\lim_{t\to\infty}V(t)=0$, we may assume that $V$ attains its minimum value at $t_0\in(0,\infty)$, which implies $V''(t_0)\geq0$.
Then by \eqref{eq.C.01}, we have $U'(t_0)=V''(t_0)+f'(U(t_0))V(t_0)\geq0$, which contradicts Proposition~\ref{proposition:B.1}(a).
This shows that $V$ is positive on $[0,\infty)$.
Since $V'(0)>0$ and $\dd\lim_{t\to\infty}V(t)=0$, there exists $t^*\in(0,\infty)$ such that $V$ attains its maximum value at $t^*$ and $V'(t^*)=0$.
Suppose by contradiction that there exists another maximum point $t_1$ such that $V'(t_1)=0$.
Without loss of generality, we may assume that $t_1<t^*$, and there exists $t_2\in(t_1,t^*)$ such that $V$ attains its local minimum value at $t_2$ with $V'(t_2)=0$ and $V'(t)\geq0$ on $(t_2,t^*)$.
Integrating \eqref{eq.C.01} over $[t,\infty)$ and using (a), we obtain
\begin{align}
\label{eq.C.09}
V'(t)=\frac{f(U(t))V(t)+\int_t^\infty\!U'^2(s)\,\mathrm ds}{-U'(t)}\quad\text{for}~t\geq0.
\end{align}
Clearly, $V'(t_2)=V'(t^*)=0$.
Let $G(t)=f(U(t))V(t)+\int_t^\infty\!U'^2(s)\,\mathrm ds$ for $t\in\R$. Then $G(t_2)=G(t^*)=0$.
Differentiating $G$ gives
\[G'(t)=f'(U(t))U'(t)V(t)+f(U(t))V'(t)-U'^2(t)\quad\text{for}~t\in\R.\]
By Proposition~\ref{proposition:B.1}(a) and (A1)--(A2), we find that $U'(t)<0$, $f(U(t))<0$ and $f'(U(t))<0$.
Since $V(t)>0$ and $V'(t)>0$ on $(t_2,t^*)$, we get $G'(t)<0$ on $(t_2,t^*)$, which contradcits with $g(t_2)=g(t^*)=0$.
Therefore, there exists a unique $t^*\in(0,\infty)$ such that $V$ attains its maximum value.
The proof of (a) is complete.

Next we assume $\Phi_{bd}<\phi^*$ and prove (b).
By \Cref{proposition:B.1}(b), we have $U'(0)>0$ and $f(U_0)>0$. Along with \eqref{eq.C.05}, we get $V(0)=V_0<0$, and $V'(0)=-(U'(0)+\gamma f(U_0))^{-1}\int_0^\infty\!U'^2(t)\,\mathrm dt<0$.
Suppose by contradiction that there exists $t_0\in(0,\infty)$ such that $V(t_0)\geq0$.
Since $\dd\lim_{t\to\infty}V(t)=0$, we may assume that $V$ attains its maximum value at $t_0\in(0,\infty)$, which implies $V''(t_0)\leq0$.
Then by \eqref{eq.C.01}, we have $U'(t_0)=V''(t_0)+f'(U(t_0))V(t_0)\leq0$, which contradicts to \Cref{proposition:B.1}(b).
This shows that $V$ is negative on $[0,\infty)$.
Since $V'(0)<0$ and $\dd\lim_{t\to\infty}V(t)=0$, there exists $t^*\in(0,\infty)$ such that $V$ attains its minimum value at $t^*$ and $V'(t^*)=0$.
Suppose by contradiction that there exists another minimum point $t_1$ such that $V'(t_1)=0$.
Then by a similar fashion of (b), we can use \eqref{eq.C.09} to get a contradiction because $U'(t)>0$, $f(U(t))>0$ and $f'(U(t))<0$ (cf. \Cref{proposition:B.1}(b) and (A1)--(A2)).
Hence there exists a unique $t^*\in(0,\infty)$ such that $V$ attains its minimum value, which implis (b).
Therefore, we complete the proof of \Cref{proposition:C.1}.
\end{proof}
%The proof of \Cref{proposition:C.1} can be easily obtained by calculus and \Cref{proposition:B.1} so we omit it here.

