\caption{We sketch the numerical profile for the solution $V$ to \eqref{eq.C.01}--\eqref{eq.C.03} for the case (a) $\Phi_{bd}=1$ and the case (b) $\Phi_{bd}=-1$, which is consistent with \Cref{proposition:C.1}.
Here $f(\phi)=\exp(\phi)-\exp(-\phi)$ and $\gamma=0.1$.}
