\begin{proposition}\label{prop:C.2}
Let $U$ and $V$ be the unique solutions to \eqref{eq.B.01}--\eqref{eq.B.03} and \eqref{eq.C.01}--\eqref{eq.C.03}, respectively.\\
If $\Phi_{bd}\neq\phi^{*}$, then function $g:=f(U)V+U'V'$ is negative on $[0,\infty)$.
\end{proposition}
\begin{proof}
By \eqref{eq.B.01}, \eqref{eq.C.01} and \Cref{proposition:B.1}, we have
\[g'(t)=f'(U(t))U'(t)V(t)+f(U(t))V'(t)+U''(t)V'(t)+U'(t)V''(t)=U'^2(t)>0\]for $t\geq0$ and $\Phi_{bd}\neq\phi^{*}$, which implies $g$ is strictly increasing on $[0,\infty)$. By (A2), \eqref{eq.B.03}, \eqref{eq.C.03} and \Cref{claim:6}, it is clear that $\dd\lim_{t\to\infty}g(t)=0$. Hence $g(t)<0$ for $t\geq0$, and the proof of \Cref{prop:C.2} is complete.
\end{proof}

\section{Properties of the solution to \texorpdfstring{\eqref{eq.1.25}}{(1.25)}--\texorpdfstring{\eqref{eq.1.27}}{(1.27)}}
\label{appendix:D}

In this appendix, we establish the existence, uniqueness, and qualitative properties for solutions to \eqref{eq.1.25}--\eqref{eq.1.27}.
\begin{align}
\label{eq.D.01}
&w_{k}''+f_{0}'(u_{k})w_{k}=-f_1(u_{k})\quad\text{in}~(0,\infty),\\
\label{eq.D.02}
&w_{k}(0)-\gamma_kw_{k}'(0)=0,\\
\label{eq.D.03}
&\lim_{t\to\infty}w_{k}(t)=Q,
\end{align}
where $u_{k}$ are the solutions to equations \eqref{eq.1.19}--\eqref{eq.1.21}, and $\gamma_k\geq0$ are given fixed constants for $k=0,1,\dots,K$.
Here $f_{0}$ and $f_1$ are smooth functions defined by
\begin{align}
\label{eq.D.04}
f_{0}(\phi)=\frac{1}{|\Omega|}\sum_{i=1}^{I}m_{i}z_{i}\exp(-z_{i}(\phi-\phi_{0}^{*}))\quad\text{and}\quad f_1(\phi)=-Qf_{0}'(\phi)+\hat f_1(\phi)\quad\text{for}~\phi\in\R,
\end{align}
where $Q\in\R$ (defined in \eqref{eq.1.30}), $m_{i}>0$ and
\begin{align}
\label{eq.D.05}
&\hat f_1(\phi)=\frac{1}{|\Omega|}\sum_{i=1}^{I}\hat{m}_iz_{i}\exp(-z_{i}(\phi-\phi_{0}^{*}))\quad\text{for}~\phi\in\R,\\
\label{eq.D.06}
&\hat m_{i}=\frac{m_{i}}{|\Omega|}\sum_{k=0}^K|\partial\Omega_k|\int_0^\infty\![1-\exp(-z_{i}(u_{k}(s)-\phi_{0}^{*}))]\,\mathrm{d}s\quad\text{for}~i=1,\dots,I,
\end{align}
In addition, $\phi_{0}^{*}$ and $u_{k}(0)$ satisfy (cf. \eqref{eq.3.026}--\eqref{eq.3.027})
\begin{align}
\label{eq.D.07}
&\phi_{bd,k}-u_{k}(0)=\sgn(\phi_{bd,k}-\phi_{0}^{*})\gamma_k\sqrt{\frac{2}{|\Omega|}\sum_{i=1}^{I}m_{i}[\exp(-z_{i}(u_{k}(0)-\phi_{0}^{*}))-1]}\quad\text{for}~k=0,1,\dots,K,\\
\label{eq.D.08}
&\sum_{k=0}^K|\partial\Omega_k|u'(0)=\sum_{k=0}^K|\partial\Omega_k|\frac{u_{k}(0)-\phi_{bd,k}}{\gamma_k}=0.
\end{align}
By standard ODE theory, the solution $w_{k}$ to equations \eqref{eq.D.01}--\eqref{eq.D.03} can be represented as
\begin{align}
\label{eq.D.09}
w_{k}(t)=\frac{w_{k}(0)}{u_{k}'(0)}u_{k}'(t)+u_{k}'(t)\int_0^t\!\frac{Qf_{0}(u_{k}(s))-\hat F_1(u_{k}(s))}{u_{k}'^2(s)}\,\mathrm{d}s\quad\text{for}~t\geq0,
\end{align}
where $w_{k}(0)$ and $\hat F_1$ are given by
\begin{align}
\label{eq.D.10}
&w_{k}(0)=\frac{\gamma_k(Qf_{0}(u_{k}(0))-\hat F_1(u_{k}(0)))}{u_{k}'(0)+\gamma_kf_{0}(u_{k}(0))},\\
\label{eq.D.11}
&\hat F_1(\phi)=\int_{\phi_{0}^{*}}^\phi\!\hat f_1(s)\,\mathrm{d}s=\frac{1}{|\Omega|}\sum_{i=1}^{I}\hat m_{i}[1-\exp(-z_{i}(\phi-\phi_{0}^{*}))]\quad\text{for}~\phi\in\R.
\end{align}
Note that \eqref{eq.D.10} is well-defined because $u_{k}'(0)+\gamma_kf_{0}(u_{k}(0))\neq0$.
Clearly, \eqref{eq.D.09} with \eqref{eq.D.10}--\eqref{eq.D.11} satisfies \eqref{eq.D.01}--\eqref{eq.D.02}.
To verify that \eqref{eq.D.09} satisfies \eqref{eq.D.03}, we need the following claim.
\begin{claim}
\label{claim:7}
Let $u_{k}$ be the solution to \eqref{eq.1.19}--\eqref{eq.1.21}, $\hat{f}_{1}$ and $\hat{F}_{1}$ defined in \eqref{eq.D.05} and \eqref{eq.D.11}, respectively, and $\phi_{0}^{*}$ be the unique zero of $f_{0}$.
Then we have
\begin{enumerate}
\item[(a)] $\hat{f}_{1}(\phi_{0}^{*})=\dfrac1{|\Omega|}\sum\limits_{i=1}^{I}\hat{m}_{i}z_{i}=0$;
\item[(b)] $\displaystyle\left|\int_{0}^{\infty}\!\frac{Qf_{0}(u_{k}(s))-\hat{F}_{1}(u_{k}(s))}{u_{k}'^2(s)}\,\mathrm{d}s\right|=\infty$ if $Q\neq0$.
\end{enumerate}
\end{claim}
\begin{proof}[Proof of \Cref{claim:7}]
By \eqref{eq.D.04} and $\sum_{i=1}^{I}m_{i}z_{i}=0$ (cf. \eqref{eq.1.03}), we have
\begin{align*}
\hat f_1(\phi_{0}^{*})&=\frac{1}{|\Omega|}\sum_{i=1}^{I}\hat m_{i}z_{i}=\frac{1}{|\Omega|}\sum_{i=1}^{I}m_{i}z_{i}\sum_{k=0}^K|\partial\Omega_k|\int_0^\infty\![1-\exp(-z_{i}(u_{k}(s)-\phi_{0}^{*}))]\,\mathrm{d}s\\
&=\frac{1}{|\Omega|}\sum_{k=0}^K|\partial\Omega_k|\int_0^\infty\!\left(\sum_{i=1}^{I}m_{i}z_{i}-\sum_{i=1}^{I}m_{i}z_{i}\exp(-z_{i}(u_{k}(s)-\phi_{0}^{*}))\right)\,\mathrm{d}s\\&=-\frac{1}{|\Omega|}\sum_{k=0}^K|\partial\Omega_k|\int_0^\infty\!f_{0}(u_{k}(s))\,\mathrm{d}s.
\end{align*}
Along with \eqref{eq.1.19}--\eqref{eq.1.20}, \eqref{eq.D.08} and \Cref{proposition:B.2}(a), we get
\[\hat f_1(\phi_{0}^{*})=\frac{1}{|\Omega|}\sum_{k=0}^K|\partial\Omega_k|\int_0^\infty\!u_{k}''(s)\,\mathrm{d}s=\frac{1}{|\Omega|}\sum_{k=0}^K|\partial\Omega_k|(-u_{k}'(0))=\frac{1}{|\Omega|}\sum_{k=0}^K|\partial\Omega_k|\frac{\phi_{bd,k}-u_{k}(0)}{\gamma_k}=0.\]
which shows (a).
To prove (b), we use \eqref{eq.1.19} and L'H\^opital's rule to get
\begin{align*}
\lim_{t\to\infty}\frac{Qf_{0}(u_{k}(t))-\hat F_1(u_{k}(t))}{u_{k}'^2(t)}&=\lim_{t\to\infty}\frac{Qf_{0}'(u_{k}(t))u_{k}'(t)-\hat f_1(u_{k}(t))u_{k}'(t)}{2u_{k}'(t)u_{k}''(t)}\\&=\lim_{t\to\infty}\frac{-Qf_{0}'(u_{k}(t))+\hat f_1(u_{k}(t))}{2f_{0}(u_{k}(t))}.
\end{align*}
By \eqref{eq.1.21}--\eqref{eq.1.28}, \eqref{eq.3.017}, \Cref{proposition:B.1}, we have $f_{0}(u_{k}(t))\neq0$ for $t\geq0$ and $\dd\lim_{t\to\infty}f_{0}(u_{k}(t))=0$.
By \eqref{eq.1.21}, \eqref{eq.3.017}, (a) and the condition $Q\neq0$, we get \[\lim_{t\to\infty}(-Qf_{0}'(u_{k}(t))+\hat f_1(u_{k}(t)))=-Qf_{0}'(\phi_{0}^{*})\neq0.\]
Hence $\left|\int_0^\infty\!(u_{k}'(s))^{-2}[Qf_{0}(u_{k}(s))-\hat F_1(u_{k}(s))]\,\mathrm{d}s\right|=\infty$, which gives (b) and completes the proof of \Cref{claim:7}.
\end{proof}

Now we show that \eqref{eq.D.09} satisfies \eqref{eq.D.03} and obtain the existence of \eqref{eq.D.01}--\eqref{eq.D.03}. For the case that $Q\neq0$, we can use \eqref{eq.B.01}, \Cref{claim:7} and L'H\^opital's rule to get
\begin{align}
\label{eq.D.12}
\begin{aligned}
\lim_{t\to\infty}w_{k}(t)&=\lim_{t\to\infty}\frac{\dd\frac{w_{k}(0)}{u_{k}'(0)}+\int_{0}^{t}\!\frac{Qf_{0}(u_{k}(s))-\hat F_1(u_{k}(s))}{u_{k}'^2(s)}\,\mathrm{d}s}{\dd\frac{1}{u_{k}'(t)}}\\&=\lim_{t\to\infty}\frac{\dd\frac{Qf_{0}(u_{k}(t))-\hat F_1(u_{k}(t))}{u_{k}'^2(t)}}{\dd-\frac{u_{k}''(t)}{u_{k}'^2(t)}}\\
&=\lim_{t\to\infty}\frac{Qf_{0}(u_{k}(t))-\hat F_1(u_{k}(t))}{f_{0}(u_{k}(t))}=Q+\lim_{t\to\infty}\frac{-\hat f_1(u_{k}(t))u_{k}'(t)}{f_{0}'(u_{k}(t))u_{k}'(t)}\\&=Q-\lim_{t\to\infty}\frac{\hat f_1(u_{k}(t))}{f_{0}'(u_{k}(t))}=Q-\frac{\hat f_1(\phi_{0}^{*})}{f_{0}'(\phi_{0}^{*})}=Q,
\end{aligned}
\end{align}
which gives \eqref{eq.D.03} for $Q\neq0$.
This shows the existence of a solution \eqref{eq.D.01}--\eqref{eq.D.03} for $Q\neq0$.
For the case of $Q=0$, we define $w_{k}^0$ and $w_{k}^\pm$ by \eqref{eq.D.09} for $Q=0$ and $Q=\pm1$, respectively.
Then due to the linearity of \eqref{eq.D.09} (with respect to $Q$), $w_{k}^0=(w_{k}^++w_{k}^-)/2$.
By \eqref{eq.D.12} with $Q=\pm1$, we find that $\lim\limits_{t\to\infty}w_{k}^0(t)=\lim\limits_{t\to\infty}(w_{k}^+(t)+w_{k}^-(t))/2=(1+(-1))/2=0$, which implies that $w_{k}^0$ satisfies \eqref{eq.D.03} for $Q=0$.
Therefore, we get the existence of the solution to \eqref{eq.D.01}--\eqref{eq.D.03} for $Q\in\R$.

It remains to prove the uniqueness of the solution to \eqref{eq.D.01}--\eqref{eq.D.03}.
Suppose that there exist two solutions $w_{k}$ and $\tilde w_{k}$ of \eqref{eq.D.01}--\eqref{eq.D.03}.
Let $\overline w_{k}=w_{k}-\tilde w_{k}$.
Then $\overline w_{k}$ satisfies
\begin{align*}
&\overline w_{k}''+f_{0}'(u_{k})\overline w_{k}=0\quad\text{in}~(0,\infty),\\
&\overline w_{k}(0)-\gamma_k\overline w_{k}'(0)=0,\\
&\lim_{t\to\infty}\overline w_{k}(t)=0.
\end{align*}
By the standard maximum principle, it is easy to obtain $\overline w_{k}\equiv0$ on $[0,\infty)$, which gives the uniqueness of solution to \eqref{eq.D.01}--\eqref{eq.D.03}.

