For any $u \in W _{\(0,q\)}^{k} \(\Om\)$, the $L^2$-Sobolev norm is defined by $$\lnm u \rnm _{k} ^{2} = \sideset{}{'}{\sum}_{J}\sum_{\alpha = 0}^N \sum _{|i| = 0} ^{k} \chi_{\alpha} \int _{U _{\alpha}} |\nabla^i u _{J} |^2 dV,$$
where $\nabla^i =\frac{\partial^{|i|}}{\partial x_1^{i_1} \cdots \partial x_{2n}^{i_{2n}}}$ denotes the real differential operator with $i=(i_1, \cdots, i_{2n})$.  
Note that the $L^2$-Sobolev norm defined above is equivalent to the $L^2$-Sobolev norm defined with respect to the Euclidean coordinates. 

%We say that $\bar{\partial}$-Neumann operator is exact regularity when it maps the $\mathcal{L} ^{2}$-Sobolev space $W _{\(0, q\)} ^{k} \(\Om\)$ of forms with coefficients in $W _{\(0, q\)}^{k} \(\Om\)$ to themselves. 


If the $(0, q)$-form $u$ is supported in $U_{\alpha}$ for $0 \leq \alpha \leq N$, we have
\begin{align*}
  \bar{\partial}u = \sideset{}{'}\sum_{J} \sum_{j\notin J} \bar{L} _{j} u _{J} \bar{w} _{j} \wedge \bar{w} _{J} + 0\text{-th order of } u
%  + \sideset{}{'}\sum_{J} \sum_{j} u _{J} \bar{L} _{j} \bar{w} _{J}
\end{align*}
and the domain of $\bar{\partial}$ is
\begin{align*}
  \dom \(\bar{\partial}\) := \lbk u \in L _{\(0, q\)} ^{2} \(\Om\): \bar{\partial} u \in L _{\(0, q + 1\)} ^{2} \(\Om\)\rbk.
\end{align*}
Let $\vartheta$ be the formal adjoint of $\bar{\partial}$. If the $(0, q)$-form $u$ is supported in $U_{\alpha}$ for $0 \leq \alpha \leq N$, then 
\begin{align*}
  \vartheta u = - \sideset{}{'}\sum _{|K| = q-1}\(\sum _{j = 1} ^{n} L _{j} u _{jK}\) \bar{\omega} _{K} + 0\text{-th order of } u.
\end{align*}
The Hilbert space adjoint of $\bar{\partial}$ is denoted by $\bar{\partial} ^{*}$, and its domain is defined by
\begin{align*}
  \dom \(\bar{\partial} ^{*}\) := \lbk v \in L _{\(0, q + 1\)} ^{2} \(\Om\) :  \left| \(\bar{\partial} u, v\) \right| \lesssim  \lnm u \rnm {\rm ~for~ all~} u \in \dom \(\bar{\partial} \)\rbk.
\end{align*}
It follows that $u \in \dom \(\bar{\partial} ^{*}\)$ is equivalent to $u _{J} = 0$ on $\partial \Om$ when $n \in J$. For $1 \leq q \leq n$, the Kohn Laplacian $\square _{q}$ is defined by $\square _{q} = \bar{\partial} \bar{\partial} ^{*} + \bar{\partial} ^{*} \bar{\partial} : L _{\(0, q\)} ^{2} \(\Om\) \to L _{\(0, q\)} ^{2} \(\Om\)$. The domain of $\square _{q}$ is
\begin{align*}
  \dom\(\square _{q}\) = \lbk u \in \dom \(\bar{\partial}\) \cap \dom \(\bar{\partial} ^{*}\) \cap L _{\(0, q\)} ^{2} \(\Om\):  \bar{\partial} u \in\dom \(\bar{\partial} ^{*}\), \bar{\partial} ^{*} u \in \dom \(\bar{\partial}\)\rbk.
\end{align*}
It is the standard fact in the $\bar\partial$-Neumann theory that $\square _{q}$ is self-adjoint and surjective, and it has a self-adjoint bounded inverse, called the $\bar{\partial}$-Neumann operator $N _{q}$. In this paper, we will work with the special boundary charts. 



\subsection{Unified $L^2$ estimates}

We first recall the following unified estimates obtained by Yue Zhang (see Corollary 3.3  in \cite{YZ2021}). 

\begin{thm}\label{basic estimate thm}
  Let $\Om$ be a smooth bounded domain in $\bbC ^{n}$ with a defining function $\rho$  and $U$ be a small open neighborhood of some boundary point. Suppose $g, \phi \in C ^{2}\(\cl{\Om}\)$ and $ g > 0$. 
  For $\gamma >0$ and $0 < \eta < \frac{1}{2}$, and for every ordered index set $I _s = \{j _k: 1 \leq k \leq s\} \subset \{1,2, \cdots, n-1\}$ and $J_s = \{1,2, \cdots, n\} \setminus I_s$ with $1\leq s\leq n-1$, there is a constant $C _{\eta, \gamma} > 0$ independent of $u$, $\phi$ and $g$, such that:

  \begin{align}\label{basic inequality}
    &\lnm \sqrt{g} \bar{\partial} u \rnm _{\phi}^2 + \(1 + \frac{1}{\gamma}\) \lnm \sqrt{g} \bar{\partial} _{\phi} ^{*} u \rnm _{\phi} ^{2} + C _{\eta, \gamma} \lnm \sqrt{g} u \rnm _{\phi} ^{2}\\\nonumber
    \geq & - \(\gamma + \frac{1}{\eta}\) \sideset{}{'}{\sum }_{\lmdl J \rmdl = q} \sum _{j \leq n} \lnm \frac{1}{\sqrt{g}} \(L _{j} g\) u_J \rnm _{\phi} ^2\\\nonumber
    &+ \eta \sideset{}{'}{\sum}_{\lmdl J \rmdl = q} \( \sum_{j \in J_s} \lnm \sqrt{g} \cl{L}_j u _J \rnm _{\phi}^2 + \sum_{j \in I_s} \lnm \sqrt{g} \delta_{w_j} u_J \rnm _\phi^2\)\\\nonumber
    & + \sideset{}{'}{\sum} _{\lmdl J \rmdl = q} \sum_{j \in I_s} \(\(\(g _{jj} - g \phi _{jj}\) u_J, u_J \)_\phi - \int_{\partial \Om} g \rho_{jj} u_J \cl{u} _J e^{-\phi} \,dS\)\\\nonumber
    & + \sideset{}{'}{\sum}_{\lmdl K \rmdl = q - 1}\sum_{i,j = 1} ^{n} \(\(\(-g_{ij} + g \phi_{ij}\) u _{iK}, u _{jK} \) _\phi + \int _{\partial \Om} g \rho_{ij} u_{iK} \cl{u }_{jK} e^{-\phi} \,dS\)\nonumber
  \end{align}
  holds  for all 
$  u = \sideset{}{'}{\sum} _J u _J \bar{w}_J \in C _{\(0, q\)}^ \infty \(\cl{\Om} \) \cap \dom\(\bar{\partial}^*\)$
  with support in $\cl{\Om} \cap U$.
\end{thm}

For the boundary term, we can use Lemma 3.5 in \cite{YZ2021}.

\begin{lem}\label{boundary term}
  Let $\Om$ be a bounded pseudoconvex domain in $\bbC ^n$ with $ n > 2$ and $\rho$ be the smooth defining function and let $U$ be a small open neighborhood of some boundary point. For a fixed $s$ with $1 \leq s \leq n-2$, there exist $ q _0 $ with $s+1 \leq q _0 \leq n-1$ and an ordered index set $I _s = \{j_k: 1 \leq k \leq s \} \subset \{1,2,\cdots, n-1 \}$ such that the following inequality holds for any $u \in C _{\(0, q\)} ^\infty \(\cl{\Om}\) \cap \dom \(\bar{\partial}^*\)$ supported in $\cl{\Om} \cap U$ with $n-1\geq q \geq q_0$ :
  \begin{align}\label{boundary estimate}
    \sideset{}{'}{\sum} _{\lmdl K \rmdl = q - 1} \sum_{i,j = 1}^{n} \int_{\partial \Om} g \rho_{ij} u _{iK} \cl{u_{jK}} e ^{- \phi} \, dS - \sideset{}{'}{\sum}_{\lmdl J \rmdl = q} \sum_{j \in I_s} \int _{\partial \Om} g \rho_{jj} \lmdl u_J \rmdl ^2  e ^{-\phi} \,dS \geq 0.
  \end{align}
  In particular, if $s = n - 2$, then $q_0 = n-1$ and $I_s = \{1,2,\cdots, n-1 \} \setminus \{ t \}$, for any $1 \leq t \leq n-1$.
\end{lem}

\begin{proof}
Since  $u_N = 0$ on $\partial\Om$, then 
 $$  \sideset{}{'}{\sum} _{\lmdl K \rmdl = q - 1} \sum_{i,j = 1}^{n}  \rho_{ij} u _{iK} \cl{u_{jK}} \geq M \sideset{}{'}{\sum}_{\lmdl J \rmdl =q} \lmdl u_J \rmdl ^2 $$ holds on $\partial\Om$  if and only if the sum of the smallest $q$ eigenvalues of the Hessian matrix $ \left( \rho_{ij}\right)$  restricted to $T^{(1, 0)}\partial \Om_\delta$ is at least $M$ (cf. Lemma 4.7 in \cite{S10}). Because $\partial\bar\partial \rho$ is non-negative restricted to $T^{(1, 0)}\partial \Om_\delta$, for any $s$ with $1 \leq s \leq n-2$, $q_0 = n-1$ will enable (\ref{boundary estimate}) to hold.  
%(\ref{boundary estimate}) holds for every $u \in  C _{\(0, q+1\)}^ \infty \(\cl{\Om_\delta} \) \cap \dom\(\bar{\partial}^*\)$ by the same reason. Therefore,  $\Om$ possesses a family of transverse vector fields satisfying Property ($\widetilde{P} _{q+1} ^{\#}$)
\end{proof}

