\subsection{Standard Sobolev estimates}

\begin{lem}
  For any $k \geq 2$, there exists a constant $C > 0$ independent of $\delta$ (for $0<\delta <<1$), such that 
  \begin{align*}
    \lnm (u_\delta)_N \rnm_k \leq C \(\lnm \square u_\delta \rnm_{k-2} + \lnm u_\delta \rnm_{k-1}\)
  \end{align*}
  for all $u_\delta \in \dom(\bar{\partial}^*) \cap W_{(0,q)}^k \(\Om _{\delta}\)$, 
  where $(u_\delta)_{N}$ is the normal component of $u_\delta$. 
\end{lem}

\begin{proof}
  Assume $(u_\delta)_{N}$ satisfies
  \begin{align*}
    \left\{  
     \begin{array}{lr}  
     \Delta (u_\delta)_{N} = f,  \quad\quad~\text{in}~~~ \Om _{\delta}&  \\  
     (u_\delta)_{N} = 0,  \quad\quad\quad~\text{on}~~~  \partial\Om _{\delta}.     
     \end{array}  
    \right.  
  \end{align*}
  When $\delta>0$ is small, there exists $K _{\delta} \subset \subset \Om _{\delta}, K \subset \subset \Om$, such that $F _{\delta}: \Om \setminus K \to \Om _{\delta} \setminus K _{\delta}$ is a diffeomorphism. Then $F _{\delta} ^{*} (u_\delta) _{N} = u _{\delta, N}$ and $F _{\delta} ^{*} f = f _{\delta}$ satisfy
  \begin{align*}
  \left\{  
    \begin{array}{lr}  
    L _{\delta} u _{\delta, N} = f _{\delta},  \quad\quad~\text{in}~~~ \Om \setminus K&  \\  
    u _{\delta, N} = 0,  \quad\quad\quad\quad~\text{on}~~~  \partial\Om.     
    \end{array}  
  \right.  
  \end{align*}
  Moreover, if writing operator $L _{\delta} = \sum _{i,j = 1} ^{2n} a _{ij, \delta} \(x\) \frac{\partial ^{2}}{\partial x _{i} \partial x _{j}} + \sum _{i = 1} ^{2n} b _{i, \delta} \(x\) \frac{\partial}{\partial x _{i}}$, where $\(x _{1}, x _{2}, \cdots, x _{n}\)$ is the Euclidean coordinate on $\Om$. Then $L _{\delta}$ is uniform elliptic independent of $\delta$ and 
  \begin{align*}
    \max \left\{\lnm a _{ij, \delta}\rnm _{W ^{k}\(\cl{\Om \setminus K}\)}, \lnm b _{i, \delta}\rnm _{W ^{k}\(\cl{\Om \setminus K}\)} \right\} \leq C,
  \end{align*}
  for some $C > 0$ depending on $\Om, K, k$. By the interior elliptic regularity and the boundary regularity, we have
  % in a \cite{Evans2022}(p.309,317,323)
  \begin{align*}
    \lnm u _{\delta, N} \rnm _{k} 
    \leq C \(\lnm f _{\delta} \rnm  _{k - 2} + \lnm u _{\delta, N} \rnm\).
  \end{align*}
  This yields
  \begin{align}\label{uN delta estimate}
    \lnm (u_\delta) _{N} \rnm _{k, \Om _{\delta}} 
    \leq C \(\lnm f \rnm  _{k - 2, \Om _{\delta}} + \lnm (u_\delta) _{N} \rnm _{\Om _{\delta}}\)
    \leq C \(\lnm f \rnm  _{k - 2, \Om _{\delta}} + \lnm u_\delta \rnm _{\Om _{\delta}}\).
  \end{align}
  Let $(u_\delta) _{N} = \sum' _{J} A _{\delta, J} (u_\delta) _{\tilde{J}} d \bar{z} _{J}$, where the Sobolev norm of $A _{\delta, J}$ is uniformly bounded independent of $\delta$. Then
  \begin{align*}
    f &= \Delta \(\sideset{}{'}{\sum} _{J} A _{\delta, J} (u_\delta) _{\tilde{J}} d \bar{z} _{J}\)\\
    &= \sideset{}{'}{\sum} _{J} A _{\delta, J} \Delta (u_\delta) _{\tilde{J}} d \bar{z} _{J} + \sideset{}{'}{\sum} _{J} \nabla A _{\delta, J}\nabla \(u _\delta\) _{\tilde{J}}  d \bar{z} _{J} + \sideset{}{'}{\sum} _{J} \Delta A _{\delta, J} (u_\delta) _{\tilde{J}} d \bar{z} _{J}\\
    &= \(\Box u_\delta\) _{N} + \sideset{}{'}{\sum} _{J} \nabla A _{\delta, J}\nabla \(u _\delta\) _{\tilde{J}} d \bar{z} _{J} + \sideset{}{'}{\sum} _{J} \Delta A _{\delta, J} (u_\delta) _{\tilde{J}} d \bar{z} _{J}.
  \end{align*}
  It follows that
  \begin{align}\label{f delta estimate}
    \lnm f \rnm_{k - 2, \Om _{\delta}}
    \lesssim \lnm \(\Box u _\delta\) _{N} \rnm  _{k - 2, \Om _{\delta}} + \lnm u _{\delta} \rnm _{k - 1, \Om _{\delta}}
    \leq\lnm \Box u _{\delta} \rnm _{k - 2, \Om _{\delta}} + \lnm u _{\delta}\rnm _{k - 1, \Om _{\delta}}.
  \end{align}
  Then (\ref{uN delta estimate}) and (\ref{f delta estimate}) yields
  \begin{align*}
    \lnm \(u _{\delta}\) _{N} \rnm _{k, \Om _{\delta}}
    \leq C \(\lnm \Box u _{\delta} \rnm  _{k - 2, \Om _{\delta}} + \lnm u _{\delta} \rnm  _{k - 1, \Om _{\delta}}\).
  \end{align*}
\end{proof}

\begin{coro}\label{uN estimate}
For any $k \geq 2$, there exists a constant $C > 0$ independent of $\delta$ (for $0<\delta <<1$), such that
  \begin{align*}
    \lnm \(u _{\delta} \)_N \rnm_k 
    \leq C \(\lnm \bar{\partial} u _{\delta} \rnm_{k-1} + \lnm \bar{\partial} ^{*} u _{\delta} \rnm_{k-1} + \lnm u _{\delta}\rnm_{k-1}\)
  \end{align*}
for all $u_\delta \in \dom(\bar{\partial}^*) \cap W_{(0,q)}^k \(\Om _{\delta}\)$, where $(u_\delta)_{N}$ is the normal component of $u_\delta$.  
\end{coro}

The following important benign estimates are due to Boas and Straube \cite{BS91}.
\begin{lem}\label{benign estimate}
  Let $\Om$ be a smooth bounded pseudoconvex domain in $\bbC^n$ with defining function $\rho$, $k \in \mathbb{N}$, $0 \leq q \leq n$ and $Y$ be a tangential vector field of type (1,0) with coefficients in $C^\infty \(\cl{\Om}\)$. %with $Y \rho = 0$ on $b\Om$. 
  Then there is a constant $C$ such that for $u \in C_{(0,q)}^\infty \(\cl{\Om}\)\cap \dom \(\bar{\partial}^*\)$, we have %the estimates
  \begin{align*}
    \sum_{j,J} \lnm \frac{\partial u_J}{\partial \bar{z}_j} \rnm _{k - 1}^2 
    \leq C \( \lnm \bar{\partial} u \rnm _{k-1}^2 + \lnm \bar{\partial}^* u \rnm_{k-1}^2 + \lnm u \rnm _{k-1}^2 \);
  \end{align*}

  \begin{align*}
    \lnm Yu  \rnm _{k-1}^2 
    \leq C \( \lnm \bar{\partial} u \rnm _{k-1}^2 + \lnm \bar{\partial}^* u \rnm_{k-1}^2 + \lnm u \rnm_{k-1} \lnm u \rnm_{k} \).
  \end{align*}
Moreover, if $u$ is compactly supported in $\Om$, then 
  \begin{align}\label{interior estimate}
    \lnm u \rnm _{k} ^{2} \leq C \( \lnm \bar{\partial} u \rnm _{k-1}^2 + \lnm \bar{\partial}^* u \rnm_{k-1}^2\).
  \end{align}
\end{lem}


