 \begin{align*}
  \theta ^{v} = \frac{d\rho \(\left[\bar{\partial}, v\right]\)}{d\rho\(v\)}.
 \end{align*}
\end{deft}
Using special boundary charts, write $v = \sum _{j = 1} ^{n} v_{j} L _{j}$. Then
\begin{align*}
  d\rho\(v\) = v \rho = \sum _{j = 1} ^{n} v_{j} L _{j} \rho, ~~\text{         }~~~~~\theta ^{v} = \(v \rho\) ^{- 1} \sum _{i,j = 1} ^{n} \left( \(L _{j} \rho\) \(\bar{L} _{i} v _{j}\) + v_j [\bar{L} _{i}, L _{j}] \rho\right) \bar{\omega} _{i}.
\end{align*} 
Write
$\theta^{v} = \theta^{v} _{T} + \theta^{v} _{N}$, where $\theta^{v} _{T} = \sum _{j = 1} ^{n - 1} \theta^{v} _{j} \bar{\omega} _{j}$ is called the tangential component and $\theta^{v} _{N} = \theta^{v} _{n} \bar{\omega} _{n}$ is called the normal component. 


