  %  \leq & \sqrt{\(M _{\varepsilon, q} ^{-1} \left[\bar{\partial},  \(\chi _{\varepsilon} v_{\alpha, \varepsilon}\) ^{k}\right] f, \left[\bar{\partial}, \(\chi _{\varepsilon} v_{\alpha, \varepsilon}\) ^{k} \right] f\)} + C_\varepsilon \left( \lnm \bar{\partial} f\rnm _{k} + \sqrt{\lnm f \rnm _{k}\lnm \bar{\partial} f \rnm _{k}} \right) \\\nonumber
