 \leq & k \sqrt{\(\(M _{\varepsilon, q}^{\alpha}\) ^{-1} \theta^{v_{\alpha, \varepsilon}} \wedge v_{\alpha, \varepsilon} ^{k} f, \theta^{v_{\alpha, \varepsilon}} \wedge v_{\alpha, \varepsilon} ^{k} f\)} + C_{\varepsilon} \bigg(\sqrt{\lnm f \rnm_{k - 1}\lnm f \rnm_{k}} + \sqrt{\lnm \bar{\partial}f \rnm_{k}\lnm f \rnm_{k}}\\\nonumber 
 &+ \sqrt{\lnm \bar{\partial} ^{*} f \rnm_{k - 1}\lnm f\rnm _{k}} + \sqrt{\lnm f \rnm ^{\frac{1}{2}}_{k - 1}\lnm f\rnm^{\frac{3}{2}} _{k}} + \lnm \bar{\partial} f \rnm_{k} + \lnm \bar{\partial} ^{*} f \rnm_{k - 1}\bigg).\\ \nonumber
  \end{align*}
  for any $f$ supported in $V _{\alpha, \varepsilon}$.
