	\title{On the rate of convergence of estimating the Hurst parameter of rough stochastic volatility models}
\author{Xiyue Han$^*$ and Alexander Schied\thanks{
		Department of Statistics and Actuarial Science, University of Waterloo, 200 University Ave W, Waterloo, Ontario, N2L 3G1, Canada. E-Mails: {\tt xiyue.han@uwaterloo.ca, aschied@uwaterloo.ca}.\hfill\break
