	%

	\begin{abstract}
		In this paper, we are motivated by two conjectures proposed by C. Bender et al.\ in 2024, which have remained open questions. The first conjecture states that if the complemented zero-divisor graph \( G(S) \) of a commutative semigroup \( S \) with a zero element has the clique number three or greater, then the reduced graph \( G_r(S) \) is isomorphic to the graph \( G(\mathcal{P}(n)) \). The second conjecture asserts that if \( G(S) \) is a complemented zero-divisor graph with the clique number three or greater, then \( G(S) \) is uniquely complemented.

		In this work, we construct a commutative semigroup \( S \) with a zero element that serves as a counter-example to both conjectures. 
	\end{abstract}	

	\maketitle \noindent{ \small \textbf{Keywords}: Clique number, commutative semi-group,  complemented graph, reduced graph, uniquely complemented graph, zero-divisor graph.} 
    \maketitle

	\section{Introduction}
	The zero-divisor graph associated with a commutative ring was first introduced by I.~Beck~\cite{B}, with the goal of studying graph coloring. Later, Anderson and Livingston~\cite{AL} modified the definition so that the vertex set consists only of the nonzero zero-divisors of the ring. This construction was further extended to the context of semigroups and posets in~\cite{DD,DMS, JA 2}. 

In a graph $G$, two distinct vertices $a$ and $b$ are called \textit{orthogonal}, denoted $a\perp b$, if $a$ and $b$ are adjacent and there does not exist a vertex $c$ adjacent to both $a$ and $b$. Equivalently, adjacent vertices $a$ and $b$ are \textit{orthogonal} if the edge $a - b$ is not an edge of any triangle (3-cycle). A graph $G$ is called \textit{complemented} if for every vertex $a$, there exists a vertex $b$ such that $a\perp b$. A graph $G$ is called \textit{uniquely complemented} if $G$ is complemented and has the property that if $a, b, c$ are distinct vertices with $a\perp b$ and $a\perp c$, then $N(b) = N(c)$. This graph-theoretic property has been studied in the context of the zero-divisor graph associated with a commutative ring; \textit{see} \cite{L}. 

		Throughout the paper, let $S$ denote a finite commutative semigroup with $0$. The set of zero-divisors of $S$, denoted $Z(S)$, forms an ideal in $S$. The zero-divisor graph associated with $S$, denoted $G(S)$, is the graph whose vertices are given by the nonzero zero-divisors and  two distinct vertices $a$ and $b$ are	adjacent  when $ab = 0$.
	  A \textit{clique}	in a graph $G$ is a sub-graph of $G$ where every pair of distinct vertices in the sub-graph are adjacent. The	\textit{clique number} of a graph $G$ is the number of vertices in a maximal clique in $G$ and is denoted $\omega(G)$.

	Define an equivalence relation $\sim$ on the vertex set $V(G)$ of a graph $G$ by $a\sim b$ if	and only if $N(a) = N(b)$. Denote the equivalence class of $a\in V(G)$ by $[a]$. The \textit{reduced graph} of $G$, denoted $G_r$, is the graph whose vertex set is the set of equivalence classes under relation $\sim$, where two distinct vertices $[a]$, $[b]$ in the vertex set of $G_r$ are adjacent if and only if vertices $a$ and $b$ are	adjacent in the graph $G$; \textit{see} Bender et al.\cite{C}.



	Let $\mathcal{P}(n)$ denote the semigroup consisting of the power set of an $n$-element set, equipped with the operation of intersection.

	  In \cite{C}, Bender et al.  mentioned that	every known example of a zero-divisor graph $G(S)$, for finite $S$, which is complemented and has the clique number $n \geq 3$ has reduced graph isomorphic to $G(\mathcal{P}(n))$ and is also a uniquely complemented graph. The case where the order of $S$ is infinite is open. Hence they raised the following conjectures.

	\begin{cnj} If $G(S)$ is a complemented zero-divisor graph with the clique number $n \geq 3$, then $G(S)$ has the reduced graph $G_r$ which is isomorphic to  $G(\mathcal{P}(n))$.
		\end{cnj}
		\begin{cnj} If $G(S)$ is a complemented zero-divisor graph with the clique number $3$ or greater, then $G(S)$ is uniquely complemented.
			\end{cnj}
	To settle these conjectures, we explored the underlying structures of complemented zero-divisor graphs in commutative semigroups with zero. 


	\section{Counter-example}
	Consider the set $S=\mathcal{P}(3)\times \mathbb{Z}_4=\{(X,\overline{a})~|~ X \in \mathcal{P}(3),~\overline{a} \in \mathbb{Z}_4 \}$. 
	Clearly, $S$ is a nonempty set, as $(\emptyset,\overline{0}) \in S$.  We define a binary operation, denoted by $``*"$ on the set $S$ such that $(X,\overline{a}) * (Y,\overline{b})=(X \cap Y,~~\overline{a}\times_4\overline{b})$, for $(X,\overline{a}), (Y,\overline{b}) \in S$. For simplicity, we denote the binary operation $\times_4$ on $\mathbb{Z}_4$ by $``."$. 

Since $(\mathcal{P}(3),\cap)$~ and ~ $ (\mathbb{Z}_4,.)$ are both commutative semigroups with zero elements, we can easily prove that $(S,*)$ is a commutative semigroup with zero element $(\emptyset, \overline{0})$.

Observe that,
$V(G(S))=\{(X,\overline{a}) \in S \setminus (\emptyset,\overline{0}) ~|~ (X,\overline{a})*(Y,\overline{b})=(\emptyset,\overline{0})$, \linebreak ~~\text{for some}~~ $(Y,\overline{b}) \in S \setminus\{(\emptyset,\overline{0})\}\}$. Clearly, $V(G(S)) \neq \emptyset$, since $(\emptyset, \overline{1})*(\{123\}, \overline{0})=(\emptyset, \overline{0})$. Further, we can easily prove that $V(G(S))=S\setminus \{(\emptyset, \overline{0}), (\{123\},\overline{1}), (\{123\},\overline{3})\}$. 

First, we claim that the zero-divisor graph $G(S)$ is complemented.	

Let $(X,\overline{a}) \in V(G(S))$ be any element. Thus $(X,\overline{a})\neq (\emptyset, \overline{0})$ and there exists $(Y,\overline{b}) \neq (\emptyset, \overline{0})$ such that $(X,\overline{a})*(Y,\overline{b})= (\emptyset, \overline{0}).$ Therefore, $X \cap Y=\emptyset$ and $\overline{a}.\overline{b}=\overline{0}$.
Since $(X,\overline{a}) \neq (\emptyset,\overline{0})$, we have $X \neq \emptyset ~~ \text{or} ~~ \overline{a} \neq \overline{0}$.
Thus, we have the following cases:

	\begin{enumerate} \item[Case (I) :] Let $X =\emptyset$ and $\overline{a} \in \{\overline{1},\overline{2},\overline{3}\}$. Then $(X,\overline{a})\in \{(\emptyset,\overline{1}), (\emptyset,\overline{2}), (\emptyset,\overline{3})\}$.\\ It is easy to observe that $(X,\overline{a})\perp (\{1,2,3\},\overline{0})$. 
		\item[Case (II) :] Let $X \neq \emptyset$ and $\overline{a}=\{\overline{0}\}$. 
	Clearly, one can see that $(X,\overline{0}) \perp (Y, \overline{b})$ where \linebreak $(Y, \overline{b}) \in \biggl\{ (\{1,2,3\}\setminus X,\; \overline{1}), (\{1,2,3\}\setminus X,\; \overline{2}), (\{1,2,3\}\setminus X, \;\overline{3})\biggr\}$.
		\item[Case (III) :] Let $X \neq \emptyset$ and $\overline{a} \in \{\overline{1},\overline{2},\overline{3}\}$.  Then we have $ (Y, \overline{b})\perp (\{1,2,3\}\setminus X,\overline{0})$, where $(Y, \overline{b}) \in\biggl\{(X,\overline{1}), (X,\overline{3})\biggr\}$ provided $\{1,2,3\}\setminus X\neq \emptyset$. 	Further, $(X,\overline{2}) \perp (Y, \overline{b})$ where $(Y, \overline{b}) \in\biggl\{ (\{1,2,3\}\setminus  X,\overline{0}), (\{1,2,3\}\setminus X,\overline{2})\biggr\}$.
	\end{enumerate} 
Thus in any case, for any element $(X,\overline{a})\in V(G(S))$ has a complement in $G(S)$.	Therefore, $G(S)$ is a complemented graph. Clearly, $G(S)$ contains a cycle of length $3$, namely, $(\{1\},\overline{0})-(\{2\},\overline{0})-(\{3\},\overline{0})-(\{1\},\overline{0})$. This implies that {\textbf{$\omega{(G(S))} \geq 3$}}. 

\vskip10pt	
\noindent\textbf{Proof of Conjecture 1.1:} 


	Now, for the reduced graph $G_r(S)$, first we determine neighborhood $N((X,\overline{a}))$, for every vertex $(X,\overline{a})\in V(G(S))$ as follows; 

	\begin{enumerate}
		\item[A)] Let $X=\emptyset$ and $\overline{a}\in \{\overline{1},\overline{2}, \overline{3}\}$. \begin{enumerate}\item $N((\emptyset,\overline{1}))=\{(X,\overline{0})~|~X(\neq \emptyset) \in \mathcal{P}(3)\}$ \\ $~~~~=\{(\{1\},\overline{0}),(\{2\},\overline{0}),(\{3\},\overline{0}),(\{1,2\},\overline{0}),(\{1,3\},\overline{0})\},(\{2,3\},\overline{0}),(\{1,2,3\},\overline{0})$
		$=N((\emptyset,\overline{3}))$.

		\item $N((\emptyset,\overline{2}))=\{(X,\overline{0}),(X,\overline{2})~|~X(\neq \emptyset) \in \mathcal{P}(3)\}$ \\ $~~~~=\{(\{1\},\overline{0}),(\{2\},\overline{0}),(\{3\},\overline{0}),(\{1,2\},\overline{0}),(\{1,3\},\overline{0})\},(\{2,3\},\overline{0}),(\{1,2,3\},\overline{0}), \\ ~~~~~~~~~~~~~~ (\{1\},\overline{2}),(\{2\},\overline{2}),(\{3\},\overline{2}),(\{1,2\},\overline{2}),(\{1,3\},\overline{2})\},(\{2,3\},\overline{2}),(\{1,2,3\},\overline{2})$.
		\end{enumerate}
		\item[B)] Let $X\neq \emptyset$ and $\overline{a}=\overline{0}$. \\Thus, $N((X,\overline{0}))=\{(\emptyset,\overline{a}),(Y,\overline{b})~|~\overline{a} \in \{\overline{1},\overline{2},\overline{3}\}, \overline{b} \in \mathbb{Z}_4, Y(\neq \emptyset) \in \mathcal{P}(3)$, such that $X \cap Y=\emptyset \}$. 
		\begin{enumerate}
			\item \mbox{ $N((\{1\},\overline{0}))=\{(\emptyset,\overline{a}),(\{2\},\overline{b}),(\{3\},\overline{b}), (\{2,3\},\overline{b})~|~ \overline{a}\in \{\overline{1},\overline{2}, \overline{3}\} ~\text{and}~ \overline{b}\in \mathbb{Z}_4\}$.}
			\item \mbox{$N((\{2\},\overline{0}))=\{(\emptyset,\overline{a}),(\{1\},\overline{b}),(\{3\},\overline{b}), (\{1,3\},\overline{b})~|~ \overline{a}\in \{\overline{1},\overline{2}, \overline{3}\} ~\text{and}~ \overline{b}\in \mathbb{Z}_4\}$.}
			\item \mbox{$N((\{3\},\overline{0}))=\{(\emptyset,\overline{a}),(\{1\},\overline{b}),(\{2\},\overline{b}), (\{1,2\},\overline{b})~|~ \overline{a}\in \{\overline{1},\overline{2}, \overline{3}\} ~\text{and}~ \overline{b}\in \mathbb{Z}_4\}$.}
			\item \mbox{$N((\{1,2\},\overline{0}))=\{(\emptyset,\overline{a}),(\{3\},\overline{b})~|~ \overline{a}\in \{\overline{1},\overline{2}, \overline{3}\} ~\text{and}~ \overline{b}\in \mathbb{Z}_4\}$.}
