    \caption{Density in real space for the BEC at zero temperature for different rotation speeds. Top panels show $\rho(z,y,z=0)$. The other rows show $\rho(x, y = 0, z = 0)/\rho_c$ for fixed potential (mid panels) and for fixed volume (bottom panels). }
    \label{Figure:densities}
\end{figure}

