\section{LINEARIZATION FOR SINGLE POINT POSITIONING (SPP)}\label{app:linearform}
The right-hand side (RHS) of the pseudorange measurement model in Eq. \eqref{eq:meas_model} can be linearized by taking the first-order Taylor expansion at $x_{0}=\left[u_{x,0},u_{y,0},u_{z,0}, u_{t,0}\right]^T$ as follows:
\begin{equation}
\begin{aligned}
    \varrho_i {=}& \varrho_{i,0} -a_{i,1}\left(u_x-u_{x,0}\right)-a_{i,2}\left(u_y-u_{y,0}\right)\\
    &{-}a_{i,3}\left(u_z-u_{z,0}\right) + u_t - u_{t,0} +\eta_i \,,
\label{eq:linear_meas_model}
\end{aligned}
\end{equation}
where 
\begin{subequations}
\begin{align}
    \varrho_{i,0}{=}&\sqrt{\left(p_{x}^{i}-u_{x,0}\right)^2+\left(p_{y}^{i}-u_{y,0}\right)^2+\left(p_{z}^{i}-u_{z,0}\right)^2}+u_{t,0} \\
    a_{i,1}{=}&\frac{p_{x}^{i}-u_{x,0}}{\sqrt{\left(p_{x}^{i}-u_{x,0}\right)^2+\left(p_{y}^{i}-u_{y,0}\right)^2+\left(p_{z}^{i}-u_{z,0}\right)^2}} \\
    a_{i,2}{=}&\frac{p_{y}^{i}-u_{y,0}}{\sqrt{\left(p_{x}^{i}-u_{x,0}\right)^2+\left(p_{y}^{i}-u_{y,0}\right)^2+\left(p_{z}^{i}-u_{z,0}\right)^2}} \\
    a_{i,3}{=}&\frac{p_{z}^{i}-u_{z,0}}{\sqrt{\left(p_{x}^{i}-u_{x,0}\right)^2+\left(p_{y}^{i}-u_{y,0}\right)^2+\left(p_{z}^{i}-u_{z,0}\right)^2}}\,.
\end{align}
\end{subequations}
The matrix form of the linearized pseudorange measurement model with $n$ measurements can be written as
\begin{equation}
    y=\mathbf{G}x+\varepsilon \,,
    \label{eq:SPP matrix form}
\end{equation}
where
\begin{equation}
\begin{aligned}
    &y=\begin{bmatrix}
        \varrho_{1,0}-\varrho_1 \\
        \vdots \\
        \varrho_{n,0}-\varrho_n
    \end{bmatrix}\,,
    \mathbf{G} = \begin{bmatrix}
     a_{1,1} & a_{1,2} & a_{1,3} & 1\\
     \vdots  & \vdots  & \vdots & \vdots \\
    a_{n,1} & a_{n,2} & a_{n,3}  & 1
    \end{bmatrix} \,, \\
     &\varepsilon=\begin{bmatrix}
        \eta_1 \\
        \vdots \\
        \eta_n
    \end{bmatrix} \,,
    x=\begin{bmatrix}
        u_x-u_{x,0} \\
        u_y-u_{y,0} \\
        u_z-u_{z,0} \\
        -(u_t - u_{t,0})
    \end{bmatrix}\,.
\label{eq:SPP matrix meaning}
\end{aligned}
\end{equation}
For single-frequency receivers (such as L1 or L5), the measurement error $\eta_i$ mainly includes the satellite clock and ephemeris error $\epsilon_{eph\&clk,i}$, ionospheric delay $\epsilon_{iono,i}$, tropospheric delay $\epsilon_{trop,i}$ and code noise and multipath error $\epsilon_{cnmp,i}$:
\begin{equation}
    \eta_i = \epsilon_{eph\&clk,i} + \epsilon_{iono,i} + \epsilon_{trop,i} + \epsilon_{cnmp,i}\,.
\end{equation}
For double frequency receivers (e.g., L1-L5), the ionospheric delay can be eliminated by differencing pseudorange measurements on both frequencies as follows \citep{misra_global_2006}:
\begin{subequations}
\begin{align}
    \varrho_{iono\text{-}free}=\frac{\gamma \varrho_{L1}-\varrho_{L5}}{\gamma-1} \\\
    \gamma = \left(\frac{f_{L1}}{f_{L5}}\right)^2 \,,
\end{align}
\label{eq:iono-free pseudorange}
\end{subequations}
where $\varrho_{iono\text{-}free}$ represents the ionospheric-free pseudorange, and $f_{L1}$ and $f_{L5}$ represents the L1 and L5 frequencies, respectively. Then, the measurement error can be represented as follows \citep{blanch2023evaluation}:
\begin{equation}
    \eta_i = \epsilon_{eph\&clk,i}^{L1\text{-}L5} + \epsilon_{trop,i} + \frac{\gamma}{\gamma-1}\epsilon_{cnmp,i}^{L1} - \frac{1}{\gamma-1}\epsilon_{cnmp,i}^{L5} \,,
    \label{eq:dual freq error}
\end{equation}
where $\epsilon_{eph\&clk,i}^{L1\text{-}L5}$ is the satellite clock and ephemeris error for the L1-L5 ionospheric free combination. With the definition in Eqs. \eqref{eq:iono-free pseudorange} and \eqref{eq:dual freq error}, the linearized pseudorange measurement model for the dual frequency SPP takes a similar form as in Eqs. \eqref{eq:SPP matrix form} and \eqref{eq:SPP matrix meaning}.


\section{DISTRIBUTION OF JACKKNIFE RESIDUAL UNDER GAUSSIAN NOISES}\label{app:JK_res_proof}
The Gauss-Markov conditions concern the set of noises in the linear system $y=\mathbf{G}x+\bm{\varepsilon}$ as follows:
\begin{enumerate}
    \item Zero mean: $\E[\varepsilon_i] = 0 ~\forall i$;
    \item Homoscedastic: $\Var[\varepsilon_i]=\sigma^2<\infty~\forall i$;
    \item Uncorrelated: $\Cov[\varepsilon_i,\varepsilon_j]=0 ~\forall i\neq j$.
\end{enumerate} 
Under Gauss-Markov conditions, the ordinary least squares (OLS) estimator is the best linear unbiased estimator (BLUE). \par
A further generalization of the Gauss-Markov conditions to heteroscedastic and correlated errors has been developed \cite{aitken1936on}, and its application to the weighted least squares (WLS) estimator can be stated as follows:
\begin{displayquote}
``WLS is the BLUE if the weight matrix is equal to the inverse of the variance-covariance matrix of the noises."
\end{displayquote}
Based on the generalized Gauss-Markov conditions, the subsolution in Eq. (\ref{eq:subsolution}a) has the following properties:
\begin{subequations}
\begin{align}
    \E[\hat{\mathbf{x}}^{(k)}]{=}&0 \\
    \Var[\hat{\mathbf{x}}^{(k)}]{=}&\mathbf{S}^{(k)}\mathbf{W}^{-1}\mathbf{S}^{(k)^T} \,.
\end{align}
\end{subequations}
By substituting Eq. \eqref{eq:prediction} into Eq. \eqref{eq:JK_residual}, the jackknife residual can be written by
\begin{equation}
\begin{aligned}
    t_k &= y_k - \mathbf{g}_k \hat{\mathbf{x}}^{(k)} \\
    & = \mathbf{g}_k \mathbf{x}^{(k)} + \varepsilon_k  - \mathbf{g}_k \hat{\mathbf{x}}^{(k)} \\
    & = \mathbf{g}_k (\mathbf{x}^{(k)}-\hat{\mathbf{x}}^{(k)}) + \varepsilon_k \,.
\end{aligned}
\label{eq:ti_1}
\end{equation}
The expectation and variance of the jackknife residual in \eqref{eq:ti_1} are given by
\begin{subequations}
\begin{align}
    \E[t_k] {=}& 0 \\
    \Var[t_k] {=}& \mathbf{g}_k \Var\left[  \mathbf{x}^{(k)} - \hat{\mathbf{x}}^{(k)}\right] \mathbf{g}_k^T + \sigma_k^2 \notag \\
            {=}& \mathbf{g}_k \mathbf{S}^{(k)}\mathbf{W}^{-1}\mathbf{S}^{(k)^T} \mathbf{g}_k^T + \sigma_k^2 \,.
\end{align}
\end{subequations}
As shown in Eq. \eqref{eq:ti_2}, the Jackknife residual can be rewritten as
\begin{equation}
    t_k= \tilde{\mathbf{p}}_k \bm{\varepsilon} \,,
\end{equation}
which is a linear combination of measurement errors. If $\varepsilon_i$ has a zero-mean Gaussian distribution defined in Eq. \eqref{eq:GaussianNoise}, $t_k$ will have a Gaussian distribution
\begin{equation}
    t_k \sim \mathcal{N}\left(0, \tilde{\mathbf{p}}_k \mathbf{W}^{-1} \tilde{\mathbf{p}}_k^T\right) \,.
\end{equation}
Since a Gaussian distribution is uniquely defined by its mean and variance, the following equation will hold:
\begin{equation}
    \mathbf{g}_k \mathbf{S}^{(k)}\mathbf{W}^{-1}\mathbf{S}^{(k)^T} \mathbf{g}_k^T + \sigma_k^2 = \tilde{\mathbf{p}}_k \mathbf{W}^{-1} \tilde{\mathbf{p}}_k^T \,.
\end{equation}
Therefore,
\begin{equation}
    t_k \sim \mathcal{N}\left(0,\mathbf{g}_k \mathbf{S}^{(k)}\mathbf{W}^{-1}\mathbf{S}^{(k)^T} \mathbf{g}_k^T + \sigma_k^2 \right) \,.
\end{equation}



\section{BONFERRONI CORRECTION}\label{app:Bonferroni}
The hypotheses with Bonferroni correction \citep{bonferroni1936teoria} in Eq. \eqref{eq:correct_hypo} have the following relationship with the original hypotheses in Eq. \eqref{eq:origin_hypo}:
\begin{equation}
\begin{aligned}
    H_0 {=}&  \bigcap\limits_{i=1}^{n}H_0^{(k)} \\
    H_1 {=}&  \bigcup\limits_{i=1}^{n}H_1^{(k)} \,.
\end{aligned}    
\end{equation}
Assume that the probability of type I error of the corrected hypothesis test is $\alpha^*$. Then,
\begin{equation}
    \begin{aligned}
        1-\alpha^* {=}& P(\text{All tests accept}|H_0)  \\
                  {=}& 1-P(\text{At least one test is rejected}|H_0) \\
                  {\geq}& 1-\sum\limits_{i=1}^{n} P(\text{Origin test}~ i ~ \text{is rejected}|H_0) \\
                  {=}& 1-\sum\limits_{i=1}^{n} P(\text{Origin test}~ i ~ \text{is rejected}|H_0^{(k)}) \\
                  {=}& 1-n\alpha \,.
    \end{aligned}
\end{equation}
In addition,
\begin{equation}
    \begin{aligned}
        \alpha^* {=}& P(\text{At least one test is rejected}|H_0) \\
                 {\geq}& P(\text{Origin test}~ i ~ \text{is rejected}|H_0^{(k)}) \\
                 {=}& \alpha \,.
    \end{aligned}
\end{equation}
Therefore,
\begin{equation}
    \alpha \leq \alpha^* \leq n\alpha \,.
    \label{eq:alpha* range}
\end{equation}
To keep the type I error $\alpha^*$ not exceeding $\tau$ (e.g., 0.05),
\begin{equation}
    n\alpha=\tau \,.
\end{equation}
Thus, the type I error of the individual test would be $\alpha=\frac{\tau}{n}$.


\section{Relating jackknife residual and solution separation}\label{app:relation}
The normal equations of the WLS problem for the full set and $k$th subset measurements are given by 
\begin{subequations}
    \begin{align}
        \mathbf{G}^T \mathbf{W} \mathbf{G} \hat{\mathbf{x}} &= \mathbf{G}^T \mathbf{W} \mathbf{y} \\
        \mathbf{G}^T \mathbf{W}^{(k)} \mathbf{G} \hat{\mathbf{x}}^{(k)} &= \mathbf{G}^T \mathbf{W}^{(k)} \mathbf{y} \,.
    \end{align}
\end{subequations}
Notably, $\mathbf{W}^{(k)}$ can be re-written by
\begin{equation}
    \mathbf{W}^{(k)} = \mathbf{W} - \mathbf{W}^{\frac{1}{2}}\mathbf{e}_k \mathbf{e}_k^T \mathbf{W}^{\frac{1}{2}},
    \label{eq:W_relation}
\end{equation}
where $\mathbf{W}^{\frac{1}{2}}$ is the square root matrix of $\mathbf{W}$ and $\mathbf{e}_k$ as the $k$th column of the identity matrix. By subtracting the subset normal equation from the full normal equation, we have
\begin{equation}
    \mathbf{G}^T \mathbf{W}\mathbf{G} \hat{\mathbf{x}} - \mathbf{G}^T \mathbf{W}^{(k)} \mathbf{G} \hat{\mathbf{x}}^{(k)} = \mathbf{G}^T \mathbf{W} \mathbf{y} - \mathbf{G}^T \mathbf{W}^{(k)} \mathbf{y} \,.
    \label{eq:normal_eq_substract}
\end{equation}
By substituting Eq. \eqref{eq:W_relation} into Eq. \eqref{eq:normal_eq_substract}, the right-hand side of Eq. \eqref{eq:normal_eq_substract} can be simplified as follows:
\begin{equation}
\begin{aligned}
    \mathbf{G}^T(\mathbf{W}-\mathbf{W}^{(k)}) \mathbf{y}  &= \mathbf{G}^T\mathbf{W}^{\frac{1}{2}}\mathbf{e}_k \mathbf{e}_k^T \mathbf{W}^{\frac{1}{2}} \mathbf{y}  = (\mathbf{W}^{\frac{1}{2}}\mathbf{G})^T\mathbf{e}_k\cdot \mathbf{e}_k^T\mathbf{W}^{\frac{1}{2}}\mathbf{y} \\
    &= W_{k,k}^{\frac{1}{2}}\mathbf{g}_k^T\cdot W_{k,k}^{\frac{1}{2}}y_k=W_{k,k}\mathbf{g}_k^Ty_k \,.
\end{aligned}
\end{equation}
Similarly, the left-hand side of Eq. \eqref{eq:normal_eq_substract} can be simplified as follows:
\begin{equation}
\begin{aligned}
    \mathbf{G}^T \mathbf{W}\mathbf{G} \hat{\mathbf{x}} - \mathbf{G}^T (\mathbf{W} - \mathbf{W}^{\frac{1}{2}}\mathbf{e}_k \mathbf{e}_k^T \mathbf{W}^{\frac{1}{2}}) \mathbf{G} \hat{\mathbf{x}}^{(k)} &= \mathbf{G}^T \mathbf{W}\mathbf{G} (\hat{\mathbf{x}}-\hat{\mathbf{x}}^{(k)}) + \mathbf{G}^T \mathbf{W}^{\frac{1}{2}}\mathbf{e}_k \mathbf{e}_k^T \mathbf{W}^{\frac{1}{2}} \mathbf{G} \hat{\mathbf{x}}^{(k)} \\
    &=\mathbf{G}^T \mathbf{W}\mathbf{G} \mathbf{d}_k +  (\mathbf{W}^{\frac{1}{2}}\mathbf{G})^T\mathbf{e}_k\cdot \mathbf{e}_k^T(\mathbf{W}^{\frac{1}{2}}\mathbf{G}) \hat{\mathbf{x}}^{(k)} \\
    &=\mathbf{G}^T \mathbf{W}\mathbf{G} \mathbf{d}_k+W_{k,k}\mathbf{g}_k^T \mathbf{g}_k \hat{\mathbf{x}}^{(k)} \,.
\end{aligned}
\end{equation}
Therefore, Eq. \eqref{eq:normal_eq_substract} can be written by
\begin{equation}
    \mathbf{G}^T \mathbf{W}\mathbf{G} \mathbf{d}_k+W_{k,k}\mathbf{g}_k^T \mathbf{g}_k \hat{\mathbf{x}}^{(k)} = W_{k,k}\mathbf{g}_k^Ty_k \,.
    \label{eq:sim_normal_eq_substract}
\end{equation}
By substituting Eqs. \eqref{eq:prediction} and \eqref{eq:JK_residual} into Eq. \eqref{eq:sim_normal_eq_substract} , we have
\begin{equation}
    \mathbf{G}^T \mathbf{W}\mathbf{G} \mathbf{d}_k =\mathbf{g}_k^T W_{k,k} t_k \,.
\end{equation}
Since $\mathbf{G}^T \mathbf{W}\mathbf{G}$ is invertible, we have
\begin{equation}
    \mathbf{d}_k = (\mathbf{G}^T \mathbf{W}\mathbf{G})^{-1}\mathbf{g}_k^T W_{k,k} t_k \,.
\end{equation}

