In this section, we solve the PDEs in \eqref{eq:cIPDE} and \eqref{eq:cG}, which are subject to multiple boundary conditions that are difficult to handle with conventional methods (e.g., separation of variables, transform method, and method of characteristics\cite{PDEforScientist}), by turning them into a boundary integral equation (BIE). As shown in \figref{fig:BIEsys}, Green's second identity can be applied to PDEs to reformulate a problem into a BIE\cite{costabel1987principles,liu2009fast}. This reduces the problem's dimensionality and naturally incorporates the boundary conditions into the equation, making it useful for problems where interior behavior (e.g., the mechanism inside the cell) is less important. Then, through the application of the Adomian decomposition method, the solution to the reformulated problem can be found. We present the new results in the form of lemmas, corollaries, and theorems in order to distinguish them from the known mathematical formulations used as a starting point for our analysis.

In the following, we first present the derivation of the BIE for the generic case of a PDE with Dirichlet's and Robin's boundary condition in \secref{sec:genBIE}. We then analyze the insulin subsystem using the BIE derived with the Adomian decomposition method in \secref{sec:insulinSA}. Based on the same principle, we also analyze the glucose subsystem in \secref{sec:glucoseSA}.


\subsection{General Boundary Integral Equation}\label{sec:genBIE}
As shown in \figref{fig:BIEsys}, explicit knowledge of the solution of the fundamental differential equation (i.e., the differential equation without the boundary conditions) is required to form the BIE. The fundamental differential equation can be formulated as an unbounded diffusion-reaction equation with an impulsive input at an arbitrary location $\dv'$ and at time $t=0$ as follows\begin{align}
    \dfrac{\partial h(\dv,t|\dv')}{\partial t} =& D\nabla_{\dv}^{2}h(\dv,t|\dv')-k_{\dr}h(\dv,t|\dv')\nonumber\\& + \delta(\dv-\dv')\delta(t), \label{eq:h}
\end{align}where $h(\dv,t|\dv')$ is the molecular concentration in an unbounded environment. To determine the generic BIE that fits both the insulin and glucose subsystems, we combine the two types of boundary conditions in \eqref{eq:BC} and \eqref{eq:BC-absorbing} as follows\begin{align}
    \begin{cases}
        D\nabla_{\dv} c(\dv,t|\dv_{0},t_{0})\cdot\nv_i|_{\dv\in \parOi} = k_{\ai}c(\dv,t|\dv_{0},t_{0}),\\
        \hfill i = 1,\cdots,N_b^R,\vspace{2ex}\\
        c(\dv,t|\dv_{0},t_{0})|_{\dv\in \parOi} = 0,\\
        \hfill i=N_b^R + 1,\cdots,N_b^R + N_b^D,
    \end{cases},\label{eq:generalBC}
\end{align} where $N_b^R$ and $N_b^D$ denote the number of boundaries with generalized Robin and Dirichlet boundary conditions, respectively. Relying on Green's second identity \cite{sadiku2000numerical}, we can reformulate the diffusion-reaction equation in \eqref{eq:cIPDE} in terms of the fundamental equation in \eqref{eq:h} and the boundary conditions in \eqref{eq:generalBC}.
\begin{lemma}\label{th:1}
    The BIE for the diffusion-reaction equation in \eqref{eq:cIPDE} with the boundary conditions in \eqref{eq:generalBC} can be derived as \begin{align}
            &C(\dv',\omega|\dv_{0},t_{0})= \nonumber\\ &\sum_{i=N_b^R + 1}^{N_b}\oint_{\parOi} H(\dv,\omega|\dv') \nabla_{\dv} C(\dv,\omega|\dv_{0},t_{0})\cdot\nv_i\mathrm{d}\mathcal{S}\nonumber\\&+\sum_{i=1}^{N_b^R}\oint_{\parOi} C(\dv,\omega|\dv_{0},t_{0})[k_{\ai}H(\dv,\omega|\dv')\nonumber\\ &-D\nabla_{\dv} H(\dv,\omega|\dv')\cdot\nv_i] \mathrm{d}\mathcal{S} + H(\dv_{0},\omega|\dv')e^{-j\omega t_{0}},\label{eq:generalBIE}
        \end{align}where $C(\dv,\omega|\dv_{0},t_{0})$ and $H(\dv,\omega|\dv')$ are the Fourier transforms of $c(\dv,t|\dv_{0},t_{0})$ and the solution to the fundamental solution in \eqref{eq:h}, respectively. In \eqref{eq:generalBIE}, $N_b = N_b^R + N_b^D$ and $\oint_{\parOi}(\cdot)\mathrm{d}\mathcal{S}$ represents the surface integral over the closed boundary of the $i$th object.
\end{lemma}
\begin{proof}
   Please refer to \cite{zoofaghari2021semi} for a comprehensive explanation of the derivation.
\end{proof}
Eq.~\eqref{eq:generalBIE} is in the form of a Fredholm integral equation of the second kind which can be solved using numerical techniques (e.g., the boundary element method (BEM) \cite{liu2009fast}) to determine the unknown concentration $C(\dv,\omega|\dv_{0},t_{0})$. However, the presence of multiple objects in the environment necessitates the creation of separate linear equations for each boundary, resulting potentially in a high computational complexity. The Adomian decomposition method is a systematic and versatile approach for solving nonlinear problems, notable for its grid-free methodology that streamlines computation and implementation compared to other numerical methods \cite{rahman2007integral}. Thus, we adopt the Adomian decomposition method to analyze \eqref{eq:generalBIE}. Then, to compute the surface integrals, each boundary $\parOi$ is discretized into $M_i$ sub-boundaries called meshes $\parOim$, with the area and center of each mesh denoted by $\mathcal{S}_i^m$ and $\dv_i^m$, respectively. The solution to the considered BIE is provided in the following theorem.
\begin{theorem}\label{th:BIEsolution}
    The solution to the BIE in \eqref{eq:generalBIE} is given by\begin{align}
        c(\dv,t|\dv_{0},t_{0}) &=  \sum_{n=0}^{\infty} c_n(\dv,t|\dv_{0},t_{0}),\label{eq:BIEsolution}
    \end{align} where \begin{align}
        c_0(\dv,t|\dv_{0},t_{0}) &= h(\dv_{0},t-t_{0}|\dv), \label{eq:c0general}
    \end{align} \begin{align}
        c_n(\dv,t&|\dv_{0},t_{0}) = \sum_{i=1}^{N_b^R}\sum_{m=1}^{M_i}c_{n-1}(\dv_i^m,t|\dv_{0},t_{0})\nonumber\\&* \mathcal{S}_i^m[k_{\ai}h(\dv_i^m,t|\dv)-D\nabla_{\dv} h(\dv_i^m,t|\dv)\cdot\nv_i^m]\nonumber\\&+\sum_{i=N_b^R+1}^{N_b}\sum_{m=1}^{M_i} \nabla_{\dv} c_{n-1}(\dv_i^m,t|\dv_{0},t_{0})\cdot\nv_i^m\nonumber\\&* D\mathcal{S}_i^m h(\dv_i^m,t|\dv),\label{eq:cngeneral}
    \end{align}and $*$ is the convolution operator.
\end{theorem} 
\begin{proof}
   See \apref{ap:2}.
\end{proof}
\begin{remark}
    Eqs. (12)-(14) reveal that the concentration comprises a term corresponding to an unbounded environment, i.e., $c_{0}(\dv,t|\dv_0,t_0)$ in (13), and adjustment terms accounting for boundary effects, i.e., $c_{n}(\dv,t|\dv_0,t_0)$ in (14). As will be shown in the following subsections, the application of this theorem extends naturally to \textbf{Corollaries 1}, \textbf{2}, and \textbf{3} and demonstrates the theorem's generality and versatility in addressing a broader range of scenarios within the considered system.
\end{remark}

\subsection{Insulin Subsystem Analysis\label{sec:insulinSA}}
The insulin subsystem is governed by the PDE in \eqref{eq:cIPDE} with the boundary conditions specified in \eqref{eq:BC} and \eqref{eq:BCins}. Based on \thref{th:1}, we present the insulin concentration in the following corollary.
\begin{corollary} \label{co:cI}
    The insulin concentration is given by \eqref{eq:BIEsolution}, where $h(\dv,t|\dv')$ is the solution of the diffusion-reaction equation in \eqref{eq:h} for the unbounded environment and is given by \eqcite{Jamali2019Channel}{30} \begin{align}
    h(\dv,t|\dv') = \dfrac{1}{(4\pi D_{\I}t)^{3/2}}\exp{\bigg( -\dfrac{||\dv-\dv'||^2}{4D_{\I}t}-k_{\dr_{_{\I}}}t\bigg)},\label{eq:hsol}
\end{align} and $c_0(\dv,t|\dv_{0_{\I}},t_{0_{\I}})$ and $c_n(\dv,t|\dv_{0_{\I}},t_{0_{\I}})$ can be respectively derived as \begin{align}
        &c_0(\dv,t|\dv_{0_{\I}},t_{0_{\I}}) =\nonumber\\& \dfrac{1}{\big(4\pi D_{\I}(t-t_{0_{\I}})\big)^{3/2}}\exp{\bigg( -\dfrac{||\dv_{0_{\I}}-\dv||^2}{4D_{\I}(t-t_{0_{\I}})}-k_{\dr_{\I}}(t-t_{0_{\I}})\bigg)}, \label{eq:c0ins-2}
    \end{align} and
    \begin{align}
       &c_n(\dv,t|\dv_{0_{\I}},t_{0_{\I}}) = \sum_{i=1}^{N_b}\sum_{m=1}^{M_i} c_{n-1}(\dv_i^m,t|\dv_{0_{\I}},t_{0_{\I}})* \dfrac{\mathcal{S}_i^m}{(4\pi D_{\I}t)^{3/2}}\nonumber\\&\times\bigg\{k_{\ai}+D_{\I} \dfrac{(\dv_i^m-\dv)\cdot\nv_i^m}{4D_{\I}t}\bigg\}\exp{\bigg( -\dfrac{||\dv_i^m-\dv||^2}{4D_{\I}t}-k_{\dr_{\I}}t\bigg)}.\label{eq:cnins-2}
    \end{align} 
\end{corollary}

