\subsubsection{State $S_0$ (reflective cells)}\label{sec:anaS0}
In state $S_0$, insulin is absent and the PDE in \eqref{eq:cG} with the boundary conditions \eqref{eq:BC} for the blood vessel and \eqref{eq:BC-reflective} for the cells is valid. Using \thref{th:1}, we provide the glucose concentration for state $S_0$ in the following corollary.
\begin{corollary}\label{co:cGS0}
    The impulse response for the glucose subsystem in state $S_0$ is given by \begin{align}
        c^{S_0}_{\G}(\dv,t|\dv_{0_{\G}},t_{0_{\G}}) &=  \sum_{n=0}^{\infty} c_n(\dv,t|\dv_{0_{\G}},t_{0_{\G}}),\label{eq:cGS0}
    \end{align} where \begin{align}
            c_0(\dv&,t|\dv_{0_{\G}},t_{0_{\G}}) = \nonumber\\&\dfrac{1}{(4\pi D_{\G}(t-t_{0_{\G}}))^{3/2}}\exp{\bigg( -\dfrac{||\dv_{0_{\G}}-\dv||^2}{4D_{\G}(t-t_{0_{\G}})}\bigg)}, \label{eq:c0glucose}
        \end{align} and
        \begin{align}
        c_n(\dv&,t|\dv_{0_{\G}},t_{0_{\G}}) =\sum_{i=1}^{N_b}\sum_{m=1}^{M_i} c_{n-1}(\dv_i^m,t|\dv_{0_{\G}},t_{0_{\G}})\nonumber\\&*\dfrac{\mathcal{S}_i^m D_{\G} (\dv_i^m-\dv)\cdot\nv_i^m}{4D_{\G}t(4\pi D_{\G}t)^{3/2}}\exp{\bigg( -\dfrac{||\dv_i^m-\dv||^2}{4D_{\G}t}\bigg)}
        \nonumber\\&+ \sum_{m=1}^{M_i} c_{n-1}(\dv_{N_b}^m,t|\dv_{0_{\G}},t_{0_{\G}})\nonumber\\&*\dfrac{\mathcal{S}_{N_b}^m k_{\ai}}{(4\pi D_{\G}t)^{3/2}}\exp{\bigg( -\dfrac{||\dv_{N_b}^m-\dv||^2}{4D_{\G}t}\bigg)}. \label{eq:cnglucoseS0}
    \end{align}
\end{corollary}    

\subsubsection{State $S_1$ (fully absorbing cells)}\label{sec:anaS1}
In state $S_1$, insulin is present and the PDE in \eqref{eq:cG} with the boundary conditions \eqref{eq:BC} for the blood vessel and \eqref{eq:BC-absorbing} for the cells is valid. Using \thref{th:1}, we obtain the glucose concentration for state $S_1$ in the following corollary.
\begin{corollary}\label{co:cGS1}
The impulse response of glucose subsystem in state $S_1$ can be expressed as \begin{align}
        c^{S_1}_{\G}(\dv,t|\dv_{0_{\G}},t_{0_{\G}}) &=  \sum_{n=0}^{\infty} c_n(\dv,t|\dv_{0_{\G}},t_{0_{\G}}),\label{eq:cGS1}
    \end{align}  where $c_0(\dv,t|\dv_{0_{\G}},t_{0_{\G}})$ is given by \eqref{eq:c0glucose} and
    \begin{align}
        &c_n(\dv,t|\dv_{0_{\G}},t_{0_{\G}}) = \sum_{i=1}^{N_b-1}\sum_{m=1}^{M_i} \nabla_{\dv} c_{n-1}(\dv_i^m,t|\dv_{0_{\G}},t_{0_{\G}})\nonumber\\&\cdot\nv_i^m*\dfrac{\mathcal{S}_i^m D_{\G}}{(4\pi D_{\G}t)^{3/2}}\exp{\bigg( -\dfrac{||\dv_i^m-\dv||^2}{4D_{\G}t}\bigg)}
        \nonumber\\&+c_{n-1}(\dv_{N_b}^m,t|\dv_{0_{\G}},t_{0_{\G}})* \dfrac{\mathcal{S}_{N_b}^m}{(4\pi D_{\G}t)^{3/2}}\nonumber\\&\times\bigg\{k_{\mathrm{a}_{N_b}}+D_{\G} \dfrac{(\dv_{N_b}^m-\dv)\cdot\nv_{N_b}^m}{4D_{\G}t}\bigg\}\exp{\bigg( -\dfrac{||\dv_{N_b}^m-\dv||^2}{4D_{\G}t}\bigg)}.\label{eq:cnglucoseS1}
    \end{align}     
\end{corollary}  

\subsubsection{Glucose concentration} \label{sec:anaglu}
Since the glucose concentration derived for each state corresponds to an impulse response, the output concentration can be obtained via convolution of the input concentration and this impulse response. 
\begin{theorem}
    The glucose concentration can be derived as \eqref{eq:cGsolution}, shown at the top of next page, where $\int_\Omega(\cdot)\mathrm{d}\dv$ represents the volume integral over $\Omega$.
\end{theorem}
\begin{proof}
    % Referring to the time diagram in \subfigref{fig:systemModel}{fig:glucosestate},
