\subsubsection{Optimal Insulin Injection Time\label{sec:optime}}
To determine the optimal insulin injection time, we convert the constrained problem in \eqref{eq:opProb} into an unconstrained problem by employing the method of Lagrange multipliers \cite{boyd2004convex} as\begin{align}
    \mathcal{L}(t_{0_{\I}},\lambda,s) = f(t_{0_{\I}})-\lambda(t_{0_{\I}} - s^2),
\end{align}where $\lambda$ is the Lagrange multiplier and $s^2$ is used to ensure the positivity of the equality constraint. To find the minimum of function $f(t_{0_{\I}})$, we set all partial derivatives to zero and arrive at \begin{subequations}
    \begin{align}
        \dfrac{\partial f(t_{0_{\I}})}{\partial t_{0_{\I}}} - \lambda &= 0,\label{eq:lag1}\\
        (t_{0_{\I}} - s^2) &= 0,\label{eq:lag2}\\
        2\lambda s &= 0.\label{eq:lag3}
    \end{align}
\end{subequations} Eq.~\eqref{eq:lag3} implies that two cases need to be considered: 
\begin{itemize}
    \item \textbf{Case 1:} When $s = 0$, \eqref{eq:lag2} indicates $t_{0_{\I}} = 0$. Substituting $t_{0_{\I}} = 0$ into function $f(t_{0_{\I}})$ satisfies the stationary condition but does not yield a minimum point.
    \item \textbf{Case 2:} When $\lambda = 0$, \eqref{eq:lag1} implies $\frac{\partial f(t_{0_{\I}})}{\partial t_{0_{\I}}} = 0$, and solving this equation leads to the minimum for the optimization problem.
\end{itemize}

\begin{theorem}\label{th:4}
    The approximate maximum insulin injection time after a meal with the postprandial glucose level below threshold $\phi$ is obtained as \begin{align}
        \hat{t}_{0_{\I}} = \begin{cases}
            \infty,\hfill c_{\G}^{S_0}(\dv_{\CGM},t_{\pk}^{S_0}|\dv_{0_{\G}},0)<\phi,\\
            t_{\pk}^{S_0}-\tau,\hspace{1cm}\hfill c_{\G}^{S_0}(\dv_{\CGM},t_{\pk}^{S_0}|\dv_{0_{\G}},0)=\phi,\\
            \dfrac{-B_{1}\pm\sqrt{(B_{1})^2-4B_{2}\phi}}{2B_{2}}-\tau, \\\hfill c_{\G}^{S_0}(\dv_{\CGM},t_{\pk}^{S_0}|\dv_{0_{\G}},0)>\phi.
        \end{cases},\label{eq:tI*}
    \end{align}where $\infty$ implies that the maximum insulin injection time is boundless\footnote{This further implies that the glucose level is already below the threshold and that no insulin injection is required.}, 
    \addtocounter{equation}{-1}\begin{subequations}
        \begin{align}
        B_{1} =& \dfrac{1}{(4\pi D_{\G})^{3/2}}\exp{\bigg( -\dfrac{||\dv_{0_{\G}}-\dv||^2}{4D_{\G}}\bigg)},\end{align}
        \begin{align}
        B_{2} =& \sum_{i=1}^{N_b}\sum_{m=1}^{M_i} \dfrac{\mathcal{S}_i^m(\dv_i^m-\dv)\cdot\nv_i^m}{16(\pi D_{\G})^{3}}\nonumber\\&\times\exp{\bigg( -\dfrac{||\dv_{0_{\G}}-\dv_i^m||^2+||\dv_i^m-\dv||^2}{2D_{\G}}\bigg)}.
    \end{align}
    \end{subequations}
\end{theorem}
\begin{proof}
    See \apref{ap:4}.
\end{proof}

Note that, similar to \thref{th:3}, we resort to approximating $\frac{a}{t^{n/2}}\exp(-\frac{b}{t})$, which reduces the equation to a solvable quadratic or cubic equation. This leads to an approximated analysis with an error that is negligible when $a\exp(-b)$ is the dominating term.

