\section{Proof of \thref{th:BIEsolution}}\label{ap:2}
 We use the Adomian decomposition method \cite{rahman2007integral} and express $C_{\I}(\dv',\omega|\dv_{0_{\I}},t_{0_{\I}})$ in the form of a series as \begin{align}
        C_{\I}(\dv',\omega|\dv_{0_{\I}},t_{0_{\I}}) = \sum_{n=0}^{\infty} C_n(\dv',\omega|\dv_{0_{\I}},t_{0_{\I}}),\label{eq:ADM1}
    \end{align} where $C_0(\dv',\omega|\dv_{0_{\I}},t_{0_{\I}})$ is the term outside the integral \eqref{eq:generalBIE}, i.e., $C_0(\dv',\omega|\dv_{0_{\I}},t_{0_{\I}}) = H_{\I}(\dv_{0_{\I}},\omega|\dv')e^{-j\omega t_{0_{\I}}}$. Substituting \eqref{eq:ADM1} into \eqref{eq:generalBIE}, we can express the BIE in the form of a series as follows\begin{align}
        &\sum_{n=0}^{\infty}C_n(\dv',\omega|\dv_{0_{\I}},t_{0_{\I}})=\sum_{i=N_b^R + 1}^{N_b}\oint_{\parOi} H_{\I}(\dv,\omega|\dv') \nonumber\\&\nabla_{\dv} \bigg\{\sum_{n=0}^{\infty} C_n(\dv,\omega|\dv_{0_{\I}},t_{0_{\I}})\bigg\}\cdot\nv_i\mathrm{d}\mathcal{S} + H_{\I}(\dv_{0_{\I}},\omega|\dv')e^{-j\omega t_{0_{\I}}} \nonumber\\&+\sum_{i=1}^{N_b^R}\oint_{\parOi} \bigg\{\sum_{n=0}^{\infty} C_n(\dv,\omega|\dv_{0_{\I}},t_{0_{\I}})\bigg\}[k_{\ai}H_{\I}(\dv,\omega|\dv')\nonumber\\&-D\nabla_{\dv} H_{\I}(\dv,\omega|\dv')\cdot\nv_i] \mathrm{d}\mathcal{S}.\label{eq:ADM-BIE}
    \end{align}

    Assuming that the sum converges absolutely to $C_{\I}(\dv',\omega|\dv_{0_{\I}},t_{0_{\I}})$, we can interchange the summation and the integral in \eqref{eq:ADM-BIE}. Then, by expanding the summation on both sides and associating each $C_n(\dv',\omega|\dv_{0_{\I}},t_{0_{\I}})$ in a recursive manner, we obtain $C_{n}(\dv',\omega|\dv_{0_{\I}},t_{0_{\I}})$ as shown in \eqref{eq:ADM-BIE4} on the top of the next page.

