\medskip
\section{Relations between the Goodman-Sharma modification of Baskakov operator and the MKZ operator}
\label{s2}

A well-know (see \cite{To1983}, \cite{He2003a,He2003b,He2006}) and useful mapping of functions
defined on $[0,\infty)$ into functions with domain $[0,1)$ will help us to transfer our results for
the Goodman-Sharma modification of the Baskakov operator (see \cite{GaPaUl2025}) to their analogues
for the modified MKZ-GS operator.

Henceforth, if we have several operators of any kind (approximation, differential, etc.), written
consecutively in an expression, we will use the convention that this is the composition of the
operators and usually omit the brackets.

Let us consider the change of the variable $\sigma : [0,1)\to[0,\infty)$ with
$$
  \x = \sigma(x) := \frac{x}{1-x}\,.
$$
Then the inverse change of the variable $\sigma^{-1} : [0,\infty)\to [0,1)$ is given by
$$
  x = \sigma^{-1}(\x) = \frac{\x}{1+\x}\,.
$$

An operator $\sT$ transforming a function $\f:[0,\infty)\to \mathbb{R}$ into a function
$f:[0,1)\to \mathbb{R}$ is defined by
\begin{equation} \label{eq:2.1}
   \big(\sT \f\big)(x) = (1-x)\f\Big(\frac{x}{1-x}\Big) = f(x), \qquad x\in [0,1),
\end{equation}
Clearly, for the inverse operator $\sT^{-1}$ we have
\begin{equation} \label{eq:2.2}
  \big(\sT^{-1}f\big)(\x) = (1+\x)f\Big(\frac{\x}{1+\x}\Big) = \f(\x), \qquad \x\in [0,\infty).
\end{equation}

We mentioned above that $\wD=\varphi D^2$, $\varphi (x)=x(1-x)^2$, naturally associates with
the MKZ type operators. Similarly, the corresponding differential operator for the Baskakov type
operators has the form
$$
  \wcD = \psi D^2, \qquad \psi(\x) = \x(1+\x).
$$
Important relationships for the operators $\wD$, $\wcD$, $\sT$ and $\sT^{-1}$ are the following:
\begin{gather}
  \sT \wcD\f = \sT(\psi D^2\f) = \varphi D^2 \sT\f = \wD \sT\f, \label{eq:2.3} \\
  \sT^{-1} \wD f = \sT^{-1}(\varphi D^2 f) = \psi D^2 \sT^{-1} f = \wcD \sT^{-1} f. \label{eq:2.4}
\end{gather}

From \eqref{eq:2.1}--\eqref{eq:2.4} we obtain:
\begin{proposition} \label{pr:2.1}
  If $\,\w(\x)=(1+\x)^{-1}$, $\x\in [0,\infty)$, then $\sT:W^2(\w\psi)[0,\infty)\to W^2(\varphi)[0,1)$
  is a bijective mapping and there hold
  $$
    \big\|\wD \sT \f \big\|_{[0,1)} = \big\|\w \wcD\f\big\|_{[0,\infty)}\,, \qquad
    \big\|\w\wcD \sT^{-1} f \big\|_{[0,\infty)} = \|\wD f\|_{[0,1)}\,,
  $$
  i.e.
  \begin{equation} \label{eq:2.5}
    \big\|\wD f\big\|_{[0,1)} = \big\|\w \wcD\f\big\|_{[0,\infty)}\,.
  \end{equation}
\end{proposition}

The classical Baskakov operator \cite{Ba1957} is defined by
\begin{equation} \label{eq:2.6}
  \cB_n(\f,\x) = \sum_{k=0}^{\infty} \f\Big(\frac{k}{n}\Big)\,\cP_{n,k}(\x), \qquad
  \cP_{n,k}(\x) = \binom{n+k-1}{k}\x^k(1+\x)^{-n-k},
\end{equation}
for $\x\in [0,\infty)$.

The following statement gives a relation between the MKZ operator $M_n^{[MKZ]}$ and the Baskakov
operator $\cB_n$.

\begin{proposition}[{{\cite[Proposition~7]{IvPa2012}}}] \label{pr:2.2}
  For every function $f$ such that one of the series (representing $M_n^{[MKZ]} f$ and
  $\cB_n \f$) in \eqref{eq:2.7} is convergent and for every $n\in\mathbb{N}$ we have
  \begin{equation} \label{eq:2.7}
    M_n^{[MKZ]}(f,x) % = \sT\big(\cB_n(\sT^{-1} f,x)\big)
                     = (1-x)\cB_n\Big(\f,\frac{x}{1-x}\Big), \qquad x\in[0,1).
  \end{equation}
\end{proposition}

Finta \cite{Fi2005} introduced the operator
\begin{equation} \label{eq:2.8}
  \begin{gathered}
    V_n(\f,\x) = \sum _{k=0}^{\infty} \,v_{n,k}(\f)\cP_{n,k}(\x), \qquad \x\in[0,\infty), \\
    v_{n,0}(\f) = \f(0), \qquad v_{n,k}(\f) = (n+1)\int_0^{\infty} \cP_{n+2,k-1}(t)\f(t)\,dt,
  \end{gathered}
\end{equation}
where $\cP_{n,k}$ are the Baskakov basis functions given in \eqref{eq:2.6}. The modification $V_n \f$
of the Baskakov operator is similar to the Goodman-Sharma type variant of the classical Bernstein
operator. Then the operators \eqref{eq:1.3} and \eqref{eq:2.8} satisfy the next property.

\begin{proposition}[{{\cite[Proposition~8]{IvPa2012}}}] \label{pr:2.3}
  For every integrable function $f$ such that one of the series (representing $M_n f$ and $V_n \f$)
  in \eqref{eq:2.9} is convergent and for every $n\in\mathbb{N}$ we have
  \begin{equation} \label{eq:2.9}
    M_n(f,x) % = \sT\big(V_n(\sT^{-1} f,x)\big)
             = (1-x)V_n\Big(\f,\frac{x}{1-x}\Big), \qquad x\in[0,1).
  \end{equation}
\end{proposition}

In \cite{GaPaUl2025} the authors introduced and investigated the approximation properties of the
modified Baskakov-GS operator
\begin{equation} \label{eq:2.10}
  \begin{gathered}
    \wV_n(\f,\x) = \sum_{k=0}^{\infty} v_{n,k}(\f)\wcP_{n,k}(\x), \qquad \x\in[0,\infty), \\
    \wcP_{n,k}(\x) = \cP_{n,k}(\x) - \frac{1}{n}\,\wcD P_{n,k}(\x).
  \end{gathered}
\end{equation}
It was proved in \cite[Theorem~1]{GaPaUl2025} that the modified Baskakov-GS operator $\wV_n$ has
second order rate of approximation for continuous functions, compared with the first order for the
Finta's operator \eqref{eq:2.8}.

A similar relationship between the MKZ operator $M_n^{[MKZ]}$ defined in \eqref{eq:1.1} and the
Baskakov operator $\cB_n$ as in Proposition~\ref{pr:2.2} holds for the modified MKZ-GS operator
$\wM_n$ and the modified Baskakov-GS operator $\wV_n$. The statement is an immediate consequence
from \eqref{eq:1.5} and \eqref{eq:2.9}--\eqref{eq:2.10}.

\begin{proposition} \label{pr:2.4}
  For every integrable function $f$ such that one of the series (representing $\wM_n f$ and
  $\wV_n \f$) in \eqref{eq:2.11} is convergent and for every $n\in\mathbb{N}$ we have
  \begin{equation} \label{eq:2.11}
    \wM_n(f,x) % = \sT\big(\wV_n(\sT^{-1} f,x)\big)
               = (1-x)\wV_n\Big(\f,\frac{x}{1-x}\Big), \qquad x\in[0,1).
  \end{equation}
\end{proposition}

Combining Propositions~\ref{pr:2.1}--\,\ref{pr:2.4} we summarize as follows.
\begin{proposition} \label{pr:2.5}
  Let $\w(\x)=(1+\x)^{-1}$, $\x \in [0,\infty)$. For every integrable function $f$ on $[0,1)$ such
  that one of the series (representing $\wM_n f$ and $\wV_n \f$) in \eqref{eq:2.11} is convergent,
  for the corresponding from \eqref{eq:2.1}--\eqref{eq:2.2} function $\f$ and for every
  $n\in\mathbb{N}$ we have
  \begin{align} \label{eq:2.12}
    \|f\|_{[0,1)} & = \|\w \f\|_{[0,\infty)}, \\
    \big\|\wM_nf\big\|_{[0,1)} & = \big\|\w \wV_n\f\big\|_{[0,\infty)}, \label{eq:2.13} \\
    \big\|\wD \wM_nf\big\|_{[0,1)} & = \big\|\w \wcD \wV_n\f\big\|_{[0,\infty)}. \label{eq:2.14}
  \end{align}
\end{proposition}

