\medskip
\section{Auxiliary Results for the modified MKZ-GS operator} \label{s3}

We start this section with some properties of the MKZ-GS operator $M_n$ from \cite{IvPa2012}:

\begin{itemize}
  \item $M_n$ is a linear positive operator;
  \item $M_n(e_0,x)=e_0(x)$, $M_n(e_1,x)=e_1(x)$, where $e_k(t)=t^k$, $k=0,1$;
  \item $M_n f \le f$ for every concave continuous function $f$.
\end{itemize}

\smallskip
Setting $\alpha_0=\alpha_1=0$ in \cite[eq. (4)]{IvPa2012} we get partial cases of
Propositions~9--14 in \cite{IvPa2012} listed below, respectively.

\begin{proposition} \label{pr:3.1}
  \!
  \begin{enumerate}
    \item[(a)] If $\,f\in C[0,1)$ and $n\in\mathbb{N}$, then
          $$
            M_n(f,x) - M_{n+1}(f,x) = \frac{1}{n(n+1)}\,\wD M_n(f,x), \qquad x\in[0,1).
          $$

    \item[(b)] For every $g\in W^2_0(\varphi)[0,1)$ and $n\in\mathbb{N}$ we have
          $$
            \wD M_n(g,x) = M_n(\wD g)(x), \qquad x\in[0,1),
          $$
          i.e. $M_n$ commutes with the operator $\varphi D^2$ on $W^2_0(\varphi)[0,1)$.

    \smallskip
    \item[(c)] Let $m,n\in\mathbb{N}$. Then for every $f\in C[0,1)$ we have $M_n M_m f=M_m M_n f$, i.e.
          $M_m$ and $M_n$ commute on $C[0,1)$.

    \smallskip
    \item[(d)] For every $f\in C[0,1)$ and $n\in\mathbb{N}$ we have $\|M_n f\|\le \|f\|$,
          i.e. $\|M_n\|=1$ holds for the norm of the operator $M_n$ on $C[0,1)$.

    \smallskip
    \item[(e)] For every $g\in W^2(\varphi)[0,1)$ and $n\in\mathbb{N}$ we have
          $\|\wD M_n g\|\le \|\wD g\|$.

    \smallskip
    \item[(f)] {\em Jackson-type inequality:} If $\,g\in W^2(\varphi)[0,1)$ and $n\in \mathbb{N}$ we have
          $$
            \| M_n g - g\| \le \frac{1}{n}\,\|\wD g\|.
          $$
  \end{enumerate}
\end{proposition}

Now, we give properties of the operators $M_n$, $\wM_n$ and the differential operator $\wD$.

\begin{proposition} \label{pr:3.2}
  If the operators $M_n$, $\wM_n$ and the differential operator $\wD$ are defined as in
  \eqref{eq:1.3}, \eqref{eq:1.5} and \eqref{eq:1.4}, respectively, then

  \smallskip
  \begin{enumerate}
    \item[(a)] $\wM_n f = M_n\big(f-\frac{1}{n}\,\wD f\big)$, for $f\in W^2_0(\varphi)[0,1)$;

    \smallskip
    \item[(b)] $\wD \wM_n f = \wM_n \wD f$, for $f\in W^2_0(\varphi)[0,1)$;

    \smallskip
    \item[(c)] $M_n \wM_n f = \wM_n M_n f$, for $f\in W^2_0(\varphi)[0,1)$;

    \smallskip
    \item[(d)] $\wM_m \wM_n f = \wM_n \wM_m f$, for $f\in W^2_0(\varphi)[0,1)$;

    \smallskip
    \item[(e)] $\lim\limits_{n\to \infty} \wM_n f = f$, for $f\in W^2(\varphi)[0,1)$.
  \end{enumerate}
\end{proposition}

\begin{proof}
We have
\begin{align*}
  \wM_{n} f & = \sum_{k=0}^{\infty} u_{n,k}(f)\wP_{n,k}
              = \sum_{k=0}^{\infty} u_{n,k}(f)\Big(P_{n,k} - \frac{1}{n}\,\wD P_{n,k}\Big) \\
            & = \sum_{k=0}^{\infty} u_{n,k}(f) P_{n,k} - \frac{\varphi}{n}\sum_{k=0}^{\infty} u_{n,k}(f)D^2P_{n,k}
              = M_n f - \frac{1}{n}\,\varphi D^2M_n f \\
            & = M_n f - \frac{1}{n}\,\wD M_n f.
\end{align*}
Then from Proposition~\ref{pr:3.1}\,(b) we obtain
$$
  \wM_n f = M_n f - \frac{1}{n}\,\wD M_n f = M_n f - \frac{1}{n}\,M_n \wD f
          = M_n\Big(f-\frac{1}{n}\,\wD f\Big),
$$
which proves (a).

Now, commutative properties (b) and (c) follow from (a) and Proposition~\ref{pr:3.1}\,(b):
\begin{align*}
  \wD \wM_n f  & = \wD M_n\Big(f-\frac{1}{n}\,\wD f\Big) = M_n\Big(\wD f - \frac{1}{n}\,\wD \wD f\Big)
                           = \wM_n(\wD f), \\
  M_n \wM_n f & = M_n\Big(M_nf-\frac{1}{n}\,\wD M_n f \Big) = M_n M_n f - \frac{1}{n}\,M_n \wD M_n f \\
                        & = M_n M_n f - \frac{1}{n}\,\wD M_n M_n f = M_n (M_n f)-\frac{1}{n}\,\wD M_n (M_n f)
                            = \wM_n M_n f.
\end{align*}

The modified MKZ-GS operators commute in the sense of (d) since
\begin{align*}
  \wM_m \wM_n f & = \wM_m \Big(M_n f - \frac{1}{n}\,\wD M_n f\Big) \\
                & = M_m \Big(M_n f - \frac{1}{n}\,\wD M_n f\Big)
                    -\frac{1}{m} \wD M_m\Big(M_n f -\frac{1}{n}\,\wD M_n f\Big) \\
                & = M_m M_n \Big(f - \frac{m+n}{mn}\,\wD f + \frac{1}{mn}\,\wD^2 f\Big).
\end{align*}
The same expression in the last line we obtain for $\wM_n \wM_m f$ because of property (a) and
Proposition~\ref{pr:3.1}\,(b)--(c).

Applying Proposition~\ref{pr:3.1}\,(b),\,(e)--(f) we have
$$
  \|\wM_n f - f\| = \Big\|M_n f  -\frac{1}{n}\,M_n \wD f - f\Big\|
                   \le \|M_n f - f\| + \frac{1}{n}\,\big\|M_n \wD f\big\|
                   \le \frac{2}{n}\,\|\wD f\|.
$$
Therefore $\lim\limits_{n\to \infty} \|\wM_n f - f\|=0$, i.e. property (e) holds true.
\end{proof}

