\medskip
\section{Auxiliary Results for the Baskakov Basis Functions $\cP_{n,k}$} \label{s4}

Let $\x\in [0,\infty)$. It is easy to verify that the Baskakov basis functions $\cP_{n,k}$ satisfy
\begin{equation} \label{eq:4.1}
    k \cP_{n,k}(\x) = n\x\,\cP_{n+1,k-1}(\x), \qquad (n+k)\cP_{n,k}(\x) = n(1+\x)\cP_{n+1,k}(\x),
\end{equation}
setting $\cP_{n,k}:=0$ if $k<0$. The central moments of the Baskakov operator $\cB_n$ are
$$
  \mu_{n,j}(\x) = \cB_n\big((t-\x)^j,\x\big)
               = \sum_{k=0}^{\infty} \Big(\frac{k}{n}-\x\Big)^j \cP_{n,k}(\x), \qquad j=0,1,\ldots\,,
$$
with
\begin{equation} \label{eq:4.2}
  \mu_{n,0}(\x) = 1, \quad \mu_{n,1}(\x) = 0, \quad
  \mu_{n,2}(\x) = \frac{\psi(\x)}{n}, \qquad \mu_{n,3}(\x) = \frac{(1+2\x)\psi(\x)}{n^2}.
\end{equation}

Now we introduce a function that relates $\wcD \cP_{n,k}$ and $\cP_{n,k}$, namely
\begin{align} \label{eq:4.3}
  T_{n,k}(\x) & := k(k-1)\frac{1+\x}{\x} - 2k(n+k) + (n+k)(n+k+1)\frac{\x}{1+\x} \\
              & = n\bigg[-1-\frac{1+2\x}{\psi(\x)}\Big(\frac{k}{n}-\x\Big) + \frac{n}{\psi(\x)}\Big(\frac{k}{n}-\x\Big)^{\!2}\bigg].
                \notag
\end{align}
For its derivatives one can see that
\begin{align}
  T_{n,k}'(\x)  & = - \frac{k(k-1)}{\x^2} + \frac{(n+k)(n+k+1)}{(1+\x)^2}, \label{eq:4.4} \\
  T_{n,k}''(\x) & = \frac{2k(k-1)}{\x^3} - \frac{2(n+k)(n+k+1)}{(1+\x)^3}. \label{eq:4.5}
\end{align}

Below are a few more properties of the function $T_{n,k}(\x)$ that will be useful later on.

\begin{proposition}[{\cite[Proposition~2.3]{GaPaUl2025}}] \label{pr:4.1}

  \smallskip
  \! Let $\x\in [0,\infty)$.
  \begin{enumerate}
    \item[(a)] The following relation concerning functions $\cP_{n,k}$, $T_{n,k}$ and differential operator
                  $\wcD$ are valid:
                  \begin{equation} \label{eq:4.6}
                    \wcD \cP_{n,k}(\x) = T_{n,k}(\x) \cP_{n,k}(\x).
                 \end{equation}

    \smallskip
    \item[(b)] If $\,\alpha$ is an arbitrary real number, then
                  $$
                      \Phi_n(\alpha) := \sum_{k=0}^{\infty} \Big(\alpha - \frac{1}{n}\,T_{n,k}(\x)\!\Big)^2 \cP_{n,k}(\x)
                                              = \alpha^2 + 2 + \frac{2}{n}\,.
                  $$
  \end{enumerate}
\end{proposition}

\begin{proposition} \label{pr:4.2}
  For all $\x\in [0,\infty)$,
  $$
    \sum_{k=0}^{\infty} \,T_{n,k}(\x)\Big(\frac{k}{n}-\x\Big)\,\cP_{n,k}(\x) = 0.
  $$
\end{proposition}

\begin{proof}
From \eqref{eq:4.2} and \eqref{eq:4.3} we obtain
$$
  \sum_{k=0}^{\infty} \,T_{n,k}(\x)\Big(\frac{k}{n}-\x\Big)\cP_{n,k}(\x)
  = n\bigg[-\mu_{n,1}(\x)-\frac{1+2\x}{\psi(\x)}\,\mu_{n,2}(\x) + \frac{n}{\psi(\x)}\,\mu_{n,3}(\x)\bigg] = 0.
$$
%\begin{align*}
%  \sum_{k=0}^{\infty} \,T_{n,k}(\x)\Big(\frac{k}{n}-\x\Big)\cP_{n,k}(\x)
%    & = n\bigg[-\mu_{n,1}(\x)-\frac{1+2\x}{\psi(\x)}\,\mu_{n,2}(\x) + \frac{n}{\psi(\x)}\,\mu_{n,3}(\x)\bigg] \\
%    & = n\bigg[-0-\frac{1+2\x}{\psi(\x)}\,\frac{\psi(\x)}{n} + \frac{n}{\psi(\x)}\,\frac{(1+2\x)\psi(\x)}{n^2}\bigg] = 0.
%\end{align*}
\end{proof}

