\medskip
\section{A Direct Inequality} \label{s5}

We will first prove the next upper estimate for the norm of the modified MKZ-GS operator $\wM_n$
defined in \eqref{eq:1.5}.

\begin{lemma} \label{le:5.1}
  If $\,n\in \mathbb{N},$  $n\ge 2$ and $f\in C[0,1)$, then
  \begin{equation} \label{eq:5.1}
    \big\|\wM_n f\big\| \le \sqrt{6}\,\|f\|, \qquad\mbox{i.e.} \qquad  \|\wM_n\| \le \sqrt{6}.
  \end{equation}
\end{lemma}

\begin{proof}
In view of Proposition~\ref{pr:2.5}, it is sufficient to prove that if $\w(\x)=(1+\x)^{-1}$,
$n\in\mathbb{N}$, $n\ge 2$, and $\f\in C[0,\infty)$, then
\begin{equation} \label{eq:5.2}
  \| \w \wV_n \f\|_{[0,\infty)} \le \,\sqrt{6}\, \|\w\f\|_{[0,\infty)}.
\end{equation}

Obviously, $|v_{n,k}(\w^{-1}\w\f)| \le \|\w\f\|_{[0,\infty)}|v_{n,k}(\w^{-1})|$. Then for
$\x\in [0,\infty)$ we have
\begin{align*}
  \big|\w(\x)\wV_n(\f,\x)\big|
    & \le \w(\x)\sum_{k=0}^\infty |v_{n,k}(\f)|\,\big|\wcP_{n,k}(\x)\big|
      = \w(\x) \sum_{k=0}^\infty |v_{n,k}(\w^{-1}\w\f)|\,\big|\wcP_{n,k}(\x)\big| \\
    & \le \|\w\f\|_{[0,\infty)}\, \w(\x)\sum_{k=0}^\infty v_{n,k}(\w^{-1})\,\big|\wcP_{n,k}(\x)\big| \\
    & = \|\w\f\|_{[0,\infty)}\, \w(\x)\sum_{k=0}^\infty \frac{n+k}n\,\big|\wcP_{n,k}(\x)\big|,
\end{align*}
i.e.
\begin{equation} \label{eq:5.3}
  \big|\w(\x)\wV_n(\f,\x)\big| \le
  \|\w\f\|_{[0,\infty)}\, \w(\x)\sum_{k=0}^\infty \frac{n+k}n\,\big|\wcP_{n,k}(\x)\big|\,.
\end{equation}
From \eqref{eq:2.10} and \eqref{eq:4.6} we get
$$
  \wcP_{n,k}(\x) = \Big(1 - \frac{1}{n}\,T_{n,k}(\x)\Big) \cP_{n,k}(\x).
$$
Then the Cauchy inequality, \eqref{eq:4.2} and Proposition~\ref{pr:4.1}\,(b) with
$\alpha=1$ yield
\begin{align*}
  \w(\x)\sum_{k=0}^{\infty} \frac{n+k}n\,\big|\wcP_{n,k}(\x)\big|
  & = \w(\x)\sum_{k=0}^{\infty} \Big|1 - \frac{1}{n}\,T_{n,k}(\x)\Big| \frac{n+k}n\,\cP_{n,k}(\x) \\
  & \le \w(\x) \sqrt{\sum_{k=0}^{\infty} \Big(1-\frac{1}{n}\,T_{n,k}(\x)\Big)^{\!2} \cP_{n,k}(\x)}\,
             \sqrt{\sum_{k=0}^{\infty} \Big(\frac{k}{n}+1\Big)^{\!2} \cP_{n,k}(\x)} \\
  & = \w(\x) \sqrt{\Phi_n(1)}\,\sqrt{(1+\x)^2+\frac{\psi(\x)}{n}} \\
  & = \w(\x) \sqrt{3 + \frac{2}{n}}\,\sqrt{(1+\x)^2\Big(1+\frac{\x}{n(1+\x)}\Big)} \\
  & \le \sqrt{3 + \frac{2}{n}}\,\sqrt{1+\frac{1}{n}}\,.
\end{align*}
Hence for $\x\in [0,\infty)$  we have
\begin{equation} \label{eq:5.4}
  \w(\x)\sum_{k=0}^{\infty} \frac{n+k}n\,\big|\wcP_{n,k}(\x)\big| \le \sqrt{6}, \qquad n\ge 2.
\end{equation}

Now, inequality \eqref{eq:5.2} follows immediately from \eqref{eq:5.3} and \eqref{eq:5.4}.

To complete the proof of the lemma, we apply \eqref{eq:5.2}, \eqref{eq:2.12} and \eqref{eq:2.13}:
$$
  \big\|\wM_n f\big\| =   \| \w \wV_n \f\|_{[0,\infty)}
                      \le \sqrt{6}\, \|\w\f\|_{[0,\infty)}
                      = \sqrt{6}\, \|f\|.
$$
\end{proof}

To prove a direct theorem for the approximation rate for functions $f$ by the modified MKZ-GS
operator $\wM_n f$ we need a Jackson type inequality.

\begin{lemma} \label{le:5.2}
  If $\,n\in \mathbb{N}$, $f\in W^2_0(\varphi)[0,1)$ and $\wD f\in W^2(\varphi)[0,1)$, then
  $$
    \big\|\wM_n f - f\big\| \le \frac{1}{n^2}\,\|\wD^2 f\|.
  $$
\end{lemma}

\begin{proof}
Combining Proposition~\ref{pr:3.1}\,(a) with Proposition~\ref{pr:3.2}\,(a)--(b) we obtain
\begin{align*}
  \wM_k f - \wM_{k+1} f
    & = M_k f - \frac{1}{k}\,\wD M_k f - M_{k+1} f + \frac{1}{k+1}\,\wD M_{k+1} f \\
    & = \frac{1}{k(k+1)}\wD M_k f - \frac{1}{k}\,\wD M_k f + \frac{1}{k+1}\,\wD M_{k+1} f \\
%   & = \Big(\frac{1}{k}-\frac{1}{k+1}\Big)\wD M_k f + \frac{1}{k+1}\,\wD M_{k+1} f - \frac{1}{k}\,\wD M_k f \\
    & = - \frac{1}{k+1}\big(\wD M_k f - \wD M_{k+1} f\big)
      = - \frac{1}{k+1}\big(M_k \wD f - M_{k+1} \wD f\big) \\
    & = - \frac{1}{k+1}\cdot\frac{1}{k(k+1)}\, \wD M_k \wD f,
\end{align*}
i.e.
$$
  \wM_k f - \wM_{k+1} f = - \frac{1}{k(k+1)^2}\,\wD M_k \wD f.
$$
Therefore for every $s>n$ we have
\begin{gather*}
 \wM_n f - \wM_s f = \sum_{k=n}^{s-1} \big(\wM_k f - \wM_{k+1} f\big)
                   = - \sum_{k=n}^{s-1} \frac{1}{k(k+1)^2}\,\wD M_k \wD f.
\end{gather*}
Letting $s\to\infty$ by Proposition~\ref{pr:3.2}\,(a) and (e) we obtain
\begin{equation} \label{eq:5.5}
  \wM_n f - f = - \sum_{k=n}^{\infty} \frac{1}{k(k+1)^2}\,\wD M_k \wD f
              = - \sum_{k=n}^{\infty} \frac{1}{k(k+1)^2}\,M_k \wD^2 f.
\end{equation}
Then Proposition~\ref{pr:3.1}\,(e) yields
$$
  \|\wM_n f - f\| \le \sum_{k=n}^{\infty} \frac{1}{k(k+1)^2}\,\big\|\wD M_k \wD f\big\|
                  \le \sum_{k=n}^{\infty} \frac{1}{k(k+1)^2}\,\big\|\wD^2 f\big\|.
$$
Since $\sum_{k=n}^{\infty} \frac{1}{k(k+1)^2}\le \frac{1}{n^2}$
(see e.g. \cite[Proposition~5, eq.~(20)]{GaPaUl2025}) we conclude that
$$
  \big\|\wM_n f - f\big\| \le \frac{1}{n^2}\,\big\|\wD^2 f\big\|.
$$
\end{proof}

%A direct result on the approximation rate of functions $f\in C[0,1)$ by the operators
%\eqref{eq:1.5} in means of the K-functional \eqref{eq:1.6} follows immediately from both
%lemmas above.

\smallskip
\begin{proof}[Proof of Theorem~\ref{th:1.1}]
Let $g$ be any function with $g\in W^2_0(\varphi)[0,1)$ and $\wD g\in W^2(\varphi)[0,1)$.
Then by Lemma~\ref{le:5.1} and Lemma~\ref{le:5.2} we obtain
\begin{align*}
  \big\|\wM_n f-f\big\|
    & \le \big\|\wM_n f-\wM_n g\big\| + \big\|\wM_n g-g\big\| + \|g-f\| \\
    & \le \sqrt{6}\,\|f-g\| + \frac{1}{n^2}\,\big\|\wD^2 g\big\| + \|f-g\| \\
    & \le \big(\sqrt{6}+1\big)\Big(\|f-g\|+\frac{1}{n^2}\,\big\|\wD^2 g\big\|\Big).
\end{align*}
Taking the infimum over all functions $g\in W^2_0(\varphi)[0,1)$ with $\wD g\in W^2(\varphi)[0,1)$
we obtain
$$
  \big\|\wM_n f-f\big\| \le \big(\sqrt{6}+1\big)\,K\Big(f,\frac{1}{n}\Big).
$$
\end{proof}

