\bigskip
\section{A Strong Converse Result} \label{s6}

First, we will prove a Voronovskaya type result for the operator $\wM_n$.

\begin{lemma} \label{le:6.1}
  If $\,n\ge 2$, $n\in \mathbb{N}$, $\,\lambda(n) = \sum\limits_{k=n}^{\infty} \dfrac{1}{k(k+1)^2}$,
  $\,\theta(n) = \sum\limits_{k=n}^{\infty} \dfrac{1}{k^2(k+1)^2}$, and $f\in C[0,1)$ is such that
  $f,\,\wD f\in W^2_0(\varphi)[0,1)$ and $\wD^3 f\in L_{\infty}[0,1)$, then
  \begin{equation} \label{eq:6.1}
    \big\|\wM_n f - f + \lambda(n)\wD^2 f\big\| \le \theta(n)\,\big\|\wD^3 f\big\|.
  \end{equation}
\end{lemma}

\begin{proof}
We have from \eqref{eq:5.5} that
$$
  \wM_n f - f + \lambda(n)\wD^2 f
    = - \sum_{k=n}^{\infty} \frac{M_k\wD^2 f}{k(k+1)^2} + \sum_{k=n}^{\infty} \frac{\wD^2 f}{k(k+1)^2}
    = \sum_{k=n}^{\infty} \frac{\wD^2 f - M_k \wD^2 f}{k(k+1)^2}.
$$
Then
$$
  \big\|\wM_n f - f + \lambda(n)\wD^2 f\big\|
  \le \sum_{k=n}^{\infty} \frac{1}{k(k+1)^2}\,\big\|\wD^2 f - M_k \wD^2 f\big\|.
$$
Using the Jackson inequality Proposition~\ref{pr:3.1}\,(f) with $\wD^2 f$ replacing $g$ we obtain
$$
  \big\|\wM_n f - f + \lambda(n)\wD^2 f\big\|
    \le \sum_{k=n}^{\infty} \frac{1}{k(k+1)^2}\cdot\frac{1}{k}\,\big\|\wD \wD^2 f\big\|
    = \theta(n)\,\big\|\wD^3 f\big\|.
$$
\end{proof}

The following is an inequality of Bernstein type.

\begin{lemma} \label{le:6.2}
  If $n\in\mathbb{N}$, $n\ge 17$ and $f\in C[0,1)$, then
  \begin{equation} \label{eq:6.2}
    \|\wD \wM_n f\| \le \wC\, n\|f\|, \qquad \text{where} \ \wC=17.
  \end{equation}
\end{lemma}

\begin{proof}
Because of Proposition~\ref{pr:2.5}, it is sufficient to prove that if $\w(\x)=(1+\x)^{-1}$,
$n\in\mathbb{N}$, and $\f\in C[0,\infty)$, then for $n\ge 17$ the inequality
\begin{equation} \label{eq:6.3}
  \| \w\wcD \wV_n \f\|_{[0,\infty)} \le \wC\, n\|\w\f\|_{[0,\infty)}
\end{equation}
holds true, where $\wC=17$\,.

Similarly to the proof of Lemma~\ref{le:5.1}, for $\x\in [0,\infty)$ we have
%\begin{align*}
%  \big|\w(\x) \wcD \wV_n(\f,\x)\big|
%    & \le \w(\x) \sum_{k=0}^\infty |v_{n,k}(\f)|\,\big|\wcD\wcP_{n,k}(\x)\big| \\
%    & \le \w(\x) \sum_{k=0}^\infty |v_{n,k}(\w^{-1}\w\f)|\,\big|\wcD\wcP_{n,k}(\x)\big| \\
%   & = \|\w\f\|_{[0,\infty)} \w(\x) \sum_{k=0}^\infty v_{n,k}(w^{-1})\,\big|\wcD\wcP_{n,k}(\x)\big| \\
%    & \le \|\w\f\|_{0,\infty)} \w(\x) \sum_{k=0}^\infty \frac{n+k}n\,\big|\wcD\wcP_{n,k}(\x)\big|,
%\end{align*}
$$
  \big|\w(\x) \wcD \wV_n(\f,\x)\big| \le \w(\x) \sum_{k=0}^\infty |v_{n,k}(\f)|\,\big|\wcD\wcP_{n,k}(\x)\big|,
$$
hence
\begin{equation} \label{eq:6.4}
  \big|\w(\x) \wcD\wV_n(\f,\x)\big| \le \|\w\f\|_{[0,\infty)} \w(\x) \sum_{k=0}^\infty \frac{n+k}n\,\big|\wcD\wcP_{n,k}(\x)\big|.
\end{equation}

In order to estimate the expression on the right-hand side of \eqref{eq:6.4} we use the relation
\begin{align*}
  \wcD \wcP_{n,k}(\x) & = \frac{\psi(\x)}{n}\,T_{n,k}''(\x) \cP_{n,k}(\x)
                                        + 2\big[T_{n+1,k-1}(\x)\cP_{n+1,k-1}(\x) +T_{n+1,k}(\x)\cP_{n+1,k}(\x)\big] \\
                      & \qquad + \Big(1 - \frac{1}{n}\,T_{n,k}(\x)\!\Big) T_{n,k}(\x) \cP_{n,k}(\x),
\end{align*}
see the proof of Lemma~4, p.~11, in \cite{GaPaUl2025}. Therefore
$$
   \w(\x) \sum_{k=0}^{\infty} \frac{n+k}n\,\big|\wcD \wcP_{n,k}(\x)\big| \le \ca_n(\x) + \cb_n(\x) + \cc_n(\x),
$$
where
\begin{align*}
  \ca_n(\x) & = \w(\x) \frac{\psi(\x)}{n} \sum_{k=0}^{\infty} \big|T_{n,k}''(\x)\big| \frac{n+k}n\,\cP_{n,k}(\x), \\
  \cb_n(\x) & = 2\w(\x) \sum_{k=0}^{\infty} |T_{n+1,k-1}(\x) | \frac{n+k}n\,\cP_{n+1,k-1}(\x) \\
            & \qquad + 2\w(\x) \sum_{k=0}^{\infty} |T_{n+1,k}(\x)| \frac{n+k}n\,\cP_{n+1,k}(\x), \\
  \cc_n(\x) & = \w(\x) \sum_{k=0}^{\infty} \Big|\Big(1 - \frac{1}{n}\,T_{n,k}(\x)\!\Big) T_{n,k}(\x)\Big| \frac{n+k}n\,\cP_{n,k}(\x).
\end{align*}

\smallskip
{\sl (i) \ Estimation of $\ca_n(\x)$.}
From \cite[Proof of Lemma~4, eq.~(30)]{GaPaUl2025} we have
\begin{equation} \label{eq:6.5}
  \frac{\psi(\x)}{n} \sum_{k=0}^{\infty} |T_{n,k}''(\x)| \cP_{n,k}(\x) \le 6n, \qquad\text{for all} \ \ n\ge 17, \ \ \x\in [0,\infty).
\end{equation}
Since $T_{n,k}''(\x) = T_{n+1,k}''(\x) + \frac{4(n+k+1)}{(1+\x)^3}$, combining with \eqref{eq:4.1}
and \eqref{eq:6.5} we have
\begin{align*}
  \ca_n(\x) & = \frac{\psi(\x)}{n} \sum_{k=0}^{\infty} |T_{n,k}''(\x)| \cP_{n+1,k}(\x) \\
            & = \frac{\psi(\x)}{n} \sum_{k=0}^{\infty} \bigg|T_{n+1,k}''(\x)+\frac{4(n+k+1)}{(1+\x)^3}\bigg| \cP_{n+1,k}(\x) \\
            & \le \frac{n+1}{n}\, \frac{\psi(\x)}{n+1} \sum_{k=0}^{\infty} \big|T_{n+1,k}''(\x)\big| \cP_{n+1,k}(\x)+ \frac{4\psi(\x)}{n} \sum_{k=0}^{\infty} \frac{n+k+1}{(1+\x)^3}\, \cP_{n+1,k}(\x) \\
            & \le \frac{n+1}{n}\,6(n+1)+\frac{4\psi(\x)}{(1+\x)^3}\,\frac{n+1}{n} \sum_{k=0}^{\infty} \Big(1+\frac{k}{n+1}\Big) \cP_{n+1,k}(\x) \\
            & = \frac{6(n+1)^2}{n} + \frac{4\psi(\x)}{(1+\x)^3}\,\frac{n+1}{n}\,(1+\x) \\
            & = \frac{6(n+1)^2}{n} + \frac{4\x}{(1+\x)}\,\frac{n+1}{n} \\
            & \le \frac{6(n+1)^2}{n}+\frac{4(n+1)}{n}\,.
\end{align*}
Hence for $n\ge 14$,
\begin{equation} \label{eq:6.6}
  \ca_n(x) \le 7\,n, \qquad x\in [0,\infty).
\end{equation}

\smallskip
{\sl (ii) \ Estimation of $\cb_n(\x)$.} We have

\begin{align*}
  \frac{\cb_n(\x)}{2\w(\x)} & = \sum_{k=0}^{\infty} |T_{n+1,k-1}(\x) | \frac{n+k}n\,\cP_{n+1,k-1}(\x) + \sum_{k=0}^{\infty} |T_{n+1,k}(\x)| \frac{n+k}n\,\cP_{n+1,k}(\x) \\
                 & = \sum_{k=0}^{\infty} |T_{n+1,k}(\x) | \frac{n+1+k}n\,\cP_{n+1,k}(\x) + \sum_{k=0}^{\infty} |T_{n+1,k}(\x)| \frac{n+k}n\,\cP_{n+1,k}(\x) \\
                 & = \frac{n+1}{n} \sum_{k=0}^{\infty} |T_{n+1,k}(\x)| \frac{n+1+k}{n+1}\,\cP_{n+1,k}(\x) \\
                 & \qquad + \frac{n+1}{n} \sum_{k=0}^{\infty} |T_{n+1,k}(\x)| \Big(\frac{n+1+k}{n+1}-\frac{1}{n+1}\Big)\,\cP_{n+1,k}(\x) \\
                 & = \frac{2(n+1)}{n} \sum_{k=0}^{\infty} |T_{n+1,k}(\x)| \frac{n+1+k}{n+1}\,\cP_{n+1,k}(\x)
                     - \frac{1}{n} \sum_{k=0}^{\infty} |T_{n+1,k}(\x)|\,\cP_{n+1,k}(\x) \\
                 & \le \frac{2(n+1)}{n} \sum_{k=0}^{\infty} |T_{n+1,k}(\x)| \frac{n+1+k}{n+1}\,\cP_{n+1,k}(\x)
\end{align*}

By the Cauchy inequality and Proposition~\ref{pr:4.1}\,(b) with $\alpha=0$ we obtain
\begin{align*}
  \cb_n(\x) & \le 4\w(\x) \frac{n+1}{n} \sqrt{\sum_{k=0}^{\infty} T_{n+1,k}^2(\x) \cP_{n+1,k}(\x)}\,\sqrt{\sum_{k=0}^{\infty} \Big(\frac{n+1+k}{n+1}\Big)^2 \cP_{n+1,k}(\x)} \\
            & = 4\w(\x)\,\frac{n+1}{n}\sqrt{(n+1)^2\,\Phi_{n+1}(0)}\:\sqrt{(1+\x)^2+\frac{\psi(\x)}{n+1}} \\
            & = \frac{4(n+1)^2}{n}\,\sqrt{2+\frac2{n+1}}\,\sqrt{1+\frac{\x}{(1+\x)(n+1)}} \\
            & \le \frac{4\sqrt{2}\,(n+1)(n+2)}{n}\,.
\end{align*}
Obviously, for all $n\ge 17$,
\begin{equation} \label{eq:6.7}
  \cb_n(\x) \le 7\,n, \qquad \x\in [0,\infty).
\end{equation}

\smallskip
{\sl (iii) \ Estimation of $\cc_n(\x)$.} Let us first point out that from \eqref{eq:4.3} it follows
\begin{equation} \label{eq:6.8}
  T_{n,k}(\x) = T_{n+1,k}(\x) + \frac{2(n+1)}{1+\x}\Big(\frac{k}{n+1}-\x\Big).
\end{equation}

By applying \eqref{eq:4.1} and the Cauchy inequality we have
\begin{align*}
  \cc_n(\x) % & = \w(\x) \sum_{k=0}^{\infty} \Big|\Big(1 - \frac{1}{n}\,T_{n,k}(\x)\!\Big) T_{n,k}(\x)\Big| \frac{n+k}n\,\cP_{n,k}(\x) \\
                & = \sum_{k=0}^{\infty} \Big|\Big(1 - \frac{1}{n}\,T_{n,k}(\x)\!\Big) T_{n,k}(\x)\Big| \frac{n+k}{n(1+\x)}\,\cP_{n,k}(\x) \\
                & = \sum_{k=0}^{\infty} \Big|T_{n,k}(\x)\Big(1 - \frac{1}{n}\,T_{n,k}(\x)\Big)\Big| \cP_{n+1,k}(\x) \\
                & \le \sqrt{\sum_{k=0}^{\infty} T_{n,k}^2(\x) \cP_{n+1,k}(\x)}\,
                        \sqrt{\sum_{k=0}^{\infty} \Big(1-\frac{1}{n}\,T_{n,k}(\x)\Big)^{\!2} \cP_{n+1,k}(\x)}.
\end{align*}

From \eqref{eq:6.8} we obtain
\begin{align*}
  & \sum_{k=0}^{\infty} T_{n,k}^2(\x) \cP_{n+1,k}(\x) \\
  & \qquad = \sum_{k=0}^{\infty} \Big[T_{n+1,k}(\x)+\frac{2(n+1)}{1+\x}\Big(\frac{k}{n+1}-\x\Big)\Big]^2\,\cP_{n+1,k}(\x) \\
  & \qquad = \sum_{k=0}^{\infty} T_{n+1,k}^2(\x) \cP_{n+1,k}(\x) + \frac{4(n+1)}{1+\x} \sum_{k=0}^{\infty} T_{n+1,k}(\x) \Big(\frac{k}{n+1}-\x\Big) \cP_{n+1,k}(\x) \\
  & \qquad\qquad + \frac{4(n+1)^2}{(1+\x)^2} \sum_{k=0}^{\infty} \Big(\frac{k}{n+1}-\x\Big)^{\!2} \cP_{n+1,k}(\x).
\end{align*}

Then \eqref{eq:4.2}, Proposition~\ref{pr:4.2} and Proposition~\ref{pr:4.1}\,(b) with $\alpha=0$ yield
\begin{align*}
  \sum_{k=0}^{\infty} T_{n,k}^2(\x) \cP_{n+1,k}(\x)
    & \le (n+1)^2\,\Phi_{n+1}(0) + 0 + \frac{4(n+1)^2}{(1+\x)^2}\,\mu_{n+1,2}(\x) \\
    & = (n+1)^2\Big(2+\frac{2}{n+1}\Big) + \frac{4(n+1)^2}{(1+\x)^2}\cdot\frac{\psi(\x)}{n+1} \\
    & \le 2(n+1)(n+2) + 4(n+1) \\
    & = 2(n+1)(n+4)\,.
\end{align*}
Moreover, using \eqref{eq:6.8} we get
\begin{align*}
  & \sum_{k=0}^{\infty} \Big(1-\frac{1}{n}\, T_{n,k}(\x) \Big)^{\!2} P_{n+1,k}(\x) \\
  & \qquad = \sum_{k=0}^{\infty} \Big[1-\frac{1}{n}\, T_{n+1,k}(\x) -\frac{2(n+1)}{n(1+\x)}\Big(\frac{k}{n+1}-\x\Big)\Big]^2\,\cP_{n+1,k}(\x) \\
  & \qquad = \sum_{k=0}^{\infty} \Big(1-\frac{1}{n}\, T_{n+1,k}(\x) \Big)^{\!2}\cP_{n+1,k}(\x)
                     - \frac{4(n+1)}{n(1+\x)} \sum_{k=0}^{\infty} \Big(\frac{k}{n+1}-\x\Big) \cP_{n+1,k}(\x) \\
  & \qquad\quad + \frac{4(n+1)}{n^2(1+\x)} \sum_{k=0}^{\infty} T_{n+1,k}(\x)\Big(\frac{k}{n+1}-\x\Big) \cP_{n+1,k}(\x) \\
  & \qquad\quad + \frac{4(n+1)^2}{n^2(1+\x)^2}\sum_{k=0}^{\infty} \Big(\frac{k}{n+1}-\x\Big)^{\!2} \cP_{n+1,k}(\x).
\end{align*}

Now, \eqref{eq:4.2}, Proposition~\ref{pr:4.2} and Proposition~\ref{pr:4.1}\,(b) with $\alpha=1$ yield
\begin{align*}
  \sum_{k=0}^{\infty} \Big(1-\frac1n T_{n,k}(\x) \Big)^{\!2} P_{n+1,k}(\x)
    & = \Phi_{n+1}(1) + 0 + 0 + \frac{4(n+1)^2}{n^2(1+\x)^2}\,\mu_{n+1,2}(\x) \\
    & = 3+\frac{2}{n+1} + \frac{4(n+1)^2}{n^2(1+\x)^2}\cdot\frac{\psi(\x)}{n+1} \\
    & \le 3+\frac{2}{n+1} + \frac{4(n+1)}{n^2}\,.
\end{align*}

Then for all $n\ge 16$ and $\x\in [0,\infty)$,
\begin{equation} \label{eq:6.9}
  \cc_n(x) \le \sqrt{2(n+1)(n+4)}\, \sqrt{3+\frac{2}{n+1} + \frac{4(n+1)}{n^2}}\le 3n.
\end{equation}

From \eqref{eq:6.6}, \eqref{eq:6.7} and \eqref{eq:6.9} we obtain that for all $n\ge 17$,
$$
  \w(\x) \sum_{k=0}^{\infty} \frac{n+k}n\,\big|\wcD \wcP_{n,k}(\x)\big|  \le \ca_n(\x) + \cb_n(\x) + \cc_n(\x) \le 17n, \qquad  \x\in [0,\infty),
$$
i.e.
$$
  \big\|\w\wcD\wV_n \f\big\| \le \wC n\|\w\f\|, \qquad \text{where} \ \wC = 17\,.
$$
\end{proof}

\smallskip
Finally, following the approach of Ditzian and Ivanov~\cite{DiIv1993} we prove a strong converse
inequality.

\smallskip
\begin{proof}[Proof of Theorem~\ref{th:1.2}]

Let $n\in\mathbb{N}$, $n\ge 17$, $f\in C[0,1)$ and $\lambda(n)$, $\theta(n)$ be defined as in
Lemma~\ref{le:6.1}. Applying the Voronovskaya type inequality in Lemma~\ref{le:6.1} for the
operator $\wM_{\ell}$ and function $\wM_n^3 f$ (triple iterated $\wM_n$) replacing $f$ we obtain
\begin{align*}
  \lambda(\ell) \big\|\wD^2 \wM_n^3 f\big\|
    & = \big\|\lambda(\ell)\wD^2 \wM_n^3 f\big\| \\
    & = \big\|\wM_{\ell} \wM_n^3 f - \wM_n^3 f +\lambda(\ell)\wD^2 \wM_n^3 f
        - \wM_{\ell} \wM_n^3 f + \wM_n^3 f\big\| \\
    & \le \big\|\wM_{\ell} \wM_n^3 f - \wM_n^3 f +\lambda(\ell)\wD^2 \wM_n^3 f\big\|
          + \big\|\wM_{\ell} \wM_n^3 f - \wM_n^3 f\big\| \\
    & \le \theta(\ell) \big\|\wD^3 \wM_n^3 f\big\| + \big\|\wM_n^3\big(\wM_{\ell} f - f\big)\big\|.
\end{align*}
Using Lemma~\ref{le:6.2} for the function $\wD^2 \wM_n^2 f$ and successively three times
Lemma~\ref{le:5.1} we get
\begin{align*}
  \lambda(\ell) \big\|\wD^2 \wM_n^3 f\big\|
    & \le \wC\,n\,\theta(\ell) \big\|\wD^2 \wM_n^2 f\big\| + 6\sqrt{6}\,\big\|\wM_{\ell}f - f\big\| \\
    & \le \wC\,n\,\theta(\ell) \big\|\wD^2 \wM_n^2 (f - \wM_n f) + \wD^2 \wM_n^3 f\big\|
          + 15\big\|\wM_{\ell}f - f\big\| \\
    & \le \wC\,n\,\theta(\ell) \big\|\wD^2 \wM_n^2 (f - \wM_n f)\big\|
          + \wC\,n\,\theta(\ell) \big\|\wD^2 \wM_n^3 f\big\| + 15\big\|\wM_{\ell}f - f\big\|.
\end{align*}
Application of the Bernstein type inequality Lemma~\ref{le:6.2} twice for $f-\wM_n f$ yields
$$
  \lambda(\ell) \big\|\wD^2 \wM_n^3 f\big\|
  \le \wC^3 n^3\theta(\ell) \big\|f - \wM_n f\big\|
      + 15\big\|\wM_{\ell} f - f\big\| + \wC\,n\,\theta(\ell) \big\|\wD^2 \wM_n^3 f\big\|.
$$
For $\lambda(n)$ and $\theta(n)$ (see \cite{GaPaUl2025}[Proposition~5]) we have the estimates
$$
  \frac{1}{3n^2} \le \lambda(n) \le \frac{1}{n^2}\,, \qquad
  \theta(n) \le \frac{4}{9n^3}\, \qquad n\ge 2.
$$
Then, applying the lower bound for $\lambda(n)$ we obtain
%$$
%  \frac{1}{3\ell^2} \big\|\wD^2 \wM_n^3 f\big\|
%  \le \frac{4\wC^3 n^3}{9\ell^3} \big\|f - \wM_n f\big\|
%      + 15\big\|\wM_{\ell} f - f\big\| + \frac{4\wC n}{9\ell^3} \big\|\wD^2 \wM_n^3 f\big\|,
%$$
%i.e.
$$
  \frac{1}{\ell^2} \big\|\wD^2 \wM_n^3 f\big\|
  \le \frac{4\wC^3 n^3}{3\ell^3} \big\|f - \wM_n f\big\|
      + 45\big\|\wM_{\ell} - f\big\| + \frac{4\wC n}{3\ell^3} \big\|\wD^2 \wM_n^3 f\big\|.
$$

Now we choose $\ell$ sufficiently large such that
$$
  \frac{4\wC n}{3\ell^3} \le \frac{1}{2\ell^2}, \qquad\text{i.e.}\qquad \ell \ge \frac{8\wC}{3}\,n.
$$
If we set $L=\frac{8\wC}{3}$, for all integers $\ell\ge Ln$ we have
\begin{align}
  \frac{1}{\ell^2} \big\|\wD^2 \wM_n^3 f\big\|
    & \le \frac{4\wC^3 n^3}{3\ell^3} \big\|f - \wM_n f\big\|
        + 45\big\|\wM_{\ell} f - f\big\| + \frac{1}{2\ell^2} \big\|\wD^2 \wM_n^3 f\big\|, \notag\\
  \frac{1}{2\ell^2} \big\|\wD^2 \wM_n^3 f\big\|
    & \le \frac{4\wC^3 n^3}{3\ell^3} \big\|f - \wM_n f\big\| + 45\big\|\wM_{\ell} f - f\big\|, \notag\\
  \frac{1}{n^2} \big\|\wD^2 \wM_n^3 f\big\|
    & \le \wC^2\,\big\|f - \wM_n f\big\|
        + 90\frac{\ell^2}{n^2}\,\big\|\wM_{\ell} f - f\big\|. \label{eq:6.10}
\end{align}
By Lemma~\ref{le:5.1},
\begin{equation} \label{eq:6.11}
  \begin{aligned}
    \big\|f-\wM_n^3 f\big\|
      & \le \big\|f - \wM_n f\big\| + \big\|\wM_n f - \wM_n^2 f\big\| + \big\|\wM_n^2 f - \wM_n^3 f\big\| \\
      & \le \big\|f - \wM_n f\big\| + \sqrt{6}\big\|f - \wM_n f\big\| + 6\big\|f - \wM_n f\big\| \\
      & < 10\big\|f - \wM_n f\big\|.
  \end{aligned}
\end{equation}
Since $\wM_n^3 f\in W^2_0(\psi)$, from \eqref{eq:6.10} and \eqref{eq:6.11} it follows
\begin{align*}
  K\Big(f,\frac{1}{n^2}\Big)
    & = \inf \Big\{\|f-g\| + \frac{1}{n^2}\,\big\|\wD^2 g\big\|: \ g\in W^2_0(\psi),\,\wD g\in W^2(\psi)  \Big\} \\
    & \le \big\|f-\wM_n^3 f\| + \frac{1}{n^2}\,\big\|\wD^2 \wM_n^3 f\big\| \\
    & \le \big(10+\wC^2\big)\big\|\wM_n f-f\big\|
          + 90\,\frac{\ell^2}{n^2}\,\big\|\wM_{\ell} f-f\big\|.
\end{align*}

Hence, we obtain the following upper estimate of the K-functional,
$$
  K\Big(f,\frac{1}{n^2}\Big) \le
  C\,\frac{\ell^2}{n^2}\big(\big\|\wM_n f - f \big\| + \big\|\wM_{\ell} f - f) \big\| \big),
$$
for all $\ell\ge Ln$, where $C=10+\wC^2$ and $L=\frac{8\wC}{3}$, $\wC=17$\,.
\end{proof}

