\title{$\mathbb{E}_2$-algebra structures on the derived center of an algebraic scheme}
\author[S. Farr]{Sonja M. Farr}
\address{Department of Mathematics \& Statistics, University of Nevada,  Reno.}
\email{sonjaf@unr.edu}

