%\[
%\mathbf{c}_{2k + 1} := \mathbf{a}_{2k + 1} (1 - \varkappa)^{-1} + \mathbf{b}_{2k + 1}.
%\]
%This completes the proof.
%\end{proof}


\begin{proof}
We prove Theorem \ref{thm2} by induction. The case $k=0$ follows from Theorem \ref{thm1} with $\mathbf{c}:=(1-\varkappa)^{-1}$. We assume that Theorem \ref{thm2} holds when $k\ge 0$. 

Using the Fourier representation
\[
\langle \xi \rangle^2 \widehat{\mathbf{u}} = -\widehat{V\mathbf{u}} + \hat{f},
\]
we obtain
\[
\langle \xi \rangle^{k+3} \widehat{\mathbf{u}} = -\langle\xi\rangle^{k+1}\widehat{V\mathbf{u}} + \langle\xi\rangle^{k+1}\hat{f}.
\]
Hence, we obtain from \eqref{prod}
\[
\|\mathbf{u}\|_{B^{k+3}} \le 2^{(k+1)/2} (2\pi)^{-n} \|V\|_{B^{k+1}} \|\mathbf{u}\|_{B^{k+1}} + \|f\|_{B^{k+1}}.
\]
From the assumption by induction, we have
\begin{align*}
\|\mathbf{u}\|_{B^{k+3}} &\le 2^{(k+1)/2} (2\pi)^{-n} \mathbf{c}\|V\|_{B^{k+1}} \|f\|_{B^k} + \|f\|_{B^{k+1}}
\\
&\le \left(2^{(k+1)/2} (2\pi)^{-n} \mathbf{c}\|V\|_{B^{k+1}} +1\right)\|f\|_{B^{k+1}},
\end{align*}
where $\mathbf{c}=\mathbf{c}(n,k,V)>0$ is a constant. By setting the generic constant as
\[
\mathbf{c}(n,k+1,V):=2^{(k+1)/2} (2\pi)^{-n} \mathbf{c}(n,k,V)\|V\|_{B^{k+1}} +1,
\]
we complete the proof.
\end{proof}


To establish the $ B^{s+2} $-regularity for solutions of \eqref{Sc} when $ s \in (0, \infty) \setminus \mathbb{N} $, it is necessary to solve the equation \eqref{Sc} directly. For this purpose, we introduce the following set
\[
\mathscr{V}_s := \left\{ V \in B^s ; \; 2^{s/2} (2\pi)^{-n} \|V\|_{B^s} < 1 \right\}.
\]
By adapting the methodology employed in the proof of Theorem \ref{thm1}, we derive the following result.


\begin{theorem}\label{thm2.b}
Let $ s \geq 0 $ be a real number and $ V \in \mathscr{V}_s $. For every $ f \in B^s $, the equation \eqref{Sc} admits a unique solution $ \mathbf{u} \in B^{s+2} $ satisfying the estimate
\[
\|\mathbf{u}\|_{B^{s+2}} \leq \mathbf{c} \|f\|_{B^s},
\]
where $\mathbf{c}:=(1-2^{s/2} (2\pi)^{-n} \|V\|_{B^s})^{-1}$ is a constant.
\end{theorem}

\subsubsection{Spectral analysis for Schr\"odinger equations}

To investigate the Schr\"odinger equation without assuming a smallness condition on the potential, we conduct a spectral analysis of Schr\"odinger equations within the framework of spectral Barron spaces. 

Let $ \lambda \in \mathbb{C} \setminus \{0\} $ and $ V \in B^0 \setminus \{0\} $. Consider the eigenvalue problem
\begin{equation}\label{sp0}
(1-\Delta +\lambda V)u=0.
\end{equation}
We reformulate \eqref{sp0} into the following equation:
\begin{equation}\label{sp2}
Tu:=(1-\Delta )^{-1}Vu= -\lambda^{-1}u.
\end{equation}
Let $ \|T\| $ denote the operator norm of $ T $ in $ \mathscr{B}(B^0) $. Then, by the definition of the $ B^0 $ norm, we have
\[
\|T\| \leq (2\pi)^{-n} \|V\|_{B^0} =: \varkappa.
\]
Since $ T $ is compact by Proposition \ref{procm2}, it follows from \cite[Proposition 1.8]{Ch} that the spectrum $ \sigma(T) $ is contained in the ball $B(0, \varkappa)$. 
Moreover, the spectrum $ \sigma(T) $ is either trivial ($ \sigma(T) = \{0\} $) or its non-zero part $ \sigma(T) \setminus \{0\} $ consists of isolated eigenvalues (e.g., \cite[Lemma 1.10]{Ch}).


\begin{theorem}\label{thmsp}
Let $ V \in B^0 \setminus \{0\} $. For all $ -\lambda^{-1} \in \rho(T) = \mathbb{C} \setminus \sigma(T) $ and $ f \in B^0 $, the equation 
\[
(1 - \Delta + \lambda V) u = f
\]
admits a unique solution $ u \in B^2 $. Moreover, if $ V \in B^j $ and $ f \in B^j $ for some integer $ j \geq 1 $, then $ u \in B^{j+2} $, and the following estimate holds:
\begin{equation}\label{tsp}
\|u\|_{B^{j+2}}\le \gamma_j\left(|\lambda|\|V\|_{B^j}+1\right)^{j+1}\|f\|_{B^j},
\end{equation} 
where $ \gamma_j=\gamma_j(n)>0 $ is a  constant.
\end{theorem}

\begin{proof}
Let $ -\lambda^{-1} \in \rho(T) $. Then, for all $ f \in B^0 $, there exists a unique solution $ u \in B^0 $ satisfying
\begin{equation}\label{sp3}
Tu=-\lambda^{-1}u+f.
\end{equation}
Let $ (f_j) $ be a sequence in $ \mathscr{S} $ converging to $ f $ in $ B^0 $, and let $ u_j \in B^0 $ be the solution of \eqref{sp3} when $ f $ is replaced by $ f_j $. Since $ T u_j \in B^2 $, it follows that $ u_j \in B^2 $. 
Next, observe that
\begin{equation}\label{sp4}
\|u_j-u_k\|_{B^0}\le \|(T+\lambda^{-1})^{-1}\|\|f_j-f_k\|_{B^0}.
\end{equation}
Thus, $ (u_j) $ is a Cauchy sequence in $ B^0 $. Let $ v \in B^0 $ be the limit of $ (u_j) $ in $ B^0 $. Taking $ f = f_j $ in \eqref{sp3} and passing to the limit as $ j \to \infty $, we obtain $ v = u $. 

Now, using the identity
\[
(1 - \Delta)(u_j - u_k) = -\lambda V (u_j - u_k) + (f_j - f_k),
\]
we derive in the Fourier domain
\[
\langle \xi \rangle^2 \mathscr{F}(u_j - u_k) = -\lambda \mathscr{F}(V (u_j - u_k)) + \mathscr{F}(f_j - f_k).
\]
Taking norms, we get
\[
\|u_j - u_k\|_{B^2} \leq (2\pi)^{-n} |\lambda| \|V\|_{B^0} \|u_j - u_k\|_{B^0} + \|f_j - f_k\|_{B^0}.
\]
This shows that $ (u_j) $ is a Cauchy sequence in $ B^2 $, and hence $ u \in B^2 $. Moreover, we have
\begin{equation}\label{sp5}
\|u\|_{B^2}\le \mathbf{c}_0\|f\|_{B^0},
\end{equation}
where
\[
\mathbf{c}_0 := (2\pi)^{-n} |\lambda| \|V\|_{B^0} \|(T + \lambda^{-1})^{-1}\| + 1.
\]
Now, assume $ V \in B^1 \setminus \{0\} $ and $ f \in B^1 $. Then $ -\lambda V u + f \in B^1 $ and
\[
\|-\lambda V u + f\|_{B^1} \leq \sqrt{2} (2\pi)^{-n} |\lambda| \|V\|_{B^1} \|u\|_{B^1} + \|f\|_{B^1}.
\]

Using \eqref{sp5}, we obtain
\begin{equation}\label{sp6}
\|-\lambda Vu+f\|_{B^1}\le \left(\sqrt{2}(2\pi)^{-n}|\lambda|\|V\|_{B^1}\mathbf{c}_0+1\right)\|f\|_{B^1}.
\end{equation}
From the Fourier relation
\[
\langle \xi \rangle^3 \hat{u} = \langle \xi \rangle \mathscr{F}(-\lambda V u + f),
\]
and \eqref{sp6}, we deduce
\begin{equation}\label{sp7}
\|u\|_{B^3}\le \mathbf{c}_1\|f\|_{B^1},
\end{equation}
where
\[
\mathbf{c}_1 := \sqrt{2} (2\pi)^{-n} |\lambda| \|V\|_{B^1} \mathbf{c}_0 + 1.
\]

For general $ j \geq 1 $, assume $ V \in B^j \setminus \{0\} $ and $ f \in B^j $. Define
\[
\mathbf{c}_j := 2^{j/2} (2\pi)^{-n} |\lambda| \|V\|_{B^j} \mathbf{c}_{j-1} + 1.
\]
Using the inequality
\[
\|-\lambda V u + f\|_{B^j} \leq 2^{j/2} (2\pi)^{-n} |\lambda| \|V\|_{B^j} \|u\|_{B^j} + \|f\|_{B^j},
\]
an induction argument shows that
\begin{equation}\label{sp8}
\|u\|_{B^{j+2}}\le \mathbf{c}_j\|f\|_{B^j}.
\end{equation}
Finally, \eqref{tsp} follows from \eqref{sp8} by noting that $ \mathbf{c}_j $ can be bounded by \[ \gamma_j \left( |\lambda| \|V\|_{B^j} + 1 \right)^{j+1} \] for some constant $ \gamma_j=\gamma_j(n)>0 $. This completes the proof.
\end{proof}

\begin{theorem}\label{thmsp2}
Let $ V \in B^0 \setminus \{0\} $ and $ -\lambda^{-1} \in \sigma(T) \setminus \{0\} $. Then, the followings hold:
\\
$\mathrm{(i)}$ The null space $ N(T + \lambda^{-1}) $ is finite-dimensional.
\\
$\mathrm{(ii)}$ Each $ u \in N(T + \lambda^{-1}) $ belongs to $ B^2 $ and is a solution to the equation
\[
(T + \lambda^{-1})u = 0.
\]
$\mathrm{(iii)}$ If $ V \in B^j $ for some $ j \geq 1 $ and $ u \in N(T + \lambda^{-1}) $, then $ u \in B^{j+2} $ and the following inequality holds:
\begin{equation}\label{sp9}
\|u\|_{B^{j+2}} \leq 2^{j(j+1)/4} \left[(2\pi)^{-n} |\lambda| \|V\|_{B^j}\right]^j \|u\|_{B^0}.
\end{equation}
\end{theorem}

\begin{proof}
The finite-dimensionality of $ N(T + \lambda^{-1}) $ follows from the compactness of the operator $ T $ (e.g., \cite[Theorem 1.5]{Ch}). The rest of the proof is similar to that of Theorem \ref{thmsp}.
\end{proof}



\subsubsection{Schr\"odinger equations with a non local term}


We adopt the same notation as in the preceding subsection. Let $ V \in B^0 \setminus \{0\} $, define $ T = (1 - \Delta)^{-1} V $, and assume $ -\lambda^{-1} \in \rho(T) $. Fix $ \mathbf{k} \in L^1 $, $ f \in B^0 $, and consider the equation
\begin{equation}\label{nl1}
(1-\Delta +\lambda V)u=\mathbf{k}\ast u+f.
\end{equation}
A function $ u \in B^2 $ is a solution to \eqref{nl1} if and only if it satisfies
\begin{equation}\label{nl2}
u=\lambda^{-1}(\lambda^{-1}+T)^{-1}(1-\Delta)^{-1}[(\mathbf{k}\ast u)+f ]=:\mathbf{K}u.
\end{equation}
For simplicity, we denote the operator norm on $ \mathscr{B}(B^0) $ by $ \|\cdot\| $. Since $ \|(1 - \Delta)^{-1}\| \leq 1 $, applying Lemma \ref{lemconv} yields
\[
\|\mathbf{K} u - \mathbf{K} v\|_{B^0} \leq |\lambda|^{-1}\|(\lambda^{-1} + T)^{-1}\| \|\mathbf{k}\|_1 \|u - v\|_{B^0}, \quad u, v \in B^0.
\]
Thus, under the condition
\begin{equation}\label{nl3}
\delta:=|\lambda|^{-1}\|(\lambda^{-1}+T)^{-1}\|\|\mathbf{k}\|_1<1,
\end{equation}
the operator $ \mathbf{K}: B^0 \to B^0 $ is contractive. By the Banach contraction principle, there exists a unique solution $ u^\ast \in B^0 $ such that $ u^\ast = \mathbf{K} u^\ast $. Consequently, we get
\begin{equation}\label{nl4}
\|u\|_{B^0}\le (1-\delta)^{-1}\|f\|_{B^0}.
\end{equation}
Proceeding analogously to the proof of Theorem \ref{thmsp}, we deduce that $ u^\ast \in B^2 $ and is the unique solution to \eqref{nl1}. In Fourier space, this implies
\[
\langle \xi \rangle^2 \widehat{u^\ast} = -\lambda (2\pi)^{-n} \widehat{V} \ast \widehat{u^\ast} + \widehat{\mathbf{k}} \widehat{u^\ast} + \widehat{f},
\]
and thus
\[
\|u^\ast\|_{B^2} \leq \left( |\lambda|(2\pi)^{-n} \|V\|_{B^0} + \|\mathbf{k}\|_1 \right) \|u^\ast\|_{B^0} + \|f\|_{B^0}.
\]
Combining this with \eqref{nl4}, we obtain
\begin{equation}\label{nl5}
\|u^\ast\|_{B^2}\le \left(\left[|\lambda|(2\pi)^{-n}\|V\|_{B^0}+\|\mathbf{k}\|_1\right](1-\delta)^{-1}+1\right)\|f\|_{B^0}.
\end{equation}
In summary, we state the following result.

\begin{theorem}\label{thmnl}
Under the assumption \eqref{nl3}, the equation \eqref{nl1} admits a unique solution $ u^\ast \in B^2 $ satisfying \eqref{nl5}.
\end{theorem}



\subsection{Anisotropic Schr\"odinger equations}\label{subsec_aniso}

In this subsection, we study anisotropic Schr\"odinger equations in spectral Barron spaces. Let $ \mu > 0 $, $ \mathfrak{A}^0 = (\mathfrak{a}_{k\ell}^0) $ be a symmetric matrix, and $ \mathfrak{A} = (\mathfrak{a}_{k\ell}) $ be a matrix-valued function defined on $ \mathbb{R}^n $. 


\begin{assumption}\label{assp_aniso}
We assume that $\mathfrak{A}^0 $ and $\mathfrak{A}$ satisfies following conditions  
\begin{enumerate}
\item $ \mathfrak{a}_{k\ell} \in C_b^0 $ and $ \mathfrak{a}_{k\ell} - \mathfrak{a}_{k\ell}^0 \in B^1 $ for all $ k, \ell $.  

\item There exists $ \kappa > 0 $ such that  
\[
\mathfrak{A}^0 \xi \cdot \xi \geq \kappa |\xi|^2, \quad \xi \in \mathbb{R}^n.
\]  

\item The following inequality holds:  
\begin{equation}\label{ani0}
\eta := \sqrt{2}\varkappa (2\pi)^{-n} \sum_{k,\ell} \|\mathfrak{a}_{k\ell} - \mathfrak{a}_{k\ell}^0\|_{B^1} < 1,
\end{equation}  
where $ \varkappa := 1 / \min(\mu, \kappa) $.  
\end{enumerate}
\end{assumption}


Define the operator $ L_0: B^2 \to B^0 $ by  
\[
L_0 u = \mu u - \sum_{k,\ell} \mathfrak{a}_{k\ell}^0 \partial_{k\ell}^2 u, \quad u \in B^2.
\]  
In Fourier space, there holds
\[
\widehat{L_0 u} = (\mu + \mathfrak{A}^0 \xi \cdot \xi) \hat{u}
\]
and
\[
\min(\mu,\kappa)\langle \xi\rangle^2|\hat{u}|\le (\mu+\kappa |\xi|^2)|\hat{u}|\le |\widehat{L_0u}|.
\]
Therefore, $L_0:B^2\rightarrow B^0$ is invertible and we have
\[
\|L_0^{-1} f\|_{B^2} \leq \varkappa \|f\|_{B^0}, \quad f \in B^0.
\]  

Next, define $ L: B^2 \to B^0 $ by  
\begin{equation}\label{opeL}
L u = \mu u - \sum_{k,\ell} \partial_k (\mathfrak{a}_{k\ell} \partial_\ell u), \quad u \in B^2.
\end{equation}  
The difference $ L - L_0 $ is given by  
\[
(L - L_0) u = -\sum_{k,\ell} \partial_k \left( [\mathfrak{a}_{k\ell} - \mathfrak{a}_{k\ell}^0] \partial_\ell u \right), \quad u \in B^2.
\]  
In Fourier space, this becomes  
\[
\mathscr{F}((L - L_0) u) = -i \sum_{k,\ell} \xi_k \mathscr{F}([\mathfrak{a}_{k\ell} - \mathfrak{a}_{k\ell}^0] \partial_\ell u).
\]  
Thus,  
\[
\|(L - L_0) u\|_{B^0} \leq \sum_{k,\ell} \|[\mathfrak{a}_{k\ell} - \mathfrak{a}_{k\ell}^0] \partial_\ell u\|_{B^1} \leq \sqrt{2}(2\pi)^{-n} \sum_{k,\ell} \|\mathfrak{a}_{k\ell} - \mathfrak{a}_{k\ell}^0\|_{B^1} \|u\|_{B^2}.
\]  

Since $ L = L_0 + (L - L_0) $, we have  
\[
L_0^{-1} L = 1 + L_0^{-1} (L - L_0).
\]  
From the preceding estimates,  
\[
\|L_0^{-1} (L - L_0)\|_{\mathscr{B}(B^0)} \leq \sqrt{2}\varkappa (2\pi)^{-n} \sum_{k,\ell} \|\mathfrak{a}_{k\ell} - \mathfrak{a}_{k\ell}^0\|_{B^1} = \eta < 1.
\]  
Therefore, $ L_0^{-1} L $ is invertible, and  
\[
\|(L_0^{-1} L)^{-1}\|_{\mathscr{B}(B^0)} \leq (1 - \eta)^{-1}.
\]  
It follows that $ L: B^2 \to B^0 $ is invertible, with  
\[
\|L^{-1}\|_{\mathscr{B}(B^0, B^2)} \leq \varkappa (1 - \eta)^{-1}.
\]  

We thus state the following result.

\begin{theorem}\label{thmani}
Let Assumption \ref{assp_aniso} hold. 
For all $ f \in B^0 $, the equation  
\begin{equation}\label{ani1}
\mu u - \sum_{k,\ell} \partial_k (\mathfrak{a}_{k\ell} \partial_\ell u) = f
\end{equation}  
admits a unique solution $ u \in B^2 $. Moreover, the following estimate holds:  
\[
\|u\|_{B^2} \leq \varkappa (1 - \eta)^{-1} \|f\|_{B^0}.
\]  
\end{theorem}

\begin{remark}\label{remani0}
{\rm
Let $ V \in B^0 \setminus \{0\} $. Similar to the case of $ (1 - \Delta)^{-1} V $, we observe that $ L_0^{-1} V: B^0 \to B^0 $ is compact. Since  
\[
L^{-1} = (1 + L_0^{-1} (L - L_0))^{-1} L_0^{-1},
\]  
it follows that $ L^{-1} V: B^0 \to B^0 $ is also compact. Consequently, the spectral analysis for the problem  
\[
(L + \lambda V) u = 0, \quad \lambda \neq 0,
\]  
parallels that of $ (1 - \Delta + \lambda V) u = 0 $.  
}\end{remark}

Next, we discuss the higher regularity of the solution to equation \eqref{ani1}. Assume $ \partial_j \mathfrak{a}_{k\ell} \in B^1 $ for $ 1 \leq j, k, \ell \leq n $ and $ f \in B^1 $. Let $ u \in B^2 $ be the solution of \eqref{ani1}. We verify that $ v_j = \partial_j u $ ($ 1 \leq j \leq n $) is the unique solution in $ \mathscr{S}' $ of the equation  
\begin{align}\label{eq_Loperator}
L v_j = \sum_{k,\ell} \partial_k (\partial_j \mathfrak{a}_{k\ell} \partial_\ell u) + \partial_j f.
\end{align}
By Theorem \ref{thmani}, $ v_j \in B^2 $, and there exists a constant $ \mathbf{c} = \mathbf{c}(n,\mathfrak{A}, \kappa, \mu) >0$ such that  
\[
\|v_j\|_{B^2} \leq \mathbf{c} \|f\|_{B^1}.
\]  
Thus, $ u \in B^3 $, and by replacing $ \mathbf{c} $ with a similar constant, we obtain  
\[
\|u\|_{B^3} \leq \mathbf{c} \|f\|_{B^1}.
\]  
By induction on an integer $ m \geq 0 $, we deduce $ B^{2 + m} $ regularity for the solution of \eqref{ani1}. Specifically, we have the following result.

\begin{theorem}\label{thmani2}
Let $ m \geq 0 $ be an integer and Assumption \ref{assp_aniso} holds. Moreover, assume $ \partial^\alpha \mathfrak{a}_{k\ell} \in B^1 $ for all $ 1 \leq |\alpha| \leq m $ when $ m \geq 1 $. For all $ f \in B^m $, the equation \eqref{ani1} admits a unique solution $ u \in B^{2 + m} $ satisfying  
\[
\|u\|_{B^{2 + m}} \leq \mathbf{c} \|f\|_{B^m},
\]  
where $ \mathbf{c} = \mathbf{c}(n, \mathfrak{A}, \kappa, \mu, m) > 0 $ is a constant.  
\end{theorem}

\begin{remark}\label{remani1}
{\rm
$\mathrm{(i)}$ Theorem \ref{thmani} remains valid if $ L $ is replaced by the operator  
\[
\tilde{L} = L + \sum_k \mathfrak{b}_k \partial_k,
\]  
where $ \mathfrak{b}_k \in B^0 $ for $ 1 \leq k \leq n $, and the condition \eqref{ani0} is modified to  
\[
\eta := \varkappa (2\pi)^{-n} \left[ 2 \sum_{k,\ell} \|\mathfrak{a}_{k\ell} - \mathfrak{a}_{k\ell}^0\|_{B^1} + \sum_k \|\mathfrak{b}_k\|_{B^0} \right] < 1.
\]  
Theorem \ref{thmani2} can also be extended to $ \tilde{L} $, provided $ \mathfrak{b}_k \in B^m $ and the constant $ \mathbf{c} $ depends on $ (\mathfrak{b}_1, \ldots, \mathfrak{b}_n) $.  
\\
$\mathrm{(ii)}$ Let $s>0$, $ V \in B^s $ satisfy $ V \geq -\mu $, and let $ u \in B^2 $ satisfy $ (L_0 + V) u = 0 $. Define $ v(y) = u(\sqrt{\mathfrak{A}^0} \, y) $ and $ W(y) = V(\sqrt{\mathfrak{A}^0} \, y) $. We verify that $ (\mu - \Delta + W) v = 0 $. Using the equivalence of norms induced by $ |\sqrt{\mathfrak{A}^0} \cdot| $ on $ \mathbb{R}^n $, we adapt the proof of \cite[Proposition 3.8]{CLLZ} to conclude $ v = 0 $. By compactness with Proposition \ref{procm}, $ L_0 + V $ is invertible. Thus, for all $ f \in B^0 $, the equation $ (L_0 + V) u = f $ admits a unique solution $ u \in B^2 $ with  
\[
\|u\|_{B^2} \leq \mathbf{c} \|f\|_{B^0},
\]  
where $ \mathbf{c} = \mathbf{c}(n, \mathfrak{A}^0, V) > 0 $ is a constant.  
}\end{remark}


To establish $ B^{s+2} $ regularity for the solution when $ s \in (0, \infty) \setminus \mathbb{N} $, we solve equation \eqref{ani1} directly in $ B^{s+2} $. Instead of Assumption \ref{assp_aniso}, we impose the following assumptions, where $ s \geq 0 $ is arbitrarily fixed. 

\begin{assumption}\label{assp_aniso2}
We assume that $\mathfrak{A}^0 $ and $\mathfrak{A}$ satisfies following conditions  
\begin{enumerate}
\item $ \mathfrak{a}_{k\ell} \in C_b^0 $, and $ \mathfrak{a}_{k\ell} - \mathfrak{a}_{k\ell}^0 \in B^{1+s} $ for each $ k, \ell $.  

\item There exists $ \kappa > 0 $ such that  
\[
\mathfrak{A}^0 \xi \cdot \xi \geq \kappa |\xi|^2, \quad  \xi \in \mathbb{R}^n.
\]  

\item The following inequality holds:  
\[
\eta' := 2^{(1+s)/2} \varkappa (2\pi)^{-n} \sum_{k,\ell} \|\mathfrak{a}_{k\ell} - \mathfrak{a}_{k\ell}^0\|_{B^{1+s}} < 1,
\]  
where $ \varkappa := 1 / \min(\mu, \kappa) $.  
\end{enumerate}

\end{assumption}
By adapting the proof of Theorem \ref{thmani}, we prove the following result.

\begin{theorem}\label{thmani3}
Let $ s \geq 0 $, and let Assumption \ref{assp_aniso2} hold. Then, for all $ f \in B^s $, the equation $ Lu = f $ admits a unique solution $ u \in B^{2+s} $, and the following estimate holds:  
\[
\|u\|_{B^{2+s}} \leq \varkappa (1 - \eta')^{-1} \|f\|_{B^s}.
\]  
\end{theorem}

Combining Theorem \ref{thmehs} and Theorem \ref{thmani3}, we obtain the following H\"older regularity result.

\begin{corollary}\label{corani1}
Let Assumption \ref{assp_aniso2} hold. Let $ k \geq 0 $ be an integer, and $ 0 < \theta < 1 $. For all $ 0 < \gamma < \theta $ and $ f \in B^{k+\theta} $, the equation $ Lu = f $ has a unique solution $ u \in C_b^{2+k, \gamma} $, and  
\[
\|u\|_{C_b^{2+k, \gamma}} \leq  \mathbf{c}_\ast \varkappa (1 - \eta')^{-1} \|f\|_{B^{k+\theta}},
\]  
where $  \mathbf{c}_\ast >0$ is the norm of the embedding $ B^{k+\theta} \hookrightarrow C_b^{2+k, \gamma} $.  
\end{corollary}



\subsection{Unique continuation of Schr\"odinger equations}\label{subse_UC}

In this subsection, we investigate the unique continuation property for the Schr\"odinger equation in the context of generic anisotropic conductivity. This property is fundamental as it enables us to explore the uniqueness and stability of various inverse problems in future work.

Let $ \mathfrak{A} = (\mathfrak{a}_{k\ell}) \in (B^1)^{n \times n} $ be a real-valued matrix such that $ (\mathfrak{a}_{k\ell}(x)) $ is symmetric for each $ x \in \mathbb{R}^n $. Moreover, for all compact subsets $ \Omega \Subset \mathbb{R}^n $, there exists $ \kappa_\Omega > 0 $ such that  
\[
\mathfrak{A}(x) \xi \cdot \xi \geq \kappa_\Omega |\xi|^2,\quad  \xi \in \mathbb{R}^n, \; x \in \overline{\Omega}.
\]  
Let $ \mathfrak{B} = (\mathfrak{b}_k) \in (B^0)^n $, $ V \in B^0 $, and $ \mu \in \mathbb{C} $. Suppose $ u \in B^2 $ is a solution of the equation  
\begin{equation}\label{uce}
-\sum_{k,\ell} \partial_\ell (\mathfrak{a}_{k\ell} \partial_\ell u) + \sum_k \mathfrak{b}_k \partial_k u + (V + \mu) u = 0
\end{equation}  
satisfying $ u = 0 $ in $ \omega \Subset \mathbb{R}^n $. Choose a compact subset $ \Omega \Subset \mathbb{R}^n $ and let $ D $ be a bounded domain in $ \mathbb{R}^n $ containing both $ \omega $ and $ \Omega $. Then $ u \in C^2(\overline{D}) $, $ \mathfrak{a}_{k\ell} \in C^1(\overline{D}) $, $ \mathfrak{b}_k \in C^0(\overline{D}) $, $ V \in C^0(\overline{D}) $,  
and  
\[
-\sum_{k,\ell} \partial_\ell (\mathfrak{a}_{k\ell} \partial_\ell u) + \sum_k \mathfrak{b}_k \partial_k u + (V + \mu) u = 0 \quad \text{in } \overline{D}.
\]  
By the unique continuation property for elliptic operators (e.g., \cite[Theorem 2.22]{Ch16}), $ u = 0 $ in $ D $, and hence $ u = 0 $ in $ \Omega $. Since $ \Omega \Subset \mathbb{R}^n $ was arbitrarily chosen, we deduce that $ u $ is identically zero.  

Next, let $ \Omega $ be a bounded Lipschitz domain in $ \mathbb{R}^n $ and $ \Gamma $ be a non-empty open subset of $ \partial \Omega $. Denote by $ \partial_\nu $ the derivative along the unit exterior normal vector field $ \nu $ to $ \Gamma $. By the unique continuation property from Cauchy data (e.g., \cite[Corollary 2.23]{Ch16}), if $ u \in B^2 $ is a solution of \eqref{uce} satisfying $ u = \partial_\nu u = 0 $ on $ \Gamma $, then $ u = 0 $.  




\section{BVPs in spectral Barron spaces on bounded open sets}\label{se_BVP}



In this subsection, we conduct a rigorous and in-depth investigation of boundary value problems (BVPs) within the framework of spectral Barron spaces defined on bounded domains. Specifically, our analysis focuses on two key aspects: (i) establishing the well-posedness of these BVPs under appropriate conditions, and (ii) introducing novel analytical tools tailored to spectral Barron spaces. Among these innovations, we highlight the construction of a Dirichlet-to-Neumann (DtN) operator derived from trace-theoretic formulations, which provides a powerful bridge between boundary data and interior solution properties. 

Unless explicitly stated otherwise, the symbol $\Omega$ will denote an arbitrary but fixed bounded open subset of $\mathbb{R}^n$.


\subsection{Spectral Barron spaces $B^s(\Omega)$ with $s\ge 0$}

For $s \geq 0$, we define the closed subspace $F_s$ of $B^s$ as follows:
\begin{equation}\label{Fs}
F_s := \{f \in B^s ;\; \mathrm{supp}(f) \subset \mathbb{R}^n \setminus \Omega\}. 
\end{equation}
We then introduce the quotient space $B^s(\Omega):= B^s / F_s$.

In the sequel, $\pi_s: B^s \rightarrow B^s(\Omega)$ denotes the standard quotient map. For any $g_1, g_2 \in B^s$, the equality $\pi_s(g_1)=\pi_s(g_2)$ implies that $g_1 - g_2 \in F_s$, or equivalently, $g_1|_{\overline{\Omega}} = g_2|_{\overline{\Omega}}$.

We endow $B^s(\Omega)$ with the quotient norm defined by
\[
\|f\|_{B^s(\Omega)} = \inf \{\|g\|_{B^s};\; \pi_s(g) = f\},\quad f \in B^s(\Omega).
\]
As a result, $B^s(\Omega)$ constitutes a Banach space with respect to the norm $\|\cdot\|_{B^s(\Omega)}$.

By referring to \cite[Subsection 4.8]{Ru}, the dual space $B^s(\Omega)'$ of $B^s(\Omega)$ can be identified with
\[
F_s^\perp = \{g \in \tilde{B}^{-s};\; (g, f) = 0,\; f \in F_s\}.
\]
Here, the duality pairing $(g, f)$ is given by
\[
(g, f) = \int_{\mathbb{R}^n} \left[\langle \xi \rangle^{-s} \mathscr{F}^{-1}g\right] \left[\langle \xi \rangle^s \hat{f}\right] d\xi.
\]

With a slight abuse of notation, we often make the following identification:
\[
B^s(\Omega) = \{f = g|_{\overline{\Omega}};\; g \in B^s\}
\]
endowed with the norm
\[
\|f\|_{B^s(\Omega)}=\inf \{\|g\|_{B^s};\; g|_{\overline{\Omega}}=f\}.
\]
In what follows, we adopt the convention $C_b^{k,0}(\cdot) = C_b^k(\cdot)$. Let $s \geq 0$, $f \in B^s(\Omega)$, and $g\in B^s$ such that $g|_{\overline{\Omega}}=f$. Since $B^s \hookrightarrow C_b^{\lfloor s \rfloor, s - \lfloor s \rfloor}$, we have $g \in C_b^{\lfloor s \rfloor, s - \lfloor s \rfloor}$ and
\[
\|g\|_{C_b^{\lfloor s \rfloor, s - \lfloor s \rfloor}} \leq \mathbf{c} \|g\|_{B^s},
\]
where $\mathbf{c} = \mathbf{c}(n, s) > 0$ is a constant. Consequently, $f = g|_{\overline{\Omega}} \in C^{\lfloor s \rfloor, s - \lfloor s \rfloor}(\overline{\Omega})$ and
\[
\|f\|_{C^{\lfloor s \rfloor, s - \lfloor s \rfloor}(\overline{\Omega})} \leq \|g\|_{C_b^{\lfloor s \rfloor, s - \lfloor s \rfloor}} \leq \mathbf{c} \|g\|_{B^s},
\]
which implies
\[
\|f\|_{C^{\lfloor s \rfloor, s - \lfloor s \rfloor}(\overline{\Omega})} \leq \mathbf{c} \|f\|_{B^s(\Omega)}.
\]
Thus, we have the continuous embedding $B^s(\Omega) \hookrightarrow C^{\lfloor s \rfloor, s - \lfloor s \rfloor}(\overline{\Omega})$.

