\begin{proof}
(i) Let $f \in B^t(\Omega)$. From $B^t\hookrightarrow B^s$, we have
\[
\|f\|_{B^s(\Omega)}=\inf\{\|g\|_{B^s};\; g|_{\overline{\Omega}}=f\}\le \inf\{\|g\|_{B^t};\; g|_{\overline{\Omega}}=f\}=\|f\|_{B^t(\Omega)}.
\]

(ii) Let $s \geq 0$, $f \in B^s(\Omega)$, and $\epsilon > 0$. Choose $g\in B^s$ satisfying $g|_{\overline{\Omega}}=f$. Since $\mathscr{S}$ is dense in $B^s$, we can find $h \in \mathscr{S}$ such that $\|g - h\|_{B^s} \leq \epsilon$. Let $k:=h|_{\overline{\Omega}}\in C^\infty (\overline{\Omega})$. Using the fact that $f - k =(g - h)|_{\overline{\Omega}}$, we obtain $\|f - k\|_{B^s(\Omega)} \leq \|g - h\|_{B^s} \leq \epsilon$.

(iii) Let $f\in H^t(\Omega)$ . From \cite[Theorem 1.4.3.1]{Gr}, there exists $g\in H^t$ such that $g|_\Omega=f$ and $\|g\|_{H^t}\le \mathbf{c}\|f\|_{H^t(\Omega)}$, where $\mathbf{c}>0$ is a generic constant independent of $f$ and $g$. From Proposition \ref{pro2} (iii), we have $\|g\|_{B^s}\le \mathbf{c}\|f\|_{H^t(\Omega)}$, which implies $\|f\|_{B^s(\Omega)}\le \mathbf{c}\|f\|_{H^t(\Omega)}$.


(iv) Let $\epsilon>0$ and $h,k\in B^s$ such that $\|h\|_{B^s}\le\|f\|_{B^s(\Omega)}+\epsilon$ and $\|k\|_{B^s}\le\|g\|_{B^s(\Omega)}+\epsilon$. Since $hk\in B^s$ and $fg=(hk)|_{\overline{\Omega}}$, we obtain $fg\in B^s(\Omega)$ and Proposition \ref{pro2} (iv) yields
\[
\|fg\|_{B^s(\Omega)} \le \|hk\|_{B^s}\le 2^{s/2}(2\pi)^{-n} (\|f\|_{B^s(\Omega)}+\epsilon)(\|f\|_{B^s(\Omega)}+\epsilon).
\]
Letting $\epsilon\to 0$ completes the proof.
\end{proof}


On a bounded open subset $\Omega$, we enhance the embedding result in Theorem \ref{thmcem} as follows. 
\begin{theorem}\label{thmbd1}
For all $ 0 \leq s < t $, the embedding $ B^t(\Omega) \hookrightarrow B^s(\Omega) $ is compact.
\end{theorem}

\begin{proof}
Let $ \chi \in C_0^\infty $ be a fixed function such that $ \chi = 1 $ in a neighborhood of $ \overline{\Omega} $, and set $ K = \mathrm{supp}(\chi) $. Consider a bounded sequence $ (f_j) $ in $ B^t(\Omega) $ with $ \sup_j \|f_j\|_{B^t(\Omega)} \leq 1 $. For each $ j $, there exists $ g_j \in B^t $ such that $ f_j=g_j|_{\overline{\Omega}}=(\chi g_j)|_{\overline{\Omega}} $ and $ \|g_j\|_{B^t} \leq 2 $.

Since $ (\chi g_j) $ is a bounded sequence in $ B_K^t $, and by Theorem \ref{thmcem}, the embedding $ B_K^t \hookrightarrow B^s $ is compact, there exists a subsequence (still denoted $ (\chi g_j) $) that converges in $ B^s $. Consequently, for all $ j, k $, we have
\[
\|f_j - f_k\|_{B^s(\Omega)} \leq \|\chi g_j - \chi g_k\|_{B^s}.
\]
This implies that $ (f_j) $ is a Cauchy sequence in $ B^s(\Omega) $, and hence it converges in $ B^s(\Omega) $. The proof is complete.
\end{proof}

As an immediate consequence of Theorem \ref{thmbd1}, we obtain the following result.

\begin{corollary}\label{corbd1}
For all $ 0 \leq s < t $, the embedding $ B^t(\Omega) \hookrightarrow C^{\lfloor s \rfloor, s - \lfloor s \rfloor}(\overline{\Omega}) $ is compact. In particular, for any integer $ k \geq 0 $ and $ 0 < \gamma < \theta < 1 $, the embedding $ B^{k+\theta}(\Omega) \hookrightarrow C^{k, \gamma}(\overline{\Omega}) $ is compact.
\end{corollary}

In what follows, let $ \Gamma = \partial \Omega $, and for $ s \geq 0 $, define the trace space
\[
B^s(\Gamma) := \{ h = u|_{\Gamma} ;\; u \in B^s(\Omega) \},
\]
equipped with the quotient norm
\[
\|h\|_{B^s(\Gamma)} := \inf \{ \|u\|_{B^s(\Omega)} ;\; u|_{\Gamma} = h \}.
\]

For further applications, we note that as an immediate consequence of Proposition \ref{probd1}, the space $ C^\infty(\Gamma) $ is dense in $ B^s(\Gamma) $ for all $ s \geq 0 $. Here, $C^\infty(\Gamma):=\{h=\varphi|_\Gamma;\; \varphi\in C^\infty_0\}$.

\begin{theorem}\label{thmtr1}
For all $ 0 \leq s < t $, the embedding $ B^t(\Gamma) \hookrightarrow B^s(\Gamma) $ is compact.
\end{theorem}

\begin{proof}
Let  $ 0 \leq s < t $ and $(h_j)$ be a sequence in $B^t(\Gamma)$ satisfying $\sup_j\|h_j\|_{B^t(\Gamma)}\le 1$. For each $j$, we find $u_j\in B^t(\Omega)$ such that $u_j|_\Gamma=h_j$ and $\|u_j\|_{B^t(\Omega)}\le 2$. By the compactness of the embedding $ B^t(\Omega) \hookrightarrow B^s(\Omega) $, upon subtracting a subsequence, we can assume that $(u_j)$ converges in $B^s(\Omega)$. Now, for all $j,k$, we have
\[
\|h_j-h_k\|_{B^s(\Gamma)}\le \|u_j-u_k\|_{B^s(\Omega)}.
\]
Therefore, $(h_j)$ is a Cauchy sequence in $B^s(\Gamma)$ and hence it converges in $B^s(\Gamma)$.
\end{proof}




\subsection{BVPs in $B^s(\Omega)$ with $s\ge 0$}\label{subse_BVP}




After the formal definition of the spectral Barron spaces $ B^s(\Omega) $, we proceed to investigate BVPs in these spaces. 
For $ s \geq 0 $ and $ (f, h) \in B^s(\Omega) \times B^{s+2}(\Gamma) $, consider the BVP
\begin{equation}\label{bvp1}
(1 - \Delta) u = f \quad \text{in } \Omega, \quad u|_{\Gamma} = h.
\end{equation}
This BVP has at most one solution in $ B^{s+2}(\Omega) $, as a consequence of the fact that $ B^{s+2}(\Omega) \hookrightarrow H^2(\Omega) $ and that \eqref{bvp1} has at most one solution in $ H^2(\Omega) $.

Before stating the existence result for \eqref{bvp1}, we introduce a definition. For all $0\le s< t  $ and $\varrho>0$, let $ \mathcal{D}_\varrho^{s,t} $ be the closure in $ B^s(\Omega) \times B^{2+s}(\Gamma) $ of the set
\[
D_\varrho^t := \{(f, h) = ((1 - \Delta) u, u|_{\Gamma}) ;\; u \in B^{2+t}(\Omega),\; \|u\|_{B^{t+2}(\Omega)}\le \varrho\}.
\]

\begin{theorem}\label{thmbd2}
Let $ 0 \leq s < t $, $\varrho >0$ and $ (f, h) \in \mathcal{D}_\varrho^{s,t} $. Then \eqref{bvp1} has a unique solution $ u \in B^{2+s}(\Omega) $ satisfying $ \|u\|_{B^{2+s}(\Omega)}\le \varrho$.
\end{theorem}

\begin{proof}
We only need to prove existence. Let $ ((f_j, h_j)) = (((1 - \Delta) u_j, u_j|_{\Gamma})) $ be a sequence in $ D_\varrho^t $ converging to $ (f, h) $ in $ B^s(\Omega) \times B^{s+2}(\Gamma) $, where $ (u_j) $ is a sequence in $ B^{2+t}(\Omega) $ satisfying $\sup_j\|u_j\|_{B^{2+t}(\Omega)}\le \varrho$. Using that the embedding $B^{2+t}(\Omega)\hookrightarrow B^{2+s}(\Omega)$ is compact by Theorem \ref{thmbd1} and subtracting a subsequence if necessary, we can assume that $(u_j)$ converges in $B^{2+s}(\Omega)$ to $u\in B^{2+s}(\Omega)$. In consequence, $\|u\|_{B^{2+s}(\Omega)}\le \varrho$ and $ (((1 - \Delta) u_j, u_j|_{\Gamma})) $ converges in $ B^s(\Omega) \times B^{2+s}(\Gamma) $ to $ ((1 - \Delta) u, u|_{\Gamma}) $. By the uniqueness of the limit, we get $ ((1 - \Delta) u, u|_{\Gamma})=(f,h) $. This completes the proof.
\end{proof}


Theorem \ref{thmbd2} can be extended to the case where $ 1 - \Delta $ is replaced by $ 1 - \Delta + \lambda V $ with $V\in B^t(\Omega)$ for some $t> 0$. Before going into details we introduce some new definitions. For simplicity, we assume in the following that $ \Omega $ is at least of class $ C^{1,1} $. Let $ \Delta_D $ be the operator defined by $ \Delta_D u = \Delta u $ for $ u \in D(\Delta_D) = H_0^1(\Omega) \cap H^2(\Omega) $. We recall that this operator has a compact resolvent. Therefore, for $ V \in B^0(\Omega)\hookrightarrow C^0(\overline{\Omega}) $, the operator $ S_V = (1 - \Delta_D)^{-1}V: L^2(\Omega) \rightarrow L^2(\Omega) $ is compact.

For $ 0\le s<t$, $ \varrho >0$ and $ V \in B^t(\Omega) $, let $ \mathcal{D}_{V,\varrho}^{s,t} $ as the closure in $ B^s(\Omega) \times B^{2+s}(\Gamma) $ of the set
\[
D_{V,\varrho}^t = \left\{ (f, h) = \left( (1 - \Delta + V)u, u|_{\Gamma} \right) ;\; u \in B^{2+t}(\Omega),\; \|u\|_{B^{2+t}(\Omega)}\le \varrho \right\}.
\]


\begin{theorem}\label{thmbd3}
Let $ 0 \leq s < t $, $\varrho>0$ and $ V \in B^t(\Omega) \setminus \{0\} $, and assume that $ -\lambda^{-1} \not\in \sigma(S_V) $. For all $ \mathcal{D}_{\lambda V,\varrho}^{s,t} $, the BVP
\[
(1 - \Delta + \lambda V)u = f \quad \text{in } \Omega, \quad u|_{\Gamma} = h,
\]
admits a unique solution $ u \in B^{2+s}(\Omega) $ satisfying $\|u\|_{B^{2+s}(\Omega)}\le \varrho$.
\end{theorem}



Next, from Proposition \ref{probd1} (iii), we note that
\[
C^{k-1,1}(\overline{\Omega})\hookrightarrow W^{k,\infty}(\Omega)\hookrightarrow H^k(\Omega)\hookrightarrow B^t(\Omega)
\]
holds for $t\ge 0$ and an integer $k$ satisfying $k>t+n/2$.
The following result provides a useful consequence of Theorem \ref{thmbd3}.


\begin{theorem}\label{thmbd3.1}
Let $ s\ge 0 $, $ k > s + n/2 $ be an integer, and assume that $ \Omega $ is of class $ C^{2+k} $. Let  $V=0$ or $ V \in C^{k-1,1}(\overline{\Omega}) \setminus \{0\} $ and $ -\lambda^{-1} \notin \sigma(S_V) $. For all $ (f, h) \in H^k(\Omega) \times H^{k+3/2}(\Gamma) $, the BVP
\begin{equation}\label{bvp0}
(1 - \Delta + \lambda V)u = f \quad \text{in } \Omega, \quad u|_{\Gamma} = h,
\end{equation}
admits a unique solution $ u \in B^{2+s}(\Omega) $, and the following inequality holds:
\[
\|u\|_{B^{2+s}(\Omega)} \leq \mathbf{c} \left( \|f\|_{H^k(\Omega)} + \|h\|_{H^{k+3/2}(\Gamma)} \right).
\]
Here, $ \mathbf{c} = \mathbf{c}(n, \Omega, k, s, V, \lambda) > 0 $ is a constant.
\end{theorem}

\begin{proof}
Assume that $V\ne 0$. Then the case $(f,h)=0$ is trivial. Let $ 0\neq (f, h) \in H^k(\Omega) \times H^{k+3/2}(\Gamma)$. Since $ -\lambda^{-1} \notin \sigma(S_V) $, the BVP \eqref{bvp0} admits a unique solution $ u \in H^2(\Omega) $. Using the fact that $ V \in C^{k-1,1}(\overline{\Omega}) $, we deduce from \cite[Theorem 8.13]{GT} that $ u \in H^{2+k}(\Omega) $ and
\begin{equation}\label{bvp0.1}
\|u\|_{H^{2+k}(\Omega)} \leq \mathbf{c}_0 \left( \|f\|_{H^k(\Omega)} + \|h\|_{H^{3/2+k}(\Gamma)} \right).
\end{equation}
Here and henceforth, $ \mathbf{c}_0 = \mathbf{c}_0(n, \Omega, k, V, \lambda) > 0 $ is a generic constant.

On the other hand, from \cite[Theorem 1.4.3.1]{Gr}, there exists $ g \in H^{2+k} $ such that $ g|_{\Omega} = u $ and
\[
\|g\|_{H^{2+k}} \leq \mathbf{c}_1 \|u\|_{H^{2+k}(\Omega)}
\]
for some constant $ \mathbf{c}_1 = \mathbf{c}_1(n, \Omega, k) > 0 $. Combined with \eqref{bvp0.1}, this inequality yields
\begin{equation}\label{bvp0.2}
\|g\|_{H^{2+k}} \leq \mathbf{c}_0 \left( \|f\|_{H^k(\Omega)} + \|h\|_{H^{3/2+k}(\Gamma)} \right).
\end{equation}
Take $s<t<k-n/2$. From Proposition \ref{pro2} (iii), we know that $ H^{2+k} \hookrightarrow B^{2+t} $. Thus, $ g \in B^{2+t} $, and from \eqref{bvp0.2}, we obtain
\begin{equation}\label{bvp0.3}
\|g\|_{B^{2+t}} \leq \mathbf{c}_2 \left( \|f\|_{H^k(\Omega)} + \|h\|_{H^{3/2+k}(\Gamma)} \right)=:\varrho\; (>0),
\end{equation}
where $ \mathbf{c}_2 = \mathbf{c}_2(n, \Omega, k,  s, V, \lambda) > 0 $ is a constant.

Now, since $ (f, h) = ((1 - \Delta + \lambda V)g|_{\overline{\Omega}}, g|_{\Gamma}) $, we have $ (f, h) \in D^t_{\lambda V,\varrho} $.
The proof is completed for the case $V\in B^t(\Omega)\setminus\{0\}$ by applying Theorem \ref{thmbd3}. The proof in the case $V=0$ is similar.
\end{proof}

\begin{remark}\label{rembvp1}
{\rm
We observe, from the previous proof, that the BVP \eqref{bvp0} admits a unique solution $u\in B^{2+s}(\Omega)$ for all $(f,h)$ in the closure of $H^k(\Omega) \times H^{k+3/2}(\Gamma)$ in $B^s(\Omega)\times B^{2+s}(\Gamma)$. But the a priori estimate \eqref{bvp0.1} is not necessarily verified in this case.
}
\end{remark}


Let $ L $ be the operator defined in (\ref{opeL}). We assume that $ L $ satisfies Assumption \ref{assp_aniso} when $ s \in \mathbb{N} $, and Assumption \ref{assp_aniso2} when $ s \in (0, \infty) \setminus \mathbb{N} $. In view of Theorems \ref{thmani}, \ref{thmani2}, and \ref{thmani3}, as well as Remark \ref{remani0}, it becomes evident that all the results presented in this section extend to the scenario where $ 1 - \Delta $ is replaced by $ L $ within the anisotropic setting, with the constants in the estimates also depending on the coefficients of $ L $.



\subsection{Smooth perturbations of BVPs}



In this subsection, we focus on the well-posedness of BVPs for the smooth perturbations of the operator $1-\Delta +\lambda V$. To achieve this, we fix $0 \leq s < t < \min(s + 2, k-n/2)$, $V \in C^{k-1,1}(\overline{\Omega}) \setminus \{0\}$ and $-\lambda^{-1} \not\in \sigma(S_V)$ or $V=0$. Assume that $\Omega$ is of class $C^{2+k}$. According to Theorem \ref{thmbd3.1}, for all $f \in H^k(\Omega)$ and $h \in H^{k+3/2}(\Gamma)$, the BVP
\begin{equation}\label{se1}
(1 - \Delta + \lambda V)u = f \quad \text{in } \Omega, \quad u|_{\Gamma} = h
\end{equation}
admits a unique solution $u=u(f, h) \in B^{2+s}(\Omega)$ satisfying
\begin{equation}\label{se2}
\|u(f, h)\|_{B^{2+s}(\Omega)} \leq \mathbf{c}\left(\|f\|_{H^k(\Omega)} + \|h\|_{H^{k+3/2}(\Gamma)}\right),
\end{equation}
where $\mathbf{c} = \mathbf{c}(n,\Omega, k, s, t, V, \lambda) > 0$ is a constant. We define
\[
\mathbf{\hat{c}} := \sup\left\{ \|u(f, h)\|_{B^{2+s}(\Omega)}; \; \|f\|_{H^k(\Omega)} + \|h\|_{H^{k+3/2}(\Gamma)} \leq 1 \right\}.
\]

Next, we fix $(f_0, h_0) \in H^k(\Omega) \times H^{k+3/2}(\Gamma)$ and let $\mathfrak{a}: B^t(\Omega) \to H^k(\Omega)$ be such that there exist $0 < \eta < \mathbf{\hat{c}}^{-1}$ and $\gamma > 0$ satisfying
\begin{equation}\label{sem}
\|\mathfrak{a}(u)\|_{H^k(\Omega)} \leq \eta \|u\|_{B^t(\Omega)} + \gamma, \quad u \in B^t(\Omega).
\end{equation}

We define
\[
\Psi: (u, \tau) \in B^t(\Omega) \times [0, 1] \mapsto \tau u(\mathfrak{a}(u) + f_0, h_0) \in B^t(\Omega).
\]
Let $(u, \tau) \in B^t(\Omega) \times [0, 1]$ such that $u = \Psi(u, t)$. We have
\begin{align}
\|u\|_{B^t(\Omega)} \leq \|u\|_{B^{2+s}(\Omega)} &\leq \|u(\mathfrak{a}(u) + f_0, h_0)\|_{B^{2+s}(\Omega)}\label{se3} \\
&\leq \mathbf{\hat{c}}\left(\eta \|u\|_{B^t(\Omega)} + \|f_0\|_{H^k(\Omega)} + \gamma + \|h_0\|_{H^{k+3/2}(\Gamma)}\right)\nonumber
\end{align}
and hence
\[
\|u\|_{B^t(\Omega)} \leq \mathbf{\hat{c}}(1 - \eta \mathbf{\hat{c}})^{-1}\left(\gamma + \|f_0\|_{H^k(\Omega)} + \|h_0\|_{H^{k+3/2}(\Gamma)}\right).
\]
On the other hand, since the embedding $B^{2+s}(\Omega) \hookrightarrow B^t(\Omega)$ is compact and
\[
\|\Psi(u, \tau)\|_{B^{2+s}(\Omega)} \leq \mathbf{\hat{c}}\left(\eta + \gamma + \|f_0\|_{H^k(\Omega)} + \|h_0\|_{H^{k+3/2}(\Gamma)}\right)
\]
for all $\tau \in [0, 1]$ and $\|u\|_{B^t(\Omega)} \le 1$, we deduce that $\Psi$ is a compact operator. Since $\Psi(\cdot, 0) = 0$, by applying the Leray-Schauder fixed-point theorem (e.g., \cite[Theorem 11.6]{GT}), we conclude that $\Psi(\cdot, 1)$ admits a fixed point $u^* \in B^t(\Omega)$. Whence, $u^* \in B^{2+s}(\Omega)$ and it  is a solution to the BVP
\begin{equation}\label{se4}
(1 - \Delta + \lambda V)u = \mathfrak{a}(u) + f_0 \quad \text{in } \Omega, \quad u|_{\Gamma} = h_0.
\end{equation}
From \eqref{se3}, it follows that
\begin{equation}\label{se5}
\|u^*\|_{B^{2+s}(\Omega)} \leq \mathbf{\hat{c}}(1 - \eta \mathbf{\hat{c}})^{-1}\left(\gamma + \|f_0\|_{H^k(\Omega)} + \|h_0\|_{H^{k+3/2}(\Gamma)}\right).
\end{equation}


\begin{theorem}\label{thmse}
Under the additional assumptions that $1 + \lambda V \geq 0$ in $\Omega$ and
\[
(\mathfrak{a}(u) - \mathfrak{a}(v))(\overline{u} - \overline{v}) \leq 0, \quad u, v \in B^t(\Omega),
\]
the BVP \eqref{se4} admits a unique solution $u^* \in B^{2+s}(\Omega)$ satisfying \eqref{se5}.
\end{theorem}

\begin{proof}
We have already established the existence of a solution. What remains is to prove uniqueness. Let $u_1, u_2 \in B^{2+s}(\Omega)$ be two solutions of \eqref{se4}. Then, we have
\[
(1 - \Delta + \lambda V)(u_1 - u_2) = \mathfrak{a}(u_1) - \mathfrak{a}(u_2) \quad \text{in } \Omega, \quad (u_1 - u_2)|_{\Gamma} = 0.
\]
Applying Green's formula, we obtain
\begin{align*}
&\int_{\Omega} \left[(1 + \lambda V)|u_1 - u_2|^2 + |\nabla (u_1 - u_2)|^2\right] dx 
\\
&\hskip 4cm = \int_{\Omega} (\mathfrak{a}(u_1) - \mathfrak{a}(u_2))(\overline{u}_1 - \overline{u}_2) dx \leq 0.
\end{align*}
This implies that $u_1 = u_2$.
\end{proof}

\begin{remark}\label{remse1}
{\rm
If we replace condition \eqref{sem} with the following: there exists $0 < \eta < \mathbf{\hat{c}}^{-1}$ such that
\begin{equation}\label{sem1}
\|\mathfrak{a}(u) - \mathfrak{a}(v)\|_{H^k(\Omega)} \leq \eta \|u - v\|_{B^t(\Omega)}, \quad u, v \in B^t(\Omega),
\end{equation}
then we can verify that the mapping
\[
\Phi: u \in B^t(\Omega) \mapsto u(\mathfrak{a}(u) + f_0, h_0) \in B^t(\Omega)
\]
is contractive. Consequently, by the Banach contraction principle, $\Phi$ admits a unique fixed point $u^*$. Since $\Phi(u) \in B^{2+s}(\Omega)$, we deduce that $u^* \in B^{2+s}(\Omega)$ and is the unique solution of \eqref{se4}. Moreover, as \eqref{sem1} implies \eqref{sem} with $\gamma = \|\mathfrak{a}(0)\|_{H^k(\Omega)}$, $u^*$ satisfies \eqref{se5} with $\gamma = \|\mathfrak{a}(0)\|_{H^k(\Omega)}$.
}\end{remark}

Let us give an example of a function $\mathfrak{a}$ satisfying \eqref{sem1}. \cite[Theorem 8.13]{GT} shows that for all integer $m\ge 0$ and $f\in H^m(\Omega)$, the BVP \eqref{se1} admits a unique solution $U(f):=(1-\Delta_D)^{-1}f\in H^{2+m}(\Omega)$ provided that $\Omega$ is of class $C^{2+m}$. Furthermore, $\|U(f)\|_{H^{m+2}(\Omega)}\le \mathbf{c}_0\|f\|_{H^m(\Omega)}$, where $\mathbf{c}_0$ is a constant independent of $f$. The particular choice of $t=m$ and $m=k-2$ yields $\|U(f)\|_{H^k(\Omega)}\le \mathbf{c} \|f\|_{B^t(\Omega)}$, where the constant $\mathbf{c} >0$ is independent of $f$. Here, we used that $B^m(\Omega)\hookrightarrow C^m(\overline{\Omega})\hookrightarrow H^m(\Omega)$. Let us observe that the condition $k>t+n/2$ holds only when $n=2$ or $n=3$. For $f_1\in H^k(\Omega)$ we verify that $\mathfrak{a}$ given by
\[
\mathfrak{a}(u):=\delta (1-\Delta_D)^{-1}u+f_1,\quad u\in B^t(\Omega),
\]
satisfies \eqref{sem1} provided that $\eta:=\delta \mathbf{c}<\mathbf{\hat{c}}^{-1}$.




\subsection{DtN map and an inverse potential problem}


In this subsection, we define the Dirichlet-to-Neumann (DtN) map and discuss an inverse potential problem. To this end, we assume that $\Omega$ is of class $C^{3+\lfloor n/2\rfloor}$. By applying Theorem \ref{thmbd3.1} with $s=0$ and $k = \lfloor n/2\rfloor + 1$, we obtain the following result.

\begin{corollary}\label{corbd3}
Let $V \in C^{\lfloor n/2\rfloor,1}(\overline{\Omega}) \setminus \{0\}$ and $-\lambda^{-1} \notin \sigma(S_V)$. For all $h \in H^{\lfloor n/2\rfloor+5/2}(\Gamma)$, the BVP
\begin{equation}\label{bvp0.0}
(1 - \Delta + \lambda V)u = 0 \quad \text{in }\Omega, \quad u|_{\Gamma} = h
\end{equation}
admits a unique solution $u = u_V(h) \in B^2(\Omega)$, and the following inequality holds:
\[
\|u\|_{B^2(\Omega)} \leq \mathbf{c} \|h\|_{H^{\lfloor n/2\rfloor+5/2}(\Gamma)},
\]
where $\mathbf{c} = \mathbf{c}(n,\Omega, V, \lambda) > 0$ is a constant.
\end{corollary}


Let $\partial_\nu$ denote the derivative along the unit normal vector field $\nu$ on $\Gamma$. In light of the fact that $B^2(\Omega)$ is continuously embedded in $C^2(\overline{\Omega})$, under the assumptions and notations of Corollary \ref{corbd3}, the mapping
\[
\Lambda_V: h \in H^{\lfloor n/2\rfloor+5/2}(\Gamma)\mapsto \partial_\nu u_V(h) \in C^1(\Gamma)
\]
defines a bounded operator, commonly referred to as the Dirichlet-to-Neumann map associated with $V$.

Given that $H^{\lfloor n/2\rfloor+5/2}(\Gamma)$ is dense in $H^{1/2}(\Gamma)$ and that $\Lambda_V$ admits a unique extension belonging to $\mathscr{B}(H^{1/2}(\Gamma), H^{-1/2}(\Gamma))$, we derive the following corollary as a consequence of the results in \cite{SU}.

\begin{corollary}\label{corbd4}  
Assume that $n \geq 3$. Let $V_1, V_2 \in C^{\lfloor n/2\rfloor,1}(\overline{\Omega}) \setminus \{0\}$  and $-\lambda^{-1} \notin \sigma(S_{V_1}) \cup \sigma(S_{V_2})$. If $\Lambda_{V_1} = \Lambda_{V_2}$, then $V_1 = V_2$.
\end{corollary}





