\section{Proofs for Section \ref{sec: sufficient conditions}}

\begin{lem}\label{lem: simple questions}
For any $\vt{d}\in\R^\Theta$, $\vt{X}\left(a\right)=\vt{u}\left(a\right)+\vt{d}$
and $\vt{X}(a)=\vt{d}$ are incentivizable.
\end{lem}

\begin{proof}
Let $L,M\in\R$ be such that, for all $a$ and $\theta$, $L<u(a;\theta)+d(\theta)<M$ and $L<d(\theta)<M$.  If $\vt{X}\left(a\right)=\vt{u}\left(a\right)+\vt{d}$, let 
\[
V\left(r,a,\theta\right)=\intop_{L}^{r}X\left(a;\theta\right)dx+\intop_{r}^{M}xdx-\frac{M^2}{2}=\left(u\left(a;\theta\right)+d\left(\theta\right)\right)(r-L)-\frac{1}{2}r^{2},
\]
where $d(\theta)$ is the $\theta$-coordinate of $\vt{d}$. For this $V$, simple calculations show that the optimal choice of $r$ given $a$ is $\E_{p}X\left(a;\theta\right)$. Since the optimal $r$ is greater than $L$, the optimal choice of action $a$ is the same as in the decision problem with utility $u$.  A similar argument applies if $\vt{X}(a)=\vt{d}$, in which case we let $V(r,a,\theta)=u\left(a;\theta\right)+d\left(\theta\right)(r-L)-\frac{1}{2}r^{2}$.
\end{proof}

\begin{proof}[Proof of Proposition \ref{Observation 0}]
Suppose $V$ incentivizes a question profile $X$. Let $\vt{Y}\left(a\right)=\gamma (a)\vt{X}\left(a\right)+\kappa(a) \vt{1}$ for some $\gamma,\kappa:A\longrightarrow\R$. Letting $W\left(r,a,\theta\right)=V\left(\frac{1}{\gamma (a)}\left(r-\kappa (a)\right),a,\theta\right)$, it is straightforward to verify that $W$ incentivizes $\vt{Y}$. The result now follows from Lemma \ref{lem: simple questions}.
\end{proof}


\section{Proofs for Section \ref{sec: necessary conditions}}

\begin{proof}[Proof of Lemma \ref{lem: adjacency}]
We first prove the latter formulation of the result (i.e., that $\bar{\vt{X}}\left(b\right)=\rho\Delta_a^b+\sigma\bar{\vt{X}}\left(a\right)$), and then prove the equivalence between the two formulations.

%\sloppy

Let $V$ be an elicitation method that incentivizes $X$. Consider two beliefs $p_{0}$ and $p_{1}$ such that (i) actions $a$ and $b$ are both optimal in the decision problem, 
%that lie on the indifference plane for two optimal actions $a,b$ (i.e., $a,b\in\arg\max_{x} p_{k}\cdot \vt{u}(x)$ for $k=0,1$)
i.e., $a,b\in\arg\max_{a'} \E_{p_{k}} [u(a';\cdot)]$ for $k=0,1$, and (ii) the question $\vt{X}(a)$ attains the same value at $p_0$ and $p_1$, i.e., $\E_{p_{0}}[X(a;\cdot)]=\E_{p_{1}}[X(a;\cdot)]$. %; such a pair of beliefs exists because $|\Theta|>3$. 
%(i.e., $p_{0}\cdot \vt{X}(a)=p_{1}\cdot \vt{X}(a)$). 
Letting $r=\E_{p_{0}}[X(a;\cdot)]$, it follows that $\left(a,r\right)$ is optimal given $V$ at all $p_{\alpha}=\alpha p_{1}+\left(1-\alpha\right)p_{0}$ for $\alpha\in [0,1]$. The optimal expected payoff $\E_{p_{\alpha}} [V\left(r,a,\cdot\right)]$ 
is therefore linear in $\alpha$. Since $b$ is also an optimal action at each $p_\alpha$, the optimal expected payoff $\max_{s}\E_{p_{\alpha}}[V\left(s,b,\cdot\right)]$ must be linear in $\alpha$ as well. Therefore, there exists some $r'$ such that, for each
$\alpha$, $r'\in\arg\max_{s}\E_{p_{\alpha}} [V\left(s,b,\cdot\right)$]. In particular, $\E_{p_{k}}[X(b;\cdot)]=r'$ for each $k=0,1$.

%\fussy

Fixing $p_0$, notice that the preceding argument applies to all $p_{1}\in\R^{\Theta}$ satisfying the following orthogonality conditions:
\begin{enumerate}
    \item $p_1-p_0\perp \vt{1}$, ensuring that $p_1$ is a well-defined belief;
    \item $p_1-p_0\perp \vt{u}(a)-\vt{u}(b)$, ensuring that the DM is indifferent between $a$ and $b$ at $p_1$; and
    \item $p_1-p_0\perp \vt{X}(a)$, ensuring that $\vt{X}(a)$ attains the same value at $p_0$ as at $p_1$.
\end{enumerate}
For any such $p_1$, the preceding argument implies that $p_1-p_0\perp \vt{X}(b)$. 
%As long as $p_{0}$ is interior to the indifference plane, the choice of $p_{1}\in\R^{\Theta}$ in the above argument is arbitrary subject to orthogonality conditions: for $d=p_{1}-p_{0}$,
%\[
%d\perp\mathbf{1},d\perp\left(\vt{u}(a)-\vt{u}(b)\right),\text{ and }d\perp \vt{X}(a).
%\]

By a standard linear algebra argument, it follows that $\vt{X}(b)\in\mathrm{span}\left(\mathbf{1},\vt{u}(a)-\vt{u}(b),\vt{X}(a)\right).$ Noting that, for any vector $\vt{v}$, $\bar{\vt{v}}$ differs from $\vt{v}$ by a scalar multiple of $\vt{1}$, and that $\vt{v}\perp \vt{1}$, we obtain
$\bar{\vt{X}}(b)=\rho\left(\bar{\vt{u}}(a)-\bar{\vt{u}}(b)\right)+\sigma\bar{\vt{X}}(a)$
for some $\rho,\sigma\in\R$.

If $\bar{\vt{X}}(b)$ is not collinear with $\bar{\vt{u}}(b)-\bar{\vt{u}}(a)$, then we must have $\sigma\neq 0$, as needed. Otherwise, switching the roles of $a$ and $b$ in the preceding argument yields that $\bar{\vt{X}}(a)$ is also collinear with
$\bar{\vt{u}}(b)-\bar{\vt{u}}(a)$, and therefore one can take $\rho$ and $\sigma$ to be nonzero.

We now show that the above conclusion is equivalent to alignment on adjacent pairs of actions. Note first that $X$ is nontrivially aligned with $u$ on a set of actions $B$ if and only if $\bar{\vt{X}}(a)\equiv_B \gamma(a) \bar{\vt{u}}(a) + \vt{d}$ for some $\gamma(a)\in\R$ and $\vt{d}\in\R^\Theta$, and is trivially aligned with $u$ on $B$ if and only if $\bar{\vt{X}}(a)\equiv_B \gamma(a)\vt{d}$ for some $\gamma(a)\in\R$ and $\vt{d}\in\R^\Theta$. In either case, eliminating $\vt{d}$ leads to an equation of the form $\bar{\vt{X}}\left(b\right)=\rho\Delta_a^b+\sigma\bar{\vt{X}}\left(a\right)$ with $\sigma\neq 0$.

For the converse, if $\rho=0$, then $X$ is trivially aligned with $u$ on $\{a,b\}$. If $\rho\neq0$, then the alignment is nontrivial, with
$
\vt{d}=\frac{1}{\rho}\bar{\vt{X}}(b)-\bar{\vt{u}}(b)
=\frac{\sigma}{\rho}\bar{\vt{X}}(a)-\bar{\vt{u}}(a),
$
$\gamma(a)=\rho/\sigma$, and $\gamma(b)=\rho$.
\end{proof}

