\begin{proof}[Proof of Lemma \ref{lem:adjacency cycles}]
Without loss of generality, let $a_0\in C$ be such that either $\bar{\vt{X}}(a_0)= 0$ or $\bar{\vt{X}}(a_0)\notin V_C$. (If no such $a_0$ exists, the lemma holds trivially.)

By Lemma \ref{lem: adjacency}, for each $i=1,\dots,n$, we have 
$\bar{\vt{X}}\left(a_{i}\right)
=\rho_{i}\Delta_{a_{i-1}}^{a_{i}}+\sigma_{i}\bar{\vt{X}}\left(a_{i-1}\right)$
for some $\sigma_i\neq0$ and some $\rho_i$. Iterating these equations gives 
\[
\bar{\vt{X}}\left(a_{0}\right)=\bar{\vt{X}}\left(a_{n}\right) =\sum_{i=1}^{n}\Gamma_{i}\rho_{i}\Delta_{a_{i-1}}^{a_{i}}+\Gamma_{0}\bar{\vt{X}}\left(a_{0}\right),
\]
where $\Gamma_{i}=\sigma_{n}\cdots\sigma_{i+1}$ and $\Gamma_{n}=1$.
Because $\Delta_{a_{0}}^{a_{1}}+\cdots+\Delta_{a_{n-1}}^{a_{n}}=0$,
we get
\begin{align*}
\sum_{i=1}^{n-1}\left(\Gamma_{i}\rho_{i}-\rho_{n}\right)\Delta_{a_{i-1}}^{a_{i}}+\left(\Gamma_{0}-1\right)\bar{\vt{X}}\left(a_{0}\right)=0.
\end{align*}
%Suppose that either $\bar{\vt{X}}(a_0)= 0$ or $\bar{\vt{X}}(a_0)\notin V_C$. 
Since either $\bar{\vt{X}}(a_0)= 0$ or $\bar{\vt{X}}(a_0)\notin V_C$, it follows that $\sum_{i=1}^{n-1}\left(\Gamma_{i}\rho_{i}-\rho_{n}\right)\Delta_{a_{i-1}}^{a_{i}}=0.$ Internal independence implies that $\Gamma_{i}\rho_{i}=\rho_{n}$ for each $i=1,\dots,n-1$. 

If $\rho_n=0$, then $\rho_i=0$ for each $i$ since $\Gamma_i\neq 0$. In this case, all $\bar{\vt{X}}(a_i)$ are collinear, which implies that $X$ is trivially aligned with $u$ on $C$. 

For the case of $\rho_n\neq 0$, first note that, by the same iteration as above, for each $k$,
\begin{align*}
\bar{\vt{X}}(a_k) &=\sum_{i=1}^{k-1}\rho_i \frac{\Gamma_i}{\Gamma_k}\Delta_{a_{i-1}}^{a_i} + \frac{\Gamma_0}{\Gamma_k}\bar{\vt{X}}(a_0)
= \frac{\rho_n}{\Gamma_k}\sum_{i=1}^{k-1}\Delta_{a_{i-1}}^{a_i} + \frac{\Gamma_0}{\Gamma_k}\bar{\vt{X}}(a_0)\\
&= \frac{\rho_n}{\Gamma_k}(\bar{\vt{u}}(a_k)-\bar{\vt{u}}(a_0)) + \frac{\Gamma_0}{\Gamma_k}\bar{\vt{X}}(a_0).
\end{align*}
Letting $\gamma(a_k)=\rho_k=\rho_{n}/\Gamma_k\neq0$ and $\vt{d}=-\bar{\vt{u}}\left(a_{0}\right)+\rho_{n}^{-1}\Gamma_{0}\bar{\vt{X}}\left(a_{0}\right)$, we have $\bar{\vt{X}}(a_k)=\gamma(a_k)\left(\bar{\vt{u}}(a_k) +\vt{d})\right)$ for all $k$, and thus $X$ is (nontrivially) aligned with $u$ on $C$.
%
%For each $k$, let $\gamma(a_k)=\rho_k=\Gamma_{k}^{-1}\rho_{n}\neq0$ and notice that 
%\begin{align*}
%\frac{1}{\gamma(a_k)}\bar{\vt{X}}\left(a_{k}\right) & =\rho_{n}^{-1}\sum_{i=1}^{k}\Gamma_{i}\rho_{i}\Delta_{a_{i-1}}^{a_{i}}+\rho_{n}^{-1}\Gamma_{1}\bar{\vt{X}}\left(a_{0}\right)\\
% & =\sum_{i=1}^{k}\Delta_{a_{i-1}}^{a_{i}}+\rho_{n}^{-1}\Gamma_{1}\bar{\vt{X}}\left(a_{0}\right)\\
% & =\bar{u}\left(a_{k}\right)-\bar{u}\left(a_{0}\right)+\rho_{n}^{-1}\Gamma_{1}\bar{\vt{X}}\left(a_{0}\right).
%\end{align*}
%Let $\vt{d}=-\bar{u}\left(a_{0}\right)+\rho_{n}^{-1}\Gamma_{1}\bar{\vt{X}}\left(a_{0}\right)$.
\end{proof}

\begin{proof}[Proof of Lemma \ref{lem:combine sets}]
Alignment with $u$ on $B$ implies that there exist $\gamma_{0}^{B},\gamma_{1}^{B}\in\R$ and $\vt{d}^{B}\in\R^{\Theta}$
such that 
\[
\gamma_{0}^{B}\bar{\vt{X}}(a_{0})-\bar{\vt{u}}(a_{0})
=\gamma_{1}^{B}\bar{\vt{X}}(a_{1})-\bar{\vt{u}}(a_{1})=\vt{d}^{B}.
\]
Together with a similar fact for $D$, we obtain
\[
\gamma_{0}^{B}\bar{\vt{X}}(a_{0})-\gamma_{1}^{B}\bar{\vt{X}}(a_{1}) =\bar{\vt{u}}(a_{0})-\bar{\vt{u}}(a_{1})
\text{ and }\gamma_{0}^{D}\bar{\vt{X}}(a_{0})-\gamma_{1}^{D}\bar{\vt{X}}(a_{1})  =\bar{\vt{u}}(a_{0})-\bar{\vt{u}}(a_{1}).
\]
Subtracting one equation from the other leads to
\[
\left(\gamma_{0}^{B}-\gamma_{0}^{D}\right)\bar{\vt{X}}(a_{0})-\left(\gamma_{1}^{B}-\gamma_{1}^{D}\right)\bar{\vt{X}}(a_{1})=0.
\]
Since $\bar{\vt{X}}(a_0)$ and  $\bar{\vt{X}}(a_1)$ are linearly independent, it must be that $\gamma_{k}^{B}=\gamma_{k}^{D}$
for each $k=0,1$. This in turn implies that $\vt{d}^{B}=\vt{d}^{D}=\vt{d}$.
%The lemma follows from the fact that the argument was independent of the choice of $a_{0},a_{1}\in B\cap D$. 

All that remains is to show that for any other action $a\in B\cup D$, the corresponding parameters $\gamma^B_a$ and $\gamma^D_a$ are equal. Since $\bar{\vt{X}}(a)$ cannot be collinear with both $\bar{\vt{X}}(a_0)$ and $\bar{\vt{X}}(a_1)$, we can repeat the argument replacing one of $a_0$ or $a_1$ with $a$ to obtain $\gamma^B_a=\gamma^D_a$.
\end{proof}

\subsection{General necessary conditions}

A set of actions $B\subseteq A$ is \emph{cycle-rich} if it contains at least four elements and, for any proper subset $B^\prime\subset B$ with at least three elements, there exists $a\in B\setminus B^\prime$ such that 
\[
\bigcap \left\{V_C:C\text{ is internally independent},
a\in C,\text{ and }
|C\cap B^\prime|\geq2
\right\}=\{\vt{0}\}.
\]
The intersection above goes over all internally independent cycles that contain $a$ and at least two elements of $B^\prime$.

