\begin{thm}\label{thm: aligned representation necessary}
Suppose $B\subseteq A$ is cycle-rich. If $X$ is incentivizable, then it is aligned with $u$ on $B$.
\end{thm}

\begin{proof}
We begin with the following observation. %Say that $X$ is \textit{trivial} if $\bar{\vt{X}}(a)$ are collinear for all actions $a$.

\begin{lem} \label{lem:trivial or colinear Delta}
    If $X$ is nontrivially aligned with $u$ on $B$, then %, either $X$ is trivial, or, 
    for any $a,b\in B$, if $\bar{\vt{X}}(a)$ and $\bar{\vt{X}}(b)$ are collinear, they are also collinear with $\Delta_a^b$. 
\end{lem}

\begin{proof}
Let $a,b\in B$ be such that $\bar{\vt{X}}(a)$ and $\bar{\vt{X}}(b)$ are collinear and let $\gamma(\cdot)\neq 0$ and $\vt{d}$ be such that $\bar{\vt{X}}(a)=\gamma(a) \left( \bar{\vt{u}}(a) +\vt{d}\right)$ and $\bar{\vt{X}}(b)=\gamma(b) \left( \bar{\vt{u}}(b) +\vt{d}\right)$. By the collinearity assumption, there exists $\alpha\neq0$ such that $\bar{\vt{u}}(a)+\vt{d}=\alpha\left(\bar{\vt{u}}(b)+\vt{d}\right).$ Because $\bar{\vt{u}}(a)\neq\bar{\vt{u}}(b)$, it must be that $\alpha\neq1$. It follows that $\vt{d}=\frac{1}{1-\alpha}\left(\alpha\bar{\vt{u}}(b)-\bar{\vt{u}}(a)\right)$ and 
\[
\frac{1}{\gamma(a)}\bar{\vt{X}}(a)
=\bar{\vt{u}}(a)+\frac{1}{1-\alpha}\left(\alpha\bar{\vt{u}}(b)-\bar{\vt{u}}(a)\right)
=\frac{\alpha}{1-\alpha}\left(\bar{\vt{u}}(b)-\bar{\vt{u}}(a)\right),
\]
as needed.
\end{proof}

