Take any distinct $a$ and $b$ such that $a_{-i}=b_{-i}$ for some $i$. Then $a$ and $b$ are adjacent, and, by Lemma \ref{lem: adjacency}, there are $x(a,b)\neq0$ and $y(a,b)$ such that $\bar{\vt{X}}(a)=x(a,b)\bar{\vt{X}}(b)+y(a,b)\Delta_{b}^{a}$. Using the above decomposition, we have
\begin{align*}
 0
=&\left[\vt{w}_{i}(a)-x(a,b)\vt{w}_{i}(b)-y(a,b)\Delta_{b_{i}}^{a_{i}}\right]+\sum_{j\neq i}\left[\vt{w}_{j}(a)-x(a,b)\vt{w}_{j}(b)\right]
+\left[\vt{w}_{0}(a)-x(a,b)\vt{w}_{0}(b)\right].
\end{align*}
The proof of Lemma \ref{lem: adjacency} shows that $x(a,b)$ is uniquely defined if and only if $\bar{\vt{X}}(a)\neq0$ and $\bar{\vt{X}}(a)$ is not collinear with $\Delta_{b_{i}}^{a_{i}}$. When this is not the case, we call $(a,b)$ a \emph{free transition}. The values of $x(a,b)$ for free transitions are carefully chosen below. Our choice always satisfies $x(a,b)x(b,a)=1$ (which always holds for non-free transitions). Let $x(a,a)=1$.

Because all vectors in square brackets lie in linearly independent spaces, they must all be equal to 0, and hence
\begin{align}
\label{eq:zero vectors1}
\vt{w}_{i}(a)-x(a,b)\vt{w}_{i}(b)&=y(a,b)\Delta_{b_{i}}^{a_{i}},\\
\label{eq:zero vectors2}
\vt{w}_{j}(a)-x(a,b)\vt{w}_{j}(b)&=0\text{ for each }j\neq i,\\
\label{eq:zero vectors3}
\text{and}\qquad \vt{w}_{0}(a)-x(a,b)\vt{w}_{0}(b)&=0.
\end{align}

\begin{lem}\label{lem:Product decomposition 1}
%For each $a$, there exist $\gamma_i(a)\neq0$ and vectors $\vt{w}^*_i(a_i)$ for each $i=1,\dots,I$ and $\gamma_0(a)\neq 0$ and a vector $\vt{w}^*_0$ such that 
There exist a vector $\vt{w}^*_0$, vectors $\vt{w}^*_i(a_i)$ for each $i=1,\dots,I$ and $a_i$, and scalars $\gamma_i(a)\neq0$ for each $a$ and $i=0,\dots,I$ such that 
$\vt{w}_i(a)=\gamma_i(a)\vt{w}^*_i(a_i)$ for each $i$, and $\vt{w}_0(a)=\gamma_0(a)\vt{w}^*_0$.
\end{lem}

This result says that, for a fixed $a_i$, the vectors $\vt{w}_i(a_{-i}a_i)$ for $a_{-i}$ are either all collinear or all equal to $0$. 

\begin{proof}
For the first claim, fix an action $a^*$. For each $a_i$, let $\vt{w}_i^*(a_i)=\vt{w}_i(a^*_{-i}a_i)$. 
For each $a$, fix an arbitrary a path of adjacent actions $a^0=a^*_{-i}a_i,\dots,a^n=a$ such that for each $l<n$, $a^l_i=a_i$. Let $\gamma_i(a)=x(a^n,a^{n-1})\cdots x(a^1,a^0)$. A repeated application of (\ref{eq:zero vectors2}) shows that 
$\vt{w}_i(a)=\gamma_i(a)\vt{w}^*_i(a_i).$ Analogous argument shows the second claim.
\end{proof}



\begin{lem}\label{lem:Product decomposition 2}\label{lem:nontrivial problems}
For each $i$, one of the following is true:
\begin{enumerate}[label=(\roman*)]
\item $\vt{w}_i^*(a_i)=0$ for each $a_i$,
\item there exists $a_i^0\in A_i$ such that $\vt{w}_i^*(a^0_i)=0$ and $\vt{w}_i^*(a_i)\neq0$ for each $a_i\neq a^0_i$,
\item $\vt{w}_i^*(a_i)\neq0$ for each $a_i$.
\end{enumerate}
If question $X$ does not depend trivially on task $i$, then there is an action $a_i$ such that $\vt{w}_i^*(a_i)\neq 0$.
\end{lem}

\begin{proof}
Suppose that there are three different actions $a_i$, $b_i$, and $c_i$ such that $\vt{w}_i^*(a_i)=\vt{w}_i^*(b_i)=\vt{0}$ and $\vt{w}_i^*(c_i)\neq0$. Equation (\ref{eq:zero vectors1}) together with Lemma \ref{lem:Product decomposition 1} imply that, for any $c_{-i}$, $\vt{w}_i(c_ic_{-i})$ is simultaneously collinear with $\Delta_{c_i}^{a_i}$ and $\Delta_{c_i}^{b_i}$, contradicting the independence assumption. 

For the last claim, suppose that $\vt{w}_i^*(a_i)=0$ for each $a_i$. Equation (\ref{eq:zero vectors1}) together with Lemma \ref{lem:Product decomposition 1} imply that $y(a,b)=0$ for each $a$ and $b$ such that $a_{-i}=b_{-i}$. But then, for each $a_{-i}$, the vectors $\bar{\vt{X}}(a_{-i}a_i)$ and $\bar{\vt{X}}(a_{-i}b_i)=x(a_{-i}b_i,a_{-i}a_i)\bar{\vt{X}}(a_{-i}a_i)$ are collinear. Hence, $X$ depends on task $i$ trivially.
\end{proof}

Case (i) of Lemma \ref{lem:Product decomposition 2} is equivalent to $X$ depending on problem $i$ trivially. Because $X$ depends nontrivially on at least three tasks, there must be at least three tasks in cases (ii) or (iii).

\subsection{Exact cycles}\label{sec:Exact cycles}

\sloppy

Recall that an adjacency cycle $a^0,\dots,a^n=a^0$ is \textit{exact} if  $\prod_{l<n}x(a^l,a^{l+1})=1.$ The goal of this subsection as well as subsections \ref{sec:Exact cycles - Tools} to \ref{sec:Exact cycles - Free transitions}  is to prove the following result.

\fussy

\begin{lem}\label{lem:all cycles exact}
    The values $x(a,b)$ for free transitions $(a,b)$ can be chosen so that (i) $x(a,b)x(b,a)=1$ for all adjacent $a$ and $b$, and (ii) every adjacency cycle is exact.
\end{lem}

Lemma \ref{lem:Product decomposition 1} and a repeated application of equation (\ref{eq:zero vectors3}) shows that, if  $\vt{w}^*_0\neq0$, then, all adjacency cycles are exact. From now on, we assume that $\vt{w}^*_0=0$.

\subsection{Tools}\label{sec:Exact cycles - Tools}

The two results in this section develop tools that we use in the subsequent analysis. 

The first tool allows us to replace the problem of whether a cycle is exact with a problem about related cycles. For each path $c=(a^0,\dots,a^{n_c})$ and each transition $(a,b)$ between two adjacent actions, define 
\[
m_a^b(c)=\#\left\{l<n_c:a^l=a,a^{l+1}=b\right\}-\#\left\{l<n_c:a^l=b,a^{l+1}=a\right\}.
\]

\begin{lem}\label{lem:sum of exact cycles}
Suppose that, for some adjacency cycle $c$, there exists a collection $D$ of exact adjacency cycles such that for each adjacent pair $a,b$,
$m_a^b(c)=\sum_{d\in D}m_a^b(d)$. Then cycle $c$ is exact.
\end{lem}

\begin{proof}
Let $\prec$ be an arbitrary strict order on the set of actions $A$. Then we have
\begin{align*}
\prod_{l<n_c}x(a^{c,l},a^{c,l+1})
&=\prod_{a\prec b}\left(x(a,b)\right)^{m_a^b(c)}
=\prod_{a\prec b}\left(x(a,b)\right)^{\sum_{d\in D}m_a^b(d)}\\
&=\prod_{d\in D} \prod_{a\prec b}\left(x(a,b)\right)^{m_a^b(d)}
=\prod_{d\in D} \prod_{l<n_d}x(a^{d,l},a^{d,l+1})
= 1,
\end{align*}
where the last equality comes from the fact that cycles in $D$   are exact. 
\end{proof}

The second result shows that it is enough to consider particular kinds of ``small'' cycles.

\begin{lem}\label{lem:small cycles}
Every adjacency cycle is exact if (and only if) the following cycles are exact:
\begin{enumerate}
\item $\left(a,b,a\right)$ for all adjacent actions $a$ and $b$,
\item $\left(a,b,c,a\right)$ for all triples of actions $a$, $b$, and $c$ such that $a_{-i}=b_{-i}=c_{-i}$,
\item $\left(a,a_{-i}b_i, a_{-ij}b_ib_j,a_{-j}b_j,a\right)$ for all actions $a$, $i\neq j$, and $b_i$ and $b_j$.
\end{enumerate}
\end{lem}

\begin{proof}
Call cycles of the three forms described in the lemma \emph{small} and any other cycle \emph{large}. 

Take any large cycle of adjacent actions $a=a^0,\dots,a^n=a$ and let $i_l$ be such that, for each $l<n$, $a^l_{-i_l}=a^{l+1}_{-i_l}$. For future reference, notice that if the action in some task $i$ is ever changed, then it must be changed at least twice: if $i_l=i$ for some $l$, then there is some $l^\prime\neq l$ such that $i_{l^\prime}=i$. We use Lemma \ref{lem:sum of exact cycles} and small cycles to reorder and reduce the large cycle without changing the value of the product of the associated $x$ terms:
\begin{itemize}
\item if $i_l>i_{l+1}$ for $l<n-1$ we use the small cycle of type (3) to switch the order of the two tasks, i.e., replace the cycle fragment $\dots,a^l,a^{l+1},a^{l+2},\dots$, where $a^{l+1}=a^l_{-i_l}a^{l+2}_{i_l}$, with 
$\dots,a^l,a^l_{-i_{l+1}}a^{l+2}_{i_{l+1}},a^{l+2},\dots$. More precisely, due to Lemma \ref{lem:sum of exact cycles} and the fact that the small cycle is exact, the exactness of the original cycle is equivalent to the exactness of the modified cycle;
\item if $i_l=i_{l+1}$ (including possibly $i_{n-1}=i_0$), we use either type (1) or type (2) to reduce the large cycle, i.e, replace the cycle fragment $\dots,a^l,a^{l+1},a^{l+2},\dots$ with $\dots,a^l,a^{l+2},\dots$ in the case of a type (2) cycle or with $\dots,a^l,\dots$ in the case of a type (1) cycle.
\end{itemize}

Consider a process in which one of the above operations is applied until it cannot be applied anymore. Because either the operations reorder tasks in an increasing direction, or, if they don't change the order, they reduce the length of the cycle, the process never reverts and it will eventually stop. If the process stops at a single-element cycle $a$, then, because $x(a,a)=1$, the original cycle must be exact.

Otherwise, the process stops with a nontrivial cycle $a=a^0,\dots,a^m=a$ for some $2\leq m\leq n$. Then it must be that $i_l<i_l+1$ for each $l<m$. But this contradicts the earlier observation that, in an adjacency cycle, if $i$ appears at least once, it must appear at least twice. 
\end{proof}

\subsection{Cycles without free transitions}\label{sec:Exact cycles - No free transitions}

Here, we consider the exactness of small cycles without free transitions. We refer to $i$ from the definition of type (2) cycles as the \textit{relevant task} for this cycle; similarly, we refer to $i$ and $j$ as the relevant tasks for type (3) cycles. We say that a type (2) or type (3) cycle $\left(a^0,\dots,a^n=a^0\right)$  is \textit{grounded} if there exists some $k$ such that $k$ is not a relevant task and $\vt{w}^*_k(a_k^0)\neq0$. 

\begin{lem}\label{lem:grounded cycles}
Any grounded type (2) or type (3) cycle is exact.  
\end{lem}

\begin{proof}
Suppose that $\vt{w}^*_k(a_k^0)\neq0$ for some irrelevant task $k$. Then $\vt{w}_k(a^i)\neq0$ for each action $a^i$ in the cycle. A repeated application of (\ref{eq:zero vectors2}) shows that for each $l\leq n$,
\[
\vt{w}_k(a^l)=\vt{w}_k(a^0)x(a^0,a^1)\cdots x(a^{l-1},a^l).
\] 
The result follows from the fact that $a^n=a^0$. 
\end{proof}

\begin{lem}\label{lem:cycles with collinear Deltas}
%Suppose that for some $a$ and $i\neq j$ and any $b_i$ and $b_j$, 
Let $\left(a,a_{-i}b_i, a_{-ij}b_ib_j,a_{-j}b_j,a\right)$ be a type (3) small cycle such that either (i) $\vt{w}^*_i(a_i)\neq0$ and $\vt{w}^*_i(a_i)$ is not collinear with $\Delta_{a_i}^{b_i}$, or (ii) $\vt{w}^*_j(a_j)\neq0$ and $\vt{w}^*_j(a_j)$ is not collinear with $\Delta_{a_j}^{b_j}$.
Then the cycle is exact. 
\end{lem}

\begin{proof}
Using \ref{eq:zero vectors1} and \ref{eq:zero vectors2}, we get
\begin{align*}
%x(a_{-i}b_i, a_{-ij}b_ib_j)& \left(x(a,a_{-i}b_i)\vt{w}_i(a)+x(a,a_{-i}b_i)\Delta_{a_i}^{b_i}\right)\\
%&=x(a_{-i}b_i, a_{-ij}b_ib_j)\vt{w}_i(a_{-i}b_i)\\
%&=\vt{w}_i(a_{-ij}b_ib_j)\\
%&=x(a_{-j}b_j, a_{-ij}b_ib_j)\vt{w}_i(a_{-j}b_j)+y(a_{-j}b_j, a_{-ij}b_ib_j)\Delta_{a_i}^{b_i}\\
%&=x(a_{-j}b_j, a_{-ij}b_ib_j)x(a, a_{-j}b_j)\vt{w}_i(a)+y(a_{-j}b_j, a_{-ij}b_ib_j)\Delta_{a_i}^{b_i}.
x(a_{-ij}b_ib_j,a_{-i}b_i)& \left(x(a_{-i}b_i,a)\vt{w}_i(a)+y(a_{-i}b_i,a)\Delta_{a_i}^{b_i}\right)\\
&=x(a_{-ij}b_ib_j,a_{-i}b_i)\vt{w}_i(a_{-i}b_i)
=\vt{w}_i(a_{-ij}b_ib_j)\\
&=x(a_{-ij}b_ib_j, a_{-j}b_j)\vt{w}_i(a_{-j}b_j)+y(a_{-ij}b_ib_j, a_{-j}b_j)\Delta_{a_i}^{b_i}\\
&=x(a_{-ij}b_ib_j, a_{-j}b_j)x(a_{-j}b_j, a)\vt{w}_i(a)+y(a_{-ij}b_ib_j, a_{-j}b_j)\Delta_{a_i}^{b_i}.
\end{align*}
Suppose without loss of generality that $\vt{w}^*_i(a_i)\neq0$ and $\vt{w}^*_i(a_i)$ is not collinear with $\Delta_{a_i}^{b_i}$, which implies that $\vt{w}_i(a)\neq 0$ and $\vt{w}_i(a)$ is not collinear with $\Delta_{a_i}^{b_i}$. The first and the last line of the above sequence of equalities yield
\[
x(a_{-ij}b_ib_j,a_{-i}b_i) x(a_{-i}b_i,a) = x(a_{-ij}b_ib_j, a_{-j}b_j)x(a_{-j}b_j, a).
%x(a_{-i}b_i, a_{-ij}b_ib_j)x(a,a_{-i}b_i)=x(a_{-j}b_j, a_{-ij}b_ib_j)x(a, a_{-j}b_j).
\]
Hence, the cycle is exact. 
\end{proof}

\begin{lem}\label{lem:nonzero relevant}
Suppose that a type (2) or type (3) small cycle is such that $\vt{w}^*_i(a_i)\neq 0$ for each action $a$ in the cycle and each relevant task $i$ and none of the transitions is free. Then it is exact.
\end{lem}

