\section*{Appendix A: Code Samples}
\addcontentsline{toc}{section}{Appendix A: Code Samples}

This appendix collects and presents extended pseudocode samples that define critical operations within the SPV (Simplified Payment Verification) model. Each procedure reflects the minimal client functionality necessary for verification, inclusion checking, and consistency with the honest chain. These algorithms are formally aligned with definitions and assertions given throughout Sections 4 through 6. The pseudocode avoids implementation-specific optimisations in favour of clarity and analytical traceability.

\subsection*{A.1 Header Verification Procedure}

\begin{algorithm}[H]
\caption*{\textbf{Procedure: \textsc{ValidateHeader}}}
\begin{algorithmic}[1]
\REQUIRE Block header $H_i$, previous header $H_{i-1}$
\ENSURE $\mathsf{true}$ if $H_i$ is valid and consistent with $H_{i-1}$, else $\mathsf{false}$
\IF{$\mathsf{PrevHash}(H_i) \ne \mathsf{Hash}(H_{i-1})$}
    \RETURN $\mathsf{false}$ \hfill\COMMENT{Broken chain linkage}
\ENDIF
\IF{$\mathsf{PoW}(H_i) < d_i$}
    \RETURN $\mathsf{false}$ \hfill\COMMENT{Insufficient proof-of-work}
\ENDIF
\IF{Invalid timestamp, version, or nonce}
    \RETURN $\mathsf{false}$ \hfill\COMMENT{Malformed or manipulated header}
\ENDIF
\RETURN $\mathsf{true}$
\end{algorithmic}
\end{algorithm}

\subsection*{A.2 SPV Transaction Inclusion Verification}

\begin{algorithm}[H]
\caption*{\textbf{Procedure: \textsc{VerifyInclusion}}}
\begin{algorithmic}[1]
\REQUIRE Transaction $T$, Merkle root $R$, proof $\pi_T$
\ENSURE $\mathsf{true}$ if $T$ is provably included under $R$, else $\mathsf{false}$
\STATE $h \gets \mathsf{Hash}(T)$
\FORALL{$s \in \pi_T$}
    \STATE $h \gets \mathsf{Hash}(h \| s)$ or $\mathsf{Hash}(s \| h)$ based on position
\ENDFOR
\IF{$h = R$}
    \RETURN $\mathsf{true}$
\ELSE
    \RETURN $\mathsf{false}$
\ENDIF
\end{algorithmic}
\end{algorithm}

\subsection*{A.3 Header Chain Parsing}

\begin{algorithm}[H]
\caption{Procedure: ParseChain}
\begin{algorithmic}[1]
\REQUIRE Header list $\mathcal{H} = [H_0, H_1, \dots, H_n]$
\ENSURE Validated chain $\mathcal{H}'$
\STATE Initialise $\mathcal{H}' \gets []$
\FOR{$i = 1$ to $n$}
    \IF{$\textsf{ValidateHeader}(H_{i-1}, H_i) = \mathsf{true}$}
        \STATE Append $H_i$ to $\mathcal{H}'$
    \ELSE
        \STATE \textbf{break}
    \ENDIF
\ENDFOR
\RETURN $\mathcal{H}'$
\end{algorithmic}
\end{algorithm}

\subsection*{A.4 SPV Client Transaction Acceptance}

\begin{algorithm}[H]
\caption*{\textbf{Procedure: \textsc{AcceptTransaction}}}
\begin{algorithmic}[1]
\REQUIRE Transaction $T$, candidate headers $\mathcal{H}$
\ENSURE $\mathcal{M}(T) = \mathsf{true}$ if $T$ is accepted; otherwise $\mathsf{false}$
\STATE Extract proof $\pi_T \gets \Pi(T)$
\FORALL{$H_i \in \mathcal{H}$}
    \STATE Extract $R_i = \mathsf{MerkleRoot}(H_i)$
    \IF{$\textsc{VerifyInclusion}(T, R_i, \pi_T) = \mathsf{true}$}
        \RETURN $\mathsf{true}$
    \ENDIF
\ENDFOR
\RETURN $\mathsf{false}$
\end{algorithmic}
\end{algorithm}








