\section*{Appendix C: Mathematical Proofs}
\addcontentsline{toc}{section}{Appendix C: Mathematical Proofs}

\begin{proof}[Proof of Lemma 26 (Equivalence Lemma)]
Let $T$ be a transaction included in block $B_k$ with Merkle root $R$, and let $\pi_T$ denote the Merkle proof for $T$ in $B_k$ such that $\mathsf{VerifyMerkleProof}(\pi_T, R) = \mathsf{true}$. By Axiom 19 (Honest Majority Axiom Revisited), let $M_H$ and $M_A$ denote honest and adversarial miners respectively, and let $\alpha = \frac{\sum M_H \mathrm{PoW}(m)}{\sum (M_H + M_A) \mathrm{PoW}(m)}$.

Assume the SPV client receives headers $\mathcal{H} = \{H_0, H_1, \dots, H_k\}$ up to height $k$. By the assumption of $\mu$-honest chain growth (Definition 21), the probability that an adversary reorganises the chain to exclude $T$ decreases exponentially with depth $d = k - i$, where $i$ is the height of the block containing $T$. 

Let $\beta = \mathbb{E}[|B_{t+\Delta}| - |B_t|]$, the expected growth in chain length over time $\Delta$. The probability $P_{\text{rev}}$ that $T$ is excluded after depth $d$ is bounded as:
\[
P_{\text{rev}} \leq \left( \frac{1 - \alpha}{\alpha} \right)^d.
\]
Therefore, as $d$ increases, $P_{\text{rev}} \to 0$ exponentially, establishing that the SPV client converges toward consistency with a full node view.
\end{proof}

\begin{proof}[Proof of Theorem: Merkle Path Soundness]
Let $D_i$ be a data block in the Merkle tree with root $R$. Let $\pi_i$ be the ordered set of sibling hashes along the path from $D_i$ to $R$. We define a recursive function $h^{(0)} = \mathsf{Hash}(D_i)$ and $h^{(j)} = \mathsf{Hash}(h^{(j-1)} \| \pi_i[j])$ for $j = 1$ to $\log_2 n$ where $n$ is the number of leaves.

Then,
\[
\mathsf{VerifyMerkleProof}(\pi_i, R) \iff h^{(\log_2 n)} = R.
\]
This recursive construction ensures that any alteration of $D_i$ or $\pi_i$ results in $h^{(\log_2 n)} \ne R$, and hence $\mathsf{VerifyMerkleProof}(\pi_i, R) = \mathsf{false}$. Thus, $\pi_i$ is sound iff $D_i \in \mathcal{D}$ such that $R = \mathsf{MerkleRoot}(\mathcal{D})$.
\end{proof}






