\label{appendix}
\section*{Appendix} \label{sec:matrad-functions}
Let $\tilde{d}=\mathcal{D}_{r}\phi\in{\mathbb{R}_{+}^{n_{r}}}$ be the vectorized dose distribution in the volume of interest $r$, using the dose-influence matrix $\mathcal{D}\in{\mathbb{R}_{+}^{n\times{m}}}$ and the fluence vector $\phi\in{\mathbb{R}_{+}^{m}}$. Then, the dose optimization functions stated in \cref{subsec:design} are:

\subsection*{Dose Uniformity}
Dose uniformity measures the standard deviation of the dose distribution, i.e.,
\begin{align*}
    f_{\text{Dose Uniformity}}(\tilde{d}) = \sqrt{\mathds{V}ar(\tilde{d})}\,.
\end{align*}

\subsection*{Squared Deviation}
Squared deviation includes a reference dose parameter $d^{ref}$, and quantifies the normalized sum of squared differences between the dose values and the reference value. The corresponding function is described by
\begin{align*}
    f_{\text{Squared Deviation}}(\tilde{d}) = \frac{1}{n_{r}}(\tilde{d}-d^{ref})^{T}(\tilde{d}-d^{ref})\,.
\end{align*}

\subsection*{Squared Underdosing}
Squared underdosing is structurally similar to squared deviation, except that it uses a minimum dose parameter $d^{min}$ and only penalizes lower values, yielding the function
\begin{align*}
    f_{\text{Squared Underdosing}}(\tilde{d}) = \frac{1}{n_{r}}\varepsilon^{T}\varepsilon\,,\quad\varepsilon_{i}=\begin{cases}
        d^{min}-\tilde{d}_{i}\,,\quad &\tilde{d}_{i}<{d^{min}} \\
        0\,,\quad &\text{else}
    \end{cases}\,,
\end{align*}
where $\varepsilon$ \enquote{clamps} the dose difference values to only consider underdosed voxels.

\subsection*{Maximum DVH}
Maximum DVH takes a reference dose $d^{ref}$ and a maximum volume fraction $v^{max}$ as input parameters, calculates the dose quantile $d^{v}$ (by inverting the DVH at $v=v^{max}$) and determines the function values from
\begin{align*}
    f_{\text{Maximum DVH}}(\tilde{d}) = \frac{1}{n_{r}}\varepsilon^{T}\varepsilon\,,\quad\varepsilon_{i}=\begin{cases}
        \tilde{d}_{i}-d^{ref}\,,\quad &\tilde{d}_{i}\in(d^{ref}, d^{v}] \text{ and } d^{ref}<d^{v} \\
        0\,,\quad &\text{else}
    \end{cases}\,,
\end{align*}
where $\varepsilon$ is only nonzero if the respective dose value contributes to moving the DVH quantile beyond the reference value.

\subsection*{Minimum DVH}
Minimum DVH, analogous to maximum DVH, utilizes the value function
\begin{align*}
    f_{\text{Minimum DVH}}(\tilde{d}) = \frac{1}{n_{r}}\varepsilon^{T}\varepsilon\,,\quad\varepsilon_{i}=\begin{cases}
        \tilde{d}_{i}-d^{ref}\,,\quad &\tilde{d}_{i}\in(d^{v}, d^{ref}] \text{ and } d^{v}<d^{ref} \\
        0\,,\quad &\text{else}
    \end{cases}\,,
\end{align*}
but defines a minimum volume fraction $v^{min}$ instead of $v^{max}$.

\subsection*{Minimum/Maximum Dose}
Minimum/Maximum dose implements a box constraint on the dose, i.e., the dose values are lower- and upper-bounded by $d^{min}$ and $d^{max}$. The constraint function is given by the identity and therefore the constraint reads
\begin{align*}
    d^{min}\leq{\tilde{d}}\leq{d^{max}}\,.
\end{align*}
Internally, matRad translates such a constraint by applying the log-sum-exp approximation.

