\section{Multilinear Maps and Tensor Decomposition in Arbitrary Order}
\label{sec:multi-cp}

\paragraph{Tensor product in arbitrary order.} Let $N\ge 2$ and let $V_i=\mathbb{R}^{d_i}$ for $i=1,\dots,N+1$ be
finite‑dimensional real vector spaces equipped with fixed ordered bases
$\{\ve_{k}^{(i)}\}_{k=1}^{d_i}$.
A multilinear map
\[
m \colon V_1\times\cdots\times V_N \longrightarrow V_{N+1}
\]
is uniquely represented by a linear map
\[
\widetilde m \colon V_1\otimes\cdots\otimes V_N \;\longrightarrow\; V_{N+1},
\qquad
m(\vx^{(1)},\dots,\vx^{(N)})=\widetilde m\!\bigl(\vx^{(1)}\otimes\cdots\otimes \vx^{(N)}\bigr).
\]
With respect to the chosen bases, $\widetilde m$ is encoded by an
$(N\!+\!1)$‑way tensor
\[
\mM \in V_{N+1}\otimes V_1^{\!*}\otimes\cdots\otimes V_N^{\!*}
\cong\mathbb{R}^{d_{N+1}\times d_1\times\cdots\times d_N},
\]
defined through
\begin{equation}
\label{eq:multi-tp}
m\!\bigl(\vx^{(1)},\dots,\vx^{(N)}\bigr)
\;=\;\sum_{i_{N+1}=1}^{d_{N+1}}\sum_{i_1=1}^{d_1}\cdots\sum_{i_{N}=1}^{d_N}\mM_{i_{N+1}i_1\cdots i_N}\vx^{(1)}_{i_1}\cdots \vx^{(N)}_{i_N} \ve^{(N+1)}_{i_{N+1}}.
\end{equation}
\paragraph{CP decomposition in arbitrary order.} To lower computational cost, we can approximate $\mM$ by a
rank‑$R$ CP decomposition
\[
\mM_{i_{N+1}i_1\cdots i_N}\;\approx\;
\sum_{r=1}^{R}
\mA_{i_{N+1}r}\,
\mB^{(1)}_{i_1 r}\cdots
\mB^{(N)}_{i_N r},
\]
where
$\mA\in\mathbb{R}^{d_{N+1}\times R}$ and
$\mB^{(i)}\in\mathbb{R}^{d_i\times R}\;(i=1,\dots,N)$. Substituting into~\cref{eq:multi-tp} and rearranging the summation the we obtain
\[
    m\!\bigl(\vx^{(1)},\dots,\vx^{(N)}\bigr)\;\approx\;
    \sum_{r=1}^{R} \left(\sum_{i_1=1}^{d_1}\mB_{i_1r}^{(1)}\vx_{i_1}^{(1)}\right)\cdots\left(\sum_{i_N=1}^{d_N} \mB_{i_N r}^{(N)}\vx_{i_N}^{(N)}\right) \left(\sum_{i_{N+1}=1}^{d_{N+1}}\mA_{i_{N+1}r} \ve^{(N+1)}_{i_{N+1}}\right),
\]
which can be expressed in matrix form
\[
m\!\bigl(\vx^{(1)},\dots,\vx^{(N)}\bigr)\;\approx\; \mA \left(\mB^{(1)\top}\vx^{(1)}\odot \cdots \odot\mB^{(N)\top}\vx^{(N)}\right)
\]
where $\odot$ denotes the Hadamard product.

\section{CP-Based Tensor Product}

\subsection{Error Bound of CP-Based Tensor Product}
\label{proof:error_bound}

\begin{theorem}{Equivariance Error Bound of CP Decomposition}{equivariance-error}
Let CG tensor $\mM\in \mathbb{R}^{d\times d\times d}$ and $\widehat{\mM}$ be the rank-$R$ CP-decomposition-based approximation obtained by Frobenius minimization. For any rotation $\mR\in SO(3)$ and any bounded $\rm{SO}(3)$-irreps $\vx,\vy\in\mathbb{R}^{d}, \lVert \vx\rVert, \lVert\vy\rVert\le C$, we have 
\[
\varepsilon(\mR,\vx,\vy)\;\le\;
 2 C^2 \Bigl(\sum_{n=1}^3\sum_{k>R_T}\sigma_{k}^{(n)2}\Bigr)^{1/2},
\]
where $R_T = \lceil R^{1/3} \rceil$ and $\sigma_k^{(n)}$ is the $k$-th singular value of mode-$n$ matricization of $\mM$.
\end{theorem}
\begin{proof}
Given any rotation $\mR$ and $\rm{SO}(3)$-irreps $\vx,\vy$,
\[
\lVert D(\mR)\vx\rVert = \sqrt{\vx^\top D(\mR)^*D(\mR) \vx} = \sqrt{\vx^\top\mI\vx} = \sqrt{\vx^\top\vx} = \lVert \vx \rVert,
\]
and
\begin{equation}
\begin{split}
\lVert (D(\mR)\otimes D(\mR)) (\vx\otimes\vy)\rVert_F &= \sqrt{\operatorname{Tr}((\vx\otimes\vy)^\top (D(\mR)\otimes D(\mR))^*(D(\mR)\otimes D(\mR)) (\vx\otimes\vy))} \\
&= \sqrt{\operatorname{Tr}((\vx\otimes\vy)^\top (D(\mR)^*D(\mR)\otimes D(\mR)^* D(\mR)) (\vx\otimes\vy))} \\
&= \sqrt{\operatorname{Tr}((\vx\otimes\vy)^\top (\mI\otimes \mI) (\vx\otimes\vy))} \\
&= \sqrt{\operatorname{Tr}((\vx\otimes\vy)^\top (\vx\otimes\vy))} \\
&= \lVert  \vx\otimes\vy \rVert_F
\end{split}
\end{equation}
Since the tensor product Frobenius norm is equal to multiplication of Frobenius norms, we have
\begin{equation}
    \begin{split}
        \varepsilon(\mR,\vx,\vy)&=\lVert\widehat{\mM}(D(\mR)\vx\otimes D(\mR)\vy)-D(\mR)\widehat{\mM}(\vx\otimes\vy)\rVert\\
        &= \lVert\widehat{\mM}(D(\mR)\vx\otimes D(\mR)\vy)- \mM(D(\mR)\vx\otimes D(\mR)\vy) \\ 
        &\quad +D(\mR)\mM(\vx\otimes\vy) - D(\mR)\widehat{\mM}(\vx\otimes\vy)\rVert\\
        &\le \lVert\widehat{\mM}(D(\mR)\vx\otimes D(\mR)\vy)- \mM(D(\mR)\vx\otimes D(\mR)\vy) \rVert \\
        &\quad + \lVert D(\mR)\mM(\vx\otimes\vy) - D(\mR)\widehat{\mM}(\vx\otimes\vy)\rVert\\
        &= \lVert(\widehat{\mM} - \mM)(D(\mR)\vx\otimes D(\mR)\vy) \rVert \\
        &\quad + \lVert D(\mR)(\mM - \widehat{\mM})(\vx\otimes\vy)\rVert\\
        &= \lVert(\widehat{\mM} - \mM)(D(\mR)\otimes D(\mR))(\vx\otimes \vy) \rVert \\
        &\quad + \lVert D(\mR)(\mM - \widehat{\mM})(\vx\otimes\vy)\rVert\\
        &\le \lVert\widehat{\mM} - \mM\rVert_F \lVert(D(\mR)\otimes D(\mR))(\vx\otimes \vy) \rVert_F \\
        &\quad + \lVert \mM - \widehat{\mM}\rVert_F \lVert \vx\otimes\vy\rVert_{F}\\
        &=2\lVert\widehat{\mM} - \mM \rVert_F \lVert \vx\otimes \vy\rVert_F\\
        &=2\lVert\widehat{\mM} - \mM \rVert_F \lVert \vx\rVert   \lVert\vy\rVert\\
        &\le 2 C^2 \Bigl(\sum_{n=1}^3\sum_{k>R_T}\sigma_k^{2}\Bigr)^{1/2}
    \end{split}
\end{equation}
\end{proof}

\subsection{Universality of CP-Based Tensor Product}
\label{proof:universality}


\begin{theorem}{Universality of CP Decomposition}{universality}
Consider $\rm{SO}(3)$-irreps $\vx\in V_1=\mathbb{R}^{d}$, $\vy\in V_2 = \mathbb{R}^{d_2}$ and $V_3= \mathbb{R}^{d_3}$. Fo any $\rm{SO}(3)$-equivariant bilinear map $\Phi$, there exist $\mB\in \mathbb{R}^{d_1\times R}$, $\mC\in \mathbb{R}^{d_2\times R}$, $\mA\in\mathbb{R}^{R\times d_3}$ such that $\Phi$ can be written as
\[
\label{hadamard}
\Phi(\vx,\vy) = \mA(\mB^\top \vx \odot \mC^\top \vy) \in V_3,
\]
if $R$ is sufficient large.
\end{theorem}


\begin{proof}
A bilinear map \(\Phi\) is uniquely encoded by a third-order tensor \(\mT\in V_3\otimes V_1\otimes V_2\) via
\(\Phi(\vx,\vy)=\mT(\vx\otimes\vy)\) and all equivariant tensors $\mT$ form the fixed-point subspace \(\mathcal H = (V_3\otimes V_1\otimes V_2)^{\rm{SO}(3)} = \operatorname{Hom}_{\rm{SO}(3)}(V_1\otimes V_2,V_3)\). Write each irrep $V_i$ as a direct sum of irreps
\[
V_i \cong\bigoplus_{\ell=0}^L c_i^{(\ell)}H^{(\ell)}
\]
where \(c_i^{(\ell)}\) is the multiplicity of the irrep of degree \(\ell\) in \(V_i\) and $H^{(\ell)}$ is the $(2\ell + 1)$-dimensional irrep. For every admissible path $(\ell_1,\ell_2,\ell_3)$ and multiplicities $ 1\le v \le c_1^{(\ell_1)},1\le w \le c_2^{(\ell_2)},1\le u \le c_3^{(\ell_3)}$, we pick orthonormal basis vectors $\va_u^{(\ell_3)}\in V_3$, $\vb_v^{(\ell_1)} \in V_1$, $\vc_w^{(\ell_2)}\in V_2$ and define
\[
\mT^{(\ell_1,\ell_2,\ell_3)}_{uvw} = \va_u^{(\ell_3)} \otimes \vb_v^{(\ell_1)} \otimes \vc_w^{(\ell_2)}
\]
so that \(\{\mT^{(\ell_1,\ell_2, \ell_3)}_{uvw}\}\) is a basis of \(\mathcal H\). And then we zero‐pad $\va^{(\ell_3)}_u,\vb^{(\ell_1)}_v,\vc^{(\ell_2)}_w$ as the vectors in $V_3$, $V_1$, and $V_2$, respectively. Now let
\[
\mu = \operatorname{dim} \mathcal H = \sum_{\ell_1 = 0}^L \sum_{\ell_2 = 0}^L \sum_{\ell_3 = |\ell_1 - \ell_2|}^{\ell_1 + \ell_2 \le L} c_1^{(\ell_1)} c_2^{(\ell_2)} c_3^{(\ell_3)},
\]
and rename the basis as $\{\mT^{(k)}\}_{k=1}^\mu$ and vectors $\va^{(\ell_3)}_u,\vb^{(\ell_1)}_v,\vc^{(\ell_2)}_w$ as $\va_k,\vb_k,\vc_k$ for the corresponding $\mT^{(k)} = \mT^{(\ell_1,\ell_2, \ell_3)}_{uvw}$. Given an arbitrary equivariant tensor \(\mT\in\mathcal H\), we expand it in that basis \(\mT=\sum_{k=1}^\mu\lambda_{k} \mT^{(k)}\) and stack the vectors correspondingly as
\[
\mA = \bigl[\lambda_1 \va_1,\dots,\lambda_{\mu}\va_{\mu}\bigr]^{\!\top},
\quad
\mB = \bigl[\vb_1,\dots,\vb_{\mu}\bigr],
\quad
\mC = \bigl[\vc_1,\dots,\vc_{\mu}\bigr].
\]
For all \(\vx,\vy\) one then has
\(
\Phi(\vx,\vy)=\mA(\mB^{\!\top}\vx\odot\mC^{\!\top}\vy).
\)
Taking \(R\ge\mu\) supplies enough columns/rows to hold this equation; any surplus columns can be zero-padded.
\end{proof}

\section{Model and Training Configurations}
\label{sec:configuration}

\paragraph{PubChemQCR training.} All experiments on the PubChemQCR benchmarks use a cutoff radius of $4.5\,$\AA, the Adam optimizer with initial learning rate $5\times10^{-4}$, and a \textsc{ReduceLROnPlateau} scheduler with a patience of 2 epochs. Models are trained for up to 100 epochs on PubChemQCR‑S and up to 15 epochs on the full PubChemQCR dataset on NVIDIA A100-80GB GPUs.


\paragraph{TDN configuration.}
For both PubChemQCR and PubChemQCR-S datasets, TDN employs 6 graph‑transformer layers with MLP attention, an irreps‑channel dimension of 256, a maximum angular degree $L=1$, and a graph-transformer layer for the force output head. Also, the model is trained with batch size 32 under the above training protocol. For the OC20 \textsc{IS2RE-Direct} task, TDN adopts the same model configuration. For the OC20 \textsc{S2EF} task, TDN uses a similar configuration but with 12 graph‑transformer layers and an additional degree-$1$ bond-order orientation (BOO) feature~\citep{qu2024the} adding to the initial node embedding. For the OC22 \textsc{IS2RE} task, TDN also uses a similar configuration but with 6 graph‑transformer layers and an additional degree-$9$ BOO feature~\citep{qu2024the} adding to the initial node embedding.


