The function $\theta(z)$, in Algorithm~\ref{algPinns}, representing the solution of the Lane-Emden equation, is approximated by a neural network  $\theta(z; \mathbf{w})$, where  $\mathbf{w}$ denotes the trainable weights. The eigenvalue, $r$ is treated as a trainable scalar parameter, reparameterized as $r = \exp(r_{\text{raw}})$ to enforce positivity. During training, the neural network model minimizes a composite loss: (1) physics-informed loss which quantifies the deviation from the Lane-Emden differential equation at multiple collocation points in the domain $z \in [0, 1] $, and (2) boundary condition loss which enforces the required physical constraints at the domain boundaries. The algorithm uses automatic differentiation to compute derivatives of the neural network outputs, ensuring precision in evaluating its residuals. Additionally, learning rate scheduling and model check-pointing are used to improve training efficiency and reliability. This approach allows the simultaneous approximation of both the eigenfunction, $\theta(z)$ and the eigenvalue, $r$. 

%%%

\begin{algorithm}[htb]
\caption{Solving the Eigenvalue Lane-Emden Equation using PINNs}
\label{algPinns}
\begin{algorithmic}
\State \textbf{Input:} 
\State Power index $ n $, number of collocation points $ N $, learning rate $ \eta $, \\ number of training epochs $ E_{\max} $

\State \textbf{Initialization:} 
\State Initialize neural network $ \theta(z; \mathbf{w}) $ with parameters $ \mathbf{w} $
\State Initialize trainable parameter $ r_{\text{raw}} \in \mathbb{R} $; define $ r = \exp(r_{\text{raw}}) $
\State Sample $ N $ collocation points $ \{ z_i \}_{i=1}^N \in [0, 1] $

\State \textbf{Training Loop:} 
\For{$\text{epoch} = 1$ to $E_{\max}$}
\State \textbf{Compute PDE residual:}
\For{each collocation point $ z_i $}
\State Compute $ \theta(z_i) $, $ \theta'(z_i) $, $ \theta''(z_i) $ using automatic differentiation
\State Compute residual:
\[
R(z_i) =  z_i \theta''(z_i) + 2 \theta'(z_i) +  z_i r^2 \theta(z_i)^n
\]
\EndFor
\State Compute physics-informed loss:
\[
\mathcal{L}_{\text{physics}} = \frac{1}{N} \sum_{i=1}^N \left( R(z_i) \right)^2
\]

\State \textbf{Compute boundary condition loss:}
\[
\mathcal{L}_{\text{bc}} = (\theta(0) - 1)^2 + (\theta'(0)-0)^2 + (\theta(1) - 0)^2
\]

\State \textbf{Total loss:} $ \mathcal{L} = \mathcal{L}_{\text{physics}} + \mathcal{L}_{\text{bc}} $

\State \textbf{Backpropagation:} 
\State Backpropagate gradients of $ \mathcal{L} $ with respect to $ \mathbf{w} $ and $ r_{\text{raw}} $
\State Update parameters using Optimizer
\State \textbf{Learning rate scheduler:} 
\State Adjust learning rate using ReduceLROnPlateau scheduler
\State \textbf{Save the best model:} 
\State Save current best model if $ \mathcal{L} $ is minimized
\EndFor

\State \textbf{Output:} 
\State Trained network $ \theta(z) $, estimated eigenvalue $ r $ and the loss plot
\end{algorithmic}
\end{algorithm}

