where  $V(w_B, p_1)\equiv\frac{1}{2}  \big(\frac{w_B+\sqrt {w^2_B -4 \mathcal{D} p_1 ^2}}{2 p _1} \big)^2 + \mathcal{D} \ln \big(\frac{w_B-\sqrt {w^2_B -4 \mathcal{D} p_1 ^2}}{2} \big).$
\end{lemma}

\begin{proof}[{\bf Proof of Lemma \ref{demand1}}]
The budget constraint of agent $B$ is $p_1c^B_1+p_2c^B_2=w_B$. To simplify notations, we ignore subscript $B$. At optimum, the budget constraint is binding $p_1c_1+p_2c_2=w$, which implies that $c_2=\frac{w-p_1c_1}{p_2}$. So, we consider the following problem
\begin{align}
\ma_{0 \leq c_1 \leq w/p_1}\frac{c_1^2}{2} + \mathcal{D}\ln(w-p_1c_1)
\end{align}
in order to determine the demand for good $1$ of agent A. 

Let us denote $f(c_1)\equiv \frac{c_1^2}{2} + \mathcal{D}\ln(w-p_1c_1)$. We have that $f'(c_1)=\frac {-p_1 c_1 ^2 + c_1 w -\mathcal D p_1}{w -p_1 c_1}$. Observe that $f'(c_1)=0\Leftrightarrow p_1c_1^2-w c_1+{\mathcal D}p_1=0$.
%\hbox{Let }x \equiv \frac{w+\sqrt{w^2-4\mathcal{D}p_1^2}}{2p_1}  \hbox{ and  }y\equiv \frac{w-\sqrt{w^2-4\mathcal{D}p_1^2}}{2p_1}

Denote $
x_1 \equiv \frac{w+\sqrt{w^2-4\mathcal{D}p_1^2}}{2p_1}  \hbox{ and  } x_2\equiv \frac{w-\sqrt{w^2-4\mathcal{D}p_1^2}}{2p_1}$.  


We consider all possible cases.

(1) If $w^2- 4\mathcal{D} p _1 ^2 <0$, then $f^\prime (c_1) < 0, \forall c_1 \geq 0$. So, the demand is $c_1=0$.

(2) If $w^2- 4\mathcal{D} p _1 ^2 =0$, then $c_1=x_1=x_2$ is the unique solution to the equation $f'(c_1)=0$. Moreover, we have $f^\prime (c_1)= \frac{-p_1 (c_1-\frac{w}{2p_1})^2}{w-p_1 c_1} \leq 0$. By consequence, the demand is again $c_1=0$.

(3) If $w^2- 4\mathcal{D} p _1 ^2 >0$, then we have $0<x_2<x_1<w/p_1$. Moreover, we observe that: $f^\prime (c_1) > 0 \Leftrightarrow x_2<c_1< x_1$. In this case, we have  $$\ma_{0 \leq c_1 \leq w/p_1}f(c_1)=\max\Big\{f(0),f(x_1)\Big\}.$$

Observe that $f(x_1)-f(0)=V(w,p_1)-\mathcal{D}ln(w)$. From these properties, we obtain the demand  as in Lemma \ref{demand1}.
%\end{itemize}

\end{proof}

We now prove Lemma \ref{agentB}.  We look at the conditions: 
$(w_B)^2>4\mathcal{D}p_1^2$ and  ${V}(w_B,p_1) \geq \mathcal{D}\ln (w_B)$. As in step 1, we have
 \begin{align}
(w_B)^2> 4\mathcal{D}p_1^2& \Leftrightarrow e^B_1+e^B_2\frac{p_2}{p_1}> 2\sqrt{\mathcal{D}} \Leftrightarrow e^B_1+p e^B_2> 2\sqrt{\mathcal{D}}\\
{V}(w_B,p_1) \geq \mathcal{D}\ln (w_B)& \Leftrightarrow g\Big(\frac{e^B_1+e^B_2\frac{p_2}{p_1}}{\sqrt{\mathcal{D}}}\Big)\geq g(x^*) \Leftrightarrow e^B_1+pe^B_2\geq x^*\sqrt{\mathcal{D}}
    \end{align}
    because the function $g$ is strictly increasing on $ [2,\infty)$.
    %
    By combining with Lemma \ref{demand1} and the fact that \blue{$x^*=2.2>2$}, we obtain Lemma \ref{agentB}. 

