\subsection{Proof of Proposition \ref{main1}}
\begin{proof}[{\bf Proof of Proposition \ref{main1}}] 

{\bf Step 1}. Assume that there is a corner equilibrium where $c^B_1=0$. We have $c^A_1=\frac{p_1e^A_1+p_2e^A_2}{2p_1}, \quad c^A_2=\frac{p_1e^A_1+p_2e^A_2}{2p_2}$ and $c^B_2=\frac{p_1e^B_1+p_2e^B_2}{p_2}$. According to market clearing condition $c^A_1+c^B_1=e^A_1+e^B_1$, we have 
\begin{align}
\frac{p_1e^A_1+p_2e^A_2}{2p_1}=e^B_1+e^A_1   \Longleftrightarrow 
\frac{p_2}{p_1}=\frac{2e^B_1+e^A_1}{e^A_2}=\pi^{cor}
\end{align}
According to Lemma \ref{agentB}, we have $e^B_1+pe^b_2\leq x^*\sqrt{\mathcal{D}}$, i.e., $e^B_1+ \pi^{cor} e^b_2\leq x^*\sqrt{\mathcal{D}}$. 

%Conversely, we can check that when $e^B_1+ \pi^{cor} e^b_2\leq x^*\sqrt{\mathcal{D}}$, there exists an equilibrium with relative price $\pi^{cor}$.





{\bf Step 2}: Assume that there is an interior equilibrium with $c^B_1>0$. Lemma \ref{demand1} implies that $(p_1e^B_1+p_2e^B_2)^2>4\mathcal{D}p_1^2$ and  ${V}(w_B,p_1) \geq  \mathcal{D}\ln (w_B)$.

According to Lemma \ref{demand1}, the market clearing condition $c^A_1+c^B_1=e^A_1+e^B_1$ becomes $
\sqrt{(p_1e^B_1+p_2e^B_2)^2-4\mathcal{D}p_1^2}=p_1(e^B_1+e^A_1)-p_2(e^B_2+e^A_2)$. 
Since $(p_1e^B_1+p_2e^B_2)^2>4\mathcal{D}p_1^2$, this equation is equivalent to $F(X)=0$ and $
(e^B_1+e^A_1)-X(e^B_2+e^A_2)>0$, where we denote
$X\equiv p_2/p_1$. 

It means that the equation $F(X)=0$ has at least one solution in $(0,\frac{e^B_1+e^A_1}{e^B_2+e^A_2})$.  By combing this with (\ref{rank}) and the facts that $F(0)=(e^B_1+e^A_1)^2-(e_1^B)^2+4\mathcal{D}>0$ and $F(\frac{e^B_1+e^A_1}{e^B_2+e^A_2})=4\mathcal{D}-(e^B_2\frac{e^B_1+e^A_1}{e^B_2+e^A_2}+e^B_1)^2$, we get that $\Delta \geq 0$ and  $e^B_1+\frac{e^B_1+e^A_1}{e^B_2+e^A_2}e^B_2-2\sqrt{\mathcal{D}}>0$. % or equivalently, 
%\begin{align}
%e^B_1+\frac{e^B_1+e^A_1}{e^B_2+e^A_2}e^B_2-2\sqrt{\mathcal{D}}>0,
%\end{align}
So, we find that  $X=\pi^{int}$.


We now look at the conditions: 
$(w_B)^2>4\mathcal{D}p_1^2$ and  ${V}(w_B,p_1) \geq \mathcal{D}\ln (w_B)$. As in step 1, we have
 \begin{align}
(w_B)^2> 4\mathcal{D}p_1^2& \Leftrightarrow e^B_1+e^B_2\frac{p_2}{p_1}> 2\sqrt{\mathcal{D}} \Leftrightarrow e^B_1+e^B_2\pi^{int}> 2\sqrt{\mathcal{D}} \\
{V}(w_B,p_1) \geq \mathcal{D}\ln (w_B)& \Leftrightarrow g(e^B_1+e^B_2\frac{p_2}{p_1})\geq g(x^*(\mathcal D)) \Leftrightarrow e^B_1+e^B_2\pi^{int}\geq x^*(\mathcal D).
    \end{align}
Finally, we get that $e^B_1+e^B_2\pi^{int}\geq x^*{(\mathcal D)}$.  



%\begin{remark}Since $x^*{(\mathcal D)}>2\sqrt{\mathcal{D}}$, condition $e^B_1+e^B_2\pi^{int}\geq x^*{(\mathcal D)}$ implies that $e^B_1+e^B_2\pi^{int}> 2\sqrt{\mathcal{D}}$.
%because  $\pi^{int}<\frac{e^B_1+e^A_1}{e^B_2+e^A_2}$ and  $x^*>2\sqrt{\mathcal{D}}$. 
%\end{remark}

{\bf Step 3}. We will prove that: if (\ref{pcor}) is satisfied, there exists a unique equilibrium, the relative price is $\frac{p_2}{p_1}=\pi^{cor} \equiv  \frac{2e^B_1+e^A_1}{e^A_2}$ and  $c^{B}_1=0$.
First, suppose that there is another equilibrium relative price. According to step 2,  it must be $\pi^{int}$ and $\Delta \geq 0$. In this case, we have $e^B_1+e^B_2\pi^{int}\geq x^*\sqrt{\mathcal{D}}$. Since $\pi^{int}<\pi^{cor}$, we get that $e^B_1+e^B_2\pi^{cor}\geq x^*\sqrt{\mathcal{D}}$, a contradiction. Therefore, we obtain the uniqueness of equilibrium relative price.

Second, we prove that $\pi^{cor}$ is an equilibrium relative price. Indeed, let $\frac{p_2}{p_1}=\pi^{cor} \equiv  \frac{2e^B_1+e^A_1}{e^A_2}$. Since $e^B_1+e^B_2\frac{2e^B_1+e^A_1}{e^A_2}\leq x^*\sqrt{\mathcal{D}}$, we have that $(c^B_1,c^B_2)=(0,{p_1e^B_1}/{p_2}+e^B_2)$ is an optimal solution {to } agent B's maximization problem. It is easy to see that $(\frac{p_1e^A_1+p_2e^A_2}{2p_1}, \frac{p_1e^A_1+p_2e^A_2}{2p_2})$ is the unique solution {to } agent A's maximization problem.


The market clearing condition   for good $1$ is
\begin{align}
\frac{p_1e^A_1+p_2e^A_2}{2p_1} + c^B_1=e^B_1+e^A_1   
\end{align}
which implies that $c^B_1=0$ is the unique good 1 consumption of agent $B$ {at} equilibrium.

{\bf Step 4}. We can prove point 2 of Proposition \ref{main1} by adopting a similar argument used in step 3. Point 3 of of Proposition \ref{main1} is a direct consequence of points 1 and 2.

\end{proof}

