\subsection{Other proofs}
\begin{proof}[{\bf Proof of Remark \ref{remark}}] Consider an equilibrium $(p_1,p_2,c^{B}_1,c^{B}_2,c^{D}_1,c^{D}_2)$. Since the utility function of agent $D$ is $U^D(c_1^D,c^D_2)=c^D_2$, we have $c_1^D=0, p_2c^D_2=w_D\equiv p_1e^{D}_1+p_2e^D_2$. The good $1$  market clearing condition implies that $c^B_1=e_1\equiv e^B_1+e^D_1>0$. Since the good 1 consumption of agent $B$ is positive, Lemma \ref{demand1} implies that $(p_1e^B_1+p_2e^B_2)^2>4\mathcal{D}p_1^2$ and  ${V}(w_B,p_1) \geq  \mathcal{D}\ln (w_B)$. Denote $X\equiv p_2/p_1$. Observe that
 \begin{align}
(w_B)^2> 4\mathcal{D}p_1^2& \Leftrightarrow e^B_1+e^B_2\frac{p_2}{p_1}> 2\sqrt{\mathcal{D}} \Leftrightarrow e^B_1+e^B_2X> 2\sqrt{\mathcal{D}} \\
{V}(w_B,p_1) \geq \mathcal{D}\ln (w_B)& \Leftrightarrow g(e^B_1+e^B_2\frac{p_2}{p_1})\geq g(x^*(\mathcal D)) \Leftrightarrow e^B_1+e^B_2X\geq x^*(\mathcal D).
    \end{align}
%
We now determine the relative price $X\equiv p_2/p_1$. The good 1 market clearing condition implies that $\sqrt{(e^B_1+e^B_2X)^2-4\mathcal{D}}=(e^B_1+2e^D_1)-e^B_2X$.  
Since $e^B_1+e^B_2X> 2\sqrt{\mathcal{D}}$, this is equivalent to
\begin{subequations}
\begin{align*}
&\begin{cases}
 (e^B_1+e^B_2X)^2-4\mathcal{D}=((e^B_1+2e^D_1)-e^B_2X)^2\\
(e^B_1+2e^D_1)-e^B_2X>0
\end{cases}
\Leftrightarrow
 e^B_2X=\frac{e^D_1(e^B_1+e^D_1)+\mathcal D}{e^B_1+e^D_1}<e^B_1+2e^D_1
\end{align*}
\end{subequations}
To sum up, parameters must satisfy
\begin{align*}
\begin{cases}
\frac{e^D_1(e^B_1+e^D_1)+\mathcal D}{e^B_1+e^D_1}<e^B_1+2e^D_1\\
e^B_1+e^B_2X\geq x^*(\mathcal D)
\end{cases}
\Leftrightarrow
\begin{cases}
 \mathcal D<e^B_1+e^D_1\\
e^B_1+e^D_1+\frac{\mathcal D}{e^B_1+e^D_1}\geq x^*(\mathcal D)
\end{cases}
\end{align*}
Conversely, we can easily check that under these conditions, there exists an equilibrium whose relative price $X$ is determined by 
$e^B_2X=\frac{e^D_1(e^B_1+e^D_1)+\mathcal D}{e^B_1+e^D_1}$.

\end{proof}

\subsection{Demand correspondences under CARA utility}\label{cara}

Assume that $U(c_1,c_2)=\frac{e^{\alpha_1c_1}}{\alpha_1}+\mathcal{D}\frac{e^{\alpha_2c_2}}{\alpha_2}$ where $\alpha_1\not=0,\alpha_2\not=0,\mathcal{D}>0$. We want to maximize this function subject to constraints
\begin{align}
c_1\geq 0,c_2\geq 0, \quad 
p_1c_1+p_2c_2=w
\end{align}
where $p_1>0,p_2>0,w>0$.

In optimal, we have $c_2=\frac{w-p_1c_1}{p_2}$. So, the problem becomes to maximize the function $f(c_1)\equiv \frac{e^{\alpha_1c_1}}{\alpha_1}+\mathcal{D}\frac{e^{\alpha_2\frac{w-p_1c_1}{p_2}}}{\alpha_2}$ subject to $0\leq c_1\leq \frac{w}{p_1}$.
We have
\begin{align*}
f'(c_1)=&e^{\alpha_1c_1}-\frac{\mathcal{D}p_1}{p_2}e^{\alpha_2\frac{w-p_1c_1}{p_2}}=e^{\alpha_2\frac{w-p_1c_1}{p_2}}\Big(e^{(\alpha_1+\alpha_2\frac{p_1}{p_2})c_1-\alpha_2\frac{w}{p_2}}-\frac{\mathcal{D}p_1}{p_2}\Big).
\end{align*}
Observe that $f'(c_1)\geq 0$ if and only if $(\alpha_1+\alpha_2\frac{p_1}{p_2})c_1\geq \alpha_2\frac{w}{p_2}+ln\big(\frac{\mathcal{D}p_1}{p_2}\big)$.

When $(\alpha_1+\alpha_2\frac{p_1}{p_2})\not=0$, we denote \begin{align}
c_1^*\equiv \frac{ln\big(\frac{\mathcal{D}p_1}{p_2}\big)}{(\alpha_1+\alpha_2\frac{p_1}{p_2})}.
\end{align}
There are three different cases.
\begin{enumerate}
\item $\alpha_1+\alpha_2\frac{p_1}{p_2}=0$. In this case, there are three cases.
\begin{enumerate}
\item $\alpha_2\frac{w}{p_2}+ln\big(\frac{\mathcal{D}p_1}{p_2}\big)=0$. We have $c_1= [0,w/p_1]$.

\item $\alpha_2\frac{w}{p_2}+ln\big(\frac{\mathcal{D}p_1}{p_2}\big)<0$. We have $f'(c_1)> 0$ for any $c_1$ and, hence, $c_1= \{w/p_1\}$.

\item $\alpha_2\frac{w}{p_2}+ln\big(\frac{\mathcal{D}p_1}{p_2}\big)>0$. We have $f'(c_1)< 0$ for any $c_1$, and, hence, $c_1= \{0\}$.
\end{enumerate}
\item $\alpha_1+\alpha_2\frac{p_1}{p_2}>0$. In this case, there are three cases.
\begin{enumerate}
\item $c_1^*\leq 0$. We have $f'(x)> 0 \forall c\in (0,w/p_1)$. So, we get $c_1=\{w/p_1\}$.
\item $c_1^*\geq w/p_1$. We have $f'(x)< 0 \forall c\in (0,w/p_1)$. So, we get $c_1=\{0\}$.
\item $c_1^*\in (0, w/p_1)$. We have $f'(x)< 0 \forall x\in (0,c_1^*)$ and $f'(x)> 0 \forall x\in (c_1^*,w/p_1)$. Hence, we have \begin{align}
c_1=\begin{cases}\{0\} &\text{ if } f(0)>f(w/p_1) \\
  \{0,  w/p_1\}& \text{ if }f(0)=f(w/p_1)\\
 \{w/p_1\} &\text{ if }f(0)<f(w/p_1).
\end{cases}
\end{align}

\end{enumerate}



\item $\alpha_1+\alpha_2\frac{p_1}{p_2}<0$. In this case, there are three cases. 
\begin{enumerate}
\item If $c_1^*\leq 0$, then $f'(x)< 0 \forall c\in (0,w/p_1)$. So, we get $c_1=\{0\}$.
\item If $c_1^*\geq w/p_1$, then $f'(x)> 0 \forall c\in (0,w/p_1)$. So, we get $c_1=\{w/p_1\}$.
\item If $c_1^*\in (0, w/p_1)$, then $f'(x)> 0 \forall x\in (0,c_1^*)$ and $f'(x)< 0 \forall x\in (c_1^*)$. So, we get $
c_1=\{c_1^*\}$

\end{enumerate}
\end{enumerate}



