\section{A recursive approach to deriving baseline AJD moments}
The general AJD process is an n-dimensional Markov process, denoted by 
$\mathbf{x}(t)$, with state space $D\subset \mathbb{R}^n$. It is governed by the following stochastic differential equation (SDE):
$$
    \d \mathbf{x}(t) = \mathbf{\mu}(\mathbf{x}(t))\d t + \mathbf{\sigma}(\mathbf{x}(t))\d \mathbf{w}(t) + \d\mathbf{z}(t),
$$
where $\mathbf{w}(t)$ is an n-dimensional standard Wiener process, and $\mathbf{z}(t)$ is an inhomogeneous compound Poisson process (CPP). The jumps in $\mathbf{z}(t)$ occur with intensity $\mathbf{\lambda}(\mathbf{x}(t)): D\rightarrow \mathbb{R}_{\geqslant 0}^n$ and are distributed according to $F_{\mathbf{j}}(\cdot)$ on $\mathbb{R}^n$. The drift $\mathbf{\mu}(\cdot)$, instantaneous covariance matrix $\mathbf{\sigma}(\cdot)\mathbf{\sigma}(\cdot)^{\mathrm{T}}$, and jump intensity $\mathbf{\lambda}(\cdot)$ all exhibit affine dependence on the state $\mathbf{x}(t)$ \citep{duffie2000transform}, determined by coefficients $(\mathbf{K},\mathbf{H},\mathbf{l})$ as
\begin{itemize}
    \item $\mathbf{\mu}(\mathbf{x}) = \mathbf{K}_0 + \mathbf{K}_1\mathbf{x}$, for  $\mathbf{K} = (\mathbf{K}_0,\mathbf{K}_1)\in \mathbb{R}^n\times \mathbb{R}^{n\times n}$.
    \item $(\mathbf{\sigma}(\mathbf{x})\mathbf{\sigma}(\mathbf{x})^{\mathrm{T}})_{ij} = (\mathbf{H}_0)_{ij} + (\mathbf{H}_1)_{ij}\cdot \mathbf{x}$, for $\mathbf{H}=(\mathbf{H}_0,\mathbf{H}_1)\in \mathbb{R}^{n\times n}\times \mathbb{R}^{n\times n\times n}$.
    \item $\mathbf{\lambda}(\mathbf{x}) = \mathbf{l}_0 + \mathbf{l}_1\cdot \mathbf{x}$, for $\mathbf{l}=(\mathbf{l}_0,\mathbf{l}_1)\in \mathbb{R}^n\times\mathbb{R}^{n\times n}$.
\end{itemize}
