\section*{Appendix B: Joint moments of contemporaneous CPPs}\label{app:joint-moments-cpps}
In this section, we present the computation of the joint moments of ($\iez_{s,t}, \iz_{s,t}, \iz_{s,t}^*$). This is accomplished by deriving the joint moment-generating function (MGF) of these contemporaneous CPP processes.

The joint MGF of ($\iez_{s,t}, \iz_{s,t}, \iz_{s,t}^*$) can be derived as follows:
\begin{align*}
    M_{\iez_{s,t},\iz_{s,t},\iz_{s,t}^*}(\mathbf{a})
    &\defeq \E[e^{a_1\iez_{s,t} + a_2\iz_{s,t} + a_3\iz_{s,t}^*}]\\
    %&= \E[\E[e^{a_1 \sum_{i=1}^{N(t-s)}e^{ks_i}J_i + a_2\sum_{i=1}^{N(t-s)}J_i + a_3\sum_{i=1}^{N(t-s)}J_i^*}|N(t-s) = n]]\\
    &= \E[\E[e^{\sum_{i=1}^n [(a_1 e^{ks_i} + a_2)J_i + a_3J_i^*]} |N(t-s) = n]]\\
    &= \E[\E[\left(\E[M_{J_i}(a_1e^{ks_i} + a_2)]\cdot M_{J_i^*}(a_3)\right)^n |N(t-s) = n]]\\
    &= \sum_{n=0}^{\infty} \left(\E[M_{J_i}(a_1e^{ks_i} + a_2)] \cdot M_{J_i^*}(a_3)\right)^n \frac{[\lambda (t-s)]^n e^{-\lambda (t-s)}}{n!}\\
    &= e^{-\lambda (t-s)}  \sum_{n=0}^{\infty}  \left[\lambda (t-s)\E[M_{J_i}(a_1e^{ks_i} + a_2)]\cdot M_{J_i^*}(a_3)\right]^n/n!\\
    %&= e^{-\lambda (t-s)} e^{\lambda (t-s)\E[M_{J_i}(a_1e^{ks_i} + a_2)]\cdot M_{J_i^*}(a_3)}\\
    &= e^{\lambda (t-s)\left(\E[M_{J_i}(a_1e^{ks_i} + a_2)]\cdot M_{J_i^*}(a_3) - 1\right)},
\end{align*}
where $\mathbf{a}$ is a vector of real numbers, i.e., $\mathbf{a} \defeq (a_1, a_2, a_3)$, $N(\cdot)$ is the shared counting process for ($\iez_{s,t}, \iz_{s,t}, \iz_{s,t}^*$), and $M_{J_i}(\cdot)$ and $M_{J_i^*}(\cdot)$ are the MGFs of $J_i^*$ and $J_i$, respectively. Note that, conditional on $N(t-s) = n$, the unsorted arrival times are uniformly distributed over the interval $(s,t]$. For notational simplicity, we use $\{s_1,\dots, s_n\}$ to denote these unsorted arrival times and omit the conditional notation $|N(t-s) = n$ in the expectation.  In what follows, we will demonstrate that $\E[M_{J_i}(a_1e^{ks_i} + a_2)]$ admits a closed-form expression.

First, we substitute the MGF of $J_i$ (conditioned on $s_i$) with its known formula:
\begin{align*}
    \E[M_{J_i}(a_1e^{ks_i} + a_2)]
    = \E[\E[e^{(a_1e^{ks_i} + a_2)J_i}|s_i]]
    = \E\left[\frac{1}{1-(a_1e^{ks_i} + a_2 )\mu_v} \right].
\end{align*}
By introducing two new variables $a \defeq - a_1\mu_v, b \defeq 1 - a_2\mu_v$, the above expectation simplifies to:
\begin{align*}
    \E[M_{J_i}(a_1e^{ks_i} + a_2)]
    = \E\left[\frac{1}{ae^{ks_i} + b}\right]
    = \frac{1}{t-s}\int_{s}^t\frac{1}{ae^{ks_i}+b}\d s_i.
\end{align*}
The integral can be computed explicitly using the variable substitution method. Let us introduce $x \defeq e^{ks_i}$. Then, $s_i = (1/k)\log x$, $\d s_i = [1/(kx)]\d x$. The integral thus becomes:
\begin{align*}
    \int_{s}^t\frac{1}{ae^{ks_i}+b}\d s_i
    = \int_{e^{ks}}^{e^{kt}} \frac{1}{ax + b} \frac{1}{k} \frac{1}{x} \d x
    = \frac{1}{k}\int_{e^{ks}}^{e^{kt}} \frac{1}{ax + b} \frac{1}{x} \d x.
\end{align*}
If $a = 0$, i.e., $a_1 = 0$, the integral simplifies to:
\begin{equation*}
    \int_{s}^t\frac{1}{ae^{ks_i}+b}\d s_i = \frac{1}{b}(t-s).
\end{equation*}
Otherwise, for $a_1\neq 0$, in any neighborhood of the origin of the vector $(a_1,a_2)$ such that  $ax + b \approx 1$, we have:
\begin{align*}
    \int_{e^{ks}}^{e^{kt}} \frac{1}{ax + b} \frac{1}{x} \d x
    %&= \int_{e^{ks}}^{e^{kt}} \left(\frac{-a/b}{ax + b} + \frac{1/b}{x}\right) dx\\
    %&= -\frac{1}{b}\int_{e^{ks}}^{e^{kt}} \frac{1}{ax+b}\d(ax+b) + \frac{1}{b}\int_{e^{ks}}^{e^{kt}}\frac{1}{x}\d x\\
    &= -\frac{1}{b}\left[\log(ae^{kt} + b) - \log(ae^{ks} + b)\right] + \frac{1}{b}k(t-s).
\end{align*}
Therefore, the integral evaluates to: 
\begin{align*}
    \int_{s}^t\frac{1}{ae^{ks_i}+b}\d s_i
    &= -\frac{1}{kb}\left[\log(ae^{kt} + b) - \log(ae^{ks} + b)\right] + \frac{1}{b}(t-s),
\end{align*}
provided that $(a_1,a_2)$ lies within a sufficiently small neighborhood of the origin $(0,0)$. Finally, we obtain the closed-form expression for $\E[M_{J_i}(a_1e^{ks_i} + a_2)]$ as:
\begin{equation}\label{eqn:mgf-J}
    \E[M_{J_i}(a_1e^{ks_i} + a_2)]
    = \frac{1}{b}\left[1 -\frac{1}{k(t-s)}\left(\log(ae^{kt} + b) - \log(ae^{ks} + b)\right)\right],
\end{equation}
where $a = -a_1\mu_v$, $b = 1 - a_2\mu_v$, and $(a_1,a_2)$ is restricted to a small neighborhood around the origin $(0,0)$. 

To simplify the notation, we define a new function $M_{E\!J,J,J^*}(\cdot)$ as the following product:
\begin{equation*}
    M_{E\!J,J,J^*}(\mathbf{a}) \defeq \E[M_{J_i}(a_1e^{ks_i} + a_2)]\cdot M_{J_i^*}(a_3).
\end{equation*}
We know that the MGF of $J_i^*$ has the following expression:
\begin{equation*}
    M_{J_i^*}(a_3) = e^{\mu_s a_3 + \sigma_s^2a_3^2/2}
\end{equation*}
since $J_I^*$ is normally distributed with mean $\mu_s$ and variance $\sigma_s^2$. Combining these results, we obtain the following closed-form expression for the joint MGF of $(\iez_{s,t}, \iz_{s,t}, \iz_{s,t}^*)$:
\begin{equation}\label{eqn:mgf-iez-iz-iz}
    M_{\iez_{s,t},\iz_{s,t},\iz_{s,t}^*}(\mathbf{a})
    = e^{\lambda (t-s) (M_{E\!J,J,J^*}(\mathbf{a})-1)},
\end{equation}
where $\mathbf{a} = (a_1,a_2,a_3)$, $a = -a_1\mu_v$, $b = 1-a_2\mu_v$, and
\begin{equation*}
    M_{E\!J,J,J^*}(\mathbf{a})
    = \frac{1}{b} \left[ 1 - \frac{1}{k(t-s)}\left(\log(ae^{kt} + b) - \log(ae^{ks} + b)\right) \right] e^{\mu_s a_3 + \sigma_s^2 a_3^2/2}.
\end{equation*}
Given Equation~\eqref{eqn:mgf-iez-iz-iz}, we can compute the joint moment of $(\iez_{s,t}, \iz_{s,t},\iz_{s,t}^*)$ of any order.

The $n$-th ($n\ge1$) partial derivative of $M_{E\!J,J,J^*}(\mathbf{a})$ with respect to $a_1$ is given by
\begin{equation*}
    \frac{\partial^nM_{E\!J,J,J^*}}{\partial a_1^{n}}
    =  \frac{1}{b}\left[\frac{e^{nkt}}{(ae^{kt}+b)^{n}}  - \frac{e^{nks}}{(ae^{ks}+b)^{n}} \right] \frac{(n-1)! \mu_v^n}{k(t-s)} M_{J_i^*}(a_3).
\end{equation*}
Consequently, the $n$-th moment of $E\!J$ can be expressed as
\begin{equation*}
    \E[(e^{ks_i}J_i)^n] = (e^{nkt} - e^{nks})\frac{1}{k(t-s)}(n-1)!\mu_v^n.
\end{equation*}

For $n_1\ge 1$ and $n_2\ge 1$, the following formula holds:
\begin{equation*}%\label{eqn:partial-mfg-ej-j-j-over-a1-a2}
    \frac{\partial^{n_1+n_2}M_{E\!J,J,J^*}}{\partial a_1^{n_1}\partial a_2^{n_2}}
    = \sum_{i=0}^{n_2} \frac{c(n_1,n_2,i)}{b^{n_2-i+1}}\left[\frac{e^{n_1kt}}{(ae^{kt}+b)^{n_1+i}} - \frac{e^{n_1ks}}{(ae^{ks}+b)^{n_1+i}} \right] \frac{\mu_v^{n_1+n_2}}{k(t-s)} M_{J_i^*}(a_3), 
\end{equation*}
where $c(n_1,n_2,i) \defeq n_2!(n_1 - 1 + i)!/(i!)$. An alternative approach involves directly computing the joint moment directly, yielding:
\begin{equation*}
    \E[(e^{ks_i}J_i)^{n_1}J_i^{n_2}] = \E[e^{n_1ks_i}]\E[J_i^{n_1+n_2}] = \frac{1}{n_1k(t-s)}(e^{n_1kt} - e^{n_1ks})(n_1+n_2)!\mu_v^{n_1+n_2}.
\end{equation*}

For $n\ge 1$, we have:
\begin{align*}
    \frac{\partial^{n}M_{E\!J,J,J^*}}{\partial a_2^{n}}
    &= \frac{n!}{b^{n+1}}  \left[ 1 - \frac{1}{k(t-s)}\left(\log(ae^{kt} + b) - \log(ae^{ks} + b)\right) \right]\mu_v^n M_{J_i^*}(a_3)\\
    &\quad + \sum_{i=1}^n\binom{n}{i}\frac{(n-i)!(i-1)!}{b^{n-i+1}} \left[\frac{1}{(ae^{kt}+b)^i} - \frac{1}{(ae^{ks} + b)^i}\right]\frac{1}{k(t-s)} \mu_v^n M_{J_I^*}(a_3)\\
    &= \frac{n!}{b^{n+1}}  \left[ 1 - \frac{1}{k(t-s)}\left(\log(ae^{kt} + b) - \log(ae^{ks} + b)\right) \right]\mu_v^n M_{J_i^*}(a_3)\\
    &\quad + \sum_{i=1}^n\frac{n!/i}{b^{n-i+1}} \left[\frac{1}{(ae^{kt}+b)^i} - \frac{1}{(ae^{ks} + b)^i}\right]\frac{1}{k(t-s)} \mu_v^n M_{J_I^*}(a_3).
\end{align*}
Thus, the $n$-th moment of $J$ is given by $\E[J_i^n] = n!\mu_v^n$.


\section*{Appendix C: Unconditional moments of the SVCJ model}
\label{app:unconditional-moment-v_t}
We have demonstrated that the conditional moment of the return, $\E[y_t^m|v_0]$, is a polynomial in $v_0$. To compute the unconditional moments of $y_t$, we first need to investigate how to calculate the unconditional moments of the variance $v_t$. We assume that the initial variance $v_0$ follows the stationary distribution of $v_t$, and the process $v_t$ is strictly stationary. This implies that $v_0\overset{d}{=} v(t)$, where $\overset{d}{=}$ denotes equality in distribution \citep{glasserman2010moment, jin2016positive}. We use $v$ to denote a random variable from this stationary distribution.

The solution (Equation~\eqref{eqn:svcj-variance-solution1}) to the variance process can be rewritten as:
\begin{equation}\label{eqn:v_t-srdj}
    e^{kt}(v_t-\theta) = (v_0-\theta) + \sigma_v \ie_t + \iez_t.
\end{equation}
The first unconditional moment is calculated as:  
$$\E[v] = \theta + \lambda\mu_v/k,$$ 
since $\E[\iez_t] = \lambda\mu_v (e^{kt}-1)/k$, $\E[\ie_t] = 0$ and $\E[v_t] = \E[v_0] = \E[v]$. This result allows us to rewrite Equation~\eqref{eqn:v_t-srdj} in the following form:
\begin{equation*}
    e^{kt}(v_t-\E[v]) = \sigma_v\ie_t + \overline{\iez}_t + (v_0-\E[v]),
\end{equation*}
where $\overline{\iez}_t \defeq \iez_t - \E[\iez_t]$ represents the centralized term. This centralized term can be decomposed similarly: $\overline{\iez}_t = \overline{\iez}_{s} + \overline{\iez}_{s,t}$ where $\overline{\iez}_{s,t} \defeq \iez_{s,t} - \E[\iez_{s,t}]$. It is straightforward to verify that $\E[\overline{\iez}_{s,t}^m]$ can be expressed as a ``polynomial'':
\begin{equation*}
    \E[\overline{\iez}_{s,t}^m] = \sum_{\mathbf{j}} c_{\mathbf{j}} e^{j_1kt}e^{j_2ks}k^{-j_3}\lambda^{j_4}\mu_v^{j_5},
\end{equation*}
where, with a slight abuse of notation, $\mathbf{j}\defeq (j_1,\dots,j_5)$, and $c_{\mathbf{j}}$ denotes the associated coefficient for the corresponding monomial. Therefore, the conditional joint moment $\E[\ie_t^{m_1}\overline{\iez}_t^{m_2}|v_0]$ can be computed using the following recursive equation:
\begin{equation*}
    \E[\ie_t^{m_1}\overline{\iez}_t^{m_2}|v_0]
    = \sum_{i=0}^{m_2}\binom{m_2}{i}\sum_{\mathbf{j}}c_{\mathbf{j}} e^{j_1kt}k^{-j_3}\lambda^{j_4}\mu_v^{j_5}P(m_1,m_2),\quad m_1 \ge 2,
\end{equation*}
where $P(m_1,m_2) \defeq [m_1(m_1-1)/2]\cdot(p_1 + p_2 + p_3 + p_4)$, and 
\begin{align*}
    p_1 &\defeq \int_0^t e^{(j_2+1)ks}\E[\ie_s^{m_1-2}\overline{\iez}_s^i|v_0] \d s \times (v_0-\E[v]),\\
    p_2 &\defeq \int_0^t e^{(j_2+2)ks}\E[\ie_s^{m_1-2}\overline{\iez}_s^i|v_0] \d s \times \E[v],\\
    p_3 &\defeq \int_0^t e^{(j_2+1)ks}\E[\ie_s^{m_1-1}\overline{\iez}_s^i|v_0] \d s \times \sigma_v,\\
    p_4 &\defeq \int_0^t e^{(j_2+1)ks}\E[\ie_s^{m_1-2}\overline{\iez}_s^{i+1}|v_0] \d s.
\end{align*}
For the special case $m_1=1$, it is easy to find that $\E[\ie_t\overline{\iez}_t^{m_2}|v_0] = 0$.

With the preparations outlined above, the $m$-th conditional central moment of $v_t$ can be calculated as:
\begin{equation*}
    e^{mkt}\E[(v_t-\E[v])^m|v_0] = \sum_{m_1+m_2+m_3=m}\binom{m}{m_1,m_2,m_3}\E[\ie_t^{m_1}\overline{\iez}_t^{m_2}|v_0]\sigma_v^{m_1}(v_0-\E[v])^{m_3}.
\end{equation*}
We note that the conditional central moment $\E[(v_t-\E[v])^m|v_0]$ will be computed as a polynomial in $(v_0-\E[v])$:
\begin{equation*}
    \E[(v_t-\E[v])^m|v_0]
    = c_m(v_0-\E[v])^m + c_{m-1}(v_0-\E[v])^{m-1} + \cdots + c_1(v_0-\E[v]) + c_0,
\end{equation*}
where $c_{m},\dots, c_0$ are coefficients, some of which may be zero and $c_m = e^{-mkt}$. The reason is that the conditional joint moment $\E[\ie_t^{m_1}\overline{\iez}_t^{m_2} | v_0]$ produces a polynomial in $(v_0 - \E[v])$ of order at most $\lfloor m_1 / 2 \rfloor$. We further note that the unconditional central moment of $v_t$ can be computed via:
\begin{equation*}
    \E[(v_t-\E[v])^m] = \E[\E[(v_t-\E[v])^m|v_0]].
\end{equation*}
Meanwhile, due to the assumption that $v_t$ is strictly stationary, we have
\begin{equation*}
    \E[(v_t-\E[v])^m] = \E[(v_0-\E[v])^m].
\end{equation*}
Thus, the $m$-th unconditional central moment of $v_t$ can be computed using the following recursive equation:
\begin{equation}\label{eqn:srjd-moment-recursive}
    (1-e^{-mkt})\E[(v_0-\E[v])^m] = c_{m-1}\E[(v_0-\E[v])^{m-1}] + \cdots + c_1\E[(v_0-\E[v])] + c_0.
\end{equation}
For example, the second central moment is computed as:
\begin{equation*}
    \E[(v_0-\E[v])^2] = \frac{\lambda\mu_v^2}{k} + \frac{\E[v]\sigma_v^2}{2k},
\end{equation*}
and the third central moment:
\begin{equation*}
    \E[(v_0-\E[v])^3] = \frac{2\lambda\mu_v^3}{k} + \frac{\sigma_v^2\lambda\mu_v^2}{k^2} + \frac{\E[v]\sigma_v^4}{2k^2}.
\end{equation*}
Using the recursive Equation~\eqref{eqn:srjd-moment-recursive}, we can compute the fourth and any higher central moments recursively. Given the central moments, the corresponding non-central moments can be easily computed.  

Combining the unconditional moments of $v_0$, computed via Equation~\eqref{eqn:srjd-moment-recursive}, with the polynomial formula in $v_0$ of the conditional moments of the return, computed via Equation~\eqref{eqn:ieii-ieziziz-polynomial}, the unconditional moments of the return of the SVCJ model can be computed. The automation of these derivations has been implemented in the Python package \emph{ajdmom} as well \citep{wu2024ajdmom}.


