\noindent A Tait graph, $\mathcal{G}(L)$, of a connected link diagram $L$ is a  graph which is constructed by first coloring the diagram in a checkerboard fashion. Then, a vertex is assigned to each shaded region, and an edge is assigned to each crossing, with a sign indicated as illustrated in Fig.~\ref{2}. The determinant of the  link $L$ is calculated  as follows:

\begin{lemma}\cite{champanerkar2009twisting} For any spanning tree $\mathcal{T}$ of $\mathcal{G}(L)$, let $\mathsf{v}(\mathcal{T})$ be the number of positive edges in $\mathcal{T}$. Let $s_{v}(L)=\sharp\{\text{spanning trees $\mathcal{T}$ of~} \mathcal{G}(L)\mid \mathsf{v}(\mathcal{T})=v \}$. Then
\[\det(L)=\Big|\displaystyle \sum_v (-1)^vs_v(L)\Big|.\]
\end{lemma}


\begin{remark}[Lemma 2.3, \cite{chbili2020quasiI}] \label{rem:ab} Let $c$ be a quasi-alternating crossing of a link diagram $L$ and $e$ be the corresponding edge in $\mathcal{G}(L)$. If $e$ is a positive edge in $\mathcal{G}(L)$, then
\[\Big(\displaystyle \sum_v (-1)^vs_{v-1}(L_0)\Big).\Big(\displaystyle \sum_v (-1)^vs_v(L_\infty)\Big)>0.\]
\noindent For our convenience, in this paper we use the following notation
\[\mathfrak{a}=\displaystyle \sum_v (-1)^vs_{v-1}(L_0),\quad \text{and},\quad \mathfrak{b}=\displaystyle \sum_v (-1)^vs_v(L_\infty).\]
It is evident that $|\mathfrak{a}|=\det(L_0)$ and $|\mathfrak{b}|=\det(L_{\infty})$.
\end{remark}

\begin{definition}\cite{chbili2020quasiI} A sub-graph $\mathcal{H}$ of a connected planar graph $\mathcal{G}$  is called an  almost spanning tree with respect to vertices $u_1$ and $u_2$, if there is no path between $u_1$ and $u_2$, and by adding one edge it becomes a spanning tree of $\mathcal{G}$.
\end{definition}

\begin{definition}  Given a tangle $T$, we define the Tait graph of $T$ as  the Tait graph of its  numerator closure $N(T)$. This graph is denoted by $\mathcal{G}(T)$.
\end{definition}
\begin{definition}\cite{chbili2020quasiI} An alternating tangle $T$ is said to be positive (respectively,  negative) if the edges of the  Tait graph $\mathcal{G}(T)$, with induced checkerboard coloring as shown in Fig.~\ref{2}, are positive (respectively,  negative).
\end{definition}


\noindent Let $e$ be the edge corresponding to a crossing $c$ with checkerboard coloring as illustrated in Fig.~\ref{2}.  Then an alternating tangle $T$  is a tangle of same type as $c$ or extends $c$, if $T$ is positive whenever $e$ is positive and negative whenever  $e$ is negative. If $T$ fails to adhere to this rule,  we refer to 
$T$ as being of opposite type with respect to $c$. The tangle shown in Fig.~\ref{positivetangle} is a positive tangle and of same type with respect to crossing $c$ depicted  in Fig.~\ref{positivetangle}. However, the tangle shown in Fig.~\ref{positivetangle} is of opposite type with respect to crossing $c$ as shown in Fig.~\ref{2}(b).

