\begin{theorem}\cite{chbili2020quasiI}\label{Thm:pre:m}
 Let $L$ be a quasi-alternating link diagram at a crossing $c$.
Let $L'$ be the  link obtained from  $L$ by replacing $c$ with a reduced alternating tangle $T$ that extends $c$. Then $L'$ is  quasi-alternating at every crossing of $T$.
 \end{theorem}
