\section{The Main Theorem}\label{main theorem}
\noindent Before outlining the main result in this section, we will first introduce some key definitions.

\begin{definition} A crossing $c$ in a link diagram $L$ is said to satisfies the determinant property, if the following condition holds at crossing $c$
\[ \det(L_0),~~ \det(L_\infty) \geq 1 \quad \text{and}\quad  \det(L) = \det(L_0) + \det(L_\infty),\]
where $L_0$ and $L_{\infty}$ are the diagrams as shown in Fig.~\ref{1}.
\end{definition}
\begin{definition} A quasi-alternating crossing $c$ in a link diagram $L$ is considered to have property (I) if, after switching crossing $c$, the resulting diagram is a diagram of a quasi-alternating link. An example of such a crossing $c$  with property (I) is depicted in Fig.~\ref{exm:In1}(a).
\end{definition}

\begin{definition} A quasi-alternating crossing $c$ in a  link diagram $L$ is said to have property (II), if the following conditions hold at crossing $c$
\begin{enumerate}
\item $\det(L_0)<\det(L_{\infty})$, where $L_0$ and $L_{\infty}$ are the diagrams as shown in Fig.~\ref{1},
\item property (I) is satisfied.
\end{enumerate}
\end{definition}

\begin{definition} A quasi-alternating crossing $c$ in a  link diagram $L$ is said to have property (III), if the following conditions hold at crossing $c$
\begin{enumerate}
\item $\det(L_{\infty})<\det(L_{0})$, where $L_0$ and $L_{\infty}$ are the diagrams as shown in Fig.~\ref{1},
\item property (I) is satisfied.
\end{enumerate}
\end{definition}
\noindent This section is divided into subsections~\ref{subsection:Alt} and \ref{subsection:NonAlt}.
\subsection{Quasi-alternating links via alternating tangles of opposite type}
\label{subsection:Alt}
\begin{theorem}\label{Thm:alt_tan_op} 
Let $L$ be a quasi-alternating link diagram with a quasi-alternating crossing $c$, and let $T$ be an alternating tangle of opposite type with respect to $c$. Then, a link $L'$ obtained from $L$ by replacing crossing $c$ with a tangle $T'$  is quasi-alternating, if either of the following conditions holds:
\begin{enumerate}
\item $T'\in \{T_+, T_-\}$ and  property (II) holds at $c$, or
\item $T'\in \{T^+, T^-\}$ and  property (III) holds at $c$ ,
\end{enumerate}
where $T_+,~T_-,~T^+$ and $T^-$ are the tangles depicted in Fig.~\ref{T+}.\\
 More precisely, every crossing of the tangle $T$ is  quasi-alternating in $L'$.
\end{theorem}
\noindent To prove Theorem~\ref{Thm:alt_tan_op}, we first need to establish the following lemma.
\begin{lemma}\label{lemma:opptwist} 
Let $L$ be a quasi-alternating link diagram with a quasi-alternating crossing $c$ such that property (I) holds at crossing $c$.
Let $L^{\overline{n}}$ and $L^{-\overline{n}}$ be  the links obtained from $L$ by replacing  crossing $c$ with $n > 1$ vertical and horizontal half twists of opposite type, respectively, see Fig.~\ref{twop}. Then 
\begin{enumerate}
\item $L^{\overline{n}}$ is quasi-alternating, if $\det(L_{0})< \det(L_{\infty})$, and
\item $L^{-\overline{n}}$ is quasi-alternating, if $\det(L_{0})>\det(L_{\infty})$, 
\end{enumerate} where $L_{\infty}$ and $L_{0}$ are the diagrams as shown in Fig.~\ref{1}. Furthermore, every new crossing of $L^{\overline{n}}$ and $L^{-\overline{n}}$ is quasi-alternating.
\end{lemma}
\begin{proof}
Let $c$ be a quasi-alternating crossing of a quasi-alternating link diagram $L$ and $e$ be its corresponding edge in $\mathcal{G}(L)$.
Let $L^{\overline{n}}$ and $L^{-\overline{n}}$ be the links obtained from $L$ by replacing  crossing $c$ with $n$ vertical and horizontal half twists of opposite type, respectively, as illustrated in Fig.~\ref{twop}. 
 \begin{figure}[!ht] {\centering
 \subfigure[$L^{\overline{n}}$]{\includegraphics[scale=0.5]{Fig/19octb.jpg} } \hspace{1cm}
\subfigure[$L$] {\includegraphics[scale=0.5]{Fig/19octa.jpg}}\hspace{1cm}
\subfigure[$L^{-\overline{n}}$] {\includegraphics[scale=0.5]{Fig/19octc.jpg}}
\caption{ Links $L$, $L^{\overline{n}}$ and $L^{-\overline{n}}$.}\label{twop}}\end{figure}

\noindent Choose the checkerboard coloring of $L$ such that the edge $e(=u_1u_2)$ in $\mathcal{G}(L)$ is positive. Let $\mathcal{G}(L^{\overline{n}})$ and $\mathcal{G}(L^{-\overline{n}})$ be the Tait graphs of $L^{\overline{n}}$ and $L^{-\overline{n}}$, respectively, with the induced checkerboard coloring. First, we consider the case of vertical half twists.

\noindent Case (1) Let $c'$ be any crossing that belongs to the new $n$ vertical half twists in  $L^{\overline{n}}$. Without lose of generality, we take $c'$ as shown in Fig.~\ref{twop}(a), and $e'$ be its corresponding edge in $\mathcal{G}(L^{\overline{n}})$.  Then the total number of spanning trees in $L^{\overline{n}}$ with $v$ number of  positive edges are given as
%%%%%%%%%%

\[s_{v}(L^{\overline{n}})=\sharp \left \{\text{ spanning trees ~} \mathcal{T} \text{~of~} L ~| ~e\in \mathcal{T}, \text{~and~} \mathsf{v}(\mathcal{T})=v+1 \right \} + \]
 \[\hspace{1cm} n~~ \sharp \left \{ \text{ spanning trees ~} \mathcal{T} \text{~of~} L ~| ~e\notin \mathcal{T}, \text{~and~} \mathsf{v}(\mathcal{T})=v \right \} . \]

 \[ s_{v}(L^{\overline{n}})=s_{v}(L_0)+ns_{v}(L_{\infty})\]

 \begin{equation}\label{eq2:twop}
\begin{split}
 \det(L^{\overline{n}})&=\Big| \displaystyle \sum_{v}(-1)^{v}s_{v}(L^{\overline{n}})\Big|=\Big|\displaystyle \sum_{v}(-1)^{v} \left\{s_{v}(L_0)+n s_{v}(L_{\infty})\right\} \Big| \\
&=\Big|\displaystyle \sum_{v}(-1)^{v} s_{v}(L_0)+n\displaystyle \sum_{v}(-1)^{v}s_{v}(L_{\infty}) \Big| = \Big|-\mathfrak{a}+n\mathfrak{b} \Big|
\end{split}
\end{equation}
Since $c$ is a quasi-alternating crossing of $L$, we have $\mathfrak{a}\mathfrak{b}>0$ by Remark~\ref{rem:ab}.
It is easy to observe that by performing smoothings at crossing $c'$ in $L^{\overline{n}}$,  $L^{\overline{n}}_{0}$ is equivalent to the link $L_{\infty}$, while $L^{\overline{n}}_{\infty}$ corresponds to the link $L^{\overline{n-1}}$.

\noindent Therefore, we have $\det(L^{\overline{n}}_{0})=\det(L_{\infty})=|\mathfrak{b}|$. Using Eq.~(\ref{eq2:twop}), we find that
\[\det(L^{\overline{n}}_{\infty})=\det(L^{\overline{n-1}})=|-\mathfrak{a}+(n-1)\mathfrak{b}|.\]
Thus,  the determinant condition holds at crossing $c'$ in $L^{\overline{n}}$ if and only if 
\[\{-\mathfrak{a}+(n-1)\mathfrak{b}\} \mathfrak{b}>0.\]
That means the determinant condition holds at $c'$ if and only if for $\mathfrak{b}\gtrless 0$, 
\begin{equation}\label{eq3:twop}(-\mathfrak{a}+(n-1)\mathfrak{b})\gtrless 0 \iff (n-1)\mathfrak{b} \gtrless \mathfrak{a}\iff (n-1)|\mathfrak{b}|>|\mathfrak{a}| \end{equation}

\noindent Next, we proof the result using induction hypothesis. For $n=1$, $L^{\overline{1}}$ is a quasi-alternating link since property (I) holds at $c$ in $L$. For $n=2$, using Eq.~(\ref{eq3:twop}) the determinant condition holds at $c'$ whenever $|\mathfrak{b}|>|\mathfrak{a}|$. Furthermore, $L^{\overline{2}}_{\infty}$ is nothing but the link  $L^{\overline{1}}$ and $L^{\overline{2}}_{0}$ is equivalent to $L_{\infty}$. Since both $L^{\overline{1}}$ and $L_{\infty}$ are quasi-alternating by hypothesis, $c'$ is a quasi-alternating crossing of $L^{\overline{2}}$. Assume that the result is true for all positive integers less than $n$. We have to prove the result for $n$. 

\noindent Given that $\det(L_0)<\det(L_{\infty})$, this implies $|\mathfrak{a}|<|\mathfrak{b}|$. It is evident that for $|\mathfrak{a}|<|\mathfrak{b}|$, Eq.~(\ref{eq3:twop}) holds, and hence the determinant condition is satisfied at $c'$ in $L^{\overline{n}}$. Moreover, $L^{\overline{n}}_{\infty}$ is nothing but the link $L^{\overline{n-1}}$, which is quasi-alternating by induction hypothesis, and $L^{\overline{n}}_{0}$ is equivalent to $L_{\infty}$ which is also quasi-alternating since $L$ is quasi-alternating at $c$. Since both $L^{\overline{n}}_{0}$ and  $L^{\overline{n}}_{\infty}$ are quasi-alternating, $c'$ is a quasi-alternating crossing of  $L^{\overline{n}}$. Hence $L^{\overline{n}}$ is a quasi-alternating link.\\

\noindent Now, we consider the case of horizontal half twists.

\noindent Case (2) Let $c'$ be any crossing that belongs to the new $n$ horizontal half twists in  $L^{-\overline{n}}$. Without lose of generality, we take $c'$ as shown in Fig.~\ref{twop}(c), and $e'$ be its corresponding edge in $\mathcal{G}(L^{-\overline{n}})$.  Then
%%%%%%%%%%

\[s_{v}(L^{\overline{n}})=n~\sharp \left \{\text{ spanning trees ~} \mathcal{T} \text{~of~} L ~| ~e\in \mathcal{T}, \text{~and~} \mathsf{v}(\mathcal{T})=v+1 \right \} + \]
 \[\hspace{1cm}  \sharp \left \{ \text{ spanning trees ~} \mathcal{T} \text{~of~} L ~| ~e\notin \mathcal{T}, \text{~and~} \mathsf{v}(\mathcal{T})=v \right \} . \]

 \[ s_{v}(L^{-\overline{n}})=ns_{v}(L_0)+s_{v}(L_{\infty})\]

 \begin{equation}\label{eq5:twop}
\begin{split}
 \det(L^{-\overline{n}})&=\Big| \displaystyle \sum_{v}(-1)^{v}s_{v}(L^{-\overline{n}})\Big|=\Big|\displaystyle \sum_{v}(-1)^{v} \left\{ ns_{v}(L_0)+ s_{v}(L_{\infty})\right\} \Big| \\
&=\Big|n\displaystyle \sum_{v}(-1)^{v} s_{v}(L_0)+\displaystyle \sum_{v}(-1)^{v}s_{v}(L_{\infty} )\Big| = \Big|-n\mathfrak{a}+\mathfrak{b} \Big|
\end{split}
\end{equation}
Since $c$ is a quasi-alternating crossing of $L$,  we have $\mathfrak{a}\mathfrak{b}>0$ holds by Remark~\ref{rem:ab}.
It is evident that by performing smoothings at crossing $c'$ in $L^{-\overline{n}}$,  $L^{-\overline{n}}_{\infty}$ is equivalent to the link $L_{0}$ and $L^{-\overline{n}}_{0}$ corresponds to the link $L^{-\overline{(n-1)}}$.

 \noindent Therefore, we have, $\det(L^{-\overline{n}}_{\infty})=\det(L_{0})=|\mathfrak{a}|$. Using Eq.~(\ref{eq5:twop}), we find that 
\[\det(L^{-\overline{n}}_{0})=\det(L^{-\overline{(n-1)}})=|-(n-1)\mathfrak{a}+\mathfrak{b}|.\]
Thus, from Eq.~(\ref{eq5:twop}) the determinant condition holds at crossing $c'$ in $L^{-\overline{n}}$ if and only if 
\[\{-(n-1)\mathfrak{a}+\mathfrak{b}\} (-\mathfrak{a})>0.\]
That means determinant condition holds if and only if for $\mathfrak{a}\gtrless 0$, $\mathfrak{-a}\lessgtr 0$ and
\begin{equation}\label{eq6:twop}
-(n-1)\mathfrak{a}+\mathfrak{b} \lessgtr 0 \iff \mathfrak{b} \lessgtr (n-1)\mathfrak{a}\iff |\mathfrak{b}|<(n-1)|\mathfrak{a}| 
\end{equation}

\noindent Next, we use induction hypothesis to prove the result. Clearly, for $n=1$, $L^{-\overline{1}}$ is a quasi-alternating link since property (I) holds at $c$ in $L$. For $n=2$, using Eq.~(\ref{eq6:twop}) the determinant condition holds at $c'$, whenever $|\mathfrak{b}|<|\mathfrak{a}|$. Further, $L^{-\overline{2}}_{0}$ is nothing but the link $L^{-\overline{1}}$ and $L^{-\overline{2}}_{\infty}$ is equivalent to $L_{0}$. Since both $L^{-\overline{1}}$ and $L_{0}$ are quasi-alternating by hypothesis, $c'$ is a quasi-alternating crossing of $L^{-\overline{2}}$ and hence $L^{-\overline{2}}$ is quasi-alternating. Assume that the result is true for all positive integers less than $n$. We have to prove the result for $n$.

\noindent Given that $\det(L_0)>\det(L_{\infty})$, this implies $|\mathfrak{a}|>|\mathfrak{b}|$. It is evident that for $|\mathfrak{b}|<|\mathfrak{a}|$,
 Eq.~(\ref{eq6:twop}) holds well, and the determinant condition holds at $c'$ of $L^{-\overline{n}}$. Moreover, $L^{-\overline{n}}_{0}$ is corresponds to the link $L^{-\overline{(n-1)}}$, which is quasi-alternating by induction hypothesis, and $L^{\overline{n}}_{\infty}$ is equivalent to $L_{0}$ which is also quasi-alternating since $L$ is quasi-alternating at $c$. Since both $L^{-\overline{n}}_{0}$ and  $L^{-\overline{n}}_{\infty}$ are quasi-alternating, $c'$ is a quasi-alternating crossing of $L^{-\overline{n}}$ and hence $L^{-\overline{n}}$ is quasi-alternating link. Hence the proof of the result.
\end{proof}


