\noindent A natural question arises about the existence of links and crossings satisfying property (I), (II) and (III). The answer to this question is stated in the following theorem.
\begin{theorem}\label{Thm1} 
There exist infinitely many quasi-alternating links with quasi-alternating crossings satisfying property (II) and (III).
\end{theorem}
\noindent Before proving this theorem, we state and prove the following lemma.
\begin{lemma}\label{lemma:sametwist} 
Let $L'$ be a link obtained from a quasi-alternating diagram $L$ by replacing a quasi-alternating crossing $c$ of $L$ with $n>1$ half twists of same type. Let $c'$ be any new half twist in $L'$. Then 
\begin{enumerate}
\item $\det(L'_{\infty})<\det(L'_{0})$, whenever the twists at $c$ are vertical half twists as shown in Fig.~\ref{twsa}(a), and
\item $\det(L'_{\infty})>\det(L'_{0})$, whenever the twists at $c$ are horizontal half twists as shown in Fig.~\ref{twsa}(c), 

\end{enumerate} 
where $L'_{\infty}$ and $L'_{0}$ are the links obtained from $L'$ by perform smoothings at crossing $c'$ of $L'$ as shown in Fig.~\ref{1}. 
\end{lemma}
\begin{proof}
Let $c$ be a quasi-alternating crossing of a quasi-alternating link diagram $L$ and $e$ be its corresponding edge in $\mathcal{G}(L)$.
Let $L'$ be  the link obtained from $L$ by replacing  crossing $c$ with $n>1$ half twists of same type, as shown in Fig.~\ref{twsa}. 
 \begin{figure}[!ht] {\centering
 \subfigure[$L^{n}$]{\includegraphics[scale=0.5]{Fig/19octd.jpg} } \hspace{1cm}
\subfigure[$L$] {\includegraphics[scale=0.5]{Fig/19octa.jpg}}\hspace{1cm}
\subfigure[$L^{-n}$] {\includegraphics[scale=0.5]{Fig/19octe.jpg}}
\caption{ Links $L$, $L^{n}$ and $L^{-n}$.}\label{twsa}}\end{figure}
\noindent Choose the checkerboard coloring of $L$ such that the edge $e(=u_1u_2)$ in $\mathcal{G}(L)$ is positive. Let $\mathcal{G}(L')$ be the Tait graph of $L'$ with the induced checkerboard coloring. First, we consider the case of vertical half twists.

\noindent Case (1) Let $c'$ be any crossing that belongs to the new $n$ vertical half twists in  $L'$. Without lose of generality, let $c'$ be as shown in Fig.~\ref{twsa}(a), and $e'$ be its corresponding edge in $\mathcal{G}(L')$. Denote $L'$ by $L^{n}$ here. Then
%%%%%%%%%%
\[s_{v}(L^{n})=\sharp \left \{\text{ spanning trees ~} \mathcal{T} \text{~of~} L ~| ~e\in \mathcal{T}, \text{~and~} \mathsf{v}(\mathcal{T})=v-n+1 \right \} + \]
 \[\hspace{2cm} n~~ \sharp \left \{ \text{ spanning trees ~} \mathcal{T} \text{~of~} L ~| ~e\notin \mathcal{T}, \text{~and~} \mathsf{v}(\mathcal{T})=v-n+1 \right \} . \]
 \begin{equation}\label{eq1:twsame}
  s_{v}(L^{n})=s_{v-n}(L_0)+ns_{v-n +1}(L_{\infty})
  \end{equation}
 \begin{equation}\label{eq2:twsame}
\begin{split}
 \det(L^{n})&=\Big| \displaystyle \sum_{v}(-1)^{v}s_{v}(L^{n})\Big|=\Big|\displaystyle \sum_{v}(-1)^{v} \{s_{v-n}(L_0)+n s_{v-n+1}(L_{\infty}) \}\Big| \\
&=\Big|\displaystyle \sum_{v}(-1)^{v} s_{v-n}(L_0)+n\displaystyle \sum_{v}(-1)^{v}s_{v-n+1}(L_{\infty}) \Big|\\
& = \Big|-(-1)^n\mathfrak{a}+n(-1)^{n-1}\mathfrak{b} \Big|=\Big|\mathfrak{a}+n\mathfrak{b} \Big|
\end{split}
\end{equation}
 Since $c$ is a quasi-alternating crossing of $L$, we have  $\mathfrak{a} \mathfrak{b}>0$ by Remark~\ref{rem:ab}.
Moreover, by perform smoothings at crossing $c'$ in $L^n$,  $L^n_{0}$ corresponds to the link $L^{n-1}$ 
 and $L^{n}_{\infty}$ is equivalent to the link $L_{\infty}$.
Therefore, $\det(L^{n}_{\infty})=\det(L_{\infty})=|\mathfrak{b}|$. Using Eq.~(\ref{eq2:twsame}), we have 
\[\det(L^{n}_{0})=\det(L^{n-1})=|\mathfrak{a}+(n-1)\mathfrak{b}|>|\mathfrak{b}|=\det(L^{n}_{\infty}),\]
since $\mathfrak{a}\mathfrak{b}>0$ and $n>1$.
Hence the desired result.\\


\noindent Case (2) Suppose that twists in $L'$ are horizontal half twists. Let $c'$ be any crossing that belongs to the new $n$ horizontal half twists in  $L'$. Without lose of generality, let $c'$ be as shown in Fig.~\ref{twsa}(c), and $e'$ be its corresponding edge in $\mathcal{G}(L')$. Denote $L'$ by $L^{-n}$ here. Then
%%%%%%%%%%
\[s_{v}(L^{n})=n~\sharp \left \{\text{ spanning trees ~} \mathcal{T} \text{~of~} L ~| ~e\in \mathcal{T}, \text{~and~} \mathsf{v}(\mathcal{T})=v \right \} + \]
 \[\hspace{2cm}\sharp \left \{ \text{ spanning trees ~} \mathcal{T} \text{~of~} L ~| ~e\notin \mathcal{T}, \text{~and~} \mathsf{v}(\mathcal{T})=v \right \} . \]
 \begin{equation}\label{eq4:twsame} s_{v}(L^{-n})=ns_{v-1}(L_0)+s_{v}(L_{\infty})
 \end{equation}
 \begin{equation}\label{eq5:twsame}
\begin{split}
 \det(L^{-n})&=\Big| \displaystyle \sum_{v}(-1)^{v}s_{v}(L^{-n})\Big|=\Big|\displaystyle \sum_{v}(-1)^{v} \{ns_{v-1}(L_0)+ s_{v}(L_{\infty})\} \Big| \\
&=\Big|n\displaystyle \sum_{v}(-1)^{v} s_{v-1}(L_0)+\displaystyle \sum_{v}(-1)^{v}s_{v}(L_{\infty}) \Big| = \Big|n\mathfrak{a}+\mathfrak{b} \Big|
\end{split}
\end{equation}
Since $c$ is a quasi-alternating crossing of $L$, we have $\mathfrak{a} \mathfrak{b}>0$ by Remark~\ref{rem:ab}.
It is evident that by smoothing at crossing $c'$ in $L^{-n}$,  $L^{-n}_{0}$ is equivalent to the link $L_{0}$ and $L^{-n}_{\infty}$ corresponds to the link $L^{-(n-1)}$. 
 Therefore, $\det(L^{-n}_{0})=\det(L_{0})=|\mathfrak{a}|$. Using Eq.~(\ref{eq5:twsame}), we have 
\[\det(L^{-n}_{\infty})=\det(L^{-(n-1)})=|(n-1)\mathfrak{a}+\mathfrak{b}|>|\mathfrak{a}|=\det(L^{-n}_{0}),\]
since $\mathfrak{a}\mathfrak{b}>0$ and $n>1$.
Hence, the desired result.
\end{proof}

%\begin{theorem}\label{Thm1} 
%There exist infinitely many quasi-alternating links with quasi-alternating crossings satisfying property (II) and (III).
%\end{theorem}
\noindent Now we are going to prove Theorem~\ref{Thm1}.
\begin{proof}
Consider a quasi-alternating link diagram $L$ with a quasi-alternating crossing $c$. We construct two links $L^{-n}$ and $L^n$ from $L$ by making $n>1$  horizontal and vertical half  twists, respectively,  at crossing $c$ in $L$.  Let $c'$ and $c''$ be any new half twisted crossings in $L^{-n}$ and $L^n$, respectively. Then by Lemma~\ref{lemma:sametwist}, at crossing $c'$ and $c''$ following inequality holds  

\begin{equation}\label{eq.II,III}
\det(L^{-n}_{0})<\det(L^{-n}_{\infty}),\quad \text{and}\quad \det(L^{n}_{\infty})<\det(L^{n}_{0}).
\end{equation} 
Further, by apply crossing change operation at $c''$ the resulting diagram becomes either $L_{0}$ for $n=2$, or $L^{-(n-2)}$ for $n>2$. Similarly, by apply crossing change operation at $c'$ the resulting diagram becomes  either $L_{\infty}$ for $n=2$, or  $L^{(n-2)}$ for $n>2$. Since $L$ is quasi-alternating at $c$, both $L_0$ and $L_{\infty}$ are quasi-alternating. Moreover, $L^{-(n-2)}$ and $L^{(n-2)}$ for $n>2$ are quasi-alternating by Theorem~\ref{Thm:pre:m}. Thus Property (I) holds at crossings $c'$ and $c''$ in $L^{-n}$ and $L^{n}$, respectively. \\
It is evident from Eq.~(\ref{eq.II,III}) that the crossings $c'$ holds property (II) in $L^{-n}$, and  the crossings $c''$ holds property (III) in $L^{n}$.

\noindent Thus, for a given quasi-alternating link diagram with a quasi-alternating crossing, one can construct new examples of distinct quasi-alternating links with quasi-alternating crossings that meet property (II) and (III). Since there are infinitely many quasi-alternating links, there exist infinitely many quasi-alternating links with quasi-alternating crossings satisfying these properties.   This concludes the proof of the theorem.
\end{proof}

