\noindent Consider a set $\Omega$ of family of non-alternating tangles 
\[\Omega=\{T_{[q]},~T^p,~T_q, ~T^{p,q},~T_{p,q},~T^{[p,q]}_{\infty},~T^{[p,q]}: p,q\in \mathbb{N}\},\]
where $T_{[q]},~T^p,~T_q, ~T^{p,q},~T_{p,q},~T^{[p,q]}_{\infty},$ and $T^{[p,q]}$ are the tangles as shown in Fig.~\ref{ntangles}. \\
Note that the denominator closure of $T^{[1,1]}$  tangle results in the mirror image of the non-alternating link $L7n2$. If the tangle $T^{[1,1]}$ possessed an alternating tangle diagram, then this would contradict the fact that its denominator closure is non-alternating. Therefore, the tangle $T^{[1,1]}$ cannot have an alternating tangle diagram. It follows that $T^{[p,q]}$ is a non-alternating tangle, since it is derived from $T^{[1,1]}$ by twisting existing crossings. 
Moreover, the denominator closure of $T^{[1,2]}$ and $T^{[2,1]}$ tangles results in the non-alternating links,  mirror image of $L8n1$ and  knot $8_{21}$, respectively. Thus, by the same argument as for $T^{[1,1]}$, the  tangles $T^{[2,1]}$ and $T^{[1,2]}$ are also non-alternating.   
On the other hand, the tangle $T^{p}$ possesses an alternating diagram as shown in Fig.~\ref{Fig.tpalt}. With the exception of the $T^p$, all the tangles in $\Omega$  appear to lack alternating tangle diagrams. Nevertheless, we use these non-alternating tangle diagrams to prove our result in Theorem~\ref{thm:nalt}. 
For our convenience, in this section crossing $c'$ of tangle $T\in \Omega$ is the crossing depicted in Fig.~\ref{ntangles}. Additionally, we refer to a non-alternating tangle diagram simply as a non-alternating tangle.

\begin{lemma}\label{lem:nalt}
Let $L$ be a quasi-alternating link diagram with a quasi-alternating crossing $c$, and let $L'$ be a link  obtained from $L$ by replacing  crossing $c$ with a non-alternating tangle $T\in \Omega$.  Then the determinant property holds at crossing $c'$ of  $T\in \Omega$ in $L'$ under the following conditions:\\
\begin{enumerate}
\item If $T=T_{[q]}$, then the determinant property holds at  $c'$   if and only if  either $q\geq 3$  or  $q=2$ with $\det(L_0)<2\det(L_{\infty})$.\\
\item If $T=T^{p}$, then the determinant property holds at  $c'$ if and only if $\det(L_0)<\det(L_{\infty})$. \\

\item If $T=T_{q}$, then the determinant property holds at $c'$  if and only if  either $q\geq 2$  or  $q=1$ with $\det(L_0)<3\det(L_{\infty})$.\\

\item If $T=T^{p,q}$, then the determinant property holds at $c'$  if and only if either $ q\geq 2$,  or $p=q=1$, or $q=1$ with $\det(L_0)<\left(1+p/(p-1)\right)\det(L_{\infty})$.\\

\item If $T=T_{p,q}$, then the determinant property holds at  $c'$ if and only if  either  $q\geq 2$,  or $q=1$ with $\det(L_0)<2\det(L_{\infty})$.\\

\item If $T=T^{[p,q]}_{\infty}$, then determinant property holds at $c'$  if and only if  either $q\geq (2p+1)$  or  $q<(2p+1)$ with $\det(L_0)<\left(\dfrac{q(2p+1)+2}{(2p+1)-q}\right)\det(L_{\infty})$.\\

\item If $T=T^{[p,q]}$, then the determinant property holds at  $c'$ if and only if  either $q>1$,  or  $q=1$ with $\det(L_0)<(6+1/p)\det(L_{\infty})$.
 \end{enumerate}
\end{lemma}
\begin{proof}
Consider a quasi-alternating link diagram $L$ with a quasi-alternating crossing $c$ and let $e$ be the edge in $\mathcal{G}(L)$ corresponding to crossing $c$. Let $L'$ be the link obtained from $L$ by replacing $c$ with a tangle $T\in \Omega$.

\noindent Choose the checkerboard coloring of $L$ such that the edge $e(=u_1u_2)$ in $\mathcal{G}(L)$ is positive. Let $\mathcal{G}(L')$ be the Tait graph of $L'$ with the induced checkerboard coloring, and $\mathcal{G}(T)$ be the sub-graph $\mathcal{G}(L')\restr{T}$ of $\mathcal{G}(L')$.
Total number of positive edges in  $\mathcal{G}(T)$ are two, as depicted in Fig.~\ref{tait:graph}. Clearly, the total number of positive edges in both the spanning tree and almost spanning tree of  $\mathcal{G}(T)$ is either one or two.\\

\noindent For $i=1,2$, let $x_i$ be the number of spanning trees of $\mathcal{G}(T)$ with $i$ number of positive edges, and $y_i$ denote the number of almost spanning trees of $\mathcal{G}(T)$ with respect to $u_1$ and $u_2$ having $i$ number of positive edges. 
Consider the $c'$ of $L'$ that belongs to $T$, as depicted in Fig.~\ref{ntangles}. Let $e'$ be its corresponding edge in $\mathcal{G}(T)$. We define $x_{i_{e'}}$ and $y_{i_{e'}}$ as the number of spanning trees and almost spanning trees of $\mathcal{G}(T)$, respectively, that contain edge $e'$ and have $i$ number of positive edges. 
%%%%%%%%%%

\noindent For each spanning tree $\mathcal{T}$ of $\mathcal{G}(L)$ such that $e \in \mathcal{T}$, there exist $\displaystyle \sum_{i=1,2}x_{i_{e'}}$ number of spanning trees containing edge $e'$ and $\displaystyle \sum_{i=1,2}(x_i-x_{i_{e'}})$ number of spanning tree without edge $e'$ in $\mathcal{G}(L')$. These satisfy the following conditions:
\begin{enumerate}
\item $u_1$ and $u_2$ are connected through sub-graph $\mathcal{G}(T)$ of $\mathcal{G}(L')$, more precisely, through spanning trees of $\mathcal{G}(T)$.
\item number of positive edges in these spanning tress of $\mathcal{G}(L')$ are  $\mathsf{v}(\mathcal{T})+(i-1)$, whenever the spanning tree of $\mathcal{G}(T)$  having $i$ number of positive edges. 
\end{enumerate} 
 Therefore, corresponding to all spanning tress of $\mathcal{G}(L)$ that contain edge $e$, there exist: 
 \begin{enumerate}
\item  $\displaystyle \sum_{i=1,2}x_{i_{e'}}s_{v-i}(L_0)$ number of spanning trees in $\mathcal{G}(L')$ that include edge $e'$ with $v$ number of positive edges, and \\

\item $\displaystyle \sum_{i=1,2}(x_i-x_{i_{e'}})s_{v-i}(L_0)$ number of  spanning trees in $\mathcal{G}(L')$ that do not include edge $e'$ while still having $v$ number of positive edges.
\end{enumerate}




\noindent For each spanning tree $\mathcal{T}$ of $\mathcal{G}(L)$ such that $e \notin \mathcal{T}$, there exist $\displaystyle \sum_{i=1,2}y_{i_{e'}}$ number of spanning trees containing edge $e'$ and $\displaystyle \sum_{i=1,2}(y_i-y_{i_{e'}})$ spanning trees does not containing edge $e'$ in $\mathcal{G}(L')$. These satisfy the following conditions: 
\begin{enumerate}
\item $u_1$ and $u_2$ are not connected through sub-graph $\mathcal{G}(T)$ of $\mathcal{G}(L')$, more precisely, through almost trees of $\mathcal{G}(T)$.
\item number of positive edges in these spanning tress of $\mathcal{G}(L')$ are  $\mathsf{v}(\mathcal{T})+i$,  whenever the spanning tree of $\mathcal{G}(T)$  having $i$ number of positive edges.

\end{enumerate}

 \noindent Therefore, corresponding to all spanning tress of $\mathcal{G}(L)$ that do not contain $e$, there exist: 
 \begin{enumerate}
\item  $\displaystyle \sum_{i=1,2}y_{i_{e'}}s_{v-i}(L_{\infty})$ number of spanning trees in $\mathcal{G}(L')$ that include edge $e'$ with $v$ number of positive edges, and \\

\item $\displaystyle \sum_{i=1,2}(y_i-y_{i_{e'}})s_{v-i}(L_\infty)$ number of  spanning trees in $\mathcal{G}(L')$ that do not include edge $e'$   while still having $v$ number of positive edges.
\end{enumerate}
\noindent For any integer $v$, we have
\vspace{-.2cm}
\begin{align*}
s_{v}(L')&=\text{number of spanning trees in~} \mathcal{G}(L')  \text{~ having~} v \text{~ number of positive edges}\\
&=x_1s_{v-1}(L_0)+x_2s_{v-2}(L_0)+y_1s_{v-1}(L_\infty)+y_2s_{v-2}(L_\infty)
\end{align*}
\vspace{-.8cm}
\begin{equation}\label{eqL'}
\begin{split} 
 \det(L')&=\Big| \displaystyle \sum_{v}(-1)^{v}s_{v}(L') \Big|\\
 &=\Big| \displaystyle \sum_{v}(-1)^{v} \left\{ x_1 s_{v-1}(L_0)+x_2s_{v-2}(L_0)+y_1s_{v-1}(L_\infty)+y_2s_{v-2}(L_\infty)\right \}\Big|\\
&=\Big| \displaystyle \sum_{v}(-1)^{v} \{x_1s_{v-1}(L_0)+x_2s_{v-2}(L_0)\}+\displaystyle \sum_{v}(-1)^{v}\{y_1s_{v-1}(L_\infty)+y_2s_{v-2}(L_\infty)\}\Big|\\
&=\Big|(x_1-x_2) \displaystyle \sum_{v'}(-1)^{v'-1}s_{v'}(L_0)+(-y_1+y_2)\displaystyle \sum_{v'}(-1)^{v'}s_{v'}(L_\infty)\Big|\\
&=\Big|(x_1-x_2)\mathfrak{a}+(-y_1+y_2)\mathfrak{b}\Big|,
\end{split}
\end{equation}
where $L'_0$ and $L'_\infty$ are the links obtained from $L'$ by performing smoothings at crossing $c'$. Since $L$ is quasi-alternating at $c$  and $e$ is a positive edge, by Remark~\ref{rem:ab}

\vspace{-.5cm}
\[\displaystyle \sum_{v}(-1)^{v} s_{v-1}(L_0). \displaystyle \sum_{v}(-1)^{v}s_{v}(L_\infty)>0, \quad \text{~that is}\quad \mathfrak{a}.\mathfrak{b}>0.\]
\vspace{-.5cm}

\noindent If the edge $e'$ in $\mathcal{G}(T)$ is negative, then the determinate of $L'_0$ and $L'_{\infty}$ are given  by the following expressions:
\vspace{-.7cm} 

\begin{align*}
s_{v}(L'_{0})&=\text{number of spanning trees in~} \mathcal{G}(L') \text{~ without egde~} e' \text{~ having~} v \text{~ number of positive edges}\\
&=(x_1-x_{1_{e'}})s_{v-1}(L_0)+(x_2-x_{2_{e'}})s_{v-2}(L_{0})+(y_1-y_{1_{e'}})s_{v-1}(L_\infty)+(y_2-y_{2_{e'}})s_{v-2}(L_\infty)
\end{align*}
\begin{equation}\label{eqL'1}
\begin{split}
 \det(L'_0)&=\Big| \displaystyle \sum_{v}(-1)^{v}s_{v}(L'_0)\Big|\\
&=\Big|\displaystyle \sum_{v}(-1)^{v} \{(x_1-x_{1_{e'}})s_{v-1}(L_0)+(x_2-x_{2_{e'}})s_{v-2}(L_{0})\\
&\hspace{.2cm}+(y_1-y_{1_{e'}})s_{v-1}(L_\infty)+(y_2-y_{2_{e'}})s_{v-2}(L_\infty)\} \Big| \\
&=\Big|\displaystyle \sum_{v}(-1)^{v}\{(x_1-x_{1_{e'}})s_{v-1}(L_0)+(x_2-x_{2_{e'}})s_{v-2}(L_{0})\}\\
&\hspace{.2cm}+\displaystyle \sum_{v}(-1)^{v}\{(y_1-y_{1_{e'}})s_{v-1}(L_\infty)+(y_2-y_{2_{e'}})s_{v-2}(L_\infty)\}\Big| \\
&=\Big|\{(x_1+x_{1_{e'}})-(x_2-x_{2_{e'}})\}\displaystyle \sum_{v'}(-1)^{v'-1}s_{v'}(L_0)+\{-(y_1-y_{1_{e'}})+(y_2-y_{2_{e'}})\} \displaystyle \sum_{v'}(-1)^{v'}s_{v'}(L_\infty)\Big| \\
&=\Big|\{(x_1-x_{1_{e'}})-(x_2-x_{2_{e'}})\}\mathfrak{a}+\{(y_2-y_{2_{e'}})-(y_1-y_{1_{e'}})\}\mathfrak{b}\Big| \\
\end{split}
\end{equation}


\begin{equation}\label{eqL'2}
\begin{split}
s_{v}(L'_{\infty})&= \text{number of spanning trees in~} \mathcal{G}(L') \text{~ with egde~} e' \text{~ having~} v \text{~ number of positive edges}\\
&=x_{1_{e'}}s_{v-1}(L_0)+x_{2_{e'}}s_{v-2}(L_{0})+y_{1_{e'}}s_{v-1}(L_\infty)+y_{2_{e'}}s_{v-2}(L_\infty)\\
\det(L'_{\infty})&=\Big| \displaystyle \sum_{v}(-1)^{v}s_{v}(L'_{\infty})\Big|\\
&=\Big|\displaystyle \sum_{v}(-1)^{v}\{ x_{1_{e'}}s_{v-1}(L_0)+x_{2_{e'}}s_{v-2}(L_{0})+y_{1_{e'}}s_{v-1}(L_\infty)+y_{2_{e'}}s_{v-2}(L_\infty)\} \Big| \\
&=\Big|\displaystyle \sum_{v}(-1)^{v}\{x_{1_{e'}}s_{v-1}(L_0)+x_{2_{e'}}s_{v-2}(L_{0})\}+\displaystyle \sum_{v}(-1)^{v}\{y_{1_{e'}}s_{v-1}(L_\infty)+y_{2_{e'}}s_{v-2}(L_\infty))\}\Big| \\
&=\Big|(x_{1_{e'}}-x_{2_{e'}})\displaystyle \sum_{v'}(-1)^{v'-1}s_{v'}(L_0)+(-y_{1_{e'}}+y_{2_{e'}}) \displaystyle \sum_{v'}(-1)^{v'}s_{v'}(L_\infty)\Big| \\
&=\Big|(x_{1_{e'}}-x_{2_{e'}})\mathfrak{a}+(y_{2_{e'}}-y_{1_{e'}})\mathfrak{b}\Big| \\
\end{split}
\end{equation}
\vspace{.1cm}

\noindent If the edge $e'$ in $\mathcal{G}(T)$ is positive, then the determinate of $L'_0$ and $L'_{\infty}$ are given  by the following expressions:
\begin{align*}
s_{v-1}(L'_{0})&=\text{number of spanning trees in~} \mathcal{G}(L') \text{~ with egde~} e' \text{~ having~} v \text{~ number of positive edges}\\
&=x_{1_{e'}}s_{v-1}(L_0)+x_{2_{e'}}s_{v-2}(L_{0})+y_{1_{e'}}s_{v-1}(L_\infty)+y_{2_{e'}}s_{v-2}(L_\infty)
\end{align*}

\vspace{-.5cm}
\begin{equation}\label{eqL'1+}
\begin{split}
 \det(L'_0)&=\Big| \displaystyle \sum_{v}(-1)^{v}s_{v}(L'_0)\Big|\\
&= \Big|\displaystyle \sum_{v}(-1)^{v}\{ x_{1_{e'}}s_{v}(L_0)+x_{2_{e'}}s_{v-1}(L_{0})+y_{1_{e'}}s_{v}(L_\infty)+y_{2_{e'}}s_{v-1}(L_\infty)\} \Big| \\
&=\Big|\displaystyle \sum_{v}(-1)^{v}\{x_{1_{e'}}s_{v}(L_0)+x_{2_{e'}}s_{v-1}(L_{0})\}+\displaystyle \sum_{v}(-1)^{v}\{y_{1_{e'}}s_{v}(L_\infty)+y_{2_{e'}}s_{v-1}(L_\infty)\}\Big| \\
&=\Big|(x_{1_{e'}}-x_{2_{e'}})\displaystyle \sum_{v'}(-1)^{v'}s_{v'}(L_0)+(y_{1_{e'}}-y_{2_{e'}}) \displaystyle \sum_{v'}(-1)^{v'}s_{v'}(L_\infty)\Big| \\
&=\Big|(x_{1_{e'}}-x_{2_{e'}})(-\mathfrak{a})+(y_{1_{e'}}-y_{2_{e'}})\mathfrak{b}\Big| =\Big|(x_{1_{e'}}-x_{2_{e'}})\mathfrak{a}+(y_{2_{e'}}-y_{1_{e'}})\mathfrak{b}\Big|\\
\end{split}
\end{equation}

\begin{align*}
s_{v}(L'_{\infty})&=\text{number of spanning trees in~} \mathcal{G}(L') \text{~ without egde~} e' \text{~ having~} v \text{~ number of positive edges}\\
&=(x_1-x_{1_{e'}})s_{v-1}(L_0)+(x_2-x_{2_{e'}})s_{v-2}(L_{0})+(y_1-y_{1_{e'}})s_{v-1}(L_\infty)+(y_2-y_{2_{e'}})s_{v-2}(L_\infty)
\end{align*}

\noindent Using Eq.~(\ref{eqL'1}), we have
\begin{equation}\label{eqL'2+}
\begin{split}
 \det(L'_{\infty})&=\Big| \displaystyle \sum_{v}(-1)^{v}s_{v}(L'_{\infty})\Big|\\
&=\Big|\{(x_1-x_{1_{e'}})-(x_2-x_{2_{e'}})\}\mathfrak{a}+\{(y_2-y_{2_{e'}})-(y_1-y_{1_{e'}})\}\mathfrak{b}\Big| \\
\end{split}
\end{equation}


\noindent {\underline{Case(1)}} Suppose that $T=T_{[q]}$, as shown in Fig.~\ref{Fig.t[q]}. Then the edge $e'$ in the Tait sub-graph $\mathcal{G}(T_{[q]})$ is negative, as depicted in Fig.~\ref{tait:graph}(a), and 
 \[x_1=2, ~x_2=q, ~x_{1_{e'}}=2, ~x_{2_{e'}}=q-1,\]
  \[y_1=2q, ~y_2=0, ~y_{1_{e'}}=2q-2,~ y_{2_{e'}}=0.\]
Using Eq.~(\ref{eqL'}), (\ref{eqL'1}), and (\ref{eqL'2}), we have
\[\det(L'_0)=|\mathfrak{a}+2\mathfrak{b}|, \quad \det(L'_{\infty})=|(q-3)\mathfrak{a}+2(q-1)\mathfrak{b}|, \text{~and}\]
\[\det(L')=|(q-2)\mathfrak{a}+2q\mathfrak{b}|=|(\mathfrak{a}+2\mathfrak{b})+\{(q-3)\mathfrak{a}+2(q-1)\mathfrak{b}\}|\]
It is evident that $\det(L')=\det(L'_0)+\det(L'_{\infty})$ holds if and only if 
\begin{equation}\label{eqt^{p}}
(\mathfrak{a}+2\mathfrak{b})\{(q-3)\mathfrak{a}+2(q-1)\mathfrak{b})\}>0.
\end{equation}
Clearly, Eq.~(\ref{eqt^{p}}) holds for all $q\geq 3$. 
If $q=2$, then Eq.~(\ref{eqt^{p}}) holds if and only if for $\mathfrak{a},\mathfrak{b}\gtrless0$, $(\mathfrak{a}+2\mathfrak{b})\gtrless 0$ and
\[(q-3)\mathfrak{a}+2(q-1)\mathfrak{b}=-\mathfrak{a}+2\mathfrak{b}\gtrless 0\quad \iff \quad 2\mathfrak{b} \gtrless \mathfrak{a} \quad \iff \quad |\mathfrak{a}|<2|\mathfrak{b}|.\]

\noindent {\underline{Case(2)}} Suppose that $T=T^{p}$, as shown in Fig.~\ref{Fig.t^p}. Then the edge $e'$ in the Tait sub-graph $\mathcal{G}(T^p)$ is positive, as depicted in Fig.~\ref{tait:graph}(b), and 
 \[x_1=2p,~x_2=p+1,~ x_{1_{e'}}=p,~ x_{2_{e'}}=p+1,\]
  \[y_1=2p,~y_2=1, ~y_{1_{e'}}=p, ~y_{2_{e'}}=1\]
Using Eq.~(\ref{eqL'}), (\ref{eqL'1+}), and (\ref{eqL'2+}), we have
\[\det(L'_0)=|\mathfrak{a}+(p-1)\mathfrak{b}|, \quad \det(L'_{\infty})=|p\mathfrak{a}-p\mathfrak{b}|, \text{~and}\]
\[\det(L')=|(p-1)\mathfrak{a}+(1-2p)\mathfrak{b}|=|(p\mathfrak{a}-p\mathfrak{b})+(-\mathfrak{a}-(p-1)\mathfrak{b})|.\]
It is evident that $\det(L')=\det(L'_0)+\det(L'_{\infty})$ holds if and only if 
\begin{equation}\label{eqt^p}
(p\mathfrak{a}-p\mathfrak{b})\{-\mathfrak{a}-(p-1)\mathfrak{b}\}>0.\end{equation}
For $a,b\gtrless0$, $(-\mathfrak{a}-(p-1)\mathfrak{b})\lessgtr 0$ and Eq.~(\ref{eqt^p}) holds if and only if  
\[p\mathfrak{a}-p\mathfrak{b}\lessgtr 0\quad \iff \quad \mathfrak{a} \lessgtr \mathfrak{b} \iff  |\mathfrak{a}|<|\mathfrak{b}|.\]

\noindent {\underline{Case(3)} } Suppose that $T=T_{q}$, as shown in Fig.~\ref{Fig.t_q}. Then the edge $e'$ in the Tait sub-graph $\mathcal{G}(T_q)$ is negative, as depicted in Fig.~\ref{tait:graph}(c), and 
 \[x_1=2, ~x_2=q+1, ~ x_{1_{e'}}=2, ~ x_{2_{e'}}=q\]
   \[y_1=2q+4, ~y_2=q+1, ~y_{1_{e'}}=2q+2, ~y_{2_{e'}}=q\]
Using Eq.~(\ref{eqL'}), (\ref{eqL'1}), and (\ref{eqL'2}), we have
\[\det(L'_0)=|a+b|, \quad \det(L'_{\infty})=|(q-2)a+(q+2)b|, \text{~and}\]
\[\det(L')=|(q-1)\mathfrak{a}+(q+3)\mathfrak{b}|=|(\mathfrak{a}+\mathfrak{b})+\{(q-2)\mathfrak{a}+(q+2)\mathfrak{b}\}|\] 
It is evident that $\det(L')=\det(L'_0)+\det(L'_{\infty})$ holds if and only if 
\begin{equation}\label{eqt_q}
(\mathfrak{a}+\mathfrak{b})\{(q-2)\mathfrak{a}+(q+2)\mathfrak{b})\}>0.\end{equation}
Clearly, Eq.~(\ref{eqt_q}) holds for all $q\geq 2$. For $q=1$, Eq.~(\ref{eqt_q}) becomes
\[(\mathfrak{a}+\mathfrak{b})(-\mathfrak{a}+3\mathfrak{b})> 0,\]
and it holds if and only if 
\[-\mathfrak{a}+3\mathfrak{b}\gtrless 0,\text{~whenever~} \mathfrak{a}\mathfrak{b}\gtrless 0 ,\text{~that is~} \iff  |\mathfrak{a}|<3|\mathfrak{b}|.\]

\noindent {\underline{Case(4)}} Suppose that $T=T^{p,q}$, as shown in Fig.~\ref{Fig.t^pq}. Then the edge $e'$ in the Tait sub-graph $\mathcal{G}(T^{p,q})$ is negative, as depicted in Fig.~\ref{tait:graph}(e), and 
 \[x_1=2p, ~x_2=pq+p+1, ~x_{1_{e'}}=2p, ~x_{2_{e'}}=pq+1\]
   \[y_1=2pq+2p, ~y_2=q+1, ~ y_{1_{e'}}=2pq, ~y_{2_{e'}}=q\]
Using Eq.~(\ref{eqL'}), (\ref{eqL'1}), and (\ref{eqL'2}), we have
\[\det(L'_0)=|p\mathfrak{a}+(2p-1)\mathfrak{b}|, \quad \det(L'_{\infty})=|(-2p+pq+1)\mathfrak{a}+(2pq-q)\mathfrak{b}|, \text{~and}\]
\begin{align*}
\det(L')&=|(pq-p+1)\mathfrak{a}+(2pq+2p-q-1)\mathfrak{b}|\\
&=|\{p\mathfrak{a}+(2p-1)\mathfrak{b}\}+\{(-2p+pq+1)\mathfrak{a}+(2pq-q)\mathfrak{b}\}|
\end{align*} 
It is evident that $\det(L')=\det(L'_0)+\det(L'_{\infty})$ holds if and only if 
\begin{equation}\label{eqt^pq}
\{p\mathfrak{a}+(2p-1)\mathfrak{b}\}\{(-2p+pq+1)\mathfrak{a}+(2pq-q)\mathfrak{b}\}>0.
\end{equation}
Clearly, Eq.~(\ref{eqt^pq}) holds for all $p\geq 1$, $q\geq 2$ and $p=q=1$. In case $q=1$ and $p>1$, Eq.~(\ref{eqt^pq}) becomes
\begin{equation}\label{eqt^pq:n}
(p\mathfrak{a}+(2p-1)\mathfrak{b})\{(1-p)\mathfrak{a}+(2p-1)\mathfrak{b}\}\gtrless 0.\end{equation}
 Moreover, for $\mathfrak{a},\mathfrak{b}\gtrless0$, $\mathfrak{a}+(2p-1)\mathfrak{b}\gtrless 0$ and  Eq.~(\ref{eqt^pq:n}) holds if and only if
 \[(1-p)\mathfrak{a}+(2p-1)\mathfrak{b}\gtrless 0,\quad \text{that is}\quad |\mathfrak{a}|<\left(1+\dfrac{p}{p-1}\right)|\mathfrak{b}|.\]

\noindent {\underline{Case(5)}} Suppose that $T=T_{p,q}$, as shown in Fig.~\ref{Fig.t_pq}. Then the edge $e'$ in the Tait sub-graph $\mathcal{G}(T_{p,q})$ is negative, as depicted in Fig.~\ref{tait:graph}(d), and 
 \[x_1=2p+2, ~x_2=pq+q, ~ x_{1_{e'}}=2, ~ x_{2_{e'}}=q\]
   \[y_1=2pq+2q+2, ~y_2=q, ~ y_{1_{e'}}=2q, ~ y_{2_{e'}}=0\]
Using Eq.~(\ref{eqL'}), (\ref{eqL'1}), and (\ref{eqL'2}), we have
\[\det(L'_0)=|(pq-2p)\mathfrak{a}+(2pq-q+2)\mathfrak{b}|, \quad \det(L'_{\infty})=|(q-2)\mathfrak{a}+2q\mathfrak{b}|, \text{~and}\]
\begin{align*}
\det(L')&=|(-2p+q+pq-2)\mathfrak{a}+(2pq+q+2)\mathfrak{b}|\\
&=|\{(q-2)\mathfrak{a}+2q\mathfrak{b}\}+\{(pq-2p)\mathfrak{a}+(2pq-q+2)\mathfrak{b}\}|
\end{align*} 
It is evident that $\det(L')=\det(L'_0)+\det(L'_{\infty})$ holds if and only if 
\begin{equation}\label{eqt_pq}
\{(q-2)\mathfrak{a}+2q\mathfrak{b}\}\{(pq-2p)\mathfrak{a}+(2pq-q+2)\mathfrak{b}\}>0.
\end{equation}
Clearly, Eq.~(\ref{eqt_pq}) holds for all $p\geq 1$ and $q\geq 2$. In case, when $q=1$ and $p\geq 1$, Eq.~(\ref{eqt_pq})
 becomes
\begin{equation}\label{eqt_pq:n}
(-\mathfrak{a}+2\mathfrak{b})\{-p\mathfrak{a}+(2p+1)\mathfrak{b}\}>0.
\end{equation} 
It is evident that for $\mathfrak{a},\mathfrak{b}\gtrless0$, Eq.~(\ref{eqt_pq:n}) holds if and only if both
\[(-\mathfrak{a}+2\mathfrak{b}) \gtrless0 \quad \text{~and~} \quad -p\mathfrak{a}+(2p+1)\mathfrak{b}\gtrless0.\] 
\[\text{~That is, ~} \quad \mathfrak{b} \gtrless -\mathfrak{a} \quad  \text{~and~}\quad \dfrac{(2p+1)}{p}\mathfrak{b}\gtrless  \mathfrak{a}.\] 
It is easy to observe that $2\mathfrak{b} \gtrless \mathfrak{a}$ implies $\dfrac{(2p+1)}{p}\mathfrak{b}\gtrless  \mathfrak{a}.$ Hence, Eq.~(\ref{eqt_pq:n}) holds for any $p\geq 1$ if and only if $|a|<2|b|.$ \\

\noindent {\underline{Case(6)}} Suppose that $T=T^{[p,q]}_{\infty}$, as shown in Fig.~\ref{Fig.t^pq1}. Then the edge $e'$ in the Tait sub-graph $\mathcal{G}(T^{[p,q]}_{\infty})$ is negative, as depicted in Fig.~\ref{tait:graph}(f), and 
 \[x_1=4p+2,~x_2=pq+p+q+2,~ x_{1_{e'}}=2p+2,~ x_{2_{e'}}=q+1\]
   \[y_1=4pq+2p+2q+2,~y_2=2q+1, ~y_{1_{e'}}=2pq+2q+2,~ y_{2_{e'}}=q\]
Using Eq.~(\ref{eqL'}), (\ref{eqL'1}), and (\ref{eqL'2}), we have
\[\det(L'_0)=|(pq-p+1)\mathfrak{a}+(2pq+2p-q-1)\mathfrak{b}| =|(p(q-1)+1)\mathfrak{a}+(2p-1)(q+1)\mathfrak{b}|,\]
\[ \det(L'_{\infty})=|(-2p+q-1)\mathfrak{a}+(2pq+q+2)\mathfrak{b}|=|(q-(2p+1))\mathfrak{a}+(2pq+q+2)\mathfrak{b}|, \text{~and}\]
\begin{align*}
\det(L')&=|(pq-3p+q)\mathfrak{a}+(4pq+2p+1)\mathfrak{b}|\\
&=|\{(pq-p+1)\mathfrak{a}+(2pq+2p-q-1)\mathfrak{b}\}+\{(-2p+q-1)\mathfrak{a}+(2pq+q+2)\mathfrak{b}\}|\\
&=|\{(p(q-1)+1)\mathfrak{a}+(2p-1)(q+1)\mathfrak{b}\}+\{(q-(2p+1))\mathfrak{a}+(2pq+q+2)\mathfrak{b}\}|
\end{align*} 
It is evident that $\det(L')=\det(L'_0)+\det(L'_{\infty})$ holds if and only if 
\begin{equation}\label{eqt'}
\{(p(q-1)+1)\mathfrak{a}+(2p-1)(q+1)\mathfrak{b}\}\{(q-(2p+1))\mathfrak{a}+(2pq+q+2)\mathfrak{b}\}>0.
\end{equation}
Clearly, Eq.~(\ref{eqt'}) holds for all $p\geq 1$ and $q\geq (2p+1)$. 
For $q<(2p+1)$ and $p\geq1$,
\[(p(q-1)+1)\mathfrak{a}+(2p-1)(q+1)\mathfrak{b}\gtrless 0, \text{~whenever~} a,b\gtrless0.\]
Therefore, Eq.~(\ref{eqt'}) holds in this case if and only if for $\mathfrak{a}\mathfrak{b}\gtrless0$,
\[(q-(2p+1)\mathfrak{a}+(2pq+q+2)\mathfrak{b}\gtrless 0,\quad \text{that is} \quad |\mathfrak{a}|<\left(\dfrac{q(2p+1)+2}{(2p+1)-q}\right)|\mathfrak{b}|.\]

\noindent {\underline{Case(7)}} Suppose that $T=T^{[p,q]}$ and $p, q\geq 1$ be positive integers, as shown in Fig.~\ref{Fig.t^[pq]}. Then the edge $e'$ in the Tait sub-graph $\mathcal{G}(T^{[p,q]})$ is negative, as depicted in Fig.~\ref{tait:graph}(g), and 
 \[x_1=6p+2, ~x_2=3pq+2p+q+1, x_{1_{e'}}=4p+2,~ x_{2_{e'}}=2pq+p+q+1\]
   \[y_1=6pq+4p+2q+2,~y_2=2pq+p+2q+1,~ y_{1_{e'}}=4pq+2p+2q+2, ~y_{2_{e'}}=2q+1\]
Using Eq.~(\ref{eqL'}), (\ref{eqL'1}), and (\ref{eqL'2}), we have
\[\det(L'_0)=|(p(q-1)+1)\mathfrak{a}+p\mathfrak{b}|, \quad \det(L'_{\infty})=|(2pq-3p+q-1)\mathfrak{a}+(4pq+2p+1)\mathfrak{b}|, \text{~and}\]
\begin{align*}
\det(L')&=|(3pq-4p+q-1)\mathfrak{a}+(4pq+3p+1)\mathfrak{b}|\\
&=|\{(pq-p)\mathfrak{a}+p\mathfrak{b}\}+\{(2pq-3p+q-1)\mathfrak{a}+(4pq+2p+1)\mathfrak{b}\}|
\end{align*} 
It is evident that $\det(L')=\det(L'_0)+\det(L'_{\infty})$ holds if and only if 
\begin{equation}\label{eqtf}
\{(pq-p)\mathfrak{a}+p\mathfrak{b}\}\{(2pq-3p+q-1)\mathfrak{a}+(4pq+2p+1)\mathfrak{b}\}>0.
\end{equation}
Clearly, Eq.~(\ref{eqtf}) holds for all $p\geq 1$ and $q>1$. For $p\geq 1$ and $q=1$, Eq.~(\ref{eqtf}) becomes
\[p\mathfrak{b}\{(-p)\mathfrak{a}+(6p+1)\}>0,\]
and it holds if and only if, for $\mathfrak{a}\mathfrak{b}\gtrless 0$
\[(-p)\mathfrak{a}+(6p+1)\mathfrak{b} \gtrless 0 \iff \dfrac{(6p+1)}{p}\mathfrak{b} \gtrless  \mathfrak{a} \iff |\mathfrak{a}|<\dfrac{(6p+1)}{p}|\mathfrak{b}|.\]

\noindent Hence the proof of the lemma.
\end{proof}
