\end{figure*}




The freeze-in energy density of axions produced from the Primakoff process can be parameterized as~\cite{Jaeckel:2014qea}
\begin{align}
\label{eq.primfreezein_full}
    &\rho_\mathrm{Prim}(T \ll T_{\mathrm{reh}})\\
    &= A_\mathrm{Prim} \frac{2.4 \times 10^{-8}}{\sqrt{g_{*}(T_\mathrm{reh})}} \left(\frac{T_{\mathrm{reh}}}{10\,\mathrm{MeV}}\right) \left(\frac{g_{a\gamma\gamma}}{10^{-11}\,\mathrm{GeV^{-1}}}\right)^2 \notag \\
    &\times \left(\frac{a(T_\mathrm{reh})}{a(T)}\right)^3 \left(\frac{m_a}{1\,\mathrm{MeV}}\right) \left(\frac{n_\mathrm{eq}(T_{\mathrm{reh}})}{1\,\mathrm{MeV}^3}\right)\, \mathrm{MeV}^4\, ,\notag
\end{align}
where $n_{\mathrm{eq}}$ is the number density of axions in thermal equilibrium at $T = T_{\mathrm{reh}}$. In the limit $m_a \ll T_{\mathrm{reh}}$, the expression above simplifies to
\begin{align}
    \label{eq:primakoff}
    & \rho_\mathrm{Prim}(T \ll T_{\mathrm{reh}}) \\
    &= A_\mathrm{Prim} \frac{2.4 \times 10^{-5}}{\sqrt{g_{*}(T_\mathrm{reh})}} \frac{\zeta(3)}{\pi^2} \left(\frac{T_{\mathrm{reh}}}{10\,\mathrm{MeV}}\right)^4 \left(\frac{g_{a\gamma\gamma}}{10^{-11}\,\mathrm{GeV^{-1}}}\right)^2 \notag\\
    &\times \left(\frac{a(T_\mathrm{reh})}{a(T)}\right)^3 \left(\frac{m_a}{1\,\mathrm{MeV}}\right)\, \mathrm{MeV}^4\, ,\notag
\end{align}
where the numerical coefficient $A_\mathrm{Prim}$, which depends on $m_a$ and $T_{\mathrm{reh}}$, is computed in Ref.~\cite{Jain:2024dtw}. The resulting freeze-in fraction of decaying axion dark matter for $T \gg T_{\rm decay}$ is then
\begin{align}
    \label{eq:primakoff_approx}
    &\mathcal{F}_\mathrm{Prim} 
    \equiv \frac{\rho_\mathrm{Prim}}{\rho_{\mathrm{DM}}} \\
    &= \frac{3.4 \times 10^{-3} A_\mathrm{Prim}}{\sqrt{g_{*}(T_\mathrm{reh})}} \left(\frac{T_{\mathrm{reh}}}{10\,\mathrm{MeV}}\right) \left(\frac{g_{a\gamma\gamma}}{10^{-11}\,\mathrm{GeV^{-1}}}\right)^2 \notag\\
    &\times \left(\frac{m_a}{1\,\mathrm{MeV}}\right)\, .\notag
\end{align}
We have cross-checked the approximation in Eq.~\eqref{eq:primakoff_approx} by computing the full integral expression for the equilibrium number density $n_{\rm eq}$ in Eq.~\eqref{eq.primfreezein_full}, including the effects of thermal suppression. While this correction slightly modifies the result at low temperatures, the impact is minimal, as discussed further in Appendix~\ref{appendix}. The approximation used in Eq.~\eqref{eq:primakoff_approx} remains valid across the relevant parameter space.

A complementary freeze-in channel arises from the inverse decay process $\gamma + \gamma \rightarrow a$, with the resulting relic fraction given by
\begin{align}
\label{eq:inversedecay_approx}
    \mathcal{F}_\mathrm{Id} &= A_\mathrm{Id} \frac{1.42 \times 10^{-4}}{\sqrt{g_*(T')}} \left(\frac{g_{a\gamma\gamma}}{10^{-11}\,\mathrm{GeV}^{-1}}\right)^2 \left(\frac{m_a}{0.1\,\mathrm{MeV}}\right)^2 \notag\\
    &\times \!\left(\! \frac{T'}{T_\mathrm{Id}} \frac{\left(4\left(\frac{T_\mathrm{Id}}{T'}\right)^2 \!-\! 1\right)^{3/2}}{3^{3/2}} \frac{\coth\!{\left(0.1 \frac{T_\mathrm{Id}}{T'}\right)}}{\coth{(0.1)}} \!\right)_{T' = \min[T_\mathrm{Id}, T_\mathrm{reh}]} \! ,
\end{align}
where $T_\mathrm{Id} \simeq 2.5 m_a$ is the inverse decay threshold, and $A_\mathrm{Id}$ is a phenomenological factor that solely depends on the axion mass~\cite{Jain:2024dtw}. In the region of interest, the contribution from $e^+ e^-$ annihilation is negligible. Finally, we define the total abundance of axions, $\mathcal{F}_a$, “as if the axion were stable”~\cite{Langhoff:2022bij}, as the sum of the freeze-in contributions from the Primakoff and inverse decay processes:
\begin{equation}
    \label{eq:F}
    \mathcal{F}_a \simeq \mathcal{F}_\mathrm{Prim} + \mathcal{F}_\mathrm{Id}\, .
\end{equation}
The above fitting formulae allow us to compute the fraction of would-be dark matter composed of axions before their decay, as a function of the axion mass $m_a$, the axion–photon coupling $g_{a\gamma\gamma}$, and the reheat temperature $T_{\rm reh}$. This fraction serves as the input for the next stage of our analysis.

Note that it is implicitly assumed that such reheating is instantaneous, i.e. inflation ends at $T_{\rm reh}$ and there are no axions produced in the prior epoch. Similarly to neglecting the possible misalignment population of axions (which can be fine-tuned away), the assumption of instantaneous reheating leads to conservative constraints from the irreducible freeze-in population. Alternatively, one could consider explicit modified cosmologies~\cite{Visinelli:2009kt,Sheridan:2024vtt} or take the abundance as an independent free parameter with $\mathcal{F}_a$ above giving the minimum~\cite{Balazs:2022tjl}. 

\section{Ionization of the intergalactic medium by axion decay}
\label{sec:reionization}

We first consider the ionization rate of our Universe between recombination and reionization, corresponding to the redshift range $10\lesssim z\lesssim 1100$. The recombination epoch  is mainly governed by the evolution of the ionization fraction $X_e$, defined as the ratio between the number densities of free electrons $n_e$ and hydrogen nuclei $n_H$,
\begin{equation}
    \label{eq.ionization rate}
    X_e=\frac{n_e}{n_H}\,,
\end{equation}
and the baryon temperature $T_b$. More precisely, the differential equations describing the evolution of these quantities read~\cite{Escudero:2023vgv,Slatyer:2016qyl}
\begin{align}
  &\frac{{\rm d}X_e}{{\rm d}z}\\
  =&\frac{C_H}{(1+z)H(z)}\!\left(\!-\beta_H(T_\gamma)(1 \!-\! X_e)e^{\frac{-E_H,2s1s}{T_\gamma}} \!\! +\! X_e^2n_H\alpha_H(T_b)\!\right)\notag\\
  &+\frac{1}{n_HE_i}\frac{{\rm d}E}{{\rm d}V{\rm d}z}\bigg|_{\mathrm{dep,ion}}\!\!\!\!+(1-C_H)\frac{1}{n_HE_{H,1s2p}}\frac{{\rm d}E}{{\rm d}V{\rm d}z}\bigg|_{\mathrm{dep,exc}}\!\!,\notag \\
    &(1+z)\frac{{\rm d}T_b}{{\rm d}z}=2T_b+\frac{8}{3}\frac{\rho_\gamma\sigma_T}{m_e\,H(z)}\frac{X_e}{1+f_{\mathrm{He}}+X_e}(T_b-T_\gamma)\notag\\
    &-\frac{2}{3}\frac{1+z}{n_H(1+f_{\mathrm{He}}+X_e)}\frac{{\rm d}E}{{\rm d}V{\rm d}z}\bigg{|}_\mathrm{dep,heat}\,, 
\end{align}
where $T_\gamma$ is the photon temperature, $H(z)$ is the Hubble parameter at redshift $z$, $E_{H,1s2s}=E_{H,1s2p}=10.2\,\mathrm{eV}$ is the energy difference between the 2s and 1s energy levels of the hydrogen atom, and $E_i=13.6\,\mathrm{eV}$ is the average ionization energy of hydrogen. The factor $C_H$ gives the probability for an electron in the first excited state to transition to the ground state before being ionized~\cite{Slatyer:2016qyl}. Moreover, the evolution of $T_b$ is influenced by the Thomson scattering cross section $\sigma_T$ and the photon energy density $\rho_\gamma$, while the coefficients $\beta_H$ and $\alpha_H$ appearing in the evolution of $X_e$ correspond to photoionization and recombination rates, respectively.



For each energy deposition channel, labeled by ``$\mathrm{c}$'', with ``ion'' for ionization, ``exc'' for excitation, and ``heat'' for IGM heating, the energy deposition rate takes the form
\begin{equation}
    \frac{{\rm d}E}{{\rm d}V\,{\rm d}z}\bigg|_{\mathrm{dep,c}} = f_{\mathrm{c}}(z)\,\frac{{\rm d}E_{\mathrm{inj}}}{{\rm d}V\,{\rm d}z}\,,
\end{equation}
where $f_{\mathrm{c}}(z)$ is the redshift-dependent efficiency for the channel ``$\mathrm{c}$''. The efficiency function $f_{\mathrm{c}}(z)$ is obtained using the \textsc{DarkHistory} code~\cite{Liu:2019bbm}, and we precompute it for our analysis. To simplify the computation, we adopt the beyond on-the-spot assumption~\cite{Poulin:2016anj}, in which energy injected at redshift $z$ is assumed to be deposited instantaneously. However, rather than assuming a constant efficiency, we retain the full redshift-dependent form of $f_{\mathrm{c}}(z)$ as computed numerically.

The energy injection rate due to axion decays is given by~\cite{Lucca:2019rxf}
\begin{equation}
    \frac{{\rm d}E_{\mathrm{inj}}}{{\rm d}V\,{\rm d}z} = \frac{\Gamma_{a\rightarrow\gamma\gamma} \,e^{-\Gamma_{a\rightarrow\gamma\gamma} t(z)}}{(1+z)\,H(z)}\,\mathcal{F}_a\,\rho_c\,\Omega_{\rm DM}\,(1+z)^3\,,
\end{equation}
where $\Gamma_{a\rightarrow\gamma\gamma}$ is the axion decay rate defined in Eq.~\eqref{eq:Gamma}, $\mathcal{F}_a$ is the DM fraction in axions prior to decay in Eq.~\eqref{eq:F}, $\Omega_{\rm DM}$ is the present DM density fraction, and $\rho_c$ is the critical density today. We also define the total number density of hydrogen, including both neutral $H$ and ionized $H^+$, as a function of photon temperature $T_\gamma$:
\begin{equation}
    n_H=n_e+n_p=3.1\times 10^{-8}\eta_{10}(T_\gamma/T_{\gamma0})^3\,\mathrm{cm}^{-3}
\end{equation}
where $\eta_{10}=10^{10}\,n_b/n_\gamma\simeq 6.1$ is the baryon-to-photon ratio~\cite{Fields:2019pfx}, $n_b$ is the baryon number density, and $T_{\gamma0}\approx 2.7$\,K is the present-day photon temperature. This leads to the photon temperature at redshift $z$ as:
\begin{equation}
    T_\gamma=T_{\gamma0}(1+z)\,.
\end{equation}

The reionization era, corresponding to redshifts $z\lesssim 10$, is modeled using the tanh parametrization, see e.g.\ Ref.~\cite{Heinrich:2021ufa}. This describes the reionization of hydrogen and singly ionized helium as:
\begin{equation}
  X_{\mathrm{rei}}=\frac{1+f_{\mathrm{He}}}{2}\left[1+\tanh\left(\frac{(1+z_{\rm re})^{3/2}-(1+z)^{3/2}}{(3/2)(1+z)^{1/2}\Delta z}\right)\right]\,,
\end{equation}
where $z_{\rm re}=6.1$, $\Delta z=0.5$ and the helium-to-hydrogen number density ratio is given by
\begin{equation}
    f_{\mathrm{He}}=\frac{n_{\mathrm{He}}}{n_\mathrm{H}}=\frac{Y_p}{4(1-Y_p)}\,,
\end{equation}
with $Y_p$ denoting the primordial helium mass fraction. In this model, the full ionization history is expressed as the sum of the contributions from recombination and reionization:
\begin{equation}
    X_e^{\mathrm{tot}}(z)=X_e(z)+X_{\mathrm{rei}}(z)\,.
\end{equation}

To illustrate the impact of axion decays on the ionization history, Fig.~\ref{fig:Xez} shows the evolution of the ionization fraction in a model with a single axion-like particle of mass $m_a = 10^5\,\mathrm{eV}$ and photon coupling $g_{a\gamma\gamma} = 6 \times 10^{-13}\,\mathrm{GeV}^{-1}$, assuming a low reheating temperature $T_{\rm reh} = 5\,\mathrm{MeV}$. The axion population, comprising a small fraction $\sim 10^{-7}$ of the DM, decays after recombination and induces substantial ionization of the intergalactic medium at high redshift, compared to the standard cosmological history (black line). This early energy injection results in an optical depth $\tau_{\rm reio} \approx 1.92$, which is in strong tension with observational limits.

