\section{Analytic solutions}\label{apdx:analytic}

Here, we derive the analytic expression for the equilibrium price and corresponding optimal trajectories when $V,g$ are given by~\eqref{eq:g_V_quad}. From Proposition~\ref{prp:min_uniqueness} we have that optimal trajectories satisfy the following system of ordinary differential equations
\begin{equation}\label{eq:z_ode}
    \begin{cases}
            c_0\ddot{z}(t,x)+\dot{\omega}(t)=r_1(z(t,x)-y_1),~t\in (0,T),\\
            z(0,x)= x,~c_0\dot{z}(T,x)+\omega(T)=-r_2(z(T,x)-y_2).
        \end{cases}
\end{equation}
Assuming that $\omega$ is an equilibrium price and introducing
\begin{equation*}
    \Lambda(t)=\int_{\mathbb{R}} x \rho_0(x) dx+\int_0^t Q(s) ds,\quad t\in [0,T],
\end{equation*}
we obtain that
\begin{equation*}
    \dot{\Lambda}(t)=Q(t)=\int_{\mathbb{R}}\dot{z}(t,x) \rho_0(x) dx=\frac{d}{dt} \int_{\mathbb{R}}z(t,x) \rho_0(x) dx,\quad \forall t\in (0,T),
\end{equation*}
and
\begin{equation*}
    \Lambda(0)=\int_{\mathbb{R}} x \rho_0(x) dx= \int_{\mathbb{R}} z(0,x) \rho_0(x) dx.
\end{equation*}
Thus, we have that
\begin{equation*}
    \Lambda(t)= \int_{\mathbb{R}} z(t,x) \rho_0(x) dx,\quad \forall t\in [0,T],
\end{equation*}
and integrating~\eqref{eq:z_ode} with respect to $\rho_0$, we obtain
\begin{equation}\label{eq:omega_ODE}
\begin{cases}
    \dot{\omega}(t)=-c_0\ddot{\Lambda}(t)+r_1(\Lambda(t)-y_1),~t\in (0,T),\\
    \omega(T)=-c_0\dot{\Lambda}(T)-r_2(\Lambda(T)-y_2).
\end{cases}
\end{equation}
The latter can be easily integrated:
\begin{equation*}
    \omega(t)=-c_0\dot{\Lambda}(T)-r_2(\Lambda(T)-y_2)-\int_t^T \left[-c_0\ddot{\Lambda}(s)+r_1(\Lambda(s)-y_1)\right] ds.
\end{equation*}

Once $\omega$ is known,~\eqref{eq:z_ode} can also be integrated. Indeed, the general solution of the second-order ordinary differential equation~\eqref{eq:z_ode} is given by
\begin{equation*}
    z(t,x)=y_1+z_{\text{hom}}(t,x)-\frac{1}{c_0}\int_0^t \omega(s)\cosh k(t-s) ds,
\end{equation*}
where $k=\sqrt{\frac{r_1}{c_0}}$, and $z_{\text{hom}}$ is a solution to the homogeneous equation
\begin{equation*}
    \ddot{z}-k^2 z  =0.
\end{equation*}
Furthermore, we have that
\begin{equation}\label{eq:z_gen_sol}
    \dot{z}(t,x)=\dot{z}_{\text{hom}}(t,x)-\frac{\omega(t)}{c_0}-\frac{k}{c_0}\int_0^t \omega(s)\sinh k(t-s) ds,
\end{equation}
so initial-terminal conditions in~\eqref{eq:z_ode} reduce to
\begin{equation}\label{eq:z_boundary}
\begin{cases}
    z_{\text{hom}}(0,x)=x-y_1,\\
    c_0\dot{z}_{\text{hom}}(T,x)+r_2 z_{\text{hom}}(T,x)=B,
\end{cases}
\end{equation}
where, for simplicity, we denote by
\begin{equation*}
    B=r_2(y_2-y_1)+\int_0^T \omega(s) \left[\frac{r_2}{c_0}\cosh k(T-s)+k \sinh k(T-s)\right] ds.
\end{equation*}
There are two possibilities.
\begin{enumerate}
    \item $r_1=0$. In this case, we have that $k=0$, and
    \begin{equation*}
        \ddot{z}_{\text{hom}}(t,x)=0 \Longrightarrow z_{\text{hom}}(t,x)=c_1(x)+c_2(x)t.
    \end{equation*}
    Furthermore,~\eqref{eq:z_boundary} yields
    \begin{equation*}
        z_{\text{hom}}(t,x)=x-y_1+\frac{B-r_2(x-y_1)}{c_0+r_2 T}t,
    \end{equation*}
    and
    \begin{equation*}
        z(t,x)=x+\frac{B-r_2(x-y_1)}{c_0+r_2 T}t-\frac{1}{c_0}\int_0^t \omega(s) ds.
    \end{equation*}
    \item $r_1\neq 0$. In this case, we have that $k \neq 0$, and
    \begin{equation*}
        z_{\text{hom}}(t,x)=c_3(x) \cosh kt+c_4(x) \sinh kt.
    \end{equation*}
    Furthermore,~\eqref{eq:z_boundary} yields
    \begin{equation*}
        z_{\text{hom}}(t,x)=(x-y_1) \cosh kt+  \frac{B-(x-y_1)(c_0 k \sinh kT+r_2 \cosh kT)}{c_0 k \cosh kT+r_2 \sinh kT} \sinh kt,
    \end{equation*}
    and
    \begin{equation*}
    \begin{split}
        z(t,x)=&y_1+(x-y_1) \cosh kt+ \frac{B-(x-y_1)(c_0 k \sinh kT+r_2 \cosh kT)}{c_0 k \cosh kT+r_2 \sinh kT} \sinh k t\\
        &-\frac{1}{c_0} \int_0^t \omega(s) \cosh k(t-s) d s.
    \end{split}
    \end{equation*}
\end{enumerate}

