\bea
\xi_s=\frac{m_s^2I_e}{2\De}
\eea
%
For $\xi_s<1$ or $\xi_s>1$ the ground state will be nonmagnetic or exhibits induced magnetic (FM or AFM) order, respectively \cite{thalmeier:24} with $\xi^c_s=1$ designating the quantum critical point. Alternatively we may also define $\hh =m_sh'=g_{\text{eff}}\mu_BH/\De$ with the effective g-factor of the two singlets given by $g_{\text{eff}}=m_sg_J$.
The above Hamiltonian
is readily diagonalized leading to energy levels
%
\bea
\eps^\pm_\lam=\pm\eps_\lam=\pm\frac{\De}{2}[1+(\ga'_\lam)^2]^\fs
\eea
%
and sublattice $\lam$ =A,B- dependent eigenstates
%
\bea
|\eps^+_\lam\ra&=&\cos\theta_\lam|1\ra-\sin\theta_\lam|0\ra\non\\
|\eps^-_\lam\ra&=&\sin\theta_\lam|1\ra+\cos\theta_\lam|0\ra
\label{eq:eigenstate}
\eea
%
with the mixing angle given by $\tan 2\theta_\lam=\ga'_\lam$.



\section{Order parameter, magnetizations and critical temperature}
\label{sec:MFA}

The eigenstates of Eq.~(\ref{eq:eigenstate}) may be used to derive
the selfconsistency equations for the mean field order parameter according to
%
\bea
\la S_x\ra_\lam=\sum_{n=\pm}p^n_\lam\la \eps^n_\lam |S_x| \eps^n_\lam\ra=
\fs\tanh(\beta\eps_\lam)\sin 2\theta_\lam
\eea
%
with $p^n_\lam=Z^{-1}_\lam\exp(\beta\eps^n_\lam)$ $(\beta=1/T; k_B\equiv 1)$ denoting the
thermal occupation of the two eigenstates and $Z_\lam=2\cosh(\beta\eps^n_\lam)$ giving
the partition function of the two levels.
Explicitly, using Eq.(\ref{eq:heff}) the order parameter is then obtained from
the selfconsistent equation
%
\bea
\la S_x\ra_\lam&=&\fs m_s(h'+\si\ga\la S_x\ra_{\blam})\frac{1}{\hDe_T^{\lam}}
\tanh\bigl[(\frac{\De}{2T})\hDe^\lam_T\bigr]\non\\
\hDe^\lam_T&\equiv&\frac{1}{\De}(\eps^\lam_+ -\eps^\lam_-)=[1+m_s^2(h'+\si\ga\la S_x\ra_{\blam})^2]^\fs\non\\
&=&[1+(m_sh'+2\si\xi_s\la S_x\ra_{\blam})^2]^\fs\
\label{eq:MF}
\eea
%
%
