    \EndFor
    \State \textbf{end for} 
    \State Get predictions $\{\hat{\boldsymbol{X}}^i\}_{i=1}^K$ from the Spaformer network;
    \State Update the Diff-spaformer network with $\mathcal{L} $ in Eq. \ref{equ:loss_total};\\
\textbf{end for}
\EndFor
\end{algorithmic}
