\begin{algorithm}[htbp]
\caption{Inference process of Diff-spaformer}
\label{alg:Diff-spaformer_interpolation}
\hspace*{0.02in} {\bf Input:}
Missing seismic data $\boldsymbol{X}_{obs}$;
Corresponding binary missing mask $\boldsymbol{M}$;
Trained Diff-spaformer model.
\begin{algorithmic}[1]
%\state Generate transition timestamps based $m$ on $m$, $l$, and $r$.
%\For{$j=1, \ldots, n$}
\State Get the conditional prior information $\boldsymbol{Z}_{c}$ form Eq. \ref{equ:spen_obs};
