    \includegraphics[width=0.48\textwidth]{fig4.pdf}
    \caption{ $\zeta_\pm$ at $m_s\in\lbrace 94,1.5\times 94,2.0\times 94\rbrace\,\mathrm{MeV}$ in the bag model. Everything evaluated at $\mu_d=400\,\mathrm{MeV}, a_4=0.7$.}
