 \section{SUPPLEMENTAL MATERIAL}
For the sake of completeness and to possibly give the reader some insight on the explicit form of the bulk scalar
and the transport coefficients, we list them below. We note that as
the forms are rather complicated, it is often simpler to obtain them
using the methods outlined in the main text, as they require merely
simple matrix operations. To simplify formulae, we define the shorthands
%
\begin{align}
\chiinvdiag{A}{}&\equiv\chiinv{d}{d}-2\chiinv{d}{s}+\chiinv{s}{s} \nonumber, \\
\chiinvdiag{B}{}&\equiv\chiinv{u}{u}-2\chiinv{u}{d}+\chiinv{d}{d}+\chiinv{e}{e} \nonumber, \\
\chiinvdiag{C}{}&\equiv\chiinv{u}{u}-2\chiinv{u}{s}+\chiinv{s}{s}+\chiinv{e}{e}, 
\end{align}
%
and will make use of the Källén function $K\left(x,y,z\right)=x^{2}+y^{2}+z^{2}-2\left(xy+yz+zx\right)$ \footnote{We opt for the notation $K$ instead of the more common $\lambda$ to avoid confusion with the rates.} and
the pairwise sum $Q\left(x,y,z\right)=xy+yz+zx$. In terms of these,
we find the components of the bulk scalar under the constraints outlined
above to read
%
\begin{align}
&\Pi_{1}K\left(\chiinvdiag{A}{},\chiinvdiag{B}{},\chiinvdiag{C}{}\right)=n_sK\left(\chiinvdiag{A}{},\chiinvdiag{B}{},\chiinvdiag{C}{}\right)+n_q\nonumber\bigg\lbrace\left[\chiinv{u}{u}+\frac{1}{3}\chiinv{e}{e}\right]\left(\chiinvdiag{A}{}+\chiinvdiag{B}{}-\chiinvdiag{C}{}\right)\nonumber \\
&-\chiinv{d}{d}\left(\chiinvdiag{A}{}-\chiinvdiag{B}{}-\chiinvdiag{C}{}\right)-2\chiinv{s}{s}\chiinvdiag{B}{}+\left(\chiinvdiag{A}{}-\chiinvdiag{B}{}+\chiinvdiag{C}{}\right)\chiinvdiag{B}{}\bigg\rbrace \nonumber  \\
&\Pi_{2}K\left(\chiinvdiag{A}{},\chiinvdiag{B}{},\chiinvdiag{C}{}\right)=n_uK\left(\chiinvdiag{A}{},\chiinvdiag{B}{},\chiinvdiag{C}{}\right)+n_q\nonumber\bigg\lbrace-2 \left[\chiinv{u}{u}+\frac{1}{3}\chiinv{e}{e}\right]\chiinvdiag{A}{}\nonumber \\
&+\chiinv{d}{d}\left(\chiinvdiag{A}{}-\chiinvdiag{B}{}+\chiinvdiag{C}{}\right)+\chiinv{s}{s}\left(\chiinvdiag{A}{}+\chiinvdiag{B}{}-\chiinvdiag{C}{}\right)-\left(\chiinvdiag{A}{}-\chiinvdiag{B}{}-\chiinvdiag{C}{}\right)\chiinvdiag{A}{}\bigg\rbrace \nonumber 
\end{align}
%
whereas the (inverse) relaxation times are
%
\begin{align}
2\tau_{\pm}^{-1}=\left(\chiinvdiag{A}{}\lambda_{1}+\chiinvdiag{B}{}\lambda_{2}+\chiinvdiag{C}{}\lambda_{3}\right)\pm\sqrt{\left(\chiinvdiag{A}{}\lambda_{1}+\chiinvdiag{B}{}\lambda_{2}+\chiinvdiag{C}{}\lambda_{3}\right)^{2}+Q\left(\lambda_{1},\lambda_{2},\lambda_{3}\right)K\left(\chiinvdiag{A}{},\chiinvdiag{B}{},\chiinvdiag{C}{}\right)}.
\end{align}
%
Lastly,  the coefficients $\zeta,\xi$ are given by 
%
\begin{align}
&\zeta Q\left(\lambda_{1},\lambda_{2},\lambda_{3}\right)K\left(\chi_{A}^{-1},\chi_{B}^{-1},\chi_{C}^{-1}\right)=\left[\left(n_{u}+n_{s}\right)\lambda_{3}\left(\Pi_{1}+\Pi_{2}\right)+n_{s}\lambda_{2}\Pi_{1}+n_{u}\lambda_{1}\Pi_{2}\right]K\left(\chi_{A}^{-1},\chi_{B}^{-1},\chi_{C}^{-1}\right)\nonumber \\
&+\Bigg\{ -\left(\chi_{A}^{-1}-\chi_{B}^{-1}\right)^{2}+\left(\chi_{A}^{-1}+\chi_{B}^{-1}\right)\chi_{C}^{-1}-\left(\chi_{A}^{-1}-\chi_{B}^{-1}+\chi_{C}^{-1}\right)\left[\left(\chi_{u}^{\ u}\right)^{-1}+\frac{1}{3}\left(\chi_{e}^{\ e}\right)^{-1}\right]\nonumber \\
&+2\chi_{C}^{-1}\left(\chi_{d}^{\ d}\right)^{-1}+\left(\chi_{A}^{-1}-\chi_{B}^{-1}-\chi_{C}^{-1}\right)\left(\chi_{s}^{\ s}\right)^{-1}\Bigg\} n_q\lambda_{3}\left(\Pi_{1}+\Pi_{2}\right)\nonumber \\
&+\Bigg\{ \left(\chi_{A}^{-1}-\chi_{B}^{-1}+\chi_{C}^{-1}\right)\chi_{B}^{-1}+\left(\chi_{A}^{-1}+\chi_{B}^{-1}-\chi_{C}^{-1}\right)\left[\left(\chi_{u}^{\ u}\right)^{-1}+\frac{1}{3}\left(\chi_{e}^{\ e}\right)^{-1}\right]\nonumber \\
&-\left(\chi_{A}^{-1}-\chi_{B}^{-1}-\chi_{C}^{-1}\right)\left(\chi_{d}^{\ d}\right)^{-1}-2\chi_{B}^{-1}\left(\chi_{s}^{\ s}\right)^{-1}\Bigg\} n_q\lambda_{2}\Pi_{1}\nonumber \\
&+\Bigg\{- \left(\chi_{A}^{-1}-\chi_{B}^{-1}-\chi_{C}^{-1}\right)\chi_{A}^{-1}-2\chi_{A}^{-1}\left[\left(\chi_{u}^{\ u}\right)^{-1}+\frac{1}{3}\left(\chi_{e}^{\ e}\right)^{-1}\right]\nonumber \\
&+\left(\chi_{A}^{-1}-\chi_{B}^{-1}+\chi_{C}^{-1}\right)\left(\chi_{d}^{\ d}\right)^{-1}+\left(\chi_{A}^{-1}+\chi_{B}^{-1}-\chi_{C}^{-1}\right)\left(\chi_{s}^{\ s}\right)^{-1}\Bigg\} n_q\lambda_{1}\Pi_{2},\nonumber \\
&\frac{\xi}{2}Q\left(\lambda_{1},\lambda_{2},\lambda_{3}\right)K\left(\chiinvdiag{A}{},\chiinvdiag{B}{},\chiinvdiag{C}{}\right)=\left\{ n_q\left[\chiinv{d}{d}-\chiinv{s}{s}\right]+\left(n_d-n_s\right)\chiinvdiag{A}{}-n_{u}\left(\chiinvdiag{B}{}-\chiinvdiag{C}{}\right)\right\} \Pi_{1} \nonumber \\
&+\left\{ n_q\left[\chiinv{d}{d}-\chiinv{u}{u}-\frac{1}{3}\chiinv{e}{e}\right]+\left(n_d-n_u\right)\chiinvdiag{B}{}-n_{s}\left(\chiinvdiag{A}{}-\chiinvdiag{C}{}\right)\right\} \Pi_{2},
\end{align}
%
from which one may evaluate $\zeta_{\pm}$ using 
Eq.~(\ref{eq:zetapm}).
