\section{Imagination Algorithm}
\label{imaginationalgo}
\begin{algorithm}[H]
\caption{Imagined Rollouts with Teammate Prediction}
\label{alg:multiagent_imagination}
\DontPrintSemicolon
\KwIn{Agents $\mathcal{N}$, world model $WM$, context observations/actions, context length $L$, batch size $B$, imagination rollout length $H$}
\KwOut{Imagined latent states, actions, rewards, terminations, teammate actions, action masks}

Initialize per-agent rollout buffers for latent states, actions, rewards, terminations, teammate actions, action masks (optional)\;

\tcp{Use Context as starting point for imagination rollout}
Encode context observations into latent state sequence $z_{0:L}$\; 
\For{$t = 0$ \KwTo $L-1$}{
    Predict next latent state, hidden state, reward, and termination using:\;
    \quad $(\hat{z}_{t+1}, h_{t+1}, \hat{r}_t, \hat{c}_t) \gets WM(z_t, a_t)$\;
}
Store $z_L$ and hidden state $h_L$ in respective buffers\;
\tcp{Begin imagination rollout}
\For{$t = 0$ \KwTo $H-1$}{ 
    \ForEach{agent $n_i \in \mathcal{N}$}{
        Get latent $z_t^{(i)}$ and hidden $h_t^{(i)}$ slice for agent batch\;
        Compute predicted teammate action probabilities: $\hat{p}_{i, t}^{(a)} \gets \text{TeammatePredictor}(z_t^{(i)})$\;


        \uIf{action masking enabled}{
            Predict action mask $\hat{m}_t \gets \text{MaskPredictor}(z_t^{(i)})$\;
            Sample action $a_{i,t} \sim \pi(z_t^{(i)}, h_t^{(i)}, \hat{p}_{i, t}^{(a)}, \hat{m}_t)$\;
            Store $\hat{m}_t$ in respective buffer
        }\Else{
            Sample action $a_{i,t} \sim \pi(z_t^{(i)}, h_t^{(i)}, \hat{p}_{i, t}^{(a)})$\;
        }

        Store $a_{i,t}$ and $\hat{p}_{i, t}^{(a)}$ in respective buffers\;
    }
    Predict next $(\hat{z}_{t+1}, h_{t+1}, \hat{r}_t, \hat{c}_t) \gets WM(z_t, a_t)$\;
    Store results in respective buffers\;
}

Return buffers for latent states, actions, rewards, terminations, teammate actions, and (optional) masks\;

\end{algorithm}
\section{Training Algorithm}
\label{matwmalgo}
\begin{algorithm}[H]
\caption{Joint Training of World Model and Agents in MATWM}
\label{alg:matwm}
\DontPrintSemicolon
\KwIn{Environment $\mathcal{E}$, world model $WM$, actor-critic agents $\{\pi_i\}_{i=1}^{N}$, replay buffers $\{RB_i\}_{i=1}^{N}$}
\KwParams{Total steps $T$, train intervals $t_{WM}, t_{\pi}$, batch sizes, context lengths}

Initialize environment $\mathcal{E}$ and per-agent buffers, context queues\;
\For{$t = 1$ \KwTo $T$}{
    \ForEach{agent $i$}{
        \eIf{$RB_i$ is ready}{
            Encode recent observations $\mathcal{O}_{i}$ into latent $z_i$ using $WM$\;
            Predict teammate behavior using $WM$'s predictor\;
            Sample action $a_i \sim \pi_i(z_i, \hat{a}_{-i})$\;
        }{
            Sample $a_i$ randomly or with action masking\;
        }
    }
    Step environment $\mathcal{E}$ with $\{a_i\}$, collect next obs, rewards, dones\;
    Store transitions in each $RB_i$ with teammate action info\;

    \If{episode terminates}{
        Reset environment and context buffers\;
    }

    \If{$t \bmod t_{WM} = 0$ and all $RB_i$ ready}{
        Sample batches from all $RB_i$\;
        Train $WM$ on combined batch (obs, actions, rewards, terminations, teammate actions)\;
    }

    \If{$t \bmod t_{\pi} = 0$ and all $RB_i$ ready}{
        Use $WM$ to imagine trajectories for each agent\;
        Train each policy $\pi_i$ using imagined data (rewards, terminations, predicted teammates)\;
    }

}
\end{algorithm}

