\title{Inflaton perturbations through an Ultra-Slow Roll transition and Hamilton-Jacobi attractors}


\author{Tomislav Prokopec$^a$ and Gerasimos Rigopoulos$^b$}
\affiliation{$^a$  Institute for Theoretical Physics, Spinoza Institute \& {\rm EMME}$\Phi$, Utrecht University, Princetonplein 5, 3584 CC Utrecht, The Netherlands \\
