	\,,\quad
	\label{appx: Hubble parameter 2}
\end{eqnarray}
%
which in the limit when $\alpha\rightarrow -\infty$ reduces to,
%
\begin{eqnarray}
	\ln\left(\frac{H(\alpha)}{H_0}\right)
	&=& \frac{\epsilon_0}{2\eta_0}
	\times\bigg[\Gamma\left(1\!+\!\frac{\eta_0}{3}\right)
	\Gamma\left(1\!-\frac{\eta_0}{3}\right)\!-\!{\rm e}^{2\eta_0\alpha} 
	\bigg]
	\,,\quad
	\label{appx: Hubble parameter 3}
\end{eqnarray}
% 
such that at early times ($\alpha\rightarrow -\infty$)
the expansion rate asymptotes to a constant 
(when $\eta_0>0$), or grows exponentially with $\alpha$ (when $\eta_0<0$). These functions are plotted in Fig.~\ref{fig:USR-evol}.


In the limit $\eta_0 \rightarrow 0$ one obtains a simpler model in which the system transits from 
a {\it constant roll} $\epsilon\simeq \epsilon_0 ={\rm const.}$ into an USR phase:
\begin{equation}
	\epsilon_1(\alpha) = \frac{\epsilon_0}{1+{\rm e}^{6\alpha}}
	\,,\qquad 
	\epsilon_2(\alpha) = -\frac{6}{1+{\rm e}^{-6\alpha}}
	\,,\qquad
	\epsilon_3(\alpha) = \frac{6}{1+{\rm e}^{6\alpha}}
	\,,
	\qquad 
\label{simple model USR}
\end{equation}
in which $\epsilon_1$ rapidly decays and the Hubble rate is 
\begin{equation}
H(\alpha) = H_0\left(1+{\rm e}^{-6\alpha}\right)^\frac{\epsilon_0}{6}
\,.\quad
\end{equation}
%
This limiting case is more like our earlier study of a slide on the  $V=V_0$ potential where the system enters a pure de Sitter phase. In this paper we will focus on the $\eta_0 < 0$ case for our numerical example, taking $\epsilon_0 = 0.03$ and $\eta_0 = -0.02$. 

Given $H(\alpha)$ one can explicitly compute a potential function $V(\phi)$ that would give rise to it. For the simple model~(\ref{simple model USR}) we have,
%
\begin{equation}
\partial_\alpha\phi = \sqrt{2\epsilon} \;\Longrightarrow\; 
  \phi(\alpha) = \phi_0 - \frac{\sqrt{2\epsilon_0}}{3}{\rm Arcsinh}\left({\rm e}^{-3\alpha}\right)
\,,\qquad
\label{simple model: phi of alpha}
\end{equation}
%
from where,
%
\begin{equation}
V(\phi) = (3-\epsilon)H^2 = H_0^2
   \left[3-\epsilon_0\tanh^2\left(\frac{3(\phi-\phi_0)}{\sqrt{2\epsilon_0}}\right)\right]
    \left[\cosh\left(\frac{3(\phi-\phi_0)}{\sqrt{2\epsilon_0}}\right)\right]^\frac{2\epsilon_0}{3}
\,.\qquad
\label{simple model: V of phi}
\end{equation}
%
Inflation in this model proceeds from a large field value $\phi\ll \phi_0$. During the early stages of inflation the inflaton rolls in a slow-roll attractor, reaching eventually an USR regime, in which the field approaches $\phi_0$ as $\alpha\rightarrow\infty$. To get a graceful exit in this model, one would have to glue another potential at $\phi\approx \phi_0$, which would provide a second period of inflation and/or an exit from inflation. This model closely resembles the USR model discussed in \cite{Prokopec:2019srf},
where the conveyor belt concept was introduced.

There is no simple way of constructing the inflationary potential for the more complicated, but more realistic model in Eqs.~(\ref{appx: SR to USR})--(\ref{appx: eps2 and eps3}).
Nevertheless, one can construct a parametric form of the potential.
Integrating $\partial_\alpha\phi = \sqrt{2\epsilon}$
gives ({\it cf.} Eq.~(\ref{simple model: phi of alpha})),~\footnote{
By recalling that, 
%
\begin{equation}
{}_2F_1\left(\frac{1}{2},\frac{1}{2};\frac{3}{2};
	-{\rm e}^{-6\alpha}\right) = {\rm e}^{3\alpha}{\rm Arcsinh}\Big({\rm e}^{-3\alpha}\Big)
\,,\qquad
\nonumber
\end{equation}
% 
one can easily see that,
in the limit when $\eta_0\rightarrow 0$, Eq.~(\ref{realistic model: phi of alpha}) reduces to 
Eq.~(\ref{simple model: phi of alpha}).
}
%
\begin{equation} 
  \phi(\alpha) = \phi_0 - \frac{\sqrt{2\epsilon_0}}{3-\eta_0}
  \!\times\!{\rm e}^{-(3-\eta_0)\alpha}{}_2F_1\left(\frac{1}{2},\frac{1}{2}-\frac{\eta_0}{6};\frac{3}{2}-\frac{\eta_0}{6};
	-{\rm e}^{-6\alpha}\right)
\,,\qquad
\label{realistic model: phi of alpha}
\end{equation}
%
and the potential $V(\phi)$ can be also written as a function of $\alpha$
 ({\it cf.} Eq.~(\ref{simple model: V of phi})),
%
\begin{equation}
V(\phi) = \big(3-\epsilon(\alpha)\big)H^2(\alpha) 
\,,\qquad
\label{realistic model: V of alpha}
\end{equation}
%
where $\epsilon(\alpha)$ and $H^2(\alpha)$ are given in Eqs.~(\ref{appx: SR to USR})
and~(\ref{appx: Hubble parameter})--(\ref{appx: Hubble parameter 2}), respectively.
The potentials~(\ref{simple model: V of phi}) 
and~(\ref{realistic model: phi of alpha})--(\ref{realistic model: V of alpha}) are plotted in Figure~\ref{fig:Potential}.
The model~\eqref{appx: SR to USR} corresponds to a potential with a slow-roll supporting part leading to a shallow minimum
visible in Figure~\ref{fig:Potential}. The relevant 
part of the potential around $\phi=\phi_0$ is,
%
\begin{equation} 
    V(\phi) \simeq 3H_0^2\left[1
    +\frac{(3\!-\!\eta_0)\eta_0}{6}\big(\phi\!-\!\phi_0)^2
    +\left(\frac{9(3\!-\!\epsilon_0)}{8\epsilon_0}
    +\mathcal{O}(\eta_0)\right)
        \big(\phi\!-\!\phi_0)^4\right]
\,,
\label{potential around minimum}
\end{equation}
%
from where we see that for $\eta_0<0$ 
the potential exhibits a double minimum at 
$\phi=\phi_0 \pm\sqrt{-\frac{2\epsilon_0\eta_0(3\!-\!\eta_0)}{27(3\!-\!\epsilon_0)}}$ 
%$\phi=\phi_0 \pm\sqrt{-[2\epsilon_0\eta_0(3\!-\!\eta_0)]/[27(3\!-%\!\epsilon_0)}]$
(when $\eta_0>0$ the minimum remains at $\phi=\phi_0$). This means that, during the USR, the field climbs a gentle hill while slowing down as the spacetime approaches de Sitter, asymptotically approaching the shallow peak at $\phi=\phi_0$ as $\alpha\rightarrow \infty$.  

