\section{Commonly used geometric slow roll parameters}\label{Appendix A}

Here we discuss two commonly used sets of geometric slow-roll 
parameters. Both share the principal slow roll parameter $\epsilon$,
which in (HJ) attractor models of inflation (which is what 
we assume here) can be expressed in terms of the Hamiltonian constrint,
%
\begin{equation}
\epsilon(\phi) = \frac{\pi^2}{2} 
      = 2\left(\frac{{\rm d}\ln(H[\phi)]}{{\rm d}\alpha}\right)^2
        = 3 - \frac{V(\phi)}{H^2(\phi)}
\,,
\label{appx: principal eps}
\end{equation}
% 
where $\alpha = \ln(a)$ is a time variable parametrizing e-folding
 of inflation (in an attractor regime of inflation, there is no reason to introduce a special time parameter, as it can be characterized by the inflaton $\phi$) From~(\ref{appx: principal eps}) we see that 
 $\epsilon$ maiximizes at 3 in kination, in which $V=0$, and 
the de Sitter space is obtained when $V=3H^2$, which are familiar limits. 

The first set is defined in terms of the derivatives of the principal slow 
roll parameter, 
%
\begin{equation}
\epsilon_{i+1} = \frac{{\rm d}\ln[\epsilon_i]}{{\rm d}\alpha}
\,,\quad (i=1,2,\cdots)\quad {\rm and} \;\; \epsilon_1\equiv \epsilon
\,.
\label{first set of slow roll}
\end{equation}
%
The second set, used mostly in this work, is defined by
%
\begin{equation}
\epsilon = \epsilon_1
\,,\qquad 
\eta = -3-\frac{1}{\pi}\frac{V'(\phi)}{H^2(\phi)}
\,,
\label{appx: second set of slow roll}
\end{equation}
% 
where $\pi = {\rm d}\phi/{\rm d}\alpha = -\sqrt{2\epsilon}$.

Upon taking a derivative of~(\ref{appx: principal eps})
with respect to $\alpha$, and taking 
into account that $\epsilon_1=\epsilon$, one obtains, 
%
\begin{equation}
\epsilon_2 = 2(\epsilon+\eta) \;\; \;\leftrightarrow \; \;\;
     \eta = -\epsilon_1 + \frac{\epsilon_2}{2}
\,.
\label{relating slow roll parameters 2}
\end{equation}
% 
It is also worth mentioning the next order in slow roll, 
%
\begin{equation}
\epsilon_2 = \frac{\epsilon'}{\epsilon}
\,,\quad \epsilon_3 = \frac{(\epsilon+\eta)'}{\epsilon+\eta}
\;\;\;\leftrightarrow \; \;\;
\epsilon' = \epsilon_1\epsilon_2
\,,\quad
(\epsilon+\eta)' = \frac12 \epsilon_2\epsilon_3
\,.
\label{relating slow roll parameters 3}
\end{equation}
% 

Classical perturbations obey second order differential equations,
which at the linear order in perturbation is known 
as the Mukhanov equation,
%
\begin{equation}
\Big(\partial_\eta^2 + k^2 - \frac{z''}{z}\Big)Q(\eta,\vec k) = 0
\,,
\label{Mukhanov eq2}
\end{equation}
% 
where $\eta$ is conformal time ($a{\rm d}\eta=N{\rm d}t$), $z'=\partial_\eta z$, 
$Q = a\delta \phi-z\psi$ 
is the gauge invariant Mukhanov-Sasaki field and 
$z = \sqrt{2\epsilon}a$ (in terms of which the curvature perturbation is given by 
${\cal R}=-Q/z$).
To convert this equation to the formalism used here, first notice 
that the times are related as, $a(\eta) {\rm d}\eta = N{\rm d}t$,
from which one infers, 
$\partial_\eta = \frac{a}{N}\partial_t = H{\rm e}^\alpha\partial_\alpha$.
This then implies for $z=\sqrt{2\epsilon}a$, 
%
\begin{equation}
z'(\eta) = aH\left(1+\frac{\epsilon}{2}\right)z
\label{appx: z prime}
\end{equation}
%
and 
%
\begin{eqnarray}
\frac{z''}{z} &=& (aH)^2\left[2-\epsilon_1+\frac32\epsilon_2
-\frac12\epsilon_1\epsilon_2
+\frac14\epsilon_2^2
+\frac12\epsilon_2\epsilon_3\right]\\
&=& (aH)^2\left[2+2\epsilon+3\eta
+\frac12\epsilon' + \eta'
+(\epsilon+\eta)^2\right]
\,.
\label{appx: z'' over z}
\end{eqnarray}
% 
Inseting these results and 
%
\begin{equation}
\partial_\eta^2 
 = (Ha)^2\big[(1-\epsilon)\partial_\alpha +\partial_\alpha^2\big]
 \,,
\label{appx: conversion d eta}
\end{equation}
%
into 
Eq.~(\ref{Mukhanov eq}) one obtains, 
%
\begin{eqnarray}
\left\{\partial_\alpha^2 + (1-\epsilon_1)\partial_\alpha+ \frac{k^2}{(aH)^2}
 - \left[2-\epsilon_1+\frac32\epsilon_2
-\frac12\epsilon_1\epsilon_2
+\frac14\epsilon_2^2
+\frac12\epsilon_2\epsilon_3\right]
\right\}Q(\alpha;\vec k) &=& 0
\qquad
\label{Mukhanov eq 2}\\
\left\{\partial_\alpha^2 + (1-\epsilon)\partial_\alpha+ \frac{k^2}{(aH)^2}
 -\left[2+2\epsilon+3\eta
+\frac12\epsilon' + \eta'
+(\epsilon+\eta)^2\right]
\right\}Q(\alpha;\vec k) &=& 0
\,.\qquad\;
\label{Mukhanov eq 3}
\end{eqnarray}
% 
For the (gauge invariant) field perturbation, ${\delta\Phi}=Q/a$, one gets,  
%
\begin{eqnarray}
\left\{\partial_\alpha^2 + (3-\epsilon_1)\partial_\alpha+ \frac{k^2}{(aH)^2}
 -\frac32\epsilon_2
+\frac12\epsilon_1\epsilon_2
-\frac14\epsilon_2^2
-\frac12\epsilon_2\epsilon_3
\right\}{\delta\Phi}(\alpha;\vec k) &=& 0
\qquad
\label{Field eq 12}\\
\left\{\partial_\alpha^2 + (3-\epsilon)\partial_\alpha+ \frac{k^2}{(aH)^2}
 -3(\epsilon+\eta)
-\frac12\epsilon' - \eta'
-(\epsilon+\eta)^2
\right\}{\delta\Phi}(\alpha;\vec k) &=& 0
\,.
\label{Field eq 2}
\end{eqnarray}
% 

