\section{PROOFS}
\label{appendix:proofs}

As expectation is preserved, the distribution of synthetic categorical variable is also preserved, by following a simple theorem.

\begin{theorem}[Category-Preserving Mixup]
    \label{thm:app:category:preserve}
    \leavevmode For any synthetic variable $\tilde \categZorC$ generated from $\categZorC$ in \eqref{eq:mixup:z}, the distribution is preserved. That is $\Pr\big\{ \categZorC= \categZorCsmall \big\} = \Pr\big\{\tilde{\categZorC}= \categZorCsmall \big\}$ for any $\categZorCsmall$.
\end{theorem}
\begin{proof}
It can be directly proved by the definition in \eqref{eq:mixup:z}, as follow.
\begin{align*}
     \Pr\big\{\tilde{\categZorC}= z\big\}
     &=
     \Pr\big\{ \categZorC_i= \categZorCsmall\big\}\Pr\big\{ W^\categZorC\geq \cutpoint\big\} 
     + \Pr\big\{ \categZorC_j= \categZorCsmall\big\}\Pr\big\{ W^\categZorC < \cutpoint\big\}
     \\ &=
     \Pr\big\{ \categZorC= \categZorCsmall\big\} \big( \Pr\big\{ W^\categZorC\geq \cutpoint\big\} + \Pr\big\{ W^\categZorC < \cutpoint\big\} \big)
     \\ &=
     \Pr\big\{ \categZorC= \categZorCsmall\big\}
\end{align*}
\end{proof}


\subsection{Regression Coefficients Are Preserved}
\label{appendix:proofs:regcoef}

\begin{theorem}
    \label{thm:app:regression}
    For any synthetic pair  $(\tilde{X}, \tilde{Y})$ generated from $({X}, {Y})$ using the standard mixup scheme, the regression coefficients are preserved. I.e.,
    \begin{equation}
    \argmin_{\beta_0, \beta_1} \E\big\| Y -\beta_0 -\beta_1 X \big\|_2^2 = \argmin_{\beta_0, \beta_1} \E\big\| \Tilde{Y} -\beta_0 -\beta_1 \Tilde{X} \big\|_2^2 \nonumber %
    .
    \end{equation}    
\end{theorem}
\begin{proof}
    It is well known that $\hat{\beta}_0 = \E\big[Y] -\hat{\beta}_1  \E\big[ X \big]$ and $\hat{\beta}_1=\Corr \big[ X,Y \big]$ from the convex optimization:
    \begin{align*}
        0
        &=
        \frac{\partial}{\partial\beta_0}\E\big\| Y -\beta_0 -\beta_1 X\big\|_2^2 \bigg|_{(\beta_0, \beta_1)=(\hat{\beta}_0,\hat{\beta}_1)}
        \\ &=
        2\hat{\beta}_0 - 2 \E\big[Y\big] -\hat{\beta}_1 \E\big[ X \big],
        \\
        0
        &=
        \frac{\partial}{\partial\beta_1}\E\big\| Y -\beta_0 -\beta_1 X \big\|_2^2 \bigg|_{(\beta_0, \beta_1)=(\hat{\beta}_0,\hat{\beta}_1)}
        \\
        &=
        2\E\big[X^2\big]\hat{\beta}_1 -2 \E \big[ X(Y-\hat{\beta}_0) \big]
        \\
        &=
        2\E\big[(X-\E\big[ X \big])^2\big]\hat{\beta}_1 -2 \E \big[ (X-\E\big[X] ) (Y-\E\big[Y] ) \big].
    \end{align*}
    By Corollary~\ref{thm:app:corr}, the correlation is preserved under the standard mixup scheme. Moreover, expectation is always preserved.  Therefore,
    \begin{align*}
        \argmin_{\beta_0, \beta_1} \E\big\| Y -\beta_0 -\beta_1 X \big\|_2^2
        &= \big(\E\big[Y] -\Corr\big[X, Y\big]  \E\big[ X \big], \; \Corr\big[X, Y\big]\big)
        \\
        &= \big(\E\big[\Tilde{X}\big] - \Corr\big[\Tilde{X}, \Tilde{Y}\big]  \E\big[ \Tilde{X} \big], \; \Corr\big[\Tilde{X}, \Tilde{Y}\big]\big)
        \\
        &= \argmin_{\beta_0, \beta_1} \E\big\| \Tilde{Y} -\beta_0 -\beta_1 \Tilde{X} \big\|_2^2.
    \end{align*}
    This can be easily generalized to multiple linear regression. For simplicity, assume that the variables are centered. Define $\mathbf{X}\in\mathbb{R}^{n\times p}$, $\mathbf{Y}\in\mathbb{R}^{n\times 1}$, and  $\beta\in\mathbb{R}^{p\times 1}$ where $\hat{\mathbf{\beta}} =
    \argmin_\mathbf{\beta} \E\big\| \mathbf{Y} - \mathbf{X} \mathbf{\beta} \big\|_2^2$. It is well known that $\hat{\mathbf{\beta}} = (\mathbf{X}^\top \mathbf{X})^{-1} \mathbf{X}^\top \mathbf{Y}$. Then, the coefficients are preserved as below,
    \begin{align}
    \hat{\mathbf{\beta}} \nonumber
    &= \nonumber
    (\mathbf{X}^\top \mathbf{X})^{-1} \mathbf{X}^\top \mathbf{Y}
    \\ 
    &= \nonumber
    \big( (\mathbf{X}-\E[\mathbf{X}])^\top (\mathbf{X}-\E[\mathbf{X}]) \big)^{-1}
    \cdot (\mathbf{X}-\E[\mathbf{X}])^\top (\mathbf{Y}-\E[\mathbf{Y}])
    \\ 
    &=
    \bigg( \big( 1 + 2\E\big[ \big(W^X\big)^2 -W^X \big] \big) (\mathbf{X}-\E[\mathbf{X}])^\top (\mathbf{X}-\E[\mathbf{X}]) \bigg)^{-1}
    % \\ &\quad
    \cdot \big( 1 + 2\E\big[ \big(W^X\big)^2 -W^X \big] \big) (\mathbf{X}-\E[\mathbf{X}])^\top (\mathbf{Y}-\E[\mathbf{Y}])
    \label{eq:regression:proof}
    \\ 
    &= \nonumber
    (\Tilde{\mathbf{X}}^\top \Tilde{\mathbf{X}})^{-1} \Tilde{\mathbf{X}}^\top \Tilde{\mathbf{Y}}
    \end{align}
    where the equality in \eqref{eq:regression:proof} holds from Corollary~\ref{thm:app:corr}. These results can be easily extended to the non-centered case when an intercept term is included in the regression, because mixup always preserves the expectation.
\end{proof}


\subsection{Proofs for Sec.~\ref{sec:properties}}
\label{appendix:proof:sec2}

\begin{lemma}[Variance]
\label{thm:app:var}
\leavevmode For any synthetic $\tilde X$ generated %by the general-weight mixup scheme 
from $X$ in (\ref{eq:mixup:x}):
\begin{enumerate}
    \item  $\Var\big[\tilde{X}\big] = \Var\big[X\big]$, if and only if the first and second moments of mixup weight are equal. That is
\begin{equation}
    % \label{eq:necessary:var}
    \E\big[\big(W^X\big)^2\big] = \E\big[W^X \big].
\end{equation}

    \item $\Var\big[\tilde{X}\big] <  \Var\big[X\big]$, 
     if and only if $\E\big[\big(W^X\big)^2\big] < \E\big[W^X \big]$.

    \item $\Var\big[\tilde{X}\big] > \Var\big[X\big]$.
    if and only if $\E\big[\big(W^X\big)^2\big] > \E\big[W^X \big]$.
\end{enumerate}
\end{lemma}

\begin{proof}
    Since $\E\big[\tilde{X}\big]=\E\big[X\big]$, the variance of synthetic data $\Var\big[\tilde{X}\big]$ is determined as
\begin{align}
    \Var\big[\tilde{X}\big]
    &= \nonumber
    \E\big[ W^X X_i + \big(1-W^X\big) X_j \big]^2 - \E\big[X\big]^2
    \\ &= \nonumber
    \E\big[\big(W^X\big)^2\big]\E\big[X_i^2\big]
    + \E\big[\big(1-W^X\big)^2\big]\E\big[X_j^2\big]
    % \\ & \quad \nonumber
    + 2\E\big[W^X\big(1-W^X\big)\big]\E\big[X_i\big]\E\big[X_j\big]
    - \E\big[X\big]^2
    \\ &= \nonumber
    \E\big[\big(W^X\big)^2 + \big(1-W^X\big)^2\big](\Var\big[X\big]+\E\big[X\big]^2)
    % \\ & \quad \nonumber
    + 2\E\big[W^X\big(1-W^X\big)\big]\E\big[X\big]^2
    - \E\big[X\big]^2
    \\&= 
    \label{eq:var:condition:full:line:proof}
    \Var\big[X\big]+
    2 \E\big[\big(W^X\big)^2 - W^X \big] \Var\big[X\big].
\end{align}
Therefore, $\Var\big[\tilde{X}\big]=\Var\big[X\big]$ holds if and only if $\E\Big[\big(W^X\big)^2 - W^X \Big]=0$.
The cases of variance reduction and inflation can be trivially shown using a similar approach.
\end{proof}


\begin{theorem}[Covariance]
\label{thm:app:cov}
\leavevmode For any synthetic pair $(\tilde{X}, \tilde{Y})$ generated from $({X}, {Y})$ using the general-weight mixup in \eqref{eq:mixup:x} and \eqref{eq:mixup:y}:
\begin{enumerate}
    \item  $\Cov\big[\tilde{X}, \tilde{Y}\big] = \Cov\big[X, Y\big]$, if and only if
    \begin{equation}
        % \label{eq:necessary:cov}
        \E\big[ W^X W^Y \big] = \frac{1}{2} \big(\E\big[ W^X  \big]+ \E\big[W^Y \big]\big).
    \end{equation}

    \item $\Cov\big[\tilde{X}, \tilde{Y}\big] < \Cov\big[X, Y\big]$,
     if and only if $\E\big[ W^X W^Y \big] < \frac{1}{2} \big(\E\big[ W^X  \big]+ \E\big[W^Y \big]\big)$.

    \item $\Cov\big[\tilde{X}, \tilde{Y}\big] > \Cov\big[X, Y\big]$, 
 if and only if $\E\big[ W^X W^Y \big] > \frac{1}{2} \big(\E\big[ W^X  \big]+ \E\big[W^Y \big]\big)$.
\end{enumerate}
\end{theorem}
\begin{proof}
    Since $\E\big[\tilde{X}\big]=\E\big[X\big]$ and $\E\big[\tilde{Y}\big]=\E\big[Y\big]$, the covariance of synthetic data $\Cov\big[\tilde{X}, \tilde{Y}\big]$ is determined as
\begin{align}
    \Cov\big[\tilde{X}, \tilde{Y}\big] 
    &= \nonumber
    \E\big[\tilde{X}\tilde{Y}\big] -\E\big[\tilde{X}\big]\E\big[\tilde{Y}\big]
    \\&= \nonumber
    \E\big[
        W^X W^Y X_i Y_i
        + (1-W^X) W^Y X_j Y_i
    \big]
    % \\ & \qquad \nonumber
    % \cdot
    \E\big[
        W^X (1-W^Y) X_i Y_j
        + (1-W^X) (1-W^Y) X_j Y_j
    \big]
    \\& \quad \nonumber
    - \E\big[X\big]\E\big[Y\big]   
    \\&= \nonumber
    \E\big[
        2W^X W^Y + 1-W^X -W^Y 
    \big] \E\big[ X_i Y_i \big]
    % \\ & \quad \nonumber
    -
    \E\big[
         2W^X W^Y
         + 1
        -W^X -W^Y
    \big] \E\big[X\big]\E\big[Y\big]    
    \\&= \nonumber
     \E\big[
        2W^X W^Y + 1-W^X -W^Y 
    \big]
    \Cov\big[X, Y\big]   
    \\&= \label{eq:cov:condition:full:line}
     \Cov\big[X, Y\big] + \E\big[
        2W^X W^Y -W^X -W^Y 
    \big]
    \Cov\big[X, Y\big].
\end{align}
Therefore, $\Cov\big[\tilde{X}, \tilde{Y}\big] = \Cov\big[X, Y\big]$ if and only if $\E\big[ 2W^X W^Y -W^X -W^Y \big] = 0$, which is equal to Eq.~\eqref{eq:necessary:cov}.
The cases of covariance reduction and inflation can be trivially shown using a similar approach.
\end{proof}


\clearpage
\begin{corollary}[Correlation]
\label{thm:app:corr}
     For any synthetic pair $(\tilde{X}, \tilde{Y})$ generated from $(X,Y)$ using the standard mixup scheme,
     we have
    \begin{equation}
    \nonumber
    \Corr\big[\tilde{X}, \tilde{Y}\big] = \Corr\big[X, Y\big].
    \end{equation}
\end{corollary}

\begin{proof}
From \eqref{eq:cov:condition:full:line} in Theorem~\ref{thm:app:cov} with using the standard mixup scheme, i.e., $W^X_k=W^Y_k$ for all $k\in[m]$, the covariance of synthetic data $\Cov\big[\tilde{X}, \tilde{Y}\big]$ is determined as
\begin{align*}
    \Cov\big[\tilde{X}, \tilde{Y}\big] 
    &=
    \Cov\big[X, Y\big] + \E\big[2W^X W^Y -W^X -W^Y\big]
    \Cov\big[X, Y\big] 
    \\ &=
    \Cov\big[X, Y\big] + 2\E\big[
        \big(W^X\big)^2 -W^X 
    \big]
    \Cov\big[X, Y\big]  
    \\ &=
     \big( 1 + 2\E\big[
        \big(W^X\big)^2 -W^X 
    \big] \big)
    \Cov\big[X, Y\big].
\end{align*}
As a result, using \eqref{eq:var:condition:full:line:proof} in Lemma~\ref{thm:app:var}, the correlation of synthetic data is preserved as 
\begin{align*}
    \Corr\big[\tilde{X}, \tilde{Y}\big]
    &=
    \frac{\Cov\big[\tilde{X}, \tilde{Y}\big]}{\sqrt{\Var\big[\tilde{X}\big] \Var\big[ \tilde{Y}\big]}}
    \\ &=
    \frac{
    \big( 1 + 2\E\big[ \big(W^X\big)^2 -W^X \big] \big)
    \Cov\big[X, Y\big]
    }{
    \sqrt{
    \big( 1 + 2\E\big[ \big(W^X\big)^2 -W^X \big] \big)^2
    \Var\big[X\big] \Var\big[ Y\big]
    }
    }
    \\ &=
    \frac{
    \big( 1 + 2\E\big[ \big(W^X\big)^2 -W^X \big] \big)
    \Cov\big[X, Y\big]
    }{
     \big| 1 + 2\E\big[ \big(W^X\big)^2 -W^X \big] \big|
    \sqrt{   
    \Var\big[X\big] \Var\big[ Y\big]
    }
    }
    \\ &=
     \Corr\big[X, Y\big].
\end{align*}
Note that the last equality comes from the fact that
\begin{align*}
    1 + 2\E\big[ \big(W^X\big)^2 -W^X \big]
    &=
    \E\big[ \big(W^X\big)^2 \big]
    + \E\big[ \big(W^X-1\big)^2 \big]
    % \\ &
    \geq 0.
\end{align*}
\end{proof}



\begin{theorem}[Conditional Mean]
\label{thm:app:con:mean} 
    For any synthetic pair  $(\tilde{X}, \tilde{\categZorC})$ generated from $({X}, {\categZorC})$ using the general-weight mixup, where $X$ is continuous and $\categZorC$ is categorical, the synthetic conditional mean $\E\big[\tilde{X} \big| \tilde{\categZorC}=\categZorCsmall \big]$ can be expressed as
    \begin{align}
        % \label{eq:thm:con:mean}
        \nonumber
        \E\big[\tilde{X} \big| \tilde{\categZorC}=\categZorCsmall \big] 
        &= (1-u\big(W^X, W^\categZorC,\cutpoint\big))\E\big[X \big| \categZorC=\categZorCsmall \big]
        + u\big(W^X, W^\categZorC,\cutpoint\big) \E\big[X \big],
    \end{align}
or, alternatively, 
       \begin{align}
        \E\big[\tilde{X} \big| \tilde{\categZorC}=\categZorCsmall \big] 
        &= \nonumber
        \big(1-u\big(W^X, W^\categZorC,\cutpoint\big) \Pr\{ \categZorC \neq \categZorCsmall\} \big)\E\big[X \big| \categZorC=\categZorCsmall \big] 
        + u\big(W^X, W^\categZorC,\cutpoint\big) \Pr\{ \categZorC \neq \categZorCsmall\} E[X|\categZorC \neq \categZorCsmall].    
    \end{align}
\end{theorem}


\begin{corollary}[Conditional Mean Gap]
\label{thm:app:con:mean:cor}
For any synthetic pair $(\tilde{X}, \tilde{\categZorC})$ generated from $({X}, {\categZorC})$ using the general-weight mixup, where $X$ is continuous and $\categZorC$ is categorical, the difference between the conditional mean  is given by
\begin{align}
% \label{eq:cond.mean.gap}
    \big|
    \E\big[\tilde{X} \big| \tilde{\categZorC}=\categZorCsmall \big]
    - \E\big[X \big| \categZorC=\categZorCsmall \big]
    \big|
    =
    \big| u\big(W^X, W^\categZorC,\cutpoint\big) \big|
    \cdot \Pr\{ \categZorC \neq \categZorCsmall\}
    \cdot
    \big|
    \E\big[X \big| \categZorC=\categZorCsmall \big]
    - \E\big[X \big| \categZorC \neq \categZorCsmall \big]
    \big| .
\end{align}
\end{corollary}
\begin{proof}[Proof of Theorem~\ref{thm:app:con:mean} and Corollary~\ref{thm:app:con:mean:cor}]
Let us define the sets $A_1 = \{\categZorC_i=\categZorCsmall, W^\categZorC \geq \cutpoint\}$ and $A_2 =\{\categZorC_j=\categZorCsmall, W^\categZorC < \cutpoint\}$, which disjointly divide the set $\big\{\tilde{\categZorC}=\categZorCsmall\big\} = A_1 \dot{\cup} A_2$. Then, $\Pr(A_1)= \Pr\{\categZorC_i=\categZorCsmall\} \Pr\{ W^\categZorC\geq \cutpoint\}$ and $\Pr(A_2)= \Pr\{\categZorC_j=\categZorCsmall\} \Pr\{ W^\categZorC < \cutpoint\}$.

To obtain $\E\big[\tilde{X} \big| \tilde{\categZorC}=\categZorCsmall \big] = \E\big[\tilde{X} \big| A_1 \cup A_2 \big]$, we first determine $\E\big[ \tilde{X}  \big| A_1 \big]$ and $\E\big[ \tilde{X}  \big| A_2 \big]$ as below:
\begin{align*}
    \E\big[ \tilde{X}  \big| A_1 \big]
    &=
    \E\big[ W^X X_i + (1-W^X) X_j \big| \{\categZorC_i=\categZorCsmall, W^\categZorC \geq \cutpoint\} \big]
    \\ &= 
    \E\big[ W^X \big| W^\categZorC \geq \cutpoint \big]
    \E\big[ X_i \big| \categZorC_i=\categZorCsmall \big]
    + \big( 1-\E\big[ W^X \big| W^\categZorC \geq \cutpoint \big] \big)
    \E\big[ X_j \big]
    \\ &= 
    \E\big[ W^X \big| W^\categZorC \geq \cutpoint \big]
    \E\big[ X \big| \categZorC=\categZorCsmall \big]
    + \big( 1-\E\big[ W^X \big| W^\categZorC \geq \cutpoint \big] \big)
    \E\big[ X \big],
    \\
    \E\big[ \tilde{X}  \big| A_2 \big]
    &= \E\big[ W^X \big| W^\categZorC < \cutpoint \big]
    \E\big[ X \big]
    + \big( 1-\E\big[ W^X \big| W^\categZorC < \cutpoint \big] \big)
    \E\big[ X  \big| \categZorC=\categZorCsmall  \big].
\end{align*}
Therefore, the mean of the continuous variable
conditioned by the categorical variable from the synthetic data is
\begin{align*}
    \E\big[\tilde{X} \big| \tilde{\categZorC}=\categZorCsmall \big] 
    &= 
    \E\big[\tilde{X} \big| A_1 \cup A_2 \big]
    \\ &= 
    \E\big[\E\big[ \tilde{X}  \big| A_i \big] \big| A_1 \cup A_2 \big]
    \\ &= 
    \E\big[ \tilde{X}  \big| A_1 \big] \Pr\big[ A_1 \big| A_1 \cup A_2 \big]
    +
    \E\big[ \tilde{X}  \big| A_2 \big] \Pr\big[ A_2 \big| A_1 \cup A_2 \big]
    \\ &= 
    \frac{
    \E\big[ \tilde{X}  \big| A_1 \big] \Pr\big[ A_1 \big]
    +
    \E\big[ \tilde{X}  \big| A_2 \big] \Pr\big[ A_2\big]
    }{Pr\big[ A_1 \cup A_2 \big]}
    \\ &= 
    \frac{
    \E\big[ \tilde{X}  \big| A_1 \big] \Pr\big[ A_1 \big]
    +
    \E\big[ \tilde{X}  \big| A_2 \big] \Pr\big[ A_2\big]
    }{\Pr\big[ A_1 \big] + \Pr\big[ A_2 \big]}
    \\ &= 
    \frac{
    \E\big[ \tilde{X}  \big| A_1 \big] \Pr\{\categZorC_i=\categZorCsmall\} \Pr\{ W^\categZorC\geq \cutpoint\}
    +
    \E\big[ \tilde{X}  \big| A_2 \big]  \Pr\{\categZorC_j=\categZorCsmall\}\Pr\{ W^\categZorC < \cutpoint\}
    }{\Pr\{\categZorC_i=\categZorCsmall\} \Pr\{ W^\categZorC\geq \cutpoint\} + \Pr\{\categZorC_j=\categZorCsmall\} \Pr\{ W^\categZorC< \cutpoint\}}
    \\ &= 
    \frac{
        \E\big[ \tilde{X}  \big| A_1 \big] \Pr\{ W^\categZorC\geq \cutpoint\}
        +
        \E\big[ \tilde{X}  \big| A_2 \big] \Pr\{ W^\categZorC < \cutpoint\}
    }{\Pr\{ W^\categZorC\geq \cutpoint\} + \Pr\{ W^\categZorC< \cutpoint\}}
    \\ &= 
    \E\big[ \tilde{X}  \big| A_1 \big] \Pr\{ W^\categZorC\geq \cutpoint\}
    +
    \E\big[ \tilde{X}  \big| A_2 \big] \Pr\{ W^\categZorC < \cutpoint\}
    \\ &=
    \big( 
    \E\big[ W^X \big| W^\categZorC \geq \cutpoint \big]
    \E\big[ X \big| \categZorC=\categZorCsmall \big]
    + \big( 1-\E\big[ W^X \big| W^\categZorC \geq \cutpoint \big] \big)
    \E\big[ X \big]
    \big)
    \Pr\{ W^\categZorC\geq \cutpoint\}    
    \\ &\quad +
    \big(
    \E\big[ W^X \big| W^\categZorC < \cutpoint \big]
    \E\big[ X \big]
    + \big( 1-\E\big[ W^X \big| W^\categZorC < \cutpoint \big] \big)
    \E\big[ X  \big| \categZorC=\categZorCsmall  \big] 
    \big)
    \big(
    1- \Pr\{ W^\categZorC \geq \cutpoint\}
    \big)
    \\ &=
    (1-u\big(W^X, W^\categZorC,\cutpoint\big))\E\big[X \big| \categZorC=\categZorCsmall \big]
    + u\big(W^X, W^\categZorC,\cutpoint\big) \E\big[X \big],
\end{align*}
where $u\big(W^X, W^\categZorC,\cutpoint\big)$ is defined as
\begin{align*}
    u\big(W^X, W^\categZorC,\cutpoint\big)
    &=
    \Pr\{ W^\categZorC\geq \cutpoint\}
    - \E\big[ W^X \big| W^\categZorC \geq \cutpoint \big]\Pr\{ W^\categZorC\geq \cutpoint\}
    \\ & \quad
    + \E\big[ W^X \big| W^\categZorC < \cutpoint \big]
    - \E\big[ W^X \big| W^\categZorC < \cutpoint \big]\Pr\{ W^\categZorC\geq \cutpoint\}
    \\ &=
    \E\big[ 1-W^X \big| W^\categZorC \geq \cutpoint \big]\Pr\{ W^\categZorC\geq \cutpoint\}
    + \E\big[ W^X \big| W^\categZorC < \cutpoint \big] \Pr\{ W^\categZorC < \cutpoint\}
    \\ &=
    \E\big[ \big(1-W^X\big) \mathbf{I} \{ W^\categZorC\geq \cutpoint\} \big]
    + \E\big[ W^X  \mathbf{I} \{ W^\categZorC < \cutpoint\} \big]
    \\ &=
    \E\big[ \big(1-W^X\big) \mathbf{I} \{ W^\categZorC\geq \cutpoint\} + W^X  \mathbf{I} \{ W^\categZorC < \cutpoint\} \big],
\end{align*}
and  $\mathbf{I}$ is an indicator function.

Moreover, the law of total expectation, 
\begin{align*}
    E[X]
    &=
    E[E[X|Y]]
    % \\ &
    =
    E[X|\categZorC =\categZorCsmall ]\Pr\{ \categZorC =\categZorCsmall \} + 
    E[X|\categZorC \neq \categZorCsmall]\Pr\{ \categZorC \neq \categZorCsmall\},
\end{align*}
implies that 
\begin{align*}
    \E\big[\tilde{X} \big| \tilde{\categZorC}=\categZorCsmall \big] 
    &=
    (1-u\big(W^X, W^\categZorC,\cutpoint\big))\E\big[X \big| \categZorC=\categZorCsmall \big]
    % \\ 
    % &\quad 
    + u\big(W^X, W^\categZorC,\cutpoint\big) E[X|\categZorC =\categZorCsmall ]\Pr\{ \categZorC =\categZorCsmall \} 
    \\ 
    &\qquad + 
    u\big(W^X, W^\categZorC,\cutpoint\big) E[X|\categZorC \neq \categZorCsmall] \Pr\{ \categZorC \neq \categZorCsmall\} 
    \\
    &=
    \big(1-u\big(W^X, W^\categZorC,\cutpoint\big) \Pr\{ \categZorC \neq \categZorCsmall\} \big)\E\big[X \big| \categZorC=\categZorCsmall \big]
    % \\
    % &
    + u\big(W^X, W^\categZorC,\cutpoint\big) \Pr\{ \categZorC \neq \categZorCsmall\} E[X|\categZorC \neq \categZorCsmall],
\end{align*}
which is equal to
\begin{align*}
    \big|
    \E\big[\tilde{X} \big| \tilde{\categZorC}=\categZorCsmall \big]
    - \E\big[X \big| \categZorC=\categZorCsmall \big]
    \big|
    =
    \big| u\big(W^X, W^\categZorC,\cutpoint\big) \big|
    \cdot \Pr\{ \categZorC \neq \categZorCsmall\}
    \cdot
    \big|
    \E\big[X \big| \categZorC=\categZorCsmall \big]
    - \E\big[X \big| \categZorC \neq \categZorCsmall \big]
    \big| .
\end{align*}
\end{proof}


\clearpage
\begin{theorem}[Conditional Variance Gap]
\label{thm:app:con:var}
    Assume that $\E\big[\big(W^X\big)^2\big] = \E\big[W^X \big]$. Then, for any synthetic pair  $(\tilde{X}, \tilde{\categZorC})$ generated from $({X}, {\categZorC})$ using the general-weight mixup, where $X$ is continuous and $\categZorC$ is categorical, the difference between the conditional variance  is bounded  as follows:
    \begin{align}
    \nonumber
    \big|\Var\big[ \tilde{X}\big| \tilde{\categZorC}=\categZorCsmall \big]
    -  \Var\big[ X \big| \categZorC=\categZorCsmall \big]\big|
     & \leq
    \big| u\big(W^X, W^\categZorC,\cutpoint\big)\big|
    \cdot \big| \Var\big[ X \big| \categZorC=\categZorCsmall \big] - \Var\big[X\big] \big|
    \\
    \nonumber
    % \label{ineq.cond.var}
    &\qquad +\big| u\big(W^X, W^\categZorC,\cutpoint\big)(1- u\big(W^X, W^\categZorC,\cutpoint\big)) \big|  
    \cdot \big(\E\big[ X \big| \categZorC=\categZorCsmall \big]-\E\big[ X \big]\big)^2.
    \end{align}
\end{theorem}
\begin{proof}
Let us define the sets $A_1 = \{\categZorC_i=\categZorCsmall, W^\categZorC \geq \cutpoint\}$ and $A_2 =\{\categZorC_j=\categZorCsmall, W^\categZorC < \cutpoint\}$, which disjointly divide the set $\big\{\tilde{\categZorC}=\categZorCsmall\big\} = A_1 \dot{\cup} A_2$. Then, $\Pr(A_1)= \Pr\{\categZorC_i=\categZorCsmall\} \Pr\{ W^\categZorC\geq \cutpoint \}$ and $\Pr(A_2)= \Pr\{\categZorC_j=\categZorCsmall\} \Pr\{ W^\categZorC < \cutpoint\}$.

To obtain $\E\big[\tilde{X}^2 \big| \tilde{\categZorC}=\categZorCsmall \big] = \E\big[\tilde{X}^2 \big| A_1 \cup A_2 \big]$, we first determine $\E\big[ \tilde{X}^2  \big| A_1 \big]$ and $\E\big[ \tilde{X}^2  \big| A_2 \big]$ as follows:
\begin{align*}
    \E\big[ \tilde{X}^2  \big| A_1 \big]
    &=
    \E\big[ (W^X)^2 X_i^2 + (1-W^X)^2 X_j^2 + 2 W^X (1-W^X) X_iX_j \big| \{\categZorC_i=\categZorCsmall, W^\categZorC \geq \cutpoint\} \big]
    \\ &= 
    \E\big[ (W^X)^2 \big| W^\categZorC \geq \cutpoint \big]
    \E\big[ X_i^2 \big| \categZorC_i=\categZorCsmall \big]
    +\E\big[ (1-W^X)^2 \big| W^\categZorC \geq \cutpoint \big]
    \E\big[ X_j^2 \big]
    \\&  \quad + 
    2\E\big[ W^X(1-W^X) \big| W^\categZorC \geq \cutpoint \big]
    \E\big[ X_i \big| \categZorC_i=\categZorCsmall \big]\E\big[ X_j \big]
    \\ &= 
    \E\big[ (W^X)^2 \big| W^\categZorC \geq \cutpoint \big]
    \E\big[ X^2 \big| \categZorC=\categZorCsmall \big]
    + \E\big[ (1-W^X)^2 \big| W^\categZorC \geq \cutpoint \big]
    \E\big[ X^2 \big]
    \\& \quad +
    2\E\big[ W^X(1-W^X) \big| W^\categZorC \geq \cutpoint \big]
    \E\big[ X \big| \categZorC=\categZorCsmall \big]\E\big[ X \big],
    \\
    \E\big[ \tilde{X}^2  \big| A_2 \big]
    &=
    \E\big[ (W^X)^2 X_i^2 + (1-W^X)^2 X_j^2 + 2 W^X (1-W^X) X_iX_j \big| \{\categZorC_j=\categZorCsmall, W^\categZorC < \cutpoint\} \big]
    \\ &= 
    \E\big[ (W^X)^2 \big| W^\categZorC < \cutpoint \big]\E\big[ X^2 \big]
    + \E\big[ (1-W^X)^2 \big| W^\categZorC < \cutpoint \big]\E\big[ X^2 \big| \categZorC=\categZorCsmall \big]
    \\& \quad +
    2\E\big[ W^X(1-W^X) \big| W^\categZorC < \cutpoint \big]
    \E\big[ X \big]\E\big[ X \big| \categZorC=\categZorCsmall \big].
\end{align*}
Then,
\begin{align}
    \E\big[\tilde{X}^2 \big| \tilde{\categZorC}=\categZorCsmall \big]
    &= \nonumber 
    \E\big[ \tilde{X}^2  \big| A_1 \big] \Pr\{ W^\categZorC\geq \cutpoint\}
    + \E\big[ \tilde{X}^2  \big| A_2 \big] \Pr\{ W^\categZorC < \cutpoint\}
    \\ &= \nonumber 
    \E\big[ (W^X)^2 \mathbf{I} \{ W^\categZorC\geq \cutpoint\} \big]
    \E\big[ X^2 \big| \categZorC=\categZorCsmall \big]
    + \E\big[ (1-W^X)^2 \mathbf{I} \{ W^\categZorC\geq \cutpoint\} \big]
    \E\big[ X^2 \big]
    \\& \nonumber \quad +
    2\E\big[ W^X(1-W^X) \mathbf{I} \{ W^\categZorC\geq \cutpoint\} \big]
    \E\big[ X \big| \categZorC=\categZorCsmall \big]\E\big[ X \big]
    \\& \nonumber \quad +
    \E\big[ (W^X)^2 \mathbf{I} \{ W^\categZorC< \cutpoint\} \big]\E\big[ X^2 \big]
    + \E\big[ (1-W^X)^2 \mathbf{I} \{ W^\categZorC<\cutpoint\}\big]\E\big[ X^2 \big| \categZorC=\categZorCsmall \big]
    \\& \nonumber \quad +
    2\E\big[ W^X(1-W^X)\mathbf{I} \{ W^\categZorC< \cutpoint\} \big]
    \E\big[ X \big]\E\big[ X \big| \categZorC=\categZorCsmall \big]
    \\ &= \nonumber 
    \E\big[ (W^X)^2 \mathbf{I} \{ W^\categZorC\geq \cutpoint\} +  (1-W^X)^2 \mathbf{I} \{ W^\categZorC< \cutpoint\} \big]
    \E\big[ X^2 \big| \categZorC=\categZorCsmall \big]
    \\& \nonumber \quad +
    \E\big[ (1-W^X)^2 \mathbf{I} \{ W^\categZorC\geq \cutpoint\} + (W^X)^2 \mathbf{I} \{ W^\categZorC< \cutpoint\}  \big]
    \E\big[ X^2 \big]
    \\& \label{eq:proof:condisec}
    \quad +
    2\E\big[ W^X(1-W^X)  \big]
    \E\big[ X \big| \categZorC=\categZorCsmall \big]\E\big[ X \big]. 
\end{align}

Note that $u\big(W^X, W^\categZorC,\cutpoint\big)=\E\big[ \big(1-W^X\big) \mathbf{I} \{ W^\categZorC\geq \cutpoint\} + W^X  \mathbf{I} \{ W^\categZorC < \cutpoint\} \big]$ by the definition in \eqref{eq:def:ufunction}.

Now, we introduce the new random variable $\tilde{W}$ where
\begin{align}    
    \tilde{W}&=\begin{cases}
    1-W^X &\text{ if } W^\categZorC \geq \cutpoint\\
    W^X &\text{ if } W^\categZorC < \cutpoint
    \end{cases}
    \label{eq:def:w:tilde}
    \\
    &= \nonumber (1-W^X) \mathbf{I} \{ W^\categZorC\geq \cutpoint\} + W^X \mathbf{I} \{ W^\categZorC< \cutpoint\},
\end{align}
which implies $\E[\tilde{W}]=u\big(W^X, W^\categZorC,\cutpoint\big)$ and $\E[1-\tilde{W}]=1-u\big(W^X, W^\categZorC,\cutpoint\big)=\E\big[ W^X \mathbf{I} \{ W^\categZorC\geq \cutpoint\} + \big(1-W^X\big) \mathbf{I} \{ W^\categZorC < \cutpoint\} \big]$.

If the assumption $\E\big[\big(W^X\big)^2\big] = \E\big[W^X \big]$, which is the exactly same condition of \eqref{eq:necessary:var} in Lemma~\ref{thm:app:var}, holds, then $\E\big[\tilde{W}^2\big] = \E\big[\tilde{W}\big]$ from
\begin{align*}
    \E\big[ \tilde{W}^2 \big]
    &=
    \E\big[ \big( \big(1-W^X\big)\mathbf{I}\big\{ W^\categZorC \geq \cutpoint \big\} + W^X\mathbf{I}\big\{ W^\categZorC < \cutpoint \big\} \big)^2 \big]
    \\ &=
    \E\big[ \big(1-W^X\big)^2\mathbf{I}\big\{ W^\categZorC \geq \cutpoint \big\} + \big(W^X)^2\mathbf{I}\big\{ W^\categZorC < \cutpoint \big\} + 0 \big]
    \\ &=
    \E\big[ \big(1-W^X\big)\mathbf{I}\big\{ W^\categZorC \geq \cutpoint \big\} + W^X\mathbf{I}\big\{ W^\categZorC < \cutpoint \big\} \big]
    \\ &=
    \E\big[ \tilde{W} \big].
\end{align*}
Therefore, $\Var\big[ \tilde{W}\big] = \E\big[ \tilde{W}^2 \big] - \E\big[ \tilde{W} \big]^2 = \E\big[ 1-\tilde{W} \big]\E\big[ \tilde{W} \big]$.

By using the random variable $\tilde{W}$ defined in \eqref{eq:def:w:tilde}, the conditioned second moment of \eqref{eq:proof:condisec} is simplified as
\begin{align*}
    \E\big[\tilde{X}^2 \big| \tilde{\categZorC}=\categZorCsmall \big]
    &= %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    \E\big[ (W^X)^2 \mathbf{I} \{ W^\categZorC\geq \cutpoint\} +  (1-W^X)^2 \mathbf{I} \{ W^\categZorC< \cutpoint\} \big]
    \E\big[ X^2 \big| \categZorC=\categZorCsmall \big]
    \\& \quad +
    \E\big[ (1-W^X)^2 \mathbf{I} \{ W^\categZorC\geq \cutpoint\} + (W^X)^2 \mathbf{I} \{ W^\categZorC< \cutpoint\}  \big]
    \E\big[ X^2 \big]
    \\& \quad +
    2\E\big[ W^X(1-W^X)  \big]
    \E\big[ X \big| \categZorC=\categZorCsmall \big]\E\big[ X \big]
    \\ &= %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    \E\big[ (1-\tilde{W})^2 \big]
    \E\big[ X^2 \big| \categZorC=\categZorCsmall \big]
     + \E\big[ \tilde{W}^2  \big]
    \E\big[ X^2 \big]
    \\& \quad +
    2\E\big[ \tilde{W}(1-\tilde{W})  \big]
    \E\big[ X \big| \categZorC=\categZorCsmall \big]\E\big[ X \big].
\end{align*}
Similarly, from \eqref{eq:thm:con:mean} in Theorem~\ref{thm:app:con:mean}, the conditional mean is also simplified as
\begin{align*}
    \E\big[\tilde{X} \big| \tilde{\categZorC}=\categZorCsmall \big]^2
    &=  
    (1-u\big(W^X, W^\categZorC,\cutpoint\big))^2\E\big[X \big| \categZorC=\categZorCsmall \big]^2
    + u\big(W^X, W^\categZorC,\cutpoint\big)^2 \E\big[X \big]^2
    \\ & \quad 
    +2(1-u\big(W^X, W^\categZorC,\cutpoint\big))u\big(W^X, W^\categZorC,\cutpoint\big) \E\big[X \big| \categZorC=\categZorCsmall \big] \E\big[X \big]
    \\ &= %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    \E\big[ 1-\tilde{W} \big]^2\E\big[X \big| \categZorC=\categZorCsmall \big]^2
    + \E\big[ \tilde{W} \big]^2 \E\big[X \big]^2
    \\& \quad +
    2\E\big[ 1-\tilde{W} \big] \E\big[ \tilde{W} \big]
    \E\big[ X \big| \categZorC=\categZorCsmall \big]\E\big[ X \big].
\end{align*}

As a result, the conditional variance is determined as
\begin{align*}
    \Var\big[ \tilde{X}\big| \tilde{\categZorC}=\categZorCsmall \big]
    &= %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    \E\big[\tilde{X}^2 \big| \tilde{\categZorC}=\categZorCsmall \big]
    - \E\big[\tilde{X} \big| \tilde{\categZorC}=\categZorCsmall \big]^2
    \\ &= %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    \E\big[ (1-\tilde{W})^2 \big]
    \E\big[ X^2 \big| \categZorC=\categZorCsmall \big]
     + \E\big[ \tilde{W}^2  \big]
    \E\big[ X^2 \big]
    % \\& \quad
    + 2\E\big[ \tilde{W}(1-\tilde{W})  \big]
    \E\big[ X \big| \categZorC=\categZorCsmall \big]\E\big[ X \big]
    \\& \quad 
    - \E\big[ 1-\tilde{W} \big]^2\E\big[X \big| \categZorC=\categZorCsmall \big]^2
    - \E\big[ \tilde{W} \big]^2 \E\big[X \big]^2
    % \\& \quad 
    - 2\E\big[ 1-\tilde{W} \big] \E\big[ \tilde{W} \big]
    \E\big[ X \big| \categZorC=\categZorCsmall \big]\E\big[ X \big]
    \\ &= %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    \E\big[ (1-\tilde{W})^2 \big] \Var\big[ X \big| \categZorC=\categZorCsmall \big]
     + \E\big[ \tilde{W}^2  \big] \Var\big[ X \big]
    \\& \quad 
    + \big( \E\big[ (1-\tilde{W})^2 \big] - \E\big[ 1-\tilde{W} \big]^2 \big)\E\big[X \big| \categZorC=\categZorCsmall \big]^2
    + \big( \E\big[ \tilde{W}^2 \big] - \E\big[ \tilde{W} \big]^2 \big) \E\big[X \big]^2
    \\& \quad
    - 2\big(\E\big[ \tilde{W}^2 \big] - \E\big[ \tilde{W} \big]^2 \big)
    \E\big[ X \big| \categZorC=\categZorCsmall \big]\E\big[ X \big]
    \\ &= %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    \E\big[ (1-\tilde{W})^2 \big] \Var\big[ X \big| \categZorC=\categZorCsmall \big]
     + \E\big[ \tilde{W}^2  \big] \Var\big[ X \big]
    % \\& \quad 
    + \Var\big[ \tilde{W}\big]
    \big(\E\big[ X \big| \categZorC=\categZorCsmall \big]-\E\big[ X \big]\big)^2
    \\ &= %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    \E\big[ 1-\tilde{W} \big] \Var\big[ X \big| \categZorC=\categZorCsmall \big]
     + \E\big[ \tilde{W} \big] \Var\big[ X \big]
    % \\& \quad 
    + \E\big[ 1-\tilde{W} \big]\E\big[ \tilde{W} \big]
    \big(\E\big[ X \big| \categZorC=\categZorCsmall \big]-\E\big[ X \big]\big)^2
    \\ &= %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    \big(1- u\big(W^X, W^\categZorC,\cutpoint\big)\big) \Var\big[ X \big| \categZorC=\categZorCsmall \big]
     + u\big(W^X, W^\categZorC,\cutpoint\big) \Var\big[ X \big]
    \\& \quad 
    + \big(1- u\big(W^X, W^\categZorC,\cutpoint\big)\big) u\big(W^X, W^\categZorC,\cutpoint\big)
    \big(\E\big[ X \big| \categZorC=\categZorCsmall \big]-\E\big[ X \big]\big)^2
    \\ &= %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    \Var\big[ X \big| \categZorC=\categZorCsmall \big]
     + u\big(W^X, W^\categZorC,\cutpoint\big) \big( \Var\big[ X \big] - \Var\big[ X \big| \categZorC=\categZorCsmall \big] \big)
    \\& \quad 
    + \big(1- u\big(W^X, W^\categZorC,\cutpoint\big)\big) u\big(W^X, W^\categZorC,\cutpoint\big)
    \big(\E\big[ X \big| \categZorC=\categZorCsmall \big]-\E\big[ X \big]\big)^2,
\end{align*}
which is equal to
\begin{align*}
    \nonumber
    \big|\Var\big[ \tilde{X}\big| \tilde{\categZorC}=\categZorCsmall \big]
    -  \Var\big[ X \big| \categZorC=\categZorCsmall \big]\big|
     & \leq
    \big| u\big(W^X, W^\categZorC,\cutpoint\big)\big|
    \cdot \big| \Var\big[ X \big| \categZorC=\categZorCsmall \big] - \Var\big[X\big] \big|
    \\
    \nonumber
    &\qquad +\big| u\big(W^X, W^\categZorC,\cutpoint\big)(1- u\big(W^X, W^\categZorC,\cutpoint\big)) \big|  
    \cdot \big(\E\big[ X \big| \categZorC=\categZorCsmall \big]-\E\big[ X \big]\big)^2.
\end{align*}
by the triangular inequality.
\end{proof}

