\begin{lemma}
    \label{thm:app:nonnegative:u}
   Under the standard mixup scheme, $u(W,\cutpoint)\in [0,1]$ holds for any $\cutpoint\in\mathbb{R}$ if $\E\big[W^2\big] = \E\big[W \big]$.
\end{lemma}
\begin{proof}
    From the definition of function $u\big(W,\cutpoint\big)$ in \eqref{eq:def:ufunction:abb},
    \begin{align*}
        u(W,\cutpoint)
        &=
        \E\big[ \big(1-W\big) \mathbf{I} \{ W\geq \cutpoint\} + W  \mathbf{I} \{ W < \cutpoint\} \big]
        \\ &=
        \E\big[ \big(1-W\big) \mathbf{I} \{ W\geq \cutpoint\} + W  \big(1 -\mathbf{I} \{ W \geq \cutpoint\} \big) \big]
        \\ &=
        \E\big[\big(W\big)^2\big]
        + \E\big[ \big(1-2W\big) \mathbf{I} \{ W\geq \cutpoint\} \big],
    \end{align*}
    where the last equality holds if  $\E\big[\big(W\big)^2\big] = \E\big[W \big]$.
    Then, it is to trivial to show the non-negativity of $u(W,\cutpoint)$ for all $c\in\mathbb{R}$ as follows:
    \begin{align*}
        u(W,\cutpoint)
        &=
        \E\big[\big(W\big)^2 \mathbf{I} \{ W < \cutpoint\}\big]
        + \E\big[ \big(1-2W+\big(W\big)^2\big) \mathbf{I} \{ W\geq \cutpoint\} \big]
        \\ &=
        \E\big[\big(W\big)^2 \mathbf{I} \{ W < \cutpoint\}\big]
        + \E\big[ \big(1-W\big)^2 \mathbf{I} \{ W\geq \cutpoint\} \big]
        \\ &\geq 0.
    \end{align*}
    In a similar manner we can show the upper bound as
    \begin{align*}
        u(W, \cutpoint)
        &=
        \E\big[ \big(1-W\big) \mathbf{I} \{ W\geq \cutpoint\} + W  \mathbf{I} \{ W < \cutpoint\} \big]
        \\ &=
        \E\big[ \big(1-W\big) \big(1 -\mathbf{I} \{ W < \cutpoint\} \big) + W  \mathbf{I} \{ W < \cutpoint\} \big]
        \\ &=
        1-\E\big[\big(W\big)^2\big]
        + \E\big[ \big(2W -1\big) \mathbf{I} \{ W < \cutpoint\} \big]
        \\ &=
        1-\E\big[\big(W\big)^2 \mathbf{I} \{ W \geq \cutpoint\}\big]
        - \E\big[ \big(1-W\big)^2 \mathbf{I} \{ W < \cutpoint\} \big]
        \\ &\leq 1.
    \end{align*}
\end{proof}



\begin{lemma}[Optimal Cut Point $\cutpoint$]
    \label{thm:app:condimean:cutpoint}
    Under the standard mixup scheme with $\E\big[W^2\big] = \E\big[W \big]$, the optimal cut point $\cutpoint$  is $0.5$. That is
    \begin{equation}
    \nonumber
    0.5 = \argmin_{\cutpoint \in \mathbb{R}} \big| u\big(W,\cutpoint\big) \big| .
    \end{equation}
\end{lemma}
\begin{proof}
    From Lemma~\ref{thm:app:nonnegative:u}, $u(W,\cutpoint)\in [0,1]$ holds for any $\cutpoint\in\mathbb{R}$. Then,
    \begin{align*}
        \big| u\big(W,\cutpoint\big) \big|
        & \geq
         u\big(W,\cutpoint\big) 
        \\ &=
        \E\big[ \big(1-W\big) \mathbf{I} \{ W\geq \cutpoint\} + W  \mathbf{I} \{ W < \cutpoint\} \big]
        \\ & \geq
        \E\big[ \min \big\{ 1-W, W\big\} \mathbf{I} \{ W\geq \cutpoint\} 
        + \min \big\{ 1-W, W\big\} \mathbf{I} \{ W < \cutpoint\} \big]
        \\ &=
        \E\big[ \min \big\{ 1-W, W\big\} \big]
        \\ &=
        \E\big[ \big(1-W\big) \mathbf{I} \{ W\geq 0.5\} + W  \mathbf{I} \{ W < 0.5\} \big]
        \\ &= u(W, 0.5)
    \end{align*}
    for any $W$. Therefore, with the condition $u(W, 0.5)\geq 0$, the optimal cut point $\cutpoint$ for the categorical variable is $0.5$. That is
    \begin{equation*}
        0.5 = \argmin_{\cutpoint \in (0,1)} \big|u\big(W,\cutpoint\big)\big|.
    \end{equation*}
\end{proof}


