\begin{corollary}[Variance-Reduction mixup]
    \label{thm:app:bounded:support:mixup}
    For any synthetic variable $\tilde X$ generated by the mixup from a continuous $X$ in (\ref{eq:mixup:x}), let the support of mixup weight variable $W^X$ be bounded in $[0,1]$. Then 
    \begin{equation}
        \Var\big[\tilde{X}\big] \leq \Var\big[X\big],\nonumber %
    \end{equation}
    where the equality holds when $\Pr\big\{W^X \in \{0, 1\} \big\}=1$.
\end{corollary}
\begin{proof}
    Note that $w^2 - w \leq 0$ holds for any $w\in[0,1]$, which implies $\E\big[\big(W^X\big)^2 - W^X\big]\leq 0$, where the equality condition is $\Pr\big\{W^X \in \{0, 1\} \big\}=1$.
    From Lemma~\ref{thm:app:var}, we have $\Var\big[\tilde{X}\big] \leq \Var\big[X\big]$.
\end{proof}


