\begin{theorem}
\label{thm:app:epbeta:var}
For given $\epsilon_0, \epsilon_1 \in [0,\infty)$, consider an arbitrary synthetic pair $(\tilde{X}, \tilde{Y})$ generated from $({X}, {Y})$ using the standard mixup scheme with  $W \sim \operatorname{EpBeta}(\alpha, \beta; \epsilon_0, \epsilon_1)$ 
, such that $\alpha, \beta \in (0, \infty)$ satisfy
\begin{equation}
    \nonumber
    (1+\epsilon_1 -\epsilon_0 (\beta/\alpha)) \cdot (1+\epsilon_0-\epsilon_1 (\alpha/\beta)) \cdot (1+\alpha+\beta)
    =
    (1+\epsilon_0+\epsilon_1)^2.
\end{equation}
Then we have  $\Var\big[\tilde{X}\big] = \Var\big[X\big] $ and $\Cov\big[\tilde{X},\tilde{Y}\big] = \Cov\big[X,Y\big] $.
\end{theorem}
\begin{proof}
    Let $W$ follow the $\operatorname{Beta}(\alpha, \beta)$ distribution, which implies $\E[W]=\frac{\alpha}{\alpha+\beta}$ and $\Var[W]=\frac{\alpha\beta}{(\alpha+\beta)^2(\alpha+\beta+1)}$. Then,
    \begin{align*}
        \E\big[(1+\epsilon_0 +\epsilon_1)W-\epsilon_0\big]
        &= \frac{(1+\epsilon_0 +\epsilon_1)\alpha}{\alpha+\beta} - \epsilon_0
        \\
        &= \frac{(1+\epsilon_1)\alpha -\epsilon_0\beta}{\alpha+\beta},
        \\
        \E\big[(1+\epsilon_0 +\epsilon_1)W-\epsilon_0\big]^2
        &= \Var\big[(1+\epsilon_0 +\epsilon_1)W-\epsilon_0\big] + \big(\E\big[(1+\epsilon_0 +\epsilon_1)W-\epsilon_0\big]\big)^2
        \\
        &=\frac{(1+\epsilon_0+\epsilon_1)^2 \alpha\beta}{(\alpha+\beta)^2(\alpha+\beta+1)}
        + \left( \frac{(1+\epsilon_1)\alpha -\epsilon_0 \beta}{\alpha+\beta} \right)^2.
    \end{align*}

By Theorem~\ref{thm:app:cov}, $\Var\big[\tilde{D}\big] = \Var\big[D\big]$ if and only if
\begin{align}
    \label{eq:proof:epbeta}
    \E\big[(1+\epsilon_0 +\epsilon_1)W-\epsilon_0\big]=\E\big[(1+\epsilon_0 +\epsilon_1)W-\epsilon_0\big]^2.
\end{align}

To find the $\alpha, \beta  \in (0, \infty)$ that satisfy \eqref{eq:proof:epbeta}, 
    \begin{align*}
    ((1+\epsilon_1)\alpha -\epsilon_0 \beta)(\alpha+\beta)
    &=
    \frac{(1+\epsilon_0+\epsilon_1)^2 \alpha\beta}{(\alpha+\beta+1)}
    + \big( (1+\epsilon_1)\alpha -\epsilon_0 \beta \big)^2,
    \end{align*}
which is equal to
    \begin{align*}
    (1+\epsilon_1 -\epsilon_0 (\beta/\alpha)) \cdot (1+\epsilon_0-\epsilon_1 (\alpha/\beta)) \cdot (1+\alpha+\beta)
    &=
    (1+\epsilon_0+\epsilon_1)^2.
    \end{align*}

    Note that the above equation can be rewritten as
    \begin{align*}
    \alpha+\beta
    &=
    \frac{(1+\epsilon_0+\epsilon_1)^2}{(1+\epsilon_1 -\epsilon_0 (\beta/\alpha)) \cdot (1+\epsilon_0-\epsilon_1 (\alpha/\beta))}
    -1 ,
    \end{align*}
    which implies that we can find $(\alpha, \beta)$ that satisfies the condition in \eqref{eq:proof:epbeta} for given $\beta/\alpha, \epsilon_0$, and $\epsilon_1$.
\end{proof}


\begin{theorem}
    \label{thm:app:epbeta:condimean}
   Consider an arbitrary synthetic triple $(\tilde{X}, \tilde{Y}, \tilde{\categZorC})$ generated from $({X}, {Y}, \categZorC)$ using the standard mixup scheme with $W \sim \operatorname{EpBeta}(\alpha, \beta; \epsilon_0, \epsilon_1)$ for given $\epsilon_0, \epsilon_1 \in [0,\infty)$ and $\cutpoint=0.5$. Now suppose that, for a given  $\delta \in [0,1]$, $(\alpha, \beta)$ satisfies (\ref{eq:epbeta:constraint}) and the following 

    \begin{equation}
    \nonumber %\label{eq:epbeta:conditional:constraint}
    \frac{ 1+\epsilon_0 -\epsilon_1 \alpha /\beta}{1+\alpha/\beta}
    + \frac{2(1+\epsilon_0+\epsilon_1)}{1+\beta/\alpha} \frac{B(\tilde{\epsilon};\alpha+1, \beta)}{B(1;\alpha+1, \beta)}
    - (1+2\epsilon_0) \frac{B\left(\tilde{\epsilon};\alpha, \beta\right)}{B(1;\alpha, \beta)}
    \leq
    \delta,
    \end{equation}
    where $B(x;\alpha, \beta) = \int_{0}^{b} t^{\alpha-1} (1-t)^{\beta-1} \,dt$ is the incomplete beta function and $\tilde{\epsilon}=\frac{0.5+\epsilon_0}{1+\epsilon_0+\epsilon_1}$.

 Then, the gap of conditional (on categorical $\categZorC$) mean and variance are bounded as follows:
 \begin{equation*}
     \big|
    \E\big[\tilde{X} \big| \tilde{\categZorC}=\categZorCsmall \big]
    - \E\big[X \big| \categZorC=\categZorCsmall \big]
    \big|
    =
    \delta
    \cdot \Pr\{ \categZorC \neq \categZorCsmall\}
    \cdot
    \big|
    \E\big[X \big| \categZorC=\categZorCsmall \big]
    - \E\big[X \big| \categZorC \neq \categZorCsmall \big]
    \big| 
 \end{equation*} and 
\begin{align*}
    \big|\Var\big[ \tilde{X}\big| \tilde{\categZorC}=\categZorCsmall \big]
    -  \Var\big[ X \big| \categZorC=\categZorCsmall \big]\big|
    & \leq 
    \delta
    \cdot \big| \Var\big[ X \big| \categZorC=\categZorCsmall \big] - \Var\big[X\big] \big|
    % \\
    % &\quad
    +\delta(1-\delta)
    \cdot \big(\E\big[ X \big| \categZorC=\categZorCsmall \big]-\E\big[ X \big]\big)^2.
\end{align*} 
\end{theorem}
\begin{proof}
    Note that the conditional mean and variance gaps are bounded by the functions of $u\big(W^X, W^\categZorC,\cutpoint\big)$ from Corollary~\ref{thm:app:con:mean:cor} and Theorem~\ref{thm:app:con:var}, respectively.
    To determine it, define the random variable $W\sim \operatorname{Beta}(\alpha,\beta)$, which implies $W^X=W^\categZorC=(1+\epsilon_0+\epsilon_1)W-\epsilon_0$. Then, with \eqref{eq:epbeta:conditional:constraint},
\begin{align*}
    u\big(W^X, W^\categZorC,\cutpoint\big) &= u(W^X, 0.5) 
    \\&=
    \E\big[ \big(1-W^X\big) \mathbf{I} \{ W^X\geq 0.5\} + W^X  \mathbf{I} \{ W^X < 0.5\} \big]
    \\&=
    \E\big[ \big(1-W^X\big) (1-\mathbf{I} \{ W^X < 0.5\}) + W^X  \mathbf{I} \{ W^X < 0.5\} \big]
    \\&=
    \E\big[ 1-W^X \big] +
    \E\big[ \big(2W^X-1\big) \mathbf{I} \{ W^X < 0.5\} \big]
    \\&=
    \frac{-\epsilon_1 \alpha + (1+\epsilon_0)\beta}{\alpha+\beta}
    % \\& \qquad
    +
    \E\big[ \big(2(1+\epsilon_0+\epsilon_1) W -1- 2\epsilon_0\big)  \mathbf{I} \{ (1+\epsilon_0+\epsilon_1) W - \epsilon_0 < 0.5\} \big]
    \\&=
    \frac{-\epsilon_1 \alpha + (1+\epsilon_0)\beta}{\alpha+\beta}
    % \\& \qquad
    +
    \E\bigg[ \bigg(2(1+\epsilon_0+\epsilon_1) W -1 -2\epsilon_0\bigg) \mathbf{I} \bigg\{ W  < \frac{0.5+\epsilon_0}{1+\epsilon_0+\epsilon_1} \bigg\} \bigg]
    \\&=
    \frac{ 1+\epsilon_0 -\epsilon_1 \alpha /\beta}{1+\alpha/\beta}
    + 2(1+\epsilon_0+\epsilon_1) \frac{B(\tilde{\epsilon};\alpha+1, \beta)}{B(1;\alpha, \beta)}
    - (1+2\epsilon_0) \frac{B\left(\tilde{\epsilon};\alpha, \beta\right)}{B(1;\alpha, \beta)}
    \\&=
    \frac{ 1+\epsilon_0 -\epsilon_1 \alpha /\beta}{1+\alpha/\beta}
