 \end{equation*} and 
\begin{align*}
    \big|\Var\big[ \tilde{X}\big| \tilde{\categZorC}=\categZorCsmall \big]
    -  \Var\big[ X \big| \categZorC=\categZorCsmall \big]\big|
    & \leq 
    \delta
    \cdot \big| \Var\big[ X \big| \categZorC=\categZorCsmall \big] - \Var\big[X\big] \big|
    % \\
    % &\quad
    +\delta(1-\delta)
    \cdot \big(\E\big[ X \big| \categZorC=\categZorCsmall \big]-\E\big[ X \big]\big)^2.
\end{align*}

Moreover, note that $\Pr\{ \categZorC \neq \categZorCsmall\}$, $\big| \E\big[X \big| \categZorC=\categZorCsmall \big] - \E\big[X \big| \categZorC \neq \categZorCsmall \big] \big|$, $\big| \Var\big[ X \big| \categZorC=\categZorCsmall \big] - \Var\big[X\big] \big|$, and $\big(\E\big[ X \big| \categZorC=\categZorCsmall \big]-\E\big[ X \big]\big)$ are constants given by the original distribution $\mathfrak{D}$. As result, when $\delta$ goes to $0$,
    \begin{align*}
    \big|  \E\big[\tilde{X} \big| \tilde{\categZorC}=\categZorCsmall \big] - \E\big[X \big| \categZorC=\categZorCsmall \big] \big|
    &\leq
    \delta \cdot \Pr\{ \categZorC \neq \categZorCsmall\}
    \cdot \big| \E\big[X \big| \categZorC=\categZorCsmall \big] - \E\big[X \big| \categZorC \neq \categZorCsmall \big] \big|
    \\ &\to 0,
    \\
    \big|\Var\big[ \tilde{X}\big| \tilde{\categZorC}=\categZorCsmall \big]
    -  \Var\big[ X \big| \categZorC=\categZorCsmall \big]\big|
    & \leq
    \delta \cdot \big| \Var\big[ X \big| \categZorC=\categZorCsmall \big] - \Var\big[X\big] \big|
    % \\&\quad
    + \delta( 1- \delta )
    \cdot \big(\E\big[ X \big| \categZorC=\categZorCsmall \big]-\E\big[ X \big]\big)^2
    \\&\to 0,
    \end{align*}
    which are equal to
    \begin{align*}
        \E\big[\tilde{X} \big| \tilde{\categZorC}=\categZorCsmall \big] &\to \E\big[X \big| \categZorC=\categZorCsmall \big],
        \\
        \Var\big[ \tilde{X}\big| \tilde{\categZorC}=\categZorCsmall \big] &\to  \Var\big[ X \big| \categZorC=\categZorCsmall \big],
    \end{align*}
    as $\delta$ goes to $0$.
\end{proof}





