                \centering
                \begin{tabular}{|c|c|c|c|c|}
                    \toprule
                    $i_0$ & $P_\tau$ & $\alpha = 0.9$ & $\alpha = 1$ & $\alpha = 1.1$\\\hline
                    \multirow{3}{*}{0} & $P_0$ & $0$ & $0$ & $0$\\
                                        & $P_{1,2}$ & $0.333$ & $0.333$ & $0.333$\\
                                        & $P_{>2}$ & $0.667$ & $0.667$ & $0.667$\\\hline
