                \includegraphics[width=0.99\columnwidth]{flatbandsdynamickago-f-15.png}
                \caption{
                The time average of the magnetization $\overline{a}_r$
                of the \KG as a function of the system size $N$ related 
                to an initial state $\ket{1, \vnu_0}$ for different values of 
                $\alpha$ over a late time interval $[\Tilde{t}, \Tilde{t} + t_m]$
                with $\Tilde{t}=10^6$ and $t_m=2000$.}
