\section{Gumbel Smoothing}\label{appendix: gumbel-smooth}
The proof of \Cref{lemma: gumbel smoothing} depends on the translation invariance of the softmax.
\begin{lemma}[Translation-Invariance of Softmax] Consider logits $\mathbf{z} \in \mathbb{R}^d$, then adding any constant $c \in \mathbb{R}$ to $\mathbf{z}$, $\mathbf{z} + c$, does not change the output of the softmax. Concretely, for any logit $z_i$ we have
\[ \mathrm{softmax}(z_i + c ) = \mathrm{softmax}(z_i )\]
\end{lemma}
\begin{proof}
Denote \( z'_i := z_i + c\), then writing the output of our softmax yields

\begin{align*}
    \mathrm{softmax}(z'_i) &= \frac{e^{z'_i}}{ \sum_j  e^{z'_i}} \\
    &= \frac{e^{ z_i + c}}{ \sum_j  e^{ z_i + c}} \\
    &= \frac{e^{z'_i}}{ \sum_j  e^{z'_i}} \\
    &= \frac{e^c \cdot e^{ z_i}}{ \sum_j  e^c \cdot e^{ z_i}} \\
    &=  \frac{e^c \cdot e^{ z_i}}{  e^c  \cdot \sum_j \cdot e^{ z_i}} \\
    &=  \frac{e^{z_i}}{ \sum_j  e^{z_i}}  = \mathrm{softmax}(z_i)
\end{align*}

\end{proof}

Restating lemma \cref{lemma: gumbel smoothing}, we write:

\begin{lemma}[Gumbel‐Smoothing]
Let \(\mathcal L: \mathbb{R}^{16} \to \ \mathbb{R} \) be twice continuously differentiable (with Lipschitz Hessian), and let
\( \mathbf{z} \in \mathbb{R}^{16}, \mathbf{g} \sim\mathrm{Gumbel}(0,1)^{16}\).  Consider \( J(\mathbf{z}) \) 

\[ J(\mathbf{z}) = \mathbb{E} \left[ \mathcal{L}(\mathrm{softmax}( ( \mathbf{z} + \mathbf{g} )/ \tau ) \right]  \]

and set \(\mathbf{a} = \mathbf{z} / \tau \) and \( f(\mathbf{a}) = \mathcal{L}(\mathrm{softmax}(\mathbf{a}) ) \), then
\[
J(\mathbf{z})
= \mathcal{L}(\mathrm{softmax}( \mathbf{z} / \tau) ) + \frac{\pi^2}{12 \tau^2} \mathrm{tr}(H_{f}( a))
+ O(\tau^{-3}).
\]
\end{lemma}

\begin{proof}
    Rewriting \( J(\mathbf{z}) \) in terms of \( f \) gives us
    \[ J( \mathbf{z}) = \mathbb{E} \left[ f \left( \mathbf{a} + \frac{\mathbf{g}}{\tau} \right) \right] \]

    Consider a second-order Taylor expansion of \(f \) around \( \mathbf{a}\)

    \[ 
    f \left( \mathbf{a} + \frac{\mathbf{g}}{\tau } \right) = f( \mathbf{a} ) + \nabla f(\mathbf{a}) ^\top \left( \frac{\mathbf{g}}{\tau}  \right) + \frac{1}{2} \left( \frac{\mathbf{g}}{\tau}  \right)^\top H_f(\mathbf{a}) \left( \frac{\mathbf{g}}{\tau} \right) + O( \| \mathbf{g} \|^3 / \tau^3)
    \]
    Taking expectations, and recalling that \( \mathbb{E}\left[ g_i\right]  = \gamma, \; \mathrm{Var}( g_i) = \pi^2/6 \), where \( \gamma \approx 0.57721 \) is the Euler-Mascheroni constant. we get
    \[
    J(\mathbf{z}) = f( \mathbf{a}) +\left( \frac{\gamma}{\tau} \right)  \nabla f( \mathbf{a})^\top \mathbf{1} + \frac{1}{2 \tau^2} \left[ \gamma^2 \mathbf{1}^\top H_f (\mathbf{a}) \mathbf{1} + \frac{\pi^2}{6} \mathrm{tr}(H_f( \mathbf{a})) \right] + O(\tau^{-3})
    \]


which follows from \( \mathbb{E}[g_i^2 ] = \mathrm{Var}(g_i) + \mathbb{E}[g_i]^2 = \pi^2/6 + \gamma^2 \), \( \mathbb{E}\left[ g_i g_j\right] = \gamma^2 \) for \( i \neq j\).

\[ 
\mathbb{E}[\mathbf{g} \mathbf{g}^\top] = \gamma^2 \mathbf{1} \mathbf{1}^\top + \frac{\pi^2}{6} I
\]
and the following  trace-lemma
\[
\mathbb{E} \left[ \mathbf{g}^\top H_f( \mathbf{a} ) \mathbf{g} \right]= \mathrm{tr}(H_f(\mathbf{a}) \mathbb{E}[\mathbf{g} \mathbf{g}^\top]) = \gamma^2 \mathbf{1}^\top H_f(\mathbf{a})\mathbf{1} + \frac{\pi^2}{6} \mathrm{tr}(H_f(\mathbf{a}))
\]

Since the softmax is translation-invariant in its input \( \mathbf{a} \), we have \( \nabla f(\mathbf{a})^\top \mathbf{1} = 0 \) and \( H_f(\mathbf{a}) \mathbf{1} = 0 \), so all terms depending on \( \gamma\) drop, finally giving us

\[ 
J(\mathbf{z})
= \mathcal{L}(\mathrm{softmax}( \mathbf{z} / \tau )  ) + \frac{\pi^2}{12 \tau^2} \mathrm{tr}(H_{f}( \mathbf{z} / \tau))
+ O(\tau^{-3}).
\]

\end{proof}


Hence, minimizing our stochastic loss implicitly smoothens the curvature by minimizing the trace of the Hessian.




