\section{Expected Entropy}\label{appendix: expected entropy}
\begin{lemma}
    The expected entropy of a newly initialized neuron in a Differentiable LGN is $\approx\log 16 - \frac{1}{2}\approx2.27$.
\end{lemma}
\begin{proof}
    A neuron has $n=16$ gates that it makes a choice over and gate $i$ has (i.i.d.) logit $z_i\sim N(0,1)$ and probability $p_i=\frac{\exp z_i}{C}$ where $C=\sum_{j=1}^n\exp z_j$. For the rest of the proof, we assume the number of gates $n$ is not fixed, and show that the expected entropy converges to $\log n-\frac{1}{2}$.

    The expected entropy of $p=(p_1,p_2,...)$ is
    \begin{align*}
        \mathbb{E}[H(p)] &= -\mathbb{E}\left[ \sum_{i=1}^n \frac{\exp z_i}{C} \log\frac{\exp z_i}{C} \right] \\
        &= \mathbb{E}\left[ \log C \right]-\mathbb{E}\left[ \sum_{i=1}^n \frac{z_i\exp z_i}{C} \right] \\
        &= \mathbb{E}\left[ \log \sum_{j=1}^n\exp z_j \right]-\mathbb{E}\left[ \sum_{i=1}^n \frac{z_i\exp z_i}{\sum_{j=1}^n\exp z_j} \right].
    \end{align*}
    Here, we have as $n\rightarrow\infty$:
    \begin{align*}
        \mathbb{E}\left[ \sum_{i=1}^n \frac{z_i\exp z_i}{\sum_{j=1}^n\exp z_j} \right]=\mathbb{E}\left[  \frac{\frac{1}{n}\sum_{i=1}^n z_i\exp z_i}{\frac{1}{n}\sum_{j=1}^n\exp z_j} \right]=\frac{\mathbb{E}[z_i\exp z_i]}{\mathbb{E}[\exp z_j]}.
    \end{align*}
    Using $\mathbb{E}[\exp z_1] = \sqrt{e}$ and $\mathbb{E}[z_1\exp z_1] = \sqrt{e}$, the above gives us that as $n\rightarrow\infty$:
    \begin{align*}
        &\mathbb{E}\left[ \log \sum_{j=1}^n\exp z_j \right]-\mathbb{E}\left[ \sum_{i=1}^n \frac{z_i\exp z_i}{\sum_{j=1}^n\exp z_j} \right] \\
        &= \log n + \mathbb{E}\left[ \log \left(\frac{1}{n}\sum_{j=1}^n\exp z_j\right) \right] - \frac{\mathbb{E}[z_i\exp z_i]}{\mathbb{E}[\exp z_j]} \\
        &= \log n + \log \mathbb{E}[\exp z_j] - \frac{\mathbb{E}[z_i\exp z_i]}{\mathbb{E}[\exp z_j]} = \log n + \frac{1}{2} - 1 = \log n - \frac{1}{2}.
    \end{align*}
    We only need to plug in $n=16$ to get the last part.
\end{proof}


