\section{Numerical implementation}
\label{app:num}
For the numerical implementation we used a standard finite volume scheme to discretize the space and membrane occupancy dimensions, see for example \cite{hundsdorfer2003numerical}. The resulting system of ODEs for the time evolution was then solved by using the pre-implemented explicit Runge-Kutta method of order 5(4) from the python package \textit{scipy.integrate.solve\_ivp}.

The space and membrane occupancy intervals ($[0,L]$ and $[0,1]$, respectively) were discretised in the following way: let $N+1$ and $M+1$ denote the number of discretisation points (including both endpoints) of the space and occupancy interval, respectively. Then the full intervals are divided into $N $ and $M$ intervals of length $\Delta x = \frac{L}{N}$ and $\Delta m = \frac{1}{M}$, respectively.  We use $L=100$, $T=30$, for the simulation window $(x,m,t)\in [0,L]\times[0,1]\times[0,T]$, $N+1 = 500$ discretisation points in space and $M+1 = 50$ in the dimension for membrane occupancy, resulting in $\Delta x = 0.2$ and $\Delta m = 0.02$. 
Let $p_{i,j}(t) := p(x_i, t, m_j) = p(i \Delta x, t, j \Delta m )$ denote the cell population density at position $x_i$ with membrane occupancy $m_j$, and $c_i (t):= c(x_i, t) = c(i \Delta x, t)$ the chemoattractive concentration at position $x_i$. The total cell density is defined as $P_i(t) := \Delta m \sum_{j=0}^{M-1} p_{i,j}(t)$.

For $0 \leq i < N$, let $f^p_{i+1/2, j}(t)$ denote the flux of the population with membrane state $m_j $ from the $x_i$ to $x_{i+1}$ at time $t$,
\begin{equation}
\label{AppxTW:eq:FluxPx}
    f_{i+1/2,j}^p (t) = \begin{cases}  - \epsilon  \frac{1}{\Delta x } D^j (p_{i+1,j} (t) - p_{i,j} (t) ) + \frac{1}{\Delta x } A^j (c_{i+1} (t) - c_i(t) ) p_{i,j} (t)\\
    \quad \text{if} \quad c_{i+1}(t) - c_i(t) >0, \\
   - \epsilon \frac{1}{\Delta x } D^j (p_{i+1,j}(t) - p_{i,j}(t)) + \frac{1}{\Delta x } A^j (c_{i+1}(t) - c_i (t) ) p_{i+1,j} (t) \\
   \quad \text{if} \quad c_{i+1}(t) - c_i (t) < 0,
\end{cases}
\end{equation}
for $j=1,\dots,M$, where $D^j = D(m_j)$ and $A^j = A(m_j)$. To enforce homogeneous Neumann boundary conditions we define $f^p_{-1/2,j} (t) = 0 $ and $f^p_{N+1/2,j} (t)= 0 $ for $0 \leq t \leq T$, $j=1,\dots,M$.
Similarly, for $0 \leq j < M$ the flux of the population located at $x_i = i\Delta x$ from membrane state $m_j$ into $m_{j+1}$ is
\begin{equation}
\label{AppxTW:eq:FluxPm}
    f^p_{i,j+1/2} (t) = K_1 \omega_1(m_j) c_i p_{i,j} - K_2 \omega_2(m_{j+1}) p_{i,j+1},
\end{equation}
for $i=1,\dots,N$, where $\omega_1, \omega_2 \in C(0,1)$ with $\omega_1 (1) = 0$ and $\omega_2 (0) = 0$. This, together with $p_{i,j}(0) = 0 $ for $j<0$ and $j>M$ ensures $f_{i,-1/2}(t) = 0 $ and $f_{i,M+1/2} (t) = 0 $, for $i=1,\dots,N$, so that the scheme is mass conserving. The flux for the chemoattractive substance from $x_i$ to $x_{i+1}$ at time $t$ is
\begin{equation}
\label{AppxTW:eq:FluxC}
f^c_{i+1/2} = - \epsilon d \frac{1}{\Delta x } (c_{i+1}(t)- c_i(t) ), 
\end{equation}
for $i=1,\dots,N$, with boundary conditions $f^c_{-1/2} (t) = 0 $ and $f^c_{N+1/2} (t) = 0$ for $0 \leq t \leq T$.
The kinetics with the non-local terms are discretised as follows:
\begin{equation}
\begin{split}
    k^p_{i,j} (t) &= \frac{1}{\epsilon } \Big( - \gamma (P_i(t)) p_{i,j}(t) + \Delta m \sum_{z=0}^{M} b(m_z,c_i(t)) B(m_z,m_j) p_{i,z} (t) \\
    &\quad \qquad  - \frac{1}{2} p_{i,j} (t) b(m_j,c_i(t)) \Delta m \sum_{z=0}^{M} B(m_j,m_z) \Big), \\
    k^c_i (t) & = \sigma K_2 \Delta m \sum_{z=1}^{M} p_{i,z} (t)  - \sigma K_1 c_i (t) \Delta m \sum_{z=0}^{M-1} p_{i,z} (t) - Q(P_i(t)) c_i(t).
\end{split}
\end{equation}

The corresponding ODE system then reads
\begin{equation}
\begin{split}
\frac{d}{dt} p_{i,j}(t) &= \frac{1}{\Delta x } (f^p_{i-1/2,j}(t) - f^p_{i+1/2,j}(t)) + \frac{1}{\Delta m } (f^p_{i,j-1/2} (t) - f^p_{i,j+1/2} (t))  + k^p_{i,j} (t), \\
\frac{d}{dt} c_i(t) &= \frac{1}{\Delta x } (f^c_{i-1/2}(t) - f^c_{i+1/2}(t)) + k^c_i(t),
\end{split}
\end{equation}
for $0 \leq i \leq N$, $0 \leq j \leq M$ and with appropriate initial conditions $p_{i,j}(0) \geq 0 $, $c_i(0) \geq 0$.

