\section{The distance between the solutions of the AL and the DGPE lattice}
\label{SecIII}\label{s3}
In this section, we present the main result concerning the estimates for the distance between the solutions of the DGPE and the AL lattice. In the first part, we provide the estimates for general initial data. We comment also for the case of the finite lattice with Dirichlet boundary conditions.  In the second part, we discuss the application of these estimates for small initial data.
\subsection{The distance between the solutions: general initial data}
\label{SubsecIIa}
\paragraph{The case of the infinite lattice.} Recall  (see \cite{JMP2011}), that the non-integrable DGPE latttice \eqref{GPE} conserves the following quantities, the Hamiltonian 
%
\begin{equation}\label{H_DGPE} 
	H_{NI} =  \sum_{\nZ}|\phi_{n+1} -\phi_n|^2 + \Omega^2 h^2\sum_{\nZ}(hn)^2|\phi_n|^2 + \frac{g h^2}{2}\sum_{\nZ}|\phi_n|^4,
\end{equation}
and the power (or $l^2$-norm)
\begin{equation}
	\label{powerDGPE}
 P=\|\phi\|_{l^2}^2 = h\sum_{\nZ} |\phi_n|^2.	
\end{equation}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
The integrable AL lattice \eqref{AL} has infinitely many invariant quantities \cite{PM1}, including the Hamiltonian
\begin{equation}\label{H2}
	H_{I} = \sum_\nZ \overline{\psi}_n(\psi_{n+1} -  \psi_{n-1}) - \frac{2}{\mu h^2} \sum_{\nZ} \ln(1+\mu h^2|\psi_n|^2) 
\end{equation}
and the deformed power 
\begin{equation}\label{norm}
	P_\mu= \frac{1}{\mu h^2}\sum_\nZ{\ln(1+\mu h^2|\psi_n|^2)}.
\end{equation} 
Therefore, for all $t>0$, we have that
\begin{eqnarray}
	\label{NGPE}
	H_{NI}(t) &=&H_{NI}(0), \quad H_{I}(t)  = H_{I}(0),\\
	\label{N}
	\|\phi(t)\|^2_{l^2}  &=& 	\|\phi(0)\|^2_{l^2}, \quad P_\mu(t) = P_\mu(0),
\end{eqnarray}
for the solutions of the DGPE and and the AL systems, respectively. Note that \cite{PM1} provides formulas for the derivation of the conserved quantities of general Hamiltonian DNLS-type systems.  For the AL lattice, Proposition \ref{SGB} implies a bound of the form \eqref{UBS}, when $\psi(0)\in l^2$, namely,
satisfies the estimate 
\begin{equation}
	\label{UBSAL}
	\|\psi(t)\|_{l^2}^2\leq M_{\mu,0}\|\psi(0)\|_{l^2}^2, \;\;\mbox{for all $t>0$}.
\end{equation}
For the conservation of the Hamiltonian \eqref{H_DGPE}, it is crucial to remark the following:  the global in time solvability in $l^2$, that is, that  $\phi(t)\in C^1([0,\infty),l^2)$ is guaranteed for all initial data $\phi(0)\in l^2$ due to the conservation of the power \eqref{powerDGPE}.  However, the fact that $\phi(t)\in C^1([0,\infty),l^2)$ do not guarantees that the Hamiltonian $H_{NI}(t)$ is  bounded,  unless 
\begin{eqnarray}
\label{ht0}
H_{NI}(0)<\infty.
\end{eqnarray}
For \eqref{ht0} to be satisfied, it is required that the initial data have {\em finite discrete variance}, that is 
 \begin{eqnarray}
 \label{ht01}
V_d(0):=h\sum_{\nZ} (hn)^2|\phi_n(0)|^2< \infty.
 \end{eqnarray}
Initial data satisfying \eqref{ht01} are in $l^2$, since 
\begin{eqnarray}
\label{ht001}
h^3\sum_{\nZ}|\phi_n(0)|^2=h^3|\phi_0(0)|+h^3\sum_{n\neq 0, n\in\mathbb{Z}}|\phi_n(0)|^2\leq h^3|\phi_0(0)|+V_d(0).
\end{eqnarray}
\begin{prop}
	\label{finHNI}
For every $\phi(0)$ satisfying \eqref{ht01}, let $\phi(t)\in C^1([0,\infty),l^2)$ be the global in time solution of the problem \eqref{GPE}-\eqref{Vbc} for the DGPE lattice. Then
\begin{equation}
\label{htrapterm}
V_d(t)=h\sum_{\nZ}(hn)^2|\phi_n(t)|^2<\infty,\;\;\mbox{for all $t>0$.}
\end{equation}
\end{prop}	
\begin{proof}
The fact that $\phi(t)\in C^1([0,\infty),l^2)$ follows directly from \eqref{ht001} and the conservation of the power  \eqref{powerDGPE}. Next, from the conservation of the Hamiltonian  	$H_{NI}(t) =H_{NI}(0)$, we have that
\begin{eqnarray}
\label{ht1}
 \Omega^2 h^2\sum_{\nZ}(hn)^2|\phi_n|^2 \leq  \sum_{\nZ}|\phi_{n+1} -\phi_n|^2 +\frac{|g| h^2}{2}\sum_{\nZ}|\phi_n|^4+\left|H_{NI}(0)\right|.
\end{eqnarray}
Since $\phi(t)\in C^1([0,\infty),l^2)$, the first term of the right-hand side of \eqref{ht1} is uniformly bounded for all $t>0$, due to the inequality
\begin{eqnarray}
\label{ht2}
\sum_{\nZ}|\phi_{n+1} -\phi_n|^2\leq 4\sum_{\nZ}|\phi_n|^2.
\end{eqnarray}
The second term of the right-hand side of \eqref{ht1} is also uniformly bounded for all $t>0$, due to the embedding $l^2\subset l^4$ (see \eqref{ineq_l}). Also, by the assumption \eqref{ht01} we have that the third term  $|H_{NI}(0)|<\infty$, and hence, \eqref{htrapterm} holds.
\end{proof}	
Obviously, Proposition \ref{finHNI} is valid for initial data  $\phi(0)\in\l^{2,2}$ of the DGPE. Note that the limitations on $h$ described in Remark \ref{DPDE} are also valid for the case of  Proposition \ref{finHNI}.

Before proceeding to the statement and proof of the main result, we summarize the well-posedness results for the DGPE and AL lattices. The problem \eqref{GPE}-\eqref{Vbc} for the DGPE lattice is globally well-posed in time in $l^2$, with uniformly bounded solutions
for all initial data $\phi(0)\in l^2$.
However, the Hamiltonian may be unbounded if the initial data do not decay faster than quadratically, as dictated by the finite variance condition \eqref{ht01}. The same uniform boundedness of solutions holds for the problem \eqref{AL}-\eqref{Vbc} for the AL lattice in $l^2$.  Since the analytical solution \eqref{ALBS} of the latter, which we aim to examine for its potential persistence in the DGPE dynamics, is bounded in $l^2$ but may have an $l^{2,2}$-norm that  becomes unbounded (without singularities) in time, the  global existence results above- ensuring $l^2$-uniformly bounded solutions, suggest that  the $l^2$-metric is more suitable and less cumbersome for our initial investigations of the potential proximal dynamics. However, as we will see below, the presence of the harmonic trap term in the equation governing the difference of solutions between the two systems will necessitate considering at least the problem \eqref{AL}-\eqref{Vbc} for the AL lattice in $l^{2,2}$. While this problem remains globally well-posed in $l^{2,2}$ it generally lacks uniformly bounded solutions. Measuring the distance in weighted spaces is a problem of interdependent interest and will be considered elsewhere. 

The main result is proved in the following theorem.

\begin{theorem}
	\label{MR}
Let $g<0$ and $\mu>0$. We assume that the initial condition for the DGPE lattice \eqref{GPE} $\phi(0)\in l^2$, and that the initial condition for the AL lattice \eqref{AL}  $\psi(0)\in l^2_w=l^{2,2}$. Then, the distance between  the solutions of the systems $\|y(t)\|_{l^2}=\|\phi(t)-\psi(t)\|_{l^2}$, which satisfy the boundary conditions \eqref{Vbc},  grows transiently, with  at most an exponential rate according to the estimate 
\begin{eqnarray}\label{final1}
	\| y(t) \|_ {l^2}  &\le& \| y(0) \|_ {l^2}  + \mathcal{A}_1t+\mathcal{A}_2\exp\left(\Gamma t\right),\\ 
	\label{final1a}
	\mathcal{A}_1 &=&|g|  \|\phi(0)\|_ {l^2}^3  + 
	2\mu C_{\mu,0}\| \psi(0) \|_ {l^2}^3,\;\;
	\mathcal{A}_2=\frac{\Omega^2}{\Gamma} \| \psi(0) \|_{l^2_w},
\end{eqnarray}
for some  constant $C_{\mu,0}>0$, which is independent of $t$ and the initial data. In particular, the growth of the upper bound holds for finite time
\begin{eqnarray}
\label{finit}
t\in [0, t^*],\;\;\mbox{satisfying the inequality}\;\;\mathcal{A}_1t&+&\mathcal{A}_2\exp\left(\Gamma t\right)\leq \mathcal{B}-\|y(0)\|_{l^2},\\
\label{finit2}
\mathcal{B}[\phi(0),\psi(0)]&=&\|\phi(0)\|_{l^2}+C^*_{\mu,0}\|\psi(0)\|_{l^2},
\end{eqnarray}
where  $C^*_{\mu,0}>0$ is again independent of $t$ and the initial data. The quantity $\mathcal{B}[\phi(0),\psi(0)]$ is the global, uniform-in-time bound for $\|y(t)\|_{l^2}$, that is, $\|y(t)\|\leq \mathcal{B}$, for all $t>0$. 
\end{theorem}
\begin{proof}
	We start by subtracting the AL lattice \eqref{AL} from the DGPE lattice \eqref{GPE} to get the evolution equation for the difference of the solutions of the systems $y_n=\phi_n-\psi_n$, which reads as 
	\begin{equation}\label{main0}
		i \dot{y}_n  +\frac{1}{h^2}  \Delta_d y_n =  \Omega^2(hn)^2\phi_n + g|\phi_n|^2 \phi_n  + \mu |\psi_n|^2 (\psi_{n+1} - \psi_{n-1}).
	\end{equation}
	We apply the trick of simultaneously adding and subtracting the term $\Omega^2(hn)^2\psi_n$ in \eqref{main0} to avoid working directly with the distance $y$ in a weighted norm. Instead, we handle only the solution of the AL lattice $\psi$ in such a norm, by using Proposition \ref{SGB}, as will become evident below. With this trick, the equation \eqref{main0} is rewritten as
	\begin{equation}\label{main}
		i \dot{y}_n  +\frac{1}{h^2}  \Delta_d y_n =  \Omega^2(hn)^2y_n + g|\phi_n|^2 \phi_n  + \mu |\psi_n|^2 (\psi_{n+1} - \psi_{n-1}) + \Omega^2(hn)^2\psi_n.
	\end{equation}
	Multiplying \eqref{main} by $ h\overline{y}_n $, taking the sum over $n$  and keeping the  imaginary parts, we get the evolution equation for the distance in the $l^2$-metric $\|y(t)\|_{l^2}=\|\phi(t)-\psi(t)\|_{l^2}$:
	\begin{equation}\label{imeq}
		\frac{1}{2} \frac{d}{dt} \|y\|_{l^2}^2  =
		g\,\mathrm{Im} \Big\{h\sum_\nZ | \phi_n |^2 \phi_n \overline{y}_n\Big\} + 
		\mu\,\mathrm{Im} \Big\{h\sum_\nZ |\psi_n |^2 (\psi_{n-1}  + \psi_{n+1})\overline{y}_n\Big\} +
		\Omega^2\,\mathrm{Im} \Big\{h\sum_\nZ (hn)^2 \psi_n \overline{y}_n\Big\},
	\end{equation}
	noting that
	$\mathrm{Im}\Big\{ \sum_\nZ n^2 |y_n|^2\Big\}= 0$.
	%
	Using  the embedding \eqref{ineq_l} and the Cauchy--Schwarz inequality, the first  and the second term of the right-hand side can be estimated as follows:
	\begin{eqnarray}
		\label{distest1}
		\Big| \mathrm{Im} \Big\{h\sum_\nZ |\phi_n|^2 \phi_n \overline{y}_n\Big\}\Big| &\le&  \|\phi\|_ {l^2}^3 \|y\|_{l^2},\\
		\label{distest2}
		\Big|\, \mathrm{Im} \Big\{h\sum_\nZ |\psi_n|^2 (\psi_{n-1} + \psi_{n+1}) \overline{y}_n\Big\} \Big|
		&\le& 2  \| \psi \|_ {l^2} ^ 3 \| y\| _ {l^2},
	\end{eqnarray}
	respectively. For the third term, the estimate will require a bound for the solution $\psi(t)\in l^2_w$, for all $t>0$, with the weight  $w_n = (1 + (hn)^2)^2$, that is, the weighted space $l_w^2=l^{2,2}$.  This bound is provided by  \eqref{expest} of Theorem \ref{THS}, for $\gamma=0$ which corresponds to the case of the AL lattice. Thus, applying the Cauchy--Schwarz inequality, we have that
	\begin{align}
		\label{distest3}
		\Big|\mathrm{Im} \Big\{h\sum_\nZ (hn)^2 \psi_n \overline{y}_n\Big\}\Big| & \le 
		h\sum_\nZ (1 + (hn)^2) |\psi_n| |\overline{y}_n|\nonumber \\ & \le 
		\|\psi\|_{l^2_w} \|y\|_{l^2} \nonumber\\ & \le
		\exp\left(\Gamma t\right)\| \psi(0) \|_{l^2_w} \|y\|_{l^2}.
	\end{align}
	Inserting the estimates \eqref{distest1}-\eqref{distest3} into equation \eqref{imeq}, we derive the differential inequality
	\begin{eqnarray}
		\label{distest4}
		\frac{1}{2} \frac{d}{dt} \|y\|_{l^2}^2  \le  
		|g|  \|\phi\|_ {l^2}^3 \|y\|_{l^2} + 
		2\mu  \| \psi \|_ {l^2} ^ 3 \| y\| _ {l^2} +
		\Omega^2	\exp\left(\Gamma t\right)\| \psi(0) \|_{l^2_w} \|y\|_{l^2}.
	\end{eqnarray}
In the first and second terms on the right-hand side of \eqref{distest4}, we apply the conservation of the $l^2$-norm \eqref{N} for $\phi(t)$ and the bound \eqref{UBSAL} for $\psi(t)$, respectively. The latter is applicable because $l^2_w = l^{2,2}$ is continuously embedded in $l^2$, as stated in \eqref{wemb}. Therefore, the assumption that $\psi(0) \in l^2_w$ implies that $\psi(0) \in l^2$, and for the corresponding solution measured in the $l^2$-norm, the estimate \eqref{UBSAL} holds. Then, \eqref{distest4} becomes
	\begin{eqnarray}
		\label{distest4a}
		\frac{1}{2} \frac{d}{dt} \|y(t)\|_{l^2}^2  \le  
		|g|  \|\phi (0)\|_ {l^2}^3 \|y(t)\|_{l^2} &+& 
		2\mu C_{\mu,0} \| \psi(0) \|_ {l^2} ^ 3 \| y(t)\| _ {l^2}\nonumber \\
		&+&
		\Omega^2\exp\left(\Gamma t\right)\| \psi(0) \|_{l^2_w}	\|y(t)\|_{l^2},\;\;C_{\mu,0}=M_{\mu,0}^{3/2}.
	\end{eqnarray}
	%
	With the help of the identity
	$$
	\frac{d}{dt}  \|y\| _{l^2} ^ 2 = 2 \| y \| _ {l^2} \frac{d}{dt} \| y \|_ {l^2},
	$$
	the inequality \eqref{distest4a} gets the form
	\begin{eqnarray}
		\label{ineqfin}
		 \frac{d}{dt} \|y(t)\|_{l^2}  \le  
		|g|  \|\phi (0)\|_ {l^2}^3  + 
		2\mu C_{\mu,0} \| \psi(0) \|_ {l^2} ^ 3  +
		\Omega^2\exp\left(\Gamma t\right)\| \psi(0) \|_{l^2_w}.
	\end{eqnarray}
	Integration of  \eqref{ineqfin} with respect to time, provides the claimed  estimate \eqref{final1}, with growth rates $\mathcal{A}_1$ and $\mathcal{A}_2$ given by \eqref{final1a}, for $\|y(t)\|_{l^2}$.

Note that the estimate \eqref{final1} is {\em general, with respect to the initial data and parameters}.   It implies {\em at most, exponential growth} of the distance $\|y(t)\|_{l^2}$ with rate $\mathcal{A}_2$, which depends on the initial data and parameters as given in \eqref{final1a}.
We show now that this exponential growth rate is {only transient}. Due to the triangle inequality, we have that the distance $\|y(t)\|_{l^2}$ is { \em globally bounded,  uniformly in time}, by the norms of the initial conditions:
\begin{eqnarray}
\label{trans1}
\|y(t)\|_{l^2}&\leq& \|\phi(t)\|_{l^2}+\|\psi(t)\|_{l^2} \nonumber\\ &\leq& \|\phi(0)\|_{l^2}+C^*_{\mu,0}\|\psi(0)\|_{l^2}:=\mathcal{B}[\phi(0),\psi(0)],\;\;\;C^*_{\mu,0}=M_{\mu,0}^{1/2}.
\end{eqnarray}
Therefore, on the account of \eqref{final1}-\eqref{final1a}, it holds that
\begin{eqnarray}
\label{trans2}
||y(t)||_{l^2}\leq \| y(0) \|_ {l^2}  + \mathcal{A}_1t+\mathcal{A}_2\exp\left(\Gamma t\right)\leq \mathcal{B},\;\;\mbox{for all $t\geq 0$},
\end{eqnarray}
since the distance can never exceed its global  bound \eqref{trans1}, and any of its other bounds is less or equal than $\mathcal{B}$, for all $t\geq 0$. Therefore, any growth of the distance is only transient, and holds at most for $t\in [0, t^*]$, satisfying \eqref{trans2}.   This way we proved \eqref{finit} and \eqref{finit2}, and thus, completed the proof of the claims of the theorem.
\end{proof}
\paragraph{The case of the finite lattice with Dirichlet boundary conditions.} The case of the finite lattice is important for the numerical simulations. We consider the case of the Dirichlet boundary conditions. Then, the systems are considered in the finite dimensional spaces
\begin{equation*}
	{l}^p_{0}:=\bigg\{U=(U_n)_{n\in\mathbb{Z}}\in\mathbb{C}:\quad U_0=U_{N}=0,\quad
	\|U\|_{\ell^p_{0}}:=\bigg(h\sum_{n=1}^{N-1}|U_n|^p\bigg)^{\frac{1}{p}}<\infty\bigg\}, \quad 1\leq p\leq\infty,
\end{equation*}
for a finite lattice of $N+1$ nodes. In the finite dimensional setting all norms are equivalent. Thus, considering the weighted norm $l^2_w=l^2_2$, there exist  positive constant $c_2(N)$, such that
\begin{eqnarray}
	\label{normequiv}
\|\phi\|_{l^2_0}\leq \|\phi\|_{l^2_w} \leq c_2\|\phi\|_{l^2_0},\;\; c_2(N)\sim 1+h^2N^2,\;\; \quad \text{for all}\quad  \phi\in l^2_{0}.
\end{eqnarray}
The equivalence of norms \eqref{normequiv} modifies the upper bounds of Theorem \ref{MR} {\em to be linear}, according to  the following corollary. 
\begin{corollary}
	\label{MRF}
	Let $g<0$ and $\mu>0$.  Consider the finite DGPE and AL lattices in $l^2_0$, that is, supplemented with Dirichlet boundary conditions, and  their initial conditions $\phi(0),\psi(0)\in l^2_0$.  Then, the distance between  the solutions of the systems $\|y(t)\|_{l^2_0}=\|\phi(t)-\psi(t)\|_{l^2_0}$  grows transiently, with  at most a linear rate according to the estimate 
	\begin{eqnarray}\label{final1D}
		\| y(t) \|_ {l^2_0}  &\le& \| y(0) \|_ {l^2_0}  + \mathcal{A}t,\\ 
		\label{final1aD}
		\mathcal{A} &=&|g|  \|\phi(0)\|_ {l^2_0}^3  + 
		2\mu \tilde{C}_{\mu,0}\| \psi(0) \|_ {l^2_0}^3 +\Omega^2\tilde{C}_{1,\mu,0}\|\psi(0)\|_{l^2_0},\;\;
	\end{eqnarray}
	for some  constants $\tilde{C}_{\mu,0}>0,\,\tilde{C}_{1,\mu,0} $, which are independent of $t$ and the initial data. In particular, the growth of the upper bound holds for finite time
	\begin{eqnarray}
		\label{finitD}
		t\in [0, t^*],\;\; t^*&=&\frac{\mathcal{B}-\|y(0)\|_{l^2_0}}{\mathcal{A}},\\
		\label{finit2D}
		\mathcal{B}[\phi(0),\psi(0)]&=&\|\phi(0)\|_{l^2_0}+\tilde{C}^*_{1,\mu,0}\|\psi(0)\|_{l^2_0},
	\end{eqnarray}
	where  $\tilde{C}^*_{1,\mu,0}>0$ is again independent of $t$ and the initial data. The quantity $\mathcal{B}[\phi(0),\psi(0)]$ is the global, uniform-in-time bound for $\|y(t)\|_{l^2_0}$, that is, $\|y(t)\|_{l^2_0}\leq \mathcal{B}$, for all $t>0$. 
\end{corollary}
 \begin{proof}
The equivalence of norms \eqref{normequiv} modifies the estimate \eqref{distest3} for the AL lattice. The bound \eqref{UBSAL} holds also for the finite lattice, that is,
\begin{equation}
	\label{UBSALD}
	\|\psi(t)\|_{l^2_0}^2\leq M_{\mu,0,f}\|\psi(0)\|_{l^2_0}^2,\;\;\mbox{for all $t>0$}.
\end{equation}
Then, instead of the inequality \eqref{distest3}, we have its counterpart
\begin{align}
	\label{distest3D}
	\Big|\mathrm{Im} \Big\{h\sum_{n=1}^{N-1} (hn)^2 \psi_n \overline{y}_n\Big\}\Big| & \le 
	h\sum_{n=1}^{N-1} (1 + (hn)^2) |\psi_n| |\overline{y}_n|\nonumber \\ & \le 
	\|\psi\|_{l^2_w} \|y\|_{l^2_0} \nonumber\\ & \le
c_2\| \psi \|_{l^2_0} \|y\|_{l^2_0}\le c_2 M_{\mu,0,f}^{1/2}
\| \psi(0) \|_{l^2_0} \|y\|_{l^2_0}.
\end{align}
By using \eqref{distest3D}, instead of \eqref{ineqfin}, we get the inequality
\begin{eqnarray}
	\label{ineqfinD}
	 \frac{d}{dt} \|y(t)\|_{l^2_0}  \le  
	|g|  \|\phi (0)\|_ {l^2_0}^3  + 
	2\mu \tilde{C}_{\mu,0} \| \psi(0) \|_ {l^2_0} ^ 3  +
	\Omega^2 \tilde{C}_{1,\mu,0}
	\| \psi(0) \|_{l^2_0},\;\; 
\end{eqnarray} 
with $\tilde{C}_{\mu,0}=M_{\mu,0,f}^{3/2}$ and $\tilde{C}_{1,\mu,0}=c_2 M_{\mu,0,f}^{1/2}$. Integration of \eqref{ineqfinD} with respect to time, leads to the estimate \eqref{final1D} with the linear growth rate \eqref{final1aD}. The global, uniform-in-time bound for the distance is
\begin{eqnarray}
	\label{trans1d}
	\|y(t)\|_{l^2_0}\leq  \|\phi(0)\|_{l^2_0}+C^*_{1,\mu,0}\|\psi(0)\|_{l^2_0}:=\mathcal{B}[\phi(0),\psi(0)],\;\;\;C^*_{1,\mu,0}=M_{\mu,0,f}^{1/2}.
\end{eqnarray} 
We conclude with the proof of \eqref{finitD}-\eqref{finit2D}, by following the last lines of the proof of Theorem \ref{MR}, this time, by using the upper bounds \eqref{final1D} and \eqref{trans1d}. 
 \end{proof}
