From the above assumptions, we find that the RHS of System~\eqref{eq:system} is of class $\mathbf{C}^{1}$, which guarantees the local existence and uniqueness of solutions. In \cite{Abernathy}, following the ideas of Kogan {\it et al.},~\cite{Kogan},  the authors proved the dissipativity of the System \eqref{eq:system} and then analyzed the tumor-free steady state. However, they obtained implicit conditions of the stability, which we would like to reformulate in explicit form. For further analysis of tumor persistence states, they posed a simplifying assumption which we also exploit in our paper.

Because System~\eqref{eq:system} is highly complex, for its further analysis we introduce the following simplifying assumption.

\begin{assumption}\label{assumption2}
We assume that $N$ is the total number of lymphocytes that enter the tumor area as a result of immunotherapy and the body's natural immune response, i.e.~Eq.~\eqref{eq:system_3} reads
$$\dot{C}=N-\mu_{C}C.$$
\end{assumption}

The assumption above implies that $v$ no longer influences other variables in the system. Thus, we can consider System~\eqref{eq:system} without the last equation.
Note that for any initial conditions the variables $C$, $y$, and $u$ converge exponentially to $C^*(N),$ $y^*(N),$ $u^*(N)$, where

\begin{equation*}
    C^*(N):=\frac{N}{\mu_{C}}, \; y^*(N):= \frac{f_{y}\big(C^*(N)\big)}{\mu_{y}}, \; u^*(N):= \frac{f_{u}\big(y^*(N)\big)}{\mu_{u}}.
\end{equation*}

Thus, we will consider a quasi-stationary approximation for $C,y,u$. Eventually, System~\eqref{eq:system} takes the following form:

\begin{subequations}\label{eq:our_system}
\renewcommand{\theequation}{\theparentequation.\arabic{equation}}
    \begin{align}
        \dot{T} &= r_{\alpha}\frac{S}{K_S}\frac{T}{K_T}(K_T-T) + r_T \left(1-\frac{T}{K_T}\right)T - f_{T}(x)G_T(N)h_{T}(T)T, \label{eq:our_system_1}\\
        \dot{S} &= r_S \left(1-\frac{S}{K_S}\right)S - r_{\alpha}\frac{S}{K_S}\frac{T}{K_T}(K_T-T) - f_{S}(x)G_S(N)h_{S}(S)S,\label{eq:our_system_2}\\
        \dot{x} &= g_{x} + a_{x,T}T + a_{x,S}S - \mu_{x}x,\label{eq:our_system_3}
    \end{align}
\end{subequations}
where
\begin{equation*}
    G_i(N):=g_{i}\big(u^*(N)\big)C^*(N),
    \quad i=T, \, S.
\end{equation*}

\begin{rem}
Under Assumption~\ref{assumption2} the stability of steady states of the full System~\eqref{eq:system} and the simplified System~\eqref{eq:our_system} is equivalent.
\end{rem}

The above remark allows us to note that without loss of generality it is enough to study steady states of the simplified system instead of the full one.


Now we proceed to the analysis of the properties of the functions $G_i(N)$, $i=T$, $S$. Based on Assumption \ref{assumption1} we get that
\begin{equation*}
    \begin{aligned}
    u^*(N)=&
    \frac{f_{u}(y^*)}{\mu_{u}}=
    %\frac{1}{\mu_u}f_{u}\left(\frac{f_{y}\big(C^*(N)\big)}{\mu_y}\right)%=
    \frac{1}{\mu_u}f_{u}\left(\frac{a_{y,C}C^*(N)}{\mu_y}\right)=
    \frac{1}{\mu_u}f_{u}\left(\frac{a_{y,C}N}{\mu_y\mu_C}\right)
    \end{aligned}
\end{equation*}
and thus
\begin{equation*}
    G_i(N)= g_{i}\left(\frac{1}{\mu_u}f_{u}\left(\frac{a_{y,C}N}{\mu_y\mu_C}\right)\right)\frac{N}{\mu_{C}},
\quad i=T,\,S.
\end{equation*}
Since the functions $f_u$ and $g_i$, $i=T$, $S$, are increasing and nonnegative, so are the functions $G_i$, $i=T$, $S$. Moreover,
\begin{equation*}
    G_i(N)=0 \iff N=0, \quad i=T,\, S,
\end{equation*}
and
\begin{equation*}
    \lim_{N\rightarrow\infty}G_i(N)=\infty, \quad i=T,\, S.
\end{equation*}
Because $\lim_{u\rightarrow\infty}g_i(u)=a_{i,u}$ and 
$g_i$ are increasing, $i=T$, $S$,
we get that
\begin{equation*}
     \lim_{N\rightarrow\infty}\frac{G_i(N)}{N}=
\lim_{N\rightarrow\infty}g_{i}\left(\frac{1}{\mu_u}f_{u}\left(\frac{a_{y,C}N}{\mu_y\mu_C}\right)\right)\frac{1}{\mu_{C}}\leqslant \frac{a_{i,u}}{\mu_C},\quad  i=T,\, S.
\end{equation*}
Furthermore, since $\forall{u>0}\;\;g_T(u)>g_S(u),$ then the following corollary holds.

\begin{cor}\label{cor:G1_G2}
If Assumptions \ref{assumption1} and \ref{assumption2} are satisfied, then the functions $G_i$,  $i=T$, $S$, are strictly increasing and linearly bounded. Moreover
\begin{equation*}
G_T(0)=G_S(0)=0 \quad \text{and} \quad
    \forall{N>0}
\ \ G_T(N)> G_{S}(N) .
\end{equation*}
\end{cor}

\begin{proposition}
If Assumption~\ref{assumption1} is satisfied, then System~\eqref{eq:our_system} has unique nonnegative solutions for nonnegative initial data. Moreover, if $T_0\leq K_T$ and $S_0\leq K_S$, then the solutions are bounded from above and defined for all $t\geqslant 0.$
\end{proposition}

\textit{Proof:} Existence and uniqueness are a simple consequence of Assumption~\ref{assumption1}. We will now show that the solutions are nonnegative. From Equation~\eqref{eq:our_system_1} we get that if $T=0$, then $\dot{T}=0$. Hence, if $T_0=0$, then $T(t)=0$ for all $t\geqslant 0$ for which the solution exists. The uniqueness of the solutions implies that if $T_0>0$, then $T(t)>0$ for all $t\geqslant 0$ for which the solution exists. The same argument applies for Eq.~\eqref{eq:our_system_2}.

Now, consider Eq.~\eqref{eq:our_system_3}. Because for $x=0$ there is $\dot x = g_{x} + a_{x,T}T + a_{x,S}S \geq g_x>0 $, the variable $x$ cannot take negative values for $x_0\geq 0$.
Thus, all the coordinates of the  solutions to System~\eqref{eq:our_system} are nonnegative.

Next, we proceed to show that the solutions to System \eqref{eq:our_system} are also bounded from above. Note that
\begin{equation}\label{eq:T_bound}
    \begin{aligned}
        \dot{T} &\leqslant r_{\alpha}\frac{S}{K_S}\frac{T}{K_T}(K_T-T) + r_T \left(1-\frac{T}{K_T}\right)T \\
        &= \left( r_{\alpha}\frac{S}{K_S} + r_T\right)\frac{T(K_T-T)}{K_T}.
    \end{aligned}
\end{equation}
Let us assume that $T_0\in [0,K_T]$ and there exists $t_1$ such that $T(t_1)=K_T$ and $T$ exceeds $K_T$ at $t_1$. Then there must exist such $\epsilon > 0$ that for each $t\in(t_1,t_1+\epsilon)$ $T(t)>K_T.$ From \eqref{eq:T_bound} we, therefore, get $\dot{T}(t)<0$ for all $t\in(t_1,t_1+\epsilon)$. On the other hand, from the Lagrange theorem there exists such $\xi \in (t_1,t_1+\epsilon)$ that
\begin{align*}
    \dot{T}(\xi)=&\frac{T(t_1+\epsilon)-T(t_1)}{\epsilon}=\frac{T(t_1+\epsilon)-K_T}{\epsilon}>0,
\end{align*}
which yields a contradiction. Thus, $T\leqslant K_T$, and hence we have
\begin{equation*}
    \begin{aligned}
        \dot{S} &= r_S \left(1-\frac{S}{K_S}\right)S - r_{\alpha}\frac{S}{K_S}\frac{T}{K_T}(K_T-T) - f_{S}(x)G_{S}(N)h_{S}(S)S \\
        &\leqslant  r_S \left(1-\frac{S}{K_S}\right)S.
    \end{aligned}
\end{equation*}
This means that $S$ does not exceed solutions of the logistic equation $$\dot{S}=r_S\left(1-\frac{S}{K_S} \right)S,$$ which implies $S\leqslant K_S$. Thus, we have
\begin{align*}
    \dot{x}=&g_{x} + a_{x,T}T + a_{x,S}S-\mu_x x\leqslant g_x + a_{x,T}K_T + a_{x,S}K_S - \mu_x x.
\end{align*}
Let us define
\begin{align*}
    \bar{x}:=\frac{g_x+a_{x,T}K_T+a_{x,S}K_S}{\mu_x}.
\end{align*}
It is easy to see that if for a given $t\geqslant 0$ we have $x(t)>\bar{x}$, then $\dot{x}(t)<0$. Hence, if $x_0>\bar{x}$, then $x(t)\leqslant x_0$ for all $t$ for which the solution exists. If $x_0\leqslant\bar{x},$ then $x(t)\leqslant \bar{x}$. Thus, $x$ is bounded from above by $x_{\max}:=\max\{x_0, \bar{x}\}$.

Finally, it is easy to show that since $T,$ $S$ and $x$ are bounded from above, then their derivatives are also bounded. Hence, the solutions to System \eqref{eq:our_system} exist for all $t\geqslant 0$.
$\hfill\square$


\begin{cor}
If Assumption \ref{assumption1} is satisfied, then the System~\eqref{eq:our_system} has an invariant set defined by $\mathcal{D}=[0,K_T]\times[0,K_S]\times[0,\bar x]$. 
\end{cor}


\section{Analysis of steady states}

In this section we will analyze the existence and uniqueness of selected steady states of System~\eqref{eq:our_system}, depending on the value of $N$. The steady states of System~\eqref{eq:our_system} solve the following system of algebraic equations
\begin{subequations}\label{eq:our_system_steady}
\renewcommand{\theequation}{\theparentequation.\arabic{equation}}
    \begin{align}
        0 &= r_{\alpha}\frac{S^*}{K_S}\frac{T^*}{K_T}(K_T-T^*) + r_T \left(1-\frac{T^*}{K_T}\right)T^* - f_{T}(x^*)G_{T}(N)h_{T}(T^*)T^*, \label{eq:our_system_steady_1}\\
        0 &= r_S \left(1-\frac{S^*}{K_S}\right)S^* - r_{\alpha}\frac{S^*}{K_S}\frac{T^*}{K_T}(K_T-T^*) - f_{S}(x^*)G_{S}(N)h_{S}(S^*)S^*,\label{eq:our_system_steady_2}\\
        0 &= g_{x} + a_{x,T}T^* + a_{x,S}S^* - \mu_{x}x^*.\label{eq:our_system_steady_3}
    \end{align}
\end{subequations}
In particular, if a point $(T^*,S^*,x^*)$ is a steady state of System~\eqref{eq:our_system}, then 
\begin{equation}\label{eq:x_steady}
 x^* = \frac{g_x + a_{x,T}T^* + a_{x,S}S^*}{\mu_x}.
\end{equation}
To analyze the stability of the steady states we will use the linearization theorem. Let us denote the RHS of Eqs.~\eqref{eq:our_system_1} and \eqref{eq:our_system_2} as $f_1$ and $f_2$, respectively. Then the Jacobian matrix $\mathcal{J}$ of System~\eqref{eq:our_system} at any point $(T,S,x)$ reads
\begin{align}\label{jacobi}
    \mathcal{J}(T,S,x)=&
    \begin{pmatrix}
        \frac{\partial f_1}{\partial T}(T,S,x)
        &
        \frac{\partial f_1}{\partial S}(T,S,x)
        &
        \frac{\partial f_1}{\partial x}(T,S,x)
        \\[10pt]
        \frac{\partial f_2}{\partial T}(T,S,x)
        &
        \frac{\partial f_2}{\partial S}(T,S,x)
        &
        \frac{\partial f_2}{\partial x}(T,S,x)
        \\[10pt]
        a_{x,T} & a_{x,S} & -\mu_x
    \end{pmatrix},
\end{align}
where
\begin{subequations}\label{eq:partial_derivatives}
\renewcommand{\theequation}{\theparentequation.\arabic{equation}}
  \begin{align}
    \frac{\partial f_1}{\partial T}(T,S,x)=& 
        \begin{aligned}[t] 
        & \frac{r_\alpha S}{K_T K_S}(K_T - 2T) - \frac{r_T}{K_T}T + r_T \left(1-\frac{T}{K_T}\right) \\ 
        &-f_T(x)G_T(N)\big(h_T'(T)T^* + h_T(T)\big),
        \end{aligned} \label{eq:partial_derivatives_1}
    \\
    \frac{\partial f_1}{\partial S}(T,S,x)=& \, \frac{r_\alpha T}{K_T K_S}(K_T - T),\label{eq:partial_derivatives_2}
    \\
    \frac{\partial f_1}{\partial x}(T,S,x)=& -f_T'(x)G_T(N)h_T(T)T,\label{eq:partial_derivatives_3}
    \\
    \frac{\partial f_2}{\partial T}(T,S,x)=& \,\frac{r_\alpha S}{K_T K_S}(K_T - 2T),\label{eq:partial_derivatives_4}
    \\
    \frac{\partial f_2}{\partial S}(T,S,x)=& 
        \begin{aligned}[t]
        & -\frac{r_S}{K_S}S + r_S \left(1-\frac{S}{K_S}\right) - \frac{r_\alpha T}{K_T K_S}(K_T - T)\\
        &- f_S(x)G_S(N)\big(h_S'(S)S + h_S(S)\big),
        \end{aligned}\label{eq:partial_derivatives_5}
    \\
    \frac{\partial f_2}{\partial x}(T,S,x)=&  -f_S'(x)G_S(N)h_S(S)S.\label{eq:partial_derivatives_6}
  \end{align}
\end{subequations}

In subsequent sections, if the context makes it clear at which point we consider a partial derivative, we will often omit the point from the notation, e.g.~we will write $\frac{\partial f_i}{\partial T}$ instead of $\frac{\partial f_i}{\partial T}(T^*,S^*,x^*)$, $i=1$, $2$.


\subsection{The case without treatment}
We begin our analysis of steady states with the case of $N\equiv 0$. 
In this case System~\eqref{eq:our_system_steady} simplifies to
\begin{subequations}\label{N=0}
\renewcommand{\theequation}{\theparentequation.\arabic{equation}}
    \begin{align}
        0 &= \left(  r_{\alpha}\frac{S^*}{K_S} + r_T 
\right)
\left(1-\frac{T^*}{K_T}\right)T^* ,\label{N=0_1} \\
        0 &= \left( r_S (K_S-{S^*}) - r_{\alpha}\frac{T^*}{K_T}(K_T-T^*)
\right) \frac{S^*}{K_S} , \label{N=0_2}\\
        0 &= g_{x} + a_{x,T}T^* + a_{x,S}S^* - \mu_{x}x^*,
    \end{align}
\end{subequations}
and it is obvious that the last coordinate satisfies Eq.~\eqref{eq:x_steady}, while Eqs.~\eqref{N=0_1} and \eqref{N=0_2} do not depend on $x^*$. Hence, we can analyze only the system for $T^*$ and $S^*$.

We easily see that in a steady state
\begin{itemize}
\item either $T^*=0$ or $T^*=K_T$;
\item for both the values of $T^*$, either $S^*=0$ or  $S^*=K_S$.
\end{itemize}
Hence, there are four steady states:
\[
A_1 =(0,0), \quad A_2 =(0,K_S), \quad A_3=(K_T,0), \quad A_4=(K_T,K_S).
\]
To study stability of these states we use the second minor of $\mathcal{J}$ that reads
\[
J_2(T,S) = 
     \begin{pmatrix}
         \frac{r_\alpha S(K_T - 2T)}{K_T K_S} +
         r_T\left(1-\frac{2T}{K_T}\right)
%R_T'(T)T + R_T(T) 
         &
         \frac{r_\alpha T(K_T - T)}{K_T K_S}
         \\[20pt]
         \frac{r_\alpha S(K_T - 2T)}{K_T K_S}
         &
         %R_S'(S)S + R_S(S) 
    r_S\left(1-\frac{2S}{K_S}\right)
         - \frac{r_\alpha T(K_T - T)}{K_T K_S} 
     \end{pmatrix},
\]
and it is easy to see that for every $A_i$, $i=1,2,3,4$, eigenvalues are real and equal to the terms on the diagonal. Therefore, in the coordinates $(T,S)$,
\begin{itemize}
    \item $A_1$ is an unstable node, as  $\lambda_1=r_T>0$, $\lambda_2=r_S>0$;
    \item $A_2$ is a saddle, as $\lambda_1=r_{\alpha}+r_T>0$, $\lambda_2=-r_S<0$;
    \item $A_3$ is a saddle, as $\lambda_1=-r_T<0$, $\lambda_2=r_S>0$;
    \item $A_4$ is a stable node, as $\lambda_1=-r_{\alpha}-r_T<0$, $\lambda_2=-r_S<0$.
\end{itemize}
Moreover, it is also easy to see that the RHS of Eq.~\eqref{eq:our_system_1} for $N=0$ is always positive for $T\in(0,K_T)$, which means that $T(t) \to K_T$ for $t\to \infty$ for any initial $T_0 \in (0,K_T)$. Then, it follows that $S(t)\to K_S$ for $S_0\in (0,K_S)$. Hence, $A_4$ is globally stable, which implies that both populations of tumor cells grow to their maximum sizes.

In the next subsection, we will formulate the conditions that allow for a~cure.


\subsection{Semitrivial cure steady state}

First, we consider the simplest case where $T^*=0$, $S^*=0$, $x^*=\frac{g_x}{\mu_x}$. This complete cure steady state (CCS) exists regardless of the value of $N$. 
From Eqs.~\eqref{jacobi} and~\eqref{eq:partial_derivatives} we have
\begin{align*}
    \mathcal{J}\left(0,0,\frac{g_x}{\mu_x}\right) &= 
    \begin{pmatrix}
    r_T - f_T\left(\frac{g_x}{\mu_x}\right)G_T(N) & 0 & 0\\
    0 & r_S - f_S\left(\frac{g_x}{\mu_x}\right)G_S(N) & 0\\
    a_{x,T} & a_{x,S} & -\mu_{x}\\
    \end{pmatrix}.
\end{align*}
Because $\mathcal{J}\left(0,0,\frac{g_x}{\mu_x}\right)$ is a lower triangular matrix its  eigenvalues are
\begin{align*}
    \lambda_{1}&=r_T - f_T\left(\frac{g_x}{\mu_x}\right)G_T(N), &
    \lambda_{2} &= r_S - f_S\left(\frac{g_x}{\mu_x}\right)G_S(N), &
    \lambda_{3} &= - \mu_x.
\end{align*}
Of course $\lambda_3$ is a negative constant, while $\lambda_1$, $\lambda_2 <0$ if and only if
\begin{equation}\label{eq:G1_G2_triv}
    \frac{r_i}{f_i\left(\frac{g_x}{\mu_x}\right)}<G_i(N), \quad i=T,\, S.
\end{equation}
Since the functions $G_i$, $i=T$, $S$, are strictly increasing, their inverse functions $G_i^{-1}$, exist and are also strictly increasing. Thus, we can define
\begin{equation*}
N_{\min}^{(i)}:=G_i^{-1}\left(\frac{r_i}{f_i\left(\frac{g_x}{\mu_x}\right)}\right), 
\quad i=T,\, S.
\end{equation*}
It is easy to see that if $N>N^{loc}_{\min}:=\max\left\{N_{\min}^{(T)}, N_{\min}^{(S)}\right\}$, then Condition \eqref{eq:G1_G2_triv} is satisfied, and therefore the CCS  is locally asymptotically stable.


As local stability is difficult to interpret in practice, we are more interested in stronger condition of global stability. Considering System~\eqref{eq:our_system} in the invariant set $\mathcal{D}$ we can pose such conditions.

\begin{theorem}
    If $N> N_{\min}^{glob}$, where
    \[ N_{\min}^{glob} = \max \left\{ G_T^{-1} \left(\frac{r_T}{f_T(\bar x)h_T(K_T)}\right), G_S^{-1} \left(\frac{r_S}{f_S(\bar x)h_S(K_S)}\right) \right\}, \], then the CCS is globally stable in $\mathcal{D}$. 
\end{theorem}
\textit{Proof:}
First note that in the invariant set, due to monotonicity of the functions $f_i$, $h_i$, $i=T$, $S$, we have
\[
f_i(x)\geq f_i(\bar x), \quad h_i(i) \geq h_i(K_i),\quad i=T, \, S,
\]
and therefore
\[
\dot S \leq r_S\left(1-\frac{S}{K_S}\right)S - f_S(\bar x)G_S(N)h_S(K_S)S
\leq S\left(r_S- f_S(\bar x)G_S(N)h_S(K_S)\right).
\]
We easily see that if the coefficient $\hat r_S=r_S- f_S(\bar x)G_S(N)h_S(K_S)$ 
 is negative, that is,
$G_S(N)>\frac{r_S}{f_S(\bar x)h_S(K_S)}$,
then $S$ tends to 0 exponentially over time.

Similarly, if $G_T(N)>\frac{r_T}{f_T(\bar x)h_T(K_T)}$, then the coefficient 
$$\hat r_T=r_T- f_T(\bar x)G_T(N)h_T(K_T)<0,$$
and according to the assumption of this theorem, there exists $\bar t>0$ such that
\[
r_{\alpha}\frac{S(t)}{K_S} < \frac{\left|\hat r_T \right|}{2}, \quad \text{for all} \ \  t > \bar t.
\]
Therefore, for $t>\bar t$,
\[
\dot T \leq r_{\alpha}\frac{S}{K_S}{T} +r_TT - f_T(\bar x)G_T(N)h_T(K_T)T <
-\frac{\left|\hat r_T \right|}{2} T ,
\]
implies that $T(t) \to 0$ as well. Then it is obvious that $x(t) \to x^*$.
$\hfill\square$


