\vspace*{0.3cm}
\subsection{Recurrence steady state}

In this section, we consider a situation in which ordinary cancer cells $T$ have been destroyed as a result of therapy but some population of cancer stem cells $S$ has survived. In other words, we will analyze the steady states $(0,S^*,x^*)$ such that $S^*>0.$ We will call this state the RSS.

Since we assume that $T^*=0$, then
$x^*=\frac{g_x+a_{x,S}S^*}{\mu_x}$, and 
Eq.~\eqref{eq:our_system_steady_2} for $S^*\ne 0$ reads
\begin{equation}\label{eq:steady_recurrence_existence_1}
     r_{S}\left(1-\frac{S^*}{K_S}\right) = f_{S}\left(\frac{g_x+a_{x,S}S^*}{\mu_x}\right)G_{S}(N)h_{S}(S^*).
\end{equation}
Note that the LHS of Eq.~\eqref{eq:steady_recurrence_existence_1} is linear decreasing, taking the values in the interval $[0,r_2]$ in the invariant set $\mathcal{D}$, where $0$ is achieved for $S^*=K_S$. Let us denote the RHS of Eq.~\eqref{eq:steady_recurrence_existence_1} by $F$, that is, 
\[ F(Z)= G_{S}(N) f_{S}\left(\frac{g_x+a_{x,S}Z}{\mu_x}\right)h_{S}(Z), \quad Z \in [0,K_S]. \].

Let us fix $N\geq 0$ and consider the number of solutions to Eq.~\eqref{eq:steady_recurrence_existence_1}. It is obvious that for $N=0$, the only solution is $S^*=K_S$. 

For $N>0$, the function $F$ takes positive values for $Z\geq 0$. Now, we study the properties of $F$. Using Assumption~\ref{assumption1} we calculate:
\begin{itemize}
\item $F(0) = G_{S}(N)f_{S}\left(\frac{g_x}{\mu_x}\right)\in \left(G_S(N)a_{S,x}, G_S(N) \right] $; 
\item $F'(Z) = G_S(N) \left(\frac{a_{x,S}}{\mu_x} f'_S \left(\frac{g_x+a_{x,S}Z}{\mu_x}\right)h_S(Z)+ f_S\left(\frac{g_x+a_{x,S}Z}{\mu_x}\right)h_S'(Z) \right)\leq 0$;
\item 
$F(K_S) = G_{S}(N)f_{S}\left(\frac{g_x+a_{x,S}K_S}{\mu_x}\right)h_S(K_S)>0$,
$\lim\limits_{Z\to\infty} F(Z) =0$.
\end{itemize}
These properties allow us to conclude the following.
\begin{rem}
If $r_S> F(0)$, then there exists at least one RSS.
\end{rem}
However, without specifying the shapes of $f_S$ and $h_S$ more precisely, we are not able to estimate this number from above. Hence, we pose additional assumptions related to these functions. 
\begin{assumption}\label{assumption:convex}
Assume that $f_S$ and $h_S$ are convex functions.
\end{assumption}
\begin{rem}
The product of two nonnegative, decreasing, convex functions is a nonnegative, decreasing, convex function.
\end{rem}
Using this property of the function $F$, we are now in a position to
study the number of RSS.

\begin{itemize}
\item If $F(0)<r_S$, then there is exactly one RSS. The smaller the value of $F(0)$, the closer the solution $S^*$ is to $K_S$.
\item If $F(0)=r_S$, then:
\subitem (I) $|F'(0)| \leq \frac{r_S}{K_S}$, then there is only one solution that overlaps with the CCS.
\subitem (II) $|F'(0)| > \frac{r_S}{K_S}$, then there are two solutions and the smaller one overlaps with the CCS. 
\item If $F(0)>r_S$, then:
\subitem (I) $|F'(0)| \leq \frac{r_S}{K_S}$, then there is no nonnegative solution. 
\subitem (II) $|F'(0)| > \frac{r_S}{K_S}$, then there are two solutions until the next bifurcation, where $F(0)$ is such that the two solutions overlap and the straight line in tangent to $F$. For larger $F(0)$, there is no solution. 
\end{itemize} 


One the basis of the above considerations, let us define the following critical values of $N$:
\[
\begin{split}
N_{th}^I  := & \ G_S^{-1}\left( \frac{r_S}{f_S(\frac{g_x}{\mu_x})} \right)=N_{\min}^{(S)}, \\
N_{th}^{II}  := & \ G_S^{-1}\left( 
\frac{r_S}
{K_S\left|
\frac{a_{x,S}}{\mu_x}f_S'(\frac{g_x}{\mu_x})+ f_S(\frac{g_x}{\mu_x})h_S'(0)\right|} 
\right),\\
N_{th}^{III} := & \ G_S^{-1}\left( \frac{r_S\left(1-\frac{S^*_{th}}{K_S} \right)}{f_S\left(\frac{g_x+a_{x,S}S^*_{th}}{\mu_x}\right)h_S(S^*_{th})} \right), \  \text{if there exists} \ S^*_{th} \ \text{satisfying}
\end{split}
\]
\begin{align*}
    \  \frac{\left(K_S-{S^*_{th}} \right)}{f_S\left(\frac{g_x+a_{x,S}S^*_{th}}{\mu_x}\right)h_S(S^*_{th})} 
    &= \frac{1}
    {\left|
    \frac{a_{x,S}}{\mu_x}f_S'(\frac{g_x+a_{x,S}S^*_{th}}{\mu_x})h_S(S^*_{th})+ f_S(\frac{g_x+a_{x,S}S^*_{th}}{\mu_x})h_S'(S^*_{th})\right|} . 
\end{align*}
Now, we are ready to formulate the following theorem.
\begin{theorem}
For System~\eqref{eq:our_system}, under Assumption~\ref{assumption:convex}, the number of the RSS varies from 0 to 2.
\begin{enumerate}
\item If $N<N_{th}^I$, then there is exactly one RSS.
\item At $N=N_{th}^I$ there is a bifurcation.
\item If $N^I_{th}< N_{th}^{II}$, then for $N \in \left( N_{th}^I,N_{th}^{II}\right]$ there is no RSS.
\item If $N^I_{th}> N_{th}^{II}$, then for $N > N_{th}^I$ there are two RSS until the next bifurcation at $N=N^{III}_{th}$.
\item If $N>N_{th}^{III}$, then there is no RSS.
\end{enumerate}
\end{theorem}

\begin{rem}
If we additionally assume $K_s>1$ (an obvious assumption in reality) and $h'(0)=-1$, then we can exclude Case 3.~in the above theorem due to the inequality $N_{th}^{II}<N_{th}^I$.
\end{rem}


\medskip



To gain a bit deeper insight into the existence and stability of the RSS and coexistence steady states, and to perform numerical simulations, in the following we introduce an additional assumption about the explicit forms of functions appearing in System~\eqref{eq:our_system}.
\begin{assumption}\label{assumption:explicit_functions} From now on we assume that
\begin{enumerate}
    \item $f_T(x)=\frac{a_{T,x} x + 1}{x+1}$ (decreasing if $a_{T,x}\in(0,1),$ $f_T(0)=1,$ $\lim_{x\rightarrow \infty}f_T(x)=a_{T,x}$),
    \item $g_T(u)=\frac{a_{T,u} u}{u+1}$ (increasing, $\lim_{u\rightarrow \infty}g_T(u)=a_{T,u}$),
    \item $h_T(T)=\frac{1}{T+1}$ (decreasing, $h_T(0)=1$, $\lim_{T\rightarrow \infty}h_T(T)=0$),
    \item $f_S(x)=\frac{a_{S,x} x + 1}{x+1}$ (decreasing if $a_{S,x}\in(0,1),$ $f_S(0)=1,$ $\lim_{x\rightarrow \infty}f_S(x)=a_{S,x}$),
    \item $g_S(u)=\frac{a_{S,u} u}{u+1}$ (increasing, $\lim_{u\rightarrow \infty}g_S(u)=a_{S,u}$),
    \item $h_S(S)=\frac{1}{S+1}$ (decreasing, $h_S(0)=1$, $\lim_{T\rightarrow \infty}h_S(S)=0$),
    \item $f_C(z)=\frac{a_{C,v} z}{z + 1}$ (increasing, $\lim_{z\rightarrow \infty}f_C(z)=a_{C,v}$, $f_C'(0)>0$, $\lim_{z\rightarrow \infty}f_C'(z)=0,$ where $z=(T+S)v$),
    \item $g_C(x)=\frac{a_{C,x} x + 1}{x+1}$ (decreasing for $a_{C,x}\in(0,1),$ $g_C(0)=1$, $\lim_{x\rightarrow \infty}g_C(x)$),
    \item $f_u(y)=\frac{a_{u,y} y}{y+1}+g_u$ (increasing, $f_u(0)=g_u,$ $\lim_{y\rightarrow \infty}f_u(z)=a_{u,y}$),
    \item $f_v(x)=\frac{1}{x+1}$ (decreasing, $f_v(0)=1,$ $\lim_{x\rightarrow \infty}f_v(x)=0$),
    \item $g_v(y)=\frac{a_{v,y} y}{y+1}$ (increasing, $g_v(0)=0,$ $\lim_{y\rightarrow \infty}g_v(y)=a_{v,y},$ $\lim_{y\rightarrow \infty}g_v'(y)=0$).
\end{enumerate}
\end{assumption}

We now reformulate conditions for the existence of RSS under Assumptions~\ref{assumption:explicit_functions}.
Since we assume that $T^*=0,$ then Eq.~\eqref{eq:our_system_steady_1} reads
\begin{equation}\label{eq:steady_recurrence_existence_11}
    \begin{aligned}
     0 &= R_{2}(S^*)S^* - f_{S}(x^*)G_{2}(N)h_{S}(S^*)S^*.
    \end{aligned}
\end{equation}

