In this case, if $H(0;N)<F(0),$ then the graphs of $F$ and $H$ will intersect exactly once for $S^*>0,$ see Figs~\ref{fig:0Sx_N=0},~\ref{fig:0Sx_H0_less_F0}, as well as if $H(0;N)=F(0)$ and $H'(0;N)<F'(0),$ see Fig.~\ref{fig:0Sx_H0_eq_F0}. However, if $H(0;N)\geqslant F(0)$ and $H'(0;N)\geqslant F'(0),$ then the graphs of $F$ and $H$ will not intersect for $S^*>0,$ see Fig.~\ref{fig:0Sx_H0_more_more_F0}. 

If conditions $H(0;N)>F(0)$ and $H'(0;N)<F'(0)$ are met for some nonnegative $N_0$, then there exists an open interval $I$ such that $N_0\in I$ and $H(0;N)>F(0),$ $H'(0;N)<F'(0)$ for all $N\in I.$ Furthermore, there exists $N_{\text{crit}}\in I$ for which the graph of $H$ is tangent to the graph of $F$ at some $S^{*}_{\text{crit}},$ i.e.~the graphs of $H$ and $F$ intersect at exactly one point for $S^*>0,$ see Fig.~\ref{fig:0Sx_N_eq_Ncrit}. Furthermore, if $N\in I$ and $N<N_{\text{crit}},$ then the graphs of $H$ and $F$ intersect twice for $S^*>0,$ see Fig.~\ref{fig:0Sx_N_less_Ncrit}. On the other hand, if $N\in I$ and $N>N_{\text{crit}},$ then the graphs of $H$ and $F$ do not intersect for $S^*>0,$ see Fig.~\ref{fig:0Sx_N_greater_Ncrit}.

In order to find $N_{\text{crit}}$ and $S^{*}_{\text{crit}}$ let us solve the system
\begin{equation*}
    \begin{aligned}
    H(T^*;N)&=F(T^*),\\
    H'(T^*;N)&=F'(T^*),
    \end{aligned}
\end{equation*}
which is equivalent to
\begin{subequations} \label{eq:N_crit_S_crit}
\renewcommand{\theequation}{\theparentequation.\arabic{equation}}
  \begin{align}
    K_S\big(a_{S,x} (g_x + a_{x,S}S^*) + \mu_x\big) G_S(N)&=F(S^*),\label{eq:N_crit_S_crit_1}\\
    K_S a_{S,x}a_{x,S}G_S(N)&=F'(S^*).\label{eq:N_crit_S_crit_2}
  \end{align}
\end{subequations}
From Eq.~\eqref{eq:N_crit_S_crit_2} we get
\begin{equation}\label{eq:N_crit_1}
    \begin{gathered}
    G_S(N)=\frac{F'(S^*)}{K_S a_{S,x} a_{x,S}}
    \end{gathered}
\end{equation}
and after substituting Eq.~\eqref{eq:N_crit_1} into Eq.~\eqref{eq:N_crit_S_crit_1} we obtain
\begin{equation}\label{eq:N_crit_S_crit_3}
\begin{gathered}
\frac{F'(S^*)}{a_{S,x} a_{x,S}}\Big(a_{S,x}(g_x+a_{x,S}S^*) + \mu_x\Big)-F(S^*)=0.
\end{gathered}
\end{equation}
Of course, the LHS of Eq.~\eqref{eq:N_crit_S_crit_3} is a third-degree polynomial so we can obtain its roots analytically. Let us denote them as $w_0,w_1,w_2.$ Since we know that there exists exactly one positive $S^{*}$ that solves Eq.~\eqref{eq:N_crit_S_crit}, then we will obtain $S^{*}_{\text{crit}}$ by taking
\begin{align}\label{eq:S_crit}
    S^{*}_{\text{crit}} = \max \left\{ \Re(w_0),\Re(w_1), \Re(w_2) \right\}.
\end{align}
On the other hand,  applying $G_{S}^{-1}$ to both sides of Eq.~\eqref{eq:N_crit_1} we obtain
\begin{align*}\label{eq:N_crit_2}
    N_{\text{crit}}&=G_{S}^{-1}\left( \frac{F'(S^{*}_{\text{crit}})}{ K_S a_{S,x}a_{x,S}}\right).
\end{align*}



\begin{cor}\label{cor:0Sx_steady_existence}
    The number of the RSS of System~\eqref{eq:our_system} under Assumption~\ref{assumption:explicit_functions} is dependent on the value of the parameter $N$ in the following way. For $N\geqslant 0$ such that
    \begin{enumerate}
        \item $H(0;N) \geqslant F(0)$ and $H'(0;N) \geqslant F'(0)$ there are no RSS;
        \item $H(0;N) < F(0)$ or $H(0;N) = F(0)$ and $H'(0;N) < F'(0)$ there is exactly one RSS;
        \item $H(0;N) > F(0)$ and $H'(0;N) < F(0)$ and
            \begin{enumerate}
                \item $N>N_{\text{crit}}$ there are no RSS;
                \item $N=N_{\text{crit}}$ there is exactly one RSS;
                \item $N<N_{\text{crit}}$ there are two RSS.
            \end{enumerate}
    \end{enumerate}
\end{cor}

Let us now proceed to analyze the RSS stability. From Eq.~\eqref{jacobi} we have

\begin{equation}\label{eq:jacobi_0Sx}
    \begin{aligned}
    \mathcal{J}(0,S^*,x^*) &= 
    \begin{pmatrix}
    \frac{\partial f_1}{\partial T}(0,S^*,x^*) & 0 & 0
    \\[2ex]
    \frac{\partial f_2}{\partial T}(0,S^*,x^*) & \frac{\partial f_2}{\partial S}(0,S^*,x^*) & \frac{\partial f_2}{\partial x}(0,S^*,x^*)
    \\[2ex]
    a_{x,T} & a_{x,S} & -\mu_{x}
    \end{pmatrix}
    \end{aligned}
\end{equation}
The characteristic polynomial of $\mathcal{J}(0,S^*,x^*)$ is given as
\begin{equation*}
    \begin{aligned}
    W(\lambda)&=
    \left(\frac{\partial f_1}{\partial T}-\lambda\right)\left( \lambda^2 +\lambda \left(\mu_{x}-\frac{\partial f_2}{\partial S}\right)
    -\left(\mu_{x}\frac{\partial f_2}{\partial S} +  a_{x,S}\frac{\partial f_2}{\partial x} \right)\right).
    \end{aligned}  
\end{equation*}
Let us denote
\begin{equation}\label{RSSstab}
    \begin{gathered}
    V(\lambda):=\lambda^2 +\lambda \left(\mu_{x}-\frac{\partial f_2}{\partial S}\right)
    -\left(\mu_{x}\frac{\partial f_2}{\partial S} + a_{x,S}\frac{\partial f_2}{\partial x} \right)
    \end{gathered}
\end{equation}
and let $v_1, v_2$ be the roots of $V(\lambda).$ Of course, if all the eigenvalues of $\mathcal{J}(0,S^*,x^*),$ i.e.~$\frac{\partial f_1}{\partial T}, v_1, v_2,$ have negative real parts, then the RSS is locally asymptotically stable. Note that from Eq.~\eqref{eq:x_steady} and Assumption~\ref{assumption:explicit_functions} we obtain
\begin{equation}\label{eq:df1/dT_0Sx}
    \begin{aligned}
    \frac{\partial f_1}{\partial T}(0,S^*,x^*)&=\frac{r_{\alpha}S^*}{K_S}+r_T - \frac{a_{T,x}(g_x+a_{x,S}S^*)+\mu_x}{g_x+a_{x,S}S^*+\mu_x}G_T(N) \\
    & = \frac{r_{\alpha}S^*}{K_S}+r_T - 
    \left(a_{T,x}+
\frac{(1-a_{T,x})\mu_x}{g_x+a_{x,S}S^*+\mu_x}\right)
    G_T(N) .
    \end{aligned}
\end{equation}
It is easy to see that for the values of $N$ close to $0$ the negative component of the RHS of Eq.~\eqref{eq:df1/dT_0Sx} is also close to $0$ and thus $\frac{\partial f_1}{\partial T}>0.$ 
On the other hand, assuming $a_{T,x}\leq 1$ and remembering that $S^*\leq K_S$ we see that it is enough to require $G_T(N)> \frac{r_{\alpha}+r_T}{a_{T,x}}$ to get 
$\frac{\partial f_1}{\partial T}< 0.$ 

Note also that for the RSS we can determine the value of $N$ as a function of $S^*.$ From the condition $H(S^*;N)=F(S^*)$ we get
\begin{equation*}
    \begin{gathered}
    K_S(a_{S,x}(g_x+a_{x,S}S^*)+\mu_x)G_S(N)=F(S^*),\\
    \end{gathered}
\end{equation*}
or equivalently 
\begin{equation}\label{eq:0Sx_N_depending _on_S}
    \begin{aligned}
    N&=G_S^{-1}\left( \frac{F(S^*)}{K_S(a_{S,x}(g_x+a_{x,S}S^*)+\mu_x)}\right).
    \end{aligned}
\end{equation}

From Corollary~\ref{cor:G1_G2} and Eq.~\eqref{eq:df1/dT_0Sx} we can deduce that

\begin{equation}\label{eq:df1/dT_leq_1}
    \begin{aligned}
        \frac{\partial f_1}{\partial T}(0,S^*,x^*) 
        & \leqslant \frac{r_{\alpha}S^*}{K_S}+r_T - \frac{a_{T,x}(g_x+a_{x,S}S^*)+\mu_x}{g_x+a_{x,S}S^*+\mu_x}G_S\left(N\right).
    \end{aligned}
\end{equation}

\begin{assumption}\label{assumption:atx=asx}
    From now on, we assume that $a_{T,x}=a_{S,x}.$
\end{assumption}

From the Assumption above and Eq.~\eqref{eq:0Sx_N_depending _on_S} we get

\begin{equation}
    \begin{aligned}
        \frac{a_{T,x}(g_x+a_{x,S}S^*)+\mu_x}{g_x+a_{x,S}S^*+\mu_x}G_S(N) &= \frac{r_S (K_S - S^*)(S^*+1)}{K_S},
    \end{aligned}
\end{equation}

\begin{comment}
\begin{equation}
    \begin{aligned}
        \frac{a_{T,x}(g_x+a_{x,S}S^*)+\mu_x}{g_x+a_{x,S}S^*+\mu_x}G_S(N) &= \frac{F(S^*)}{K_S(g_x + a_{x,S}S^*+\mu_x)} &= \frac{r_S (K_S - S^*)(S^*+1)}{K_S},
    \end{aligned}
\end{equation}
\end{comment}

which implies that

\begin{equation}\label{eq:df1/dT_leq_2}
    \begin{aligned}
        \frac{\partial f_1}{\partial T}(0,S^*,x^*) 
        & \leqslant \frac{r_{\alpha}S^* + r_T K_S - r_S (K_S - S^*)(S^*+1)}{K_S}.
    \end{aligned}
\end{equation}

Let us denote the numerator of the RHS of the inequality above as

\begin{equation*}
    \begin{aligned}
         Q(S^*)&:=r_{\alpha}S^*+r_T K_S - r_S (K_S - S^*)(S^*+1)
         \\
         & \ =r_S S^{*2} + S^*(r_S - r_S K_S + r_{\alpha}) + K_S(r_T-r_S).
     \end{aligned}
\end{equation*}

Then we have

\begin{equation}
    \begin{aligned}
        Q(S^*)<0 \implies \frac{\partial f_1}{\partial T}(0,S^*,x^*)<0.
    \end{aligned}
\end{equation}

Notice that the above condition can be satisfied only for small values of $S^*$, since for $S^*$ near $K_S$ the positive terms of $Q(S^*)$ are much larger compared to the negative one.
Coming back to Formula~\eqref{RSSstab}, to get  stability of the RSS it is enough to assume

\begin{equation}\label{eq:v1_v2_negative}
    \begin{aligned}
    \frac{\partial f_2}{\partial S} - \mu_x&<0 \quad &\land \quad
    -\mu_x \frac{\partial f_2}{\partial S} - a_{S,x}\frac{\partial f_2}{\partial x} &> 0.
    \end{aligned}
\end{equation}

We have

\begin{equation*}
    \begin{aligned}
        \frac{\partial f_2}{\partial S} - \mu_x &= 
        r_S \Big(1-\frac{2S^*}{K_S}\Big) - G_S(N)f_S(x^*)\frac{1}{(S^*+1)^2} - \mu_x,
    \end{aligned}
\end{equation*}

and note that to have the first inequality in \eqref{eq:v1_v2_negative} satisfied it is enough to assume $r_S\leq \mu_x$. In the more general case, substituting $G_S(N)$ we obtain

\begin{equation*}
    \begin{aligned}
        \frac{\partial f_2}{\partial S} - \mu_x &= 
        r_S \Big(1-\frac{2S^*}{K_S}\Big) -\frac{F(S^*)}{K_S(g_x + a_{x,T}T^* + a_{x,S}S^*+\mu_x)(S^*+1)^2} - \mu_x
        \\
        &= \frac{r_S (K_S - 2S^*)(S^*+1) - r_S(K_S-S^*) - \mu_x K_S (S^*+1)}{K_S(S^*+1)}.
    \end{aligned}
\end{equation*}

Let us denote the numerator of the expression above as

\begin{equation*}
    \begin{aligned}
        P(S^*)&:=r_S (K_S - 2S^*)(S^*+1) - r_S(K_S-S^*) - \mu_x K_S (S^*+1)\\
        & \ = -2r_S{S^*}^2 + S^*\big(r_S(K_S - 1) - \mu_x K_S\big) - \mu_x K_S.
    \end{aligned}
\end{equation*}

Then

\begin{equation*}
    \begin{gathered}
         \frac{\partial f_2}{\partial S} - \mu_x <0 \iff 
         P(S^*) <0.
    \end{gathered}
\end{equation*}

It is obvious that $P(S^*)<0$ for the values of $S^*$ exceeding $\frac{K_S}{2}$.
Moreover, since

\begin{equation*}
    \begin{aligned}
        \frac{\partial f_2}{\partial x}&=-f_S'(x^*)G_S(N)h_S(S^*)S^*=-\frac{a_{S,x}-1}{(x^*+1)^2}G_S(N) \frac{S^*}{S^*+1}
        \\
        &=\frac{\mu_x r_S(1-a_{S,x})S^*(K_S-S^*)}{K_S (g_x + a_{x,S}S^*+\mu_x)(a_{S,x}(g_x+a_{x,S}S^*)+\mu_x)},
    \end{aligned}
\end{equation*}

then

\begin{equation*}
    \begin{aligned}
        -\mu_x \frac{\partial f_2}{\partial S} - a_{S,x}\frac{\partial f_2}{\partial x} =& 
        \mu_x\frac{r_S(K_S-S^*) -r_S (K_S - 2S^*)(S^*+1)}{K_S(S^*+1)} \\
        &+a_{S,x}\frac{\mu_x r_S(a_{S,x}-1)S^*(K_S-S^*)}{K_S (g_x + a_{x,S}S^*+\mu_x)(a_{S,x}(g_x+a_{x,S}S^*)+\mu_x)}.
    \end{aligned}
\end{equation*}

After reducing the RHS of the equation above to a common denominator, we can denote its numerator as

\begin{equation*}
    \begin{aligned}
        B(S^*):=&S^*(2{S^*}+1-K_S)(g_x + a_{x,S}S^*+\mu_x)\big(a_{S,x}(g_x+a_{x,S}S^*)+\mu_x\big)\\ &-a_{S,x}(1-a_{S,x})S^*(K_S-S^*)(S^*+1).
    \end{aligned}
\end{equation*}

Thus,

\begin{equation*}
    \begin{gathered}
        -\mu_x \frac{\partial f_2}{\partial S} - a_{S,x}\frac{\partial f_2}{\partial x}>0 \iff B(S^*)>0.
    \end{gathered}
\end{equation*}

Note that $B(S^*)<0$ for small values of $S^*$.

\begin{cor}
    The RSS of System~\eqref{eq:our_system}  is locally asymptotically stable if $Q(S^*)<0$, $P(S^*)<0$, and $B(S^*)>0.$
\end{cor}

\vspace*{0.3cm}
\subsection{Coexistence steady states}

Now we will consider a situation in which a certain population of both types of cancer cells survives, i.e.~we will analyze the existence and stability of positive steady states $(T^*,S^*,x^*).$ To be consistent with the previous subsections, we will call this state the PSS. 

Recall that if $N=0$, then  System \eqref{eq:our_system_steady} simplifies to~\eqref{N=0} and the only positive 
solution to it is
\begin{equation}\label{steady_K1_K2}
    \big(K_T,K_S,x^*_{K_T,K_S}\big)=\Big(K_T,K_S,\frac{g_x + a_{x,T}K_T + a_{x,S}K_S}{\mu_x}\Big),
\end{equation}
which is a stable node.
Since System \eqref{eq:our_system} depends continuously on $N$, for the values of $N$ sufficiently close to $0$ there should also exist a locally asymptotically stable steady state $(T^*,S^*,x^*)$ with $T^*,S^*>0$. Moreover, the coordinates $T^*$, $S^*$ remain close to $K_T$ and $K_S$, respectively.

We will now state the conditions necessary for the point $(S^*, T^*, x^*),$ $S^*,T^*>0$ to be the solution to System \eqref{eq:our_system_steady}. Adding the first two equations of System~\eqref{eq:our_system_steady} by sides we get
\begin{equation}\label{eq:1i2_dodane}
    \begin{gathered}
    - r_T(T^*)T^* + f_T(x^*)G_T(N)h_T(T^*)T^* = r_S(S^*)S^* - f_S(x^*)G_S(N)h_S(S^*)S^*.
    \end{gathered}
\end{equation}
In particular, Equation \eqref{eq:1i2_dodane} holds when both sides are equal to $0$, that is
\begin{equation}\label{eq:warunek0}
    \begin{aligned}
    G_T(N)&=\frac{r_T(K_T-T^*)}{K_T f_T(x^*)h_T(T^*)}, &
    G_S(N)&=\frac{r_S(K_S-S^*)}{K_S f_S(x^*)h_S(S^*)}.
    \end{aligned}
\end{equation}
By substituting \eqref{eq:warunek0} into System \eqref{eq:our_system_steady} we get
\begin{equation*}
    \begin{aligned}
    0&=\frac{r_{\alpha}T^*S^*}{K_T K_S}(K_T-T^*),\\
    0&=-\frac{r_{\alpha}T^*S^*}{K_T K_S}(K_T-T^*),\\
    0&=g_x + a_{x,T}T^* + a_{x,S}S^*-\mu_x x^*.
    \end{aligned}
\end{equation*}
Since $T^*, S^*>0$, solutions to the system above must have the form
\begin{equation}\label{steady_K1_S}
    \big(T^*,S^*,x^*\big)=\Big(K_T,S^*,\frac{g_x + a_{x,T}K_T + a_{x,S}S^*}{\mu_x}\Big),
\end{equation}
where $S^*>0$.
Substituting \eqref{steady_K1_S} into System \eqref{eq:warunek0} we get
\begin{equation}\label{eq:warunek01}
    \begin{aligned}
    G_T(N)&=0, &
    G_S(N)&=\frac{r_S(K_S-S^*)}{K_S f_S(x^*)h_S(S^*)}.
    \end{aligned}
\end{equation}
From Corollary \ref{cor:G1_G2} we conclude that Condition \eqref{eq:warunek01} holds if and only if $N=0,$ $S^*=0$, but we have already analyzed this case.

Thus, let us assume that both sides of Equation~\eqref{eq:1i2_dodane} are different from $0$. In this case, both sides need to be of the same sign. Both sides of this equation are positive if and only if
\begin{equation*}
    \begin{aligned}
    G_T(N)&>\frac{r_T(K_T-T^*)}{K_T f_T(x^*)h_T(T^*)}, &
    G_S(N)&<\frac{r_S(K_S-S^*)}{K_S f_S(x^*)h_S(S^*)},
    \end{aligned}
\end{equation*}
and both sides are negative if and only if
\begin{equation}\label{eq:warunek2}
    \begin{aligned}
    G_T(N)&<\frac{r_T(K_T-T^*)}{K_T f_T(x^*)h_T(T^*)}, &
    G_S(N)&>\frac{r_S(K_S-S^*)}{K_S f_S(x^*)h_S(S^*)}.
    \end{aligned}
\end{equation}
Note that since $\forall{N> 0} \;G_T(N)>G_S(N),$ then Condition \eqref{eq:warunek2} does not hold for any $N$ if
% ZauwaĹĽmy jeszcze, ĹĽe poniewaĹĽ $$\forall{N> 0}\quad G_T(N)>G_S(N),$$ to warunek \eqref{eq:warunek2} nie zachodzi dla ĹĽadnego $N$, jeĹ›li
\begin{equation*}
    \frac{r_S(K_S-S^*)}{K_S f_S(x^*)h_S(S^*)} \geqslant
    \frac{r_T(K_T-T^*)}{K_T f_T(x^*)h_T(T^*)}.
\end{equation*}
\begin{cor}\label{wn:konieczne_na_TSx}
Let $T^*\in(0,K_T]$, $S^*\in(0,K_T]$ and let Assumptions \ref{assumption1}, \ref{assumption2} and \ref{assumption:explicit_functions} be satisfied. If $(T^*,S^*,x^*)$ is a steady state of System \eqref{eq:our_system}, then one of the following conditions holds
\begin{enumerate}
    \item $N=0$,
    \item $ G_T(N)>\frac{r_T(K_T-T^*)}{K_T f_T(x^*)h_T(T^*)},
    G_S(N)<\frac{r_S(K_S-S^*)}{K_S f_S(x^*)h_S(S^*)},$
    \item $G_T(N)<\frac{r_T(K_T-T^*)}{K_T f_T(x^*)h_T(T^*)},
    G_S(N)>\frac{r_S(K_S-S^*)}{K_S f_S(x^*)h_S(S^*)}.$
\end{enumerate}
\end{cor}
It is easy to see that if $N$ satisfies
\begin{equation*}
    \begin{aligned}
    G_T(N)&>\frac{r_T(K_T-T^*)}{K_T f_T(x^*)h_T(T^*)}, &
    G_S(N)&>\frac{r_S(K_S-S^*)}{K_S f_S(x^*)h_S(S^*)},
    \end{aligned}
\end{equation*}
then $N$ does not satisfy any of the conditions from Corollary \ref{wn:konieczne_na_TSx}. Moreover, for any given $T^*\in(0,K_T]$, $S^*\in(0,K_S]$ we have
\begin{equation*}
    \begin{aligned}
    \frac{r_T(K_T-T^*)}{K_T f_T(x^*)h_T(T^*)}=&
    \frac{r_T(K_T-T^*)(g_x + a_{x,T}T^*+a_{x,S}S^*+\mu_x)(T^*+1)}{K_T \big(a_{T,x}(g_x + a_{x,T}T^*+a_{x,S}S^*)+\mu_x\big)}\\
    <&\frac{r_T(g_x+a_{x,T}K_T + a_{x,S}K_S+\mu_x)(K_T+1)}{a_{T,x}g_x+\mu_x},\\
    \frac{r_S(K_S-S^*)}{K_S f_S(x^*)h_S(S^*)}=&
     \frac{r_S(K_S-S^*)(g_x + a_{x,T}T^*+a_{x,S}S^*+\mu_x)(S^*+1)}{K_S \big(a_{S,x}(g_x + a_{x,T}T^*+a_{x,S}S^*)+\mu_x\big)}\\
     <&\frac{r_S(g_x+a_{x,T}K_T + a_{x,S}K_S+\mu_x)(K_S+1)}{a_{S,x}g_x+\mu_x},
    \end{aligned}
\end{equation*}
implying the following corollary.
\begin{cor}\label{wn:nie_ma_TSx}
Let Assumptions \ref{assumption1}, \ref{assumption2}, and \ref{assumption:explicit_functions} hold. If $N$ satisfies
\begin{equation*}
    %\begin{gathered}
    G_i(N)\geqslant\frac{r_i(g_x+a_{x,T}K_T + a_{x,S}K_S+\mu_x)(K_i+1)}{a_{T,x}g_x+\mu_x},\ \ i=T,\, S,
    %\end{gathered}
\end{equation*}
then System \eqref{eq:our_system} has no steady states $(T^*,S^*,x^*)$, such that $T^*\in(0,K_T]$ and $S^*\in(0,K_S].$
\end{cor}

